function emitArrayIsArrayCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>>,
  context: EmitContext,
): string {
  const argument = expression.arguments[0];
  const domain = argument ? getRustArrayIsArrayExpressionDomainRust(argument, context) : undefined;
  if (!argument || (domain !== 'array' && domain !== 'nonArray')) {
    return emissionError(context, 'Array.isArray emission requires one statically decided argument domain');
  }
  const valueName = getGeneratedTargetNameRust('array_is_array_value', context);
  const value =
    (argument.kind === 'literal' && argument.value === null) ||
    argument.kind === 'undefinedValue' ||
    (argument.kind === 'identifier' && argument.reference.kind === 'ambient' && argument.reference.name === 'undefined')
      ? '()'
      : argument.kind === 'identifier' && argument.reference.kind === 'binding'
        ? emitIdentifierReferenceRust(argument.reference, context)
        : emitExpression(argument, context);
  return `{ let ${valueName} = &${value}; let _ = ${valueName}; ${domain === 'array' ? 'true' : 'false'} }`;
}

function emitArrayConstructorRust(
  expression: Readonly<Extract<IrExpression, { kind: 'new' }>>,
  context: EmitContext,
): string {
  const dense = context.denseArrayConstructorInitializers.get(expression);
  if (dense) {
    const initial =
      dense.element.emitted === 'String' ? 'String::new()' : dense.element.emitted === 'bool' ? 'false' : '0.0';
    return `vec![${initial}; ${String(dense.length)}]`;
  }
  const element = expression.typeArguments[0];
  if (!element) return emissionError(context, 'Array construction emission requires one explicit element type');
  const argument = expression.arguments[0];
  if (argument && !(argument.kind === 'literal' && typeof argument.value === 'number' && argument.value === 0)) {
    return emissionError(
      context,
      'Array construction with a length other than a direct numeric literal zero needs provably complete contiguous element writes before any observation, or JavaScript sparse holes and length validation that Rust Vec does not represent',
      'rust-array-constructor-sparse-length-unrepresented',
      'target-runtime',
    );
  }
  return `Vec::<${emitType(element, context)}>::new()`;
}

function emitImmediateArrayConstructorFillCallRust(
  expression: RustImmediateArrayConstructorFillCall,
  context: EmitContext,
): string {
  const constructor = expression.callee.object;
  const element = constructor.typeArguments[0];
  const length = constructor.arguments[0];
  const value = expression.arguments[0];
  if (!element || length?.kind !== 'literal' || typeof length.value !== 'number' || !value || value.kind === 'spread') {
    return emissionError(context, 'immediate Array constructor fill emission requires exact length and value evidence');
  }
  const valueName = getGeneratedTargetNameRust('array_constructor_fill_value', context);
  const elementType = emitType(element, context);
  return `{ let ${valueName}: ${elementType} = ${emitOwnedOperandRust(value, context)}; vec![${valueName}; ${String(length.value)}] }`;
}

function emitArrayOfCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>>,
  context: EmitContext,
): string {
  const result = resolveIrTypeAliasValueRust(expression.semantics.resultType, context, new Set());
  if (result.kind !== 'array') {
    return emissionError(context, 'Array.of emission requires a mutable array result carrier');
  }
  const elementType = emitType(result.element, context);
  if (expression.arguments.length === 0) return `Vec::<${elementType}>::new()`;
  const arguments_ = expression.arguments.map((argument, index) => ({
    emitted: emitOwnedOperandRust(argument, context),
    name: getGeneratedTargetNameRust(`array_of_value${String(index)}`, context),
  }));
  const initializers = arguments_.map(({ emitted, name }) => `let ${name}: ${elementType} = ${emitted};`);
  return `{ ${[...initializers, `vec![${arguments_.map(({ name }) => name).join(', ')}]`].join(' ')} }`;
}

function emitArrayFromCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>>,
  context: EmitContext,
): string {
  const source = expression.arguments[0];
  if (!source) return emissionError(context, 'Array.from emission requires one exact array source');
  const mapper = expression.arguments[1];
  const sourceName = getGeneratedTargetNameRust('array_from_source', context);
  const sharedBinding = getRustSharedArrayBindingRust(source, context);
  const result = resolveIrTypeAliasValueRust(expression.semantics.resultType, context, new Set());
  const sourceType = inferRustArrayGrowthArgumentTypeRust(source, context);
  const sourceArray = sourceType ? resolveIrTypeAliasValueRust(sourceType, context, new Set()) : undefined;
  const signature = mapper ? getRustArrayPredicateCallbackSignatureRust(mapper, context) : undefined;
  const emptySourceElement = mapper
    ? sourceArray?.kind === 'array'
      ? sourceArray.element
      : (expression.typeArguments[0] ?? signature?.parameters[0]?.type)
    : result.kind === 'array'
      ? result.element
      : undefined;
  const emittedSource =
    source.kind === 'array' && source.elements.length === 0 && emptySourceElement
      ? `Vec::<${emitType(emptySourceElement, context)}>::new()`
      : emitExpression(source, context);
  const sourceInitializer = sharedBinding
    ? `${getBindingTargetNameRust(sharedBinding, context)}.borrow()`
    : `&${emittedSource}`;
  if (!mapper) return `{ let ${sourceName} = ${sourceInitializer}; (*${sourceName}).clone() }`;

  if (!signature || signature.parameters.length > 2) {
    return emissionError(context, 'mapped Array.from emission requires one statically known fixed callback');
  }
  const callbackName = getGeneratedTargetNameRust('array_from_callback', context);
  const valuesName = getGeneratedTargetNameRust('array_from_values', context);
  const resultName = getGeneratedTargetNameRust('array_from_result', context);
  const indexName = getGeneratedTargetNameRust('array_from_index', context);
  const elementName = getGeneratedTargetNameRust('array_from_element', context);
  const arguments_ = [
    ...(signature.parameters.length >= 1 ? [`${elementName}.clone()`] : []),
    ...(signature.parameters.length === 2 ? [`${indexName} as f64`] : []),
  ];
  const callbackInitializer =
    mapper.kind === 'function'
      ? `let mut ${callbackName} = ${emitExpression(mapper, context)};`
      : `let ${callbackName} = &${emitExpression(mapper, context)};`;
  const valuesInitializer = sharedBinding ? `${sourceName}.borrow()` : sourceName;
  const mapped = `${valuesName}.iter().enumerate().map(|(${indexName}, ${elementName})| (${callbackName})(${arguments_.join(', ')})).collect::<Vec<_>>()`;
  const release = sharedBinding ? ` drop(${valuesName});` : '';
  // Array.from evaluates the source before the mapper. The shared borrow starts only after both values
  // have been staged, and ends before the fresh result is returned or either source alias is reused.
  return `{ let ${sourceName} = ${sharedBinding ? `&${getBindingTargetNameRust(sharedBinding, context)}` : `&${emittedSource}`}; ${callbackInitializer} let ${valuesName} = ${valuesInitializer}; let ${resultName} = ${mapped};${release} ${resultName} }`;
}

function emitArrayGrowthCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>>,
  context: EmitContext,
): string {
  const member = getArrayGrowthMemberRust(expression);
  if (!member || expression.callee.kind !== 'property') {
    return emissionError(context, 'array growth emission requires push or unshift semantics');
  }
  if (isArrayFixedTupleSpreadGrowthCallRust(expression)) {
    return emitArrayFixedTupleSpreadGrowthCallRust(expression, member, context);
  }
  const arguments_ = expression.arguments.map((argument, index) => ({
    emitted: emitOwnedOperandRust(argument, context),
    name: getGeneratedTargetNameRust(`array_${member}_argument${String(index)}`, context),
  }));
  const receiver = emitSharedReferenceReceiverRust(expression.callee.object, true, context);
  const mutations = arguments_.map(({ name }, index) =>
    member === 'push' ? `${receiver}.push(${name});` : `${receiver}.insert(${String(index)}, ${name});`,
  );
  const lengthReceiver = emitSharedReferenceReceiverRust(expression.callee.object, false, context);
  const initializers = arguments_.map(({ emitted, name }) => `let ${name} = ${emitted};`);
  return `{ ${[...initializers, ...mutations, `${lengthReceiver}.len() as f64`].join(' ')} }`;
}

function emitArrayFixedTupleSpreadGrowthCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>>,
  member: RustArrayGrowthMember,
  context: EmitContext,
): string {
  if (
    expression.callee.kind !== 'property' ||
    expression.callee.object.kind !== 'identifier' ||
    expression.callee.object.reference.kind !== 'binding'
  ) {
    return emissionError(context, `fixed tuple spread ${member} emission requires one stable binding receiver`);
  }
  const receiverBinding = expression.callee.object.reference.binding;
  const receiverName = getGeneratedTargetNameRust(`array_${member}_receiver`, context);
  const valuesName = getGeneratedTargetNameRust(`array_${member}_values`, context);
  const lengthName = getGeneratedTargetNameRust(`array_${member}_length`, context);
  const sharedBinding = getRustSharedArrayBindingRust(expression.callee.object, context);
  if (sharedBinding) context.needsRcImport.add('Rc');
  const targetNames = new Map(context.targetNames);
  targetNames.set(receiverBinding.id, receiverName);
  const segmentContext = { ...context, targetNames };
  const initializers: string[] = [];
  const values: string[] = [];
  for (const [position, argument] of expression.arguments.entries()) {
    if (argument.kind !== 'spread') {
      const name = getGeneratedTargetNameRust(`array_${member}_argument${String(position)}`, context);
      initializers.push(`let ${name} = ${emitOwnedOperandRust(argument, segmentContext)};`);
      values.push(name);
      continue;
    }
    const tuple = getRustFixedRequiredTupleSpreadTypeRust(argument, context);
    if (!tuple) {
      return emissionError(context, `fixed tuple spread ${member} emission requires exact required tuple evidence`);
    }
    const sourceName = getGeneratedTargetNameRust(`array_${member}_spread${String(position)}`, context);
    initializers.push(`let ${sourceName} = &(${emitExpression(argument.expression, segmentContext)});`);
    for (const [offset] of tuple.elements.entries()) {
      const name = getGeneratedTargetNameRust(
        `array_${member}_spread${String(position)}_element${String(offset)}`,
        context,
      );
      initializers.push(`let ${name} = ${sourceName}.${String(offset)}.clone();`);
      values.push(name);
    }
  }
  const receiverTarget = getBindingTargetNameRust(receiverBinding, context);
  const receiverInitializer = sharedBinding
    ? `Rc::clone(&${receiverTarget})`
    : context.referentMutatedParameterIds.has(receiverBinding.id)
      ? `&mut *${receiverTarget}`
      : `&mut ${receiverTarget}`;
  const valuesInitializer = sharedBinding ? `${receiverName}.borrow_mut()` : receiverName;
  const mutations = values.map((name, index) =>
    member === 'push' ? `${valuesName}.push(${name});` : `${valuesName}.insert(${String(index)}, ${name});`,
  );
  const release = sharedBinding ? ` drop(${valuesName});` : '';
  // The receiver identity is fixed before arguments run, but the mutable RefCell borrow is delayed
  // until every scalar and every fixed tuple field has been copied into an owned temporary. This is
  // the source call boundary: no mutation is visible to a later argument, and a same-group alias read
  // cannot overlap the one mutable borrow used for the eventual growth pack.
  return `{ let ${receiverName} = ${receiverInitializer}; ${initializers.join(' ')} let mut ${valuesName} = ${valuesInitializer}; ${mutations.join(' ')} let ${lengthName} = ${valuesName}.len() as f64;${release} ${lengthName} }`;
}

function emitArraySearchCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>>,
  context: EmitContext,
): string {
  const member = getArraySearchMemberRust(expression);
  const argument = expression.arguments[0];
  if (!member || expression.callee.kind !== 'property' || !argument || expression.arguments.length !== 1) {
    return emissionError(
      context,
      'array search emission requires indexOf, lastIndexOf, or includes with exactly one argument',
    );
  }
  const receiverType = inferIrExpressionTypeRust(expression.callee.object, context);
  const receiver = receiverType ? resolveIrTypeAliasValueRust(receiverType, context, new Set()) : undefined;
  if (receiver?.kind !== 'array') return emissionError(context, 'array search emission requires an array receiver');
  const domain = getRustDensePrimitiveArrayCarrierDomainRust(receiver.element, context);
  if (!domain) return emissionError(context, 'array search emission requires an exact primitive value carrier');

  const generatedMember = member === 'indexOf' ? 'index_of' : member === 'lastIndexOf' ? 'last_index_of' : 'includes';
  const receiverName = getGeneratedTargetNameRust(`array_${generatedMember}_receiver`, context);
  const candidateName = getGeneratedTargetNameRust(`array_${generatedMember}_candidate`, context);
  const valueName = getGeneratedTargetNameRust(`array_${generatedMember}_value`, context);
  const sharedBinding = getRustSharedArrayBindingRust(expression.callee.object, context);
  const emittedReceiver = sharedBinding
    ? `&${getBindingTargetNameRust(sharedBinding, context)}`
    : `&${emitExpression(expression.callee.object, context)}`;
  const receiverValues = sharedBinding ? `${receiverName}.borrow()` : receiverName;
  const strictEquality = `*${valueName} == *${candidateName}`;
  const equality =
    domain === 'number' && member === 'includes'
      ? `(${strictEquality} || (${valueName}.is_nan() && ${candidateName}.is_nan()))`
      : strictEquality;
  const search =
    member === 'includes' && domain !== 'number'
      ? `${receiverValues}.contains(${candidateName})`
      : `${receiverValues}.iter().${member === 'includes' ? 'any' : member === 'lastIndexOf' ? 'rposition' : 'position'}(|${valueName}| ${equality})`;
  const result = member === 'includes' ? search : `${search}.map(|index| index as f64).unwrap_or(-1.0)`;
  // A reference to each operand extends temporary lifetimes through the search without moving a
  // reusable source. The shared receiver borrow starts only after the candidate has been evaluated.
  return `{ let ${receiverName} = ${emittedReceiver}; let ${candidateName} = &${emitExpression(argument, context)}; ${result} }`;
}

function emitArrayFindIndexCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>> &
    Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }>,
  context: EmitContext,
): string {
  const callback = expression.arguments[0];
  const signature = callback ? getRustArrayPredicateCallbackSignatureRust(callback, context) : undefined;
  if (!callback || !signature || signature.parameters.length > 2) {
    return emissionError(context, 'array.findIndex emission requires one statically known fixed predicate');
  }
  const receiverName = getGeneratedTargetNameRust('array_find_index_receiver', context);
  const callbackName = getGeneratedTargetNameRust('array_find_index_callback', context);
  const valuesName = getGeneratedTargetNameRust('array_find_index_values', context);
  const resultName = getGeneratedTargetNameRust('array_find_index_result', context);
  const indexName = getGeneratedTargetNameRust('array_find_index_index', context);
  const elementName = getGeneratedTargetNameRust('array_find_index_element', context);
  const sharedBinding = getRustSharedArrayBindingRust(expression.callee.object, context);
  const emittedReceiver = sharedBinding
    ? `&${getBindingTargetNameRust(sharedBinding, context)}`
    : `&${emitExpression(expression.callee.object, context)}`;
  const receiverValues = sharedBinding ? `${receiverName}.borrow()` : receiverName;
  const arguments_ = [
    ...(signature.parameters.length >= 1 ? [`${elementName}.clone()`] : []),
    ...(signature.parameters.length === 2 ? [`${indexName} as f64`] : []),
  ];
  const callbackInitializer =
    callback.kind === 'function'
      ? `let mut ${callbackName} = ${emitExpression(callback, context)};`
      : `let ${callbackName} = &${emitExpression(callback, context)};`;
  const search = `${valuesName}.iter().enumerate().position(|(${indexName}, ${elementName})| (${callbackName})(${arguments_.join(', ')})).map(|index| index as f64).unwrap_or(-1.0)`;
  const release = sharedBinding ? ` drop(${valuesName});` : '';
  // References stage both operands without consuming reusable sources. In particular, the callback
  // is evaluated on an empty receiver, and a shared borrow starts only after both source effects.
  return `{ let ${receiverName} = ${emittedReceiver}; ${callbackInitializer} let ${valuesName} = ${receiverValues}; let ${resultName} = ${search};${release} ${resultName} }`;
}

// `some`/`every` are predicates over the receiver, so they share findIndex's staging: the source is
// referenced once, the callback is evaluated once, and the shared borrow starts only after both source
// effects. Dense iteration visits every stored element, which is why an absence-admitting element
// carrier is refused before emission (JavaScript skips holes).
function emitArrayPredicateCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>> &
    Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }>,
  member: RustArrayPredicateMember,
  context: EmitContext,
): string {
  const callback = expression.arguments[0];
  const signature = callback ? getRustArrayPredicateCallbackSignatureRust(callback, context) : undefined;
  if (!callback || !signature || signature.parameters.length > 2) {
    return emissionError(context, `array.${member} emission requires one statically known fixed predicate`);
  }
  const receiverName = getGeneratedTargetNameRust(`array_${member}_receiver`, context);
  const callbackName = getGeneratedTargetNameRust(`array_${member}_callback`, context);
  const valuesName = getGeneratedTargetNameRust(`array_${member}_values`, context);
  const resultName = getGeneratedTargetNameRust(`array_${member}_result`, context);
  const indexName = getGeneratedTargetNameRust(`array_${member}_index`, context);
  const elementName = getGeneratedTargetNameRust(`array_${member}_element`, context);
  const sharedBinding = getRustSharedArrayBindingRust(expression.callee.object, context);
  const emittedReceiver = sharedBinding
    ? `&${getBindingTargetNameRust(sharedBinding, context)}`
    : `&${emitExpression(expression.callee.object, context)}`;
  const receiverValues = sharedBinding ? `${receiverName}.borrow()` : receiverName;
  const arguments_ = [
    ...(signature.parameters.length >= 1 ? [`${elementName}.clone()`] : []),
    ...(signature.parameters.length === 2 ? [`${indexName} as f64`] : []),
  ];
  const callbackInitializer =
    callback.kind === 'function'
      ? `let mut ${callbackName} = ${emitExpression(callback, context)};`
      : `let ${callbackName} = &${emitExpression(callback, context)};`;
  const terminal = member === 'some' ? 'any' : 'all';
  const search = `${valuesName}.iter().enumerate().${terminal}(|(${indexName}, ${elementName})| (${callbackName})(${arguments_.join(', ')}))`;
  const release = sharedBinding ? ` drop(${valuesName});` : '';
  return `{ let ${receiverName} = ${emittedReceiver}; ${callbackInitializer} let ${valuesName} = ${receiverValues}; let ${resultName} = ${search};${release} ${resultName} }`;
}

// `find` and `filter` reuse the predicate staging but project their own result: find clones the one
// matching element into the Option carrier the observation gate proved, and filter clones every match
// into a fresh Vec. Both clone before a shared borrow is released.
function emitArraySearchPredicateCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>> &
    Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }>,
  member: RustArraySearchPredicateMember,
  context: EmitContext,
): string {
  const callback = expression.arguments[0];
  const signature = callback ? getRustArrayPredicateCallbackSignatureRust(callback, context) : undefined;
  if (!callback || !signature || signature.parameters.length > 2) {
    return emissionError(context, `array.${member} emission requires one statically known fixed predicate`);
  }
  const receiverName = getGeneratedTargetNameRust(`array_${member}_receiver`, context);
  const callbackName = getGeneratedTargetNameRust(`array_${member}_callback`, context);
  const valuesName = getGeneratedTargetNameRust(`array_${member}_values`, context);
  const resultName = getGeneratedTargetNameRust(`array_${member}_result`, context);
  const indexName = getGeneratedTargetNameRust(`array_${member}_index`, context);
  const elementName = getGeneratedTargetNameRust(`array_${member}_element`, context);
  const sharedBinding = getRustSharedArrayBindingRust(expression.callee.object, context);
  const emittedReceiver = sharedBinding
    ? `&${getBindingTargetNameRust(sharedBinding, context)}`
    : `&${emitExpression(expression.callee.object, context)}`;
  const receiverValues = sharedBinding ? `${receiverName}.borrow()` : receiverName;
  const arguments_ = [
    ...(signature.parameters.length >= 1 ? [`${elementName}.clone()`] : []),
    ...(signature.parameters.length === 2 ? [`${indexName} as f64`] : []),
  ];
  const callbackInitializer =
    callback.kind === 'function'
      ? `let mut ${callbackName} = ${emitExpression(callback, context)};`
      : `let ${callbackName} = &${emitExpression(callback, context)};`;
  // Iterator::find and Iterator::filter hand their predicate a reference to the enumerated tuple, so a
  // plain tuple pattern would bind `&usize` and `&&T` through match ergonomics and the callback would
  // receive references. The explicit `&(...)` pattern copies the index and leaves the element as `&T`,
  // which is what `element.clone()` and `index as f64` expect.
  const predicate = `|&(${indexName}, ${elementName})| (${callbackName})(${arguments_.join(', ')})`;
  const search =
    member === 'find'
      ? `${valuesName}.iter().enumerate().find(${predicate}).map(|(_index, element)| element.clone())`
      : `${valuesName}.iter().enumerate().filter(${predicate}).map(|(_index, element)| element.clone()).collect::<Vec<_>>()`;
  const release = sharedBinding ? ` drop(${valuesName});` : '';
  return `{ let ${receiverName} = ${emittedReceiver}; ${callbackInitializer} let ${valuesName} = ${receiverValues}; let ${resultName} = ${search};${release} ${resultName} }`;
}

// `map` collects each callback result into a fresh Vec; `forEach` evaluates the callback for every
// element and discards only a return the planning pass proved representable. Both share the staging and
// release a shared borrow before either alias is reused.
function emitArrayTransformCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>> &
    Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }>,
  member: RustArrayTransformMember,
  context: EmitContext,
): string {
  const callback = expression.arguments[0];
  const signature = callback ? getRustArrayPredicateCallbackSignatureRust(callback, context) : undefined;
  if (!callback || !signature || signature.parameters.length > 2) {
    return emissionError(context, `array.${member} emission requires one statically known fixed callback`);
  }
  const prefix = member === 'map' ? 'array_map' : member === 'flatMap' ? 'array_flat_map' : 'array_for_each';
  const receiverName = getGeneratedTargetNameRust(`${prefix}_receiver`, context);
  const callbackName = getGeneratedTargetNameRust(`${prefix}_callback`, context);
  const valuesName = getGeneratedTargetNameRust(`${prefix}_values`, context);
  const resultName = getGeneratedTargetNameRust(`${prefix}_result`, context);
  const indexName = getGeneratedTargetNameRust(`${prefix}_index`, context);
  const elementName = getGeneratedTargetNameRust(`${prefix}_element`, context);
  const sharedBinding = getRustSharedArrayBindingRust(expression.callee.object, context);
  const emittedReceiver = sharedBinding
    ? `&${getBindingTargetNameRust(sharedBinding, context)}`
    : `&${emitExpression(expression.callee.object, context)}`;
  const receiverValues = sharedBinding ? `${receiverName}.borrow()` : receiverName;
  const arguments_ = [
    ...(signature.parameters.length >= 1 ? [`${elementName}.clone()`] : []),
    ...(signature.parameters.length === 2 ? [`${indexName} as f64`] : []),
  ];
  // flatMap's staged closure is bound before the iterator call that constrains it, so an inline
  // callback body that only clones its parameter (a String identity flatten) leaves the parameter type
  // unconstrained (E0282). Annotate the inline closure's parameters from the proven callback carriers,
  // the same way the sort comparator is annotated. Referenced callbacks already carry their own types.
  const callbackInitializer =
    callback.kind === 'function'
      ? `let mut ${callbackName} = ${
          member === 'flatMap' ? emitFunctionExpressionRust(callback, context, true) : emitExpression(callback, context)
        };`
      : `let ${callbackName} = &${emitExpression(callback, context)};`;
  const transformed =
    member === 'map'
      ? `${valuesName}.iter().enumerate().map(|(${indexName}, ${elementName})| (${callbackName})(${arguments_.join(', ')})).collect::<Vec<_>>()`
      : member === 'flatMap'
        ? `${valuesName}.iter().enumerate().flat_map(|(${indexName}, ${elementName})| (${callbackName})(${arguments_.join(', ')})).collect::<Vec<_>>()`
        : `${valuesName}.iter().enumerate().for_each(|(${indexName}, ${elementName})| { let _ = (${callbackName})(${arguments_.join(', ')}); })`;
  const release = sharedBinding ? ` drop(${valuesName});` : '';
  return `{ let ${receiverName} = ${emittedReceiver}; ${callbackInitializer} let ${valuesName} = ${receiverValues}; let ${resultName} = ${transformed};${release} ${resultName} }`;
}

// `reduce` keeps the source reusable by iterating over a reference. Its explicit initial value is
// evaluated after the callback but before a shared borrow starts, matching source operand order.
function emitArrayReduceCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>> &
    Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }>,
  context: EmitContext,
): string {
  const callback = expression.arguments[0];
  const initial = expression.arguments[1];
  const signature = callback ? getRustArrayPredicateCallbackSignatureRust(callback, context) : undefined;
  if (!callback || !initial || !signature || signature.parameters.length > 3) {
    return emissionError(
      context,
      'array.reduce emission requires one statically known fixed callback and an initial value',
    );
  }
  const receiverName = getGeneratedTargetNameRust('array_reduce_receiver', context);
  const callbackName = getGeneratedTargetNameRust('array_reduce_callback', context);
  const initialName = getGeneratedTargetNameRust('array_reduce_initial', context);
  const valuesName = getGeneratedTargetNameRust('array_reduce_values', context);
  const resultName = getGeneratedTargetNameRust('array_reduce_result', context);
  const accumulatorName = getGeneratedTargetNameRust('array_reduce_accumulator', context);
  const indexName = getGeneratedTargetNameRust('array_reduce_index', context);
  const elementName = getGeneratedTargetNameRust('array_reduce_element', context);
  const sharedBinding = getRustSharedArrayBindingRust(expression.callee.object, context);
  const emittedReceiver = sharedBinding
    ? `&${getBindingTargetNameRust(sharedBinding, context)}`
    : `&${emitExpression(expression.callee.object, context)}`;
  const receiverValues = sharedBinding ? `${receiverName}.borrow()` : receiverName;
  const arguments_ = [
    ...(signature.parameters.length >= 1 ? [accumulatorName] : []),
    ...(signature.parameters.length >= 2 ? [`${elementName}.clone()`] : []),
    ...(signature.parameters.length === 3 ? [`${indexName} as f64`] : []),
  ];
  const callbackInitializer =
    callback.kind === 'function'
      ? `let mut ${callbackName} = ${emitExpression(callback, context)};`
      : `let ${callbackName} = &${emitExpression(callback, context)};`;
  const folded = `${valuesName}.iter().enumerate().fold(${initialName}, |${accumulatorName}, (${indexName}, ${elementName})| (${callbackName})(${arguments_.join(', ')}))`;
  const release = sharedBinding ? ` drop(${valuesName});` : '';
  return `{ let ${receiverName} = ${emittedReceiver}; ${callbackInitializer} let ${initialName} = ${emitExpression(initial, context)}; let ${valuesName} = ${receiverValues}; let ${resultName} = ${folded};${release} ${resultName} }`;
}

// JavaScript's join renders exact dense strings with their own spelling and booleans as
// "true"/"false"; number elements need the JavaScript number-to-string contract, so planning refuses
// them. String receivers keep the exact prior emission (explicit separator included) and gain the
// default comma; boolean receivers stage the receiver, then the separator, then map and join.
function emitArrayJoinCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>> &
    Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }>,
  context: EmitContext,
): string {
  const separator = expression.arguments[0];
  if (expression.arguments.length > 1 || separator?.kind === 'spread') {
    return emissionError(context, 'array.join emission requires at most one fixed separator');
  }
  const receiverType = inferIrExpressionTypeRust(expression.callee.object, context);
  const receiver = receiverType ? resolveIrTypeAliasValueRust(receiverType, context, new Set()) : undefined;
  const domain =
    receiver?.kind === 'array' ? getRustDensePrimitiveArrayCarrierDomainRust(receiver.element, context) : undefined;
  const emittedSeparator = separator ? emitBorrowedTextRust(separator, context) : '","';
  if (domain === 'boolean') {
    const receiverName = getGeneratedTargetNameRust('array_join_receiver', context);
    const separatorName = getGeneratedTargetNameRust('array_join_separator', context);
    const resultName = getGeneratedTargetNameRust('array_join_result', context);
    const sharedBinding = getRustSharedArrayBindingRust(expression.callee.object, context);
    const receiverInitializer = sharedBinding
      ? `${getBindingTargetNameRust(sharedBinding, context)}.borrow()`
      : `&${emitExpression(expression.callee.object, context)}`;
    return `{ let ${receiverName} = ${receiverInitializer}; let ${separatorName} = ${emittedSeparator}; let ${resultName} = ${receiverName}.iter().map(|value| if *value { "true" } else { "false" }).collect::<Vec<_>>().join(${separatorName}); ${resultName} }`;
  }
  return `${emitSharedReferenceReceiverRust(expression.callee.object, false, context)}.join(${emittedSeparator})`;
}

function emitArrayCopyWithinCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>> &
    Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }>,
  context: EmitContext,
): string {
  const [target, start, end] = expression.arguments;
  if (!target || expression.arguments.length < 1 || expression.arguments.length > 3) {
    return emissionError(context, 'array.copyWithin emission requires a target and at most start and end bounds');
  }
  const observed = context.arrayCopyWithinObservedCalls.has(expression);
  const receiverName = getGeneratedTargetNameRust('array_copy_within_receiver', context);
  const targetName = getGeneratedTargetNameRust('array_copy_within_target', context);
  const startName = getGeneratedTargetNameRust('array_copy_within_start', context);
  const endName = getGeneratedTargetNameRust('array_copy_within_end', context);
  const valuesName = getGeneratedTargetNameRust('array_copy_within_values', context);
  const lengthName = getGeneratedTargetNameRust('array_copy_within_length', context);
  const normalizedTargetName = getGeneratedTargetNameRust('array_copy_within_normalized_target', context);
  const targetIndexName = getGeneratedTargetNameRust('array_copy_within_target_index', context);
  const normalizedStartName = getGeneratedTargetNameRust('array_copy_within_normalized_start', context);
  const startIndexName = getGeneratedTargetNameRust('array_copy_within_start_index', context);
  const normalizedEndName = getGeneratedTargetNameRust('array_copy_within_normalized_end', context);
  const endIndexName = getGeneratedTargetNameRust('array_copy_within_end_index', context);
  const countName = getGeneratedTargetNameRust('array_copy_within_count', context);
  const copiedName = getGeneratedTargetNameRust('array_copy_within_copied', context);
  const offsetName = getGeneratedTargetNameRust('array_copy_within_offset', context);
  const valueName = getGeneratedTargetNameRust('array_copy_within_value', context);
  const sharedBinding = getRustSharedArrayBindingRust(expression.callee.object, context);
  const receiver = emitExpression(expression.callee.object, context);
  if (sharedBinding) context.needsRcImport.add('Rc');
  const receiverInitializer = sharedBinding
    ? `Rc::clone(&${getBindingTargetNameRust(sharedBinding, context)})`
    : observed
      ? receiver
      : emitLentOperandRust(expression.callee.object, context);
  const valuesInitializer = sharedBinding
    ? `${receiverName}.borrow_mut()`
    : observed
      ? `&mut ${receiverName}`
      : receiverName;
  const relativeIndex = (normalized: string) =>
    `if ${normalized} < 0.0 { ${lengthName} - ((-${normalized}).min(${lengthName} as f64) as usize) } else { ${normalized}.min(${lengthName} as f64) as usize }`;
  const initializers = [
    `let ${observed && !sharedBinding ? 'mut ' : ''}${receiverName} = ${receiverInitializer};`,
    `let ${targetName}: f64 = ${emitExpression(target, context)};`,
    `let ${startName}: f64 = ${start ? emitExpression(start, context) : '0.0'};`,
    `let ${endName}: f64 = ${end ? emitExpression(end, context) : 'f64::INFINITY'};`,
    `let ${sharedBinding ? 'mut ' : ''}${valuesName} = ${valuesInitializer};`,
    `let ${lengthName} = ${valuesName}.len();`,
    `let ${normalizedTargetName} = if ${targetName}.is_nan() { 0.0 } else { ${targetName}.trunc() };`,
    `let ${targetIndexName}: usize = ${relativeIndex(normalizedTargetName)};`,
    `let ${normalizedStartName} = if ${startName}.is_nan() { 0.0 } else { ${startName}.trunc() };`,
    `let ${startIndexName}: usize = ${relativeIndex(normalizedStartName)};`,
    `let ${normalizedEndName} = if ${endName}.is_nan() { 0.0 } else { ${endName}.trunc() };`,
    `let ${endIndexName}: usize = ${relativeIndex(normalizedEndName)};`,
    `let ${countName} = ${endIndexName}.saturating_sub(${startIndexName}).min(${lengthName} - ${targetIndexName});`,
    `let ${copiedName} = ${valuesName}[${startIndexName}..${startIndexName} + ${countName}].to_vec();`,
  ];
  const mutation = `for (${offsetName}, ${valueName}) in ${copiedName}.into_iter().enumerate() { ${valuesName}[${targetIndexName} + ${offsetName}] = ${valueName}; }`;
  const result = observed ? receiverName : '()';
  const releaseSharedBorrow = sharedBinding && observed ? [`drop(${valuesName});`] : [];
  return `{ ${[...initializers, mutation, ...releaseSharedBorrow, result].join(' ')} }`;
}

function emitArrayFillCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>> &
    Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }>,
  context: EmitContext,
): string {
  const [value, start, end] = expression.arguments;
  if (!value || expression.arguments.length < 1 || expression.arguments.length > 3) {
    return emissionError(context, 'array.fill emission requires a value and at most start and end bounds');
  }
  const observed = context.arrayFillObservedCalls.has(expression);
  const receiverName = getGeneratedTargetNameRust('array_fill_receiver', context);
  const valueName = getGeneratedTargetNameRust('array_fill_value', context);
  const startName = getGeneratedTargetNameRust('array_fill_start', context);
  const endName = getGeneratedTargetNameRust('array_fill_end', context);
  const valuesName = getGeneratedTargetNameRust('array_fill_values', context);
  const lengthName = getGeneratedTargetNameRust('array_fill_length', context);
  const normalizedStartName = getGeneratedTargetNameRust('array_fill_normalized_start', context);
  const startIndexName = getGeneratedTargetNameRust('array_fill_start_index', context);
  const normalizedEndName = getGeneratedTargetNameRust('array_fill_normalized_end', context);
  const endIndexName = getGeneratedTargetNameRust('array_fill_end_index', context);
  const indexName = getGeneratedTargetNameRust('array_fill_index', context);
  const sharedBinding = getRustSharedArrayBindingRust(expression.callee.object, context);
  const receiver = emitExpression(expression.callee.object, context);
  if (sharedBinding) context.needsRcImport.add('Rc');
  const receiverInitializer = sharedBinding
    ? `Rc::clone(&${getBindingTargetNameRust(sharedBinding, context)})`
    : observed
      ? receiver
      : emitLentOperandRust(expression.callee.object, context);
  const valuesInitializer = sharedBinding
    ? `${receiverName}.borrow_mut()`
    : observed
      ? `&mut ${receiverName}`
      : receiverName;
  const relativeIndex = (normalized: string) =>
    `if ${normalized} < 0.0 { ${lengthName} - ((-${normalized}).min(${lengthName} as f64) as usize) } else { ${normalized}.min(${lengthName} as f64) as usize }`;
  const initializers = [
    `let ${observed && !sharedBinding ? 'mut ' : ''}${receiverName} = ${receiverInitializer};`,
    `let ${valueName} = &${emitExpression(value, context)};`,
    `let ${startName}: f64 = ${start ? emitExpression(start, context) : '0.0'};`,
    `let ${endName}: f64 = ${end ? emitExpression(end, context) : 'f64::INFINITY'};`,
    `let ${sharedBinding ? 'mut ' : ''}${valuesName} = ${valuesInitializer};`,
    `let ${lengthName} = ${valuesName}.len();`,
    `let ${normalizedStartName} = if ${startName}.is_nan() { 0.0 } else { ${startName}.trunc() };`,
    `let ${startIndexName}: usize = ${relativeIndex(normalizedStartName)};`,
    `let ${normalizedEndName} = if ${endName}.is_nan() { 0.0 } else { ${endName}.trunc() };`,
    `let ${endIndexName}: usize = ${relativeIndex(normalizedEndName)};`,
  ];
  const mutation = `for ${indexName} in ${startIndexName}..${endIndexName}.max(${startIndexName}) { ${valuesName}[${indexName}] = (*${valueName}).clone(); }`;
  const result = observed ? receiverName : '()';
  const releaseSharedBorrow = sharedBinding && observed ? [`drop(${valuesName});`] : [];
  return `{ ${[...initializers, mutation, ...releaseSharedBorrow, result].join(' ')} }`;
}

function emitArrayConcatCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>> &
    Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }>,
  context: EmitContext,
): string {
  const receiverName = getGeneratedTargetNameRust('array_concat_receiver', context);
  const resultName = getGeneratedTargetNameRust('array_concat_values', context);
  const receiverShared = getRustSharedArrayBindingRust(expression.callee.object, context);
  const receiver = receiverShared
    ? `&${getBindingTargetNameRust(receiverShared, context)}`
    : `&${emitExpression(expression.callee.object, context)}`;
  const arguments_ = expression.arguments.map((argument, position) => {
    const name = getGeneratedTargetNameRust(
      expression.arguments.length === 1 ? 'array_concat_argument' : `array_concat_argument${String(position)}`,
      context,
    );
    const sharedBinding = getRustSharedArrayBindingRust(argument, context);
    return {
      initializer: sharedBinding
        ? `&${getBindingTargetNameRust(sharedBinding, context)}`
        : `&${emitExpression(argument, context)}`,
      name,
      values: sharedBinding ? `${name}.borrow().iter().cloned()` : `${name}.iter().cloned()`,
    };
  });
  const clonedReceiver = receiverShared ? `${receiverName}.borrow().clone()` : `(*${receiverName}).clone()`;
  const initializers = [
    `let ${receiverName} = ${receiver};`,
    ...arguments_.map(({ initializer, name }) => `let ${name} = ${initializer};`),
    `let mut ${resultName} = ${clonedReceiver};`,
  ];
  const extensions = arguments_.map(({ values }) => `${resultName}.extend(${values});`);
  // Every source expression is materialized before the receiver is cloned, matching JavaScript's
  // receiver-first, argument-left-to-right call evaluation. Each immutable RefCell borrow ends at
  // its clone or extend statement, so self and repeated shared aliases never overlap borrows.
  return `{ ${[...initializers, ...extensions, resultName].join(' ')} }`;
}

interface RustOwnedSharedArrayTupleConcatPlan {
  readonly binding: Readonly<IrBindingIdentity>;
  readonly carrier: Readonly<RustOwnedSharedArrayTupleCarrierPlan>;
}

function getRustOwnedSharedArrayTupleConcatPlanRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>>,
  context: EmitContext,
): Readonly<RustOwnedSharedArrayTupleConcatPlan> | undefined {
  const bindingId = getRustArrayConcatTuplePackBindingIdRust(expression);
  if (!bindingId) return undefined;
  const tuplePlan = context.sharedArrayTupleBindings.get(bindingId);
  const argument = expression.arguments[0];
  if (
    !tuplePlan ||
    argument?.kind !== 'spread' ||
    argument.expression.kind !== 'identifier' ||
    argument.expression.reference.kind !== 'binding'
  ) {
    return undefined;
  }
  const binding = argument.expression.reference.binding;
  return {
    binding,
    carrier: assertRustOwnedSharedArrayTupleCarrierPlanRust(binding, tuplePlan, context),
  };
}

function emitOwnedSharedArrayTupleConcatCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>>,
  selected: Readonly<RustOwnedSharedArrayTupleConcatPlan>,
  context: EmitContext,
): string {
  if (!isArrayConcatCallRust(expression)) {
    return emissionError(
      context,
      'owned shared array tuple spread lost its direct array.concat target',
      'rust-array-concat-invocation-unrepresented',
      'target-runtime',
    );
  }
  const signature = expression.semantics.signature;
  if (
    context.nativeAsyncFunction ||
    expression.optional ||
    expression.semantics.optionalChain !== undefined ||
    expression.callee.optional ||
    expression.callee.optionalChain !== undefined ||
    expression.typeArguments.length !== 0 ||
    expression.arguments.length !== 1 ||
    expression.semantics.defaultParameters !== undefined ||
    expression.semantics.optionalParameters !== undefined ||
    expression.semantics.overloadImplementation !== undefined ||
    !signature ||
    signature.parameterCount !== 1 ||
    signature.restParameter !== 0 ||
    signature.providedArgumentCount !== 'dynamic'
  ) {
    return emissionError(
      context,
      'array.concat tuple pack requires a direct non-optional fixed tuple-spread invocation',
      'rust-array-concat-invocation-unrepresented',
      'target-runtime',
    );
  }

  const receiverType = inferIrExpressionTypeRust(expression.callee.object, context);
  const receiver = receiverType ? resolveIrTypeAliasValueRust(receiverType, context, new Set()) : undefined;
  if (receiver?.kind !== 'array') {
    return emissionError(
      context,
      'array.concat tuple pack receiver requires an exact dense array carrier',
      'rust-array-concat-argument-carrier-unrepresented',
      'target-runtime',
    );
  }
  if (!isRustArrayConcatElementCarrierRust(receiver.element, context)) {
    return emissionError(
      context,
      'array.concat tuple pack elements require primitive boolean, number, or string value carriers',
      'rust-array-concat-element-carrier-unrepresented',
      'target-runtime',
    );
  }
  for (const [position, componentType] of selected.carrier.componentTypes.entries()) {
    const component = resolveIrTypeAliasValueRust(componentType, context, new Set());
    if (component.kind !== 'array') {
      return emissionError(
        context,
        `array.concat tuple pack component ${String(position)} requires an exact dense array carrier`,
        'rust-array-concat-argument-carrier-unrepresented',
        'target-runtime',
      );
    }
    if (!isRustArrayConcatElementCarrierRust(component.element, context)) {
      return emissionError(
        context,
        `array.concat tuple pack component ${String(position)} elements require primitive boolean, number, or string value carriers`,
        'rust-array-concat-element-carrier-unrepresented',
        'target-runtime',
      );
    }
    if (!isRustArrayConcatArgumentCarrierRust(receiver.element, component.element, context)) {
      return emissionError(
        context,
        `array.concat tuple pack component ${String(position)} does not have the exact Rust element carrier of the receiver`,
        'rust-array-concat-argument-carrier-unrepresented',
        'target-runtime',
      );
    }
  }
  if (!receiverType || !isRustArrayConcatResultCarrierRust(receiverType, expression.semantics.resultType, context)) {
    return emissionError(
      context,
      'array.concat tuple pack result does not have the exact mutable Rust Vec element carrier of the receiver',
      'rust-array-concat-result-carrier-unrepresented',
      'target-runtime',
    );
  }

  context.needsRcImport.add('Rc');
  const receiverName = getGeneratedTargetNameRust('array_concat_receiver', context);
  const resultName = getGeneratedTargetNameRust('array_concat_values', context);
  const tupleName = getBindingTargetNameRust(selected.binding, context);
  const receiverShared = getRustSharedArrayBindingRust(expression.callee.object, context);
  const receiverOwnedReturn = isIrOwnedSharedArrayReturnCallRust(expression.callee.object, context);
  const receiverInitializer = receiverShared
    ? `Rc::clone(&${getBindingTargetNameRust(receiverShared, context)})`
    : receiverOwnedReturn
      ? emitExpression(expression.callee.object, context)
      : `&${emitExpression(expression.callee.object, context)}`;
  const componentNames = selected.carrier.componentTypes.map((_component, position) =>
    getGeneratedTargetNameRust(`array_concat_argument${String(position)}`, context),
  );
  const handleInitializers = [
    `let ${receiverName} = ${receiverInitializer};`,
    ...componentNames.map((name, position) => `let ${name} = Rc::clone(&${tupleName}.${String(position)});`),
  ];
  const clonedReceiver =
    receiverShared || receiverOwnedReturn ? `${receiverName}.borrow().clone()` : `(*${receiverName}).clone()`;
  const resultInitializer = `let mut ${resultName} = ${clonedReceiver};`;
  const extensions = componentNames.map((name) => `${resultName}.extend(${name}.borrow().iter().cloned());`);
  // Capture every Rc handle in source order before opening any RefCell borrow. The receiver clone and
  // sequential extensions then observe mutations through every alias while still producing a fresh Vec.
  return `{ ${[...handleInitializers, resultInitializer, ...extensions, resultName].join(' ')} }`;
}

function emitArrayReverseCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>> &
    Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }>,
  context: EmitContext,
): string {
  const observed = context.arrayReverseObservedCalls.has(expression);
  const sharedBinding = getRustSharedArrayBindingRust(expression.callee.object, context);
  if (sharedBinding) {
    const receiver = getBindingTargetNameRust(sharedBinding, context);
    if (!observed) return `${receiver}.borrow_mut().reverse()`;
    context.needsRcImport.add('Rc');
    const receiverName = getGeneratedTargetNameRust('array_reverse_values', context);
    return `{ let ${receiverName} = Rc::clone(&${receiver}); ${receiverName}.borrow_mut().reverse(); ${receiverName} }`;
  }
  const receiver = emitExpression(expression.callee.object, context);
  if (!observed) return `${receiver}.reverse()`;
  const receiverName = getGeneratedTargetNameRust('array_reverse_values', context);
  return `{ let mut ${receiverName} = ${receiver}; ${receiverName}.reverse(); ${receiverName} }`;
}

function emitArraySortCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>> &
    Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }>,
  context: EmitContext,
): string {
  const comparator = expression.arguments[0];
  if (!comparator || expression.arguments.length !== 1) {
    return emissionError(context, 'array.sort emission requires exactly one comparator');
  }
  const observed = context.arraySortObservedCalls.has(expression);
  const receiverName = getGeneratedTargetNameRust('array_sort_receiver', context);
  const comparatorName = getGeneratedTargetNameRust('array_sort_comparator', context);
  const valuesName = getGeneratedTargetNameRust('array_sort_values', context);
  const leftName = getGeneratedTargetNameRust('array_sort_left', context);
  const rightName = getGeneratedTargetNameRust('array_sort_right', context);
  const comparisonName = getGeneratedTargetNameRust('array_sort_comparison', context);
  const sharedBinding = getRustSharedArrayBindingRust(expression.callee.object, context);
  const receiver = emitExpression(expression.callee.object, context);
  if (sharedBinding) context.needsRcImport.add('Rc');
  const receiverInitializer = sharedBinding
    ? `Rc::clone(&${getBindingTargetNameRust(sharedBinding, context)})`
    : observed
      ? receiver
      : emitLentOperandRust(expression.callee.object, context);
  const valuesInitializer = sharedBinding
    ? `${receiverName}.borrow_mut()`
    : observed
      ? `&mut ${receiverName}`
      : receiverName;
  const emittedComparator =
    comparator.kind === 'function'
      ? emitFunctionExpressionRust(comparator, context, true)
      : emitExpression(comparator, context);
  const ordering = `let ${comparisonName}: f64 = (${comparatorName})((*${leftName}).clone(), (*${rightName}).clone()); if ${comparisonName}.is_nan() || ${comparisonName} == 0.0 { std::cmp::Ordering::Equal } else if ${comparisonName} < 0.0 { std::cmp::Ordering::Less } else { std::cmp::Ordering::Greater }`;
  const initializers = [
    `let ${observed && !sharedBinding ? 'mut ' : ''}${receiverName} = ${receiverInitializer};`,
    `let ${comparatorName} = &${normalizeSourceTextGrouping(emittedComparator)};`,
    `let ${sharedBinding ? 'mut ' : ''}${valuesName} = ${valuesInitializer};`,
  ];
  const mutation = `${valuesName}.sort_by(|${leftName}, ${rightName}| { ${ordering} });`;
  const releaseSharedBorrow = sharedBinding && observed ? [`drop(${valuesName});`] : [];
  const result = observed ? receiverName : '()';
  return `{ ${[...initializers, mutation, ...releaseSharedBorrow, result].join(' ')} }`;
}

function emitArraySliceCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>> &
    Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }>,
  context: EmitContext,
): string {
  const [start, end] = expression.arguments;
  const startName = getGeneratedTargetNameRust('array_slice_start', context);
  const endName = getGeneratedTargetNameRust('array_slice_end', context);
  const receiverName = getGeneratedTargetNameRust('array_slice_values', context);
  const lengthName = getGeneratedTargetNameRust('array_slice_length', context);
  const normalizedStartName = getGeneratedTargetNameRust('array_slice_normalized_start', context);
  const startIndexName = getGeneratedTargetNameRust('array_slice_start_index', context);
  const normalizedEndName = getGeneratedTargetNameRust('array_slice_normalized_end', context);
  const endIndexName = getGeneratedTargetNameRust('array_slice_end_index', context);
  const sharedBinding = getRustSharedArrayBindingRust(expression.callee.object, context);
  const receiver = sharedBinding
    ? `${getBindingTargetNameRust(sharedBinding, context)}.borrow()`
    : `&${emitExpression(expression.callee.object, context)}`;
  if (!start) return `{ let ${receiverName} = ${receiver}; (*${receiverName}).clone() }`;
  const initializers = [
    `let ${startName}: f64 = ${emitExpression(start, context)};`,
    ...(end ? [`let ${endName}: f64 = ${emitExpression(end, context)};`] : []),
  ];
  const normalizedStart = `if ${startName}.is_nan() { 0.0 } else { ${startName}.trunc() }`;
  const normalizedEnd = end ? `if ${endName}.is_nan() { 0.0 } else { ${endName}.trunc() }` : `${lengthName} as f64`;
  const relativeIndex = (normalized: string) =>
    `if ${normalized} < 0.0 { ${lengthName} - ((-${normalized}).min(${lengthName} as f64) as usize) } else { ${normalized}.min(${lengthName} as f64) as usize }`;
  // JavaScript evaluates start and end from left to right before it reads the receiver's length.
  // Keeping both operands outside the borrow makes each one single-shot for local and shared arrays.
  return `{ ${[
    ...initializers,
    `let ${receiverName} = ${receiver};`,
    `let ${lengthName} = ${receiverName}.len();`,
    `let ${normalizedStartName} = ${normalizedStart};`,
    `let ${startIndexName}: usize = ${relativeIndex(normalizedStartName)};`,
    `let ${normalizedEndName} = ${normalizedEnd};`,
    `let ${endIndexName}: usize = ${relativeIndex(normalizedEndName)};`,
    `${receiverName}[${startIndexName}..${endIndexName}.max(${startIndexName})].to_vec()`,
  ].join(' ')} }`;
}

function emitArraySpliceCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>> &
    Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }>,
  context: EmitContext,
): string {
  const [start, deleteCount, ...inserted] = expression.arguments;
  if (!start || expression.arguments.length < 1) {
    return emissionError(context, 'array.splice emission requires start');
  }
  const startName = getGeneratedTargetNameRust('array_splice_start', context);
  const deleteName = getGeneratedTargetNameRust('array_splice_delete_count', context);
  const insertedItems = inserted.map((item, index) => ({
    emitted: emitOwnedOperandRust(item, context),
    name: getGeneratedTargetNameRust(`array_splice_item${String(index)}`, context),
  }));
  const receiverName = getGeneratedTargetNameRust('array_splice_values', context);
  const lengthName = getGeneratedTargetNameRust('array_splice_length', context);
  const normalizedStartName = getGeneratedTargetNameRust('array_splice_normalized_start', context);
  const startIndexName = getGeneratedTargetNameRust('array_splice_start_index', context);
  const availableName = getGeneratedTargetNameRust('array_splice_available', context);
  const normalizedDeleteName = getGeneratedTargetNameRust('array_splice_normalized_delete_count', context);
  const actualDeleteName = getGeneratedTargetNameRust('array_splice_actual_delete_count', context);
  const endName = getGeneratedTargetNameRust('array_splice_end', context);
  const sharedBinding = getRustSharedArrayBindingRust(expression.callee.object, context);
  const borrowedParameter =
    expression.callee.object.kind === 'identifier' &&
    expression.callee.object.reference.kind === 'binding' &&
    context.referentMutatedParameterIds.has(expression.callee.object.reference.binding.id);
  const receiver = sharedBinding
    ? `${getBindingTargetNameRust(sharedBinding, context)}.borrow_mut()`
    : borrowedParameter
      ? `&mut *${emitExpression(expression.callee.object, context)}`
      : `&mut ${emitExpression(expression.callee.object, context)}`;
  const initializers = [
    `let ${startName}: f64 = ${emitExpression(start, context)};`,
    `let ${deleteName}: f64 = ${deleteCount ? emitExpression(deleteCount, context) : 'f64::INFINITY'};`,
    ...insertedItems.map(({ emitted, name }) => `let ${name} = ${emitted};`),
  ];
  // JavaScript evaluates every splice argument before it mutates the array. Materializing them before
  // the Rust receiver borrow preserves that order and keeps each insertion operand single-shot.
  const mutation =
    insertedItems.length === 0
      ? `${receiverName}.drain(${startIndexName}..${endName}).collect::<Vec<_>>()`
      : `${receiverName}.splice(${startIndexName}..${endName}, vec![${insertedItems.map(({ name }) => name).join(', ')}]).collect::<Vec<_>>()`;
  return `{ ${[...initializers, `let ${sharedBinding ? 'mut ' : ''}${receiverName} = ${receiver};`, `let ${lengthName} = ${receiverName}.len();`, `let ${normalizedStartName} = if ${startName}.is_nan() { 0.0 } else { ${startName}.trunc() };`, `let ${startIndexName}: usize = if ${normalizedStartName} < 0.0 { ${lengthName} - ((-${normalizedStartName}).min(${lengthName} as f64) as usize) } else { ${normalizedStartName}.min(${lengthName} as f64) as usize };`, `let ${availableName} = ${lengthName} - ${startIndexName};`, `let ${normalizedDeleteName} = if ${deleteName}.is_nan() { 0.0 } else { ${deleteName}.trunc() };`, `let ${actualDeleteName}: usize = if ${normalizedDeleteName} <= 0.0 { 0 } else { ${normalizedDeleteName}.min(${availableName} as f64) as usize };`, `let ${endName} = ${startIndexName} + ${actualDeleteName};`, mutation].join(' ')} }`;
}

function emitArrayShiftCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>> &
    Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }>,
  context: EmitContext,
): string {
  if (expression.arguments.length !== 0) {
    emissionError(
      context,
      'array.shift with arguments has no exact Rust invocation',
      'rust-array-shift-invocation-unrepresented',
      'target-runtime',
    );
  }
  if (!isRustSingleUndefinedOptionCarrier(expression.semantics.resultType)) {
    emissionError(
      context,
      'array.shift result does not have one undefined-admitting Rust Option carrier',
      'rust-array-shift-result-carrier-unrepresented',
      'target-runtime',
    );
  }
  const receiverName = getGeneratedTargetNameRust('shift_values', context);
  const sharedBinding = getRustSharedArrayBindingRust(expression.callee.object, context);
  const borrowedParameter =
    expression.callee.object.kind === 'identifier' &&
    expression.callee.object.reference.kind === 'binding' &&
    context.referentMutatedParameterIds.has(expression.callee.object.reference.binding.id);
  const receiver = sharedBinding
    ? `${getBindingTargetNameRust(sharedBinding, context)}.borrow_mut()`
    : borrowedParameter
      ? emitExpression(expression.callee.object, context)
      : `&mut ${emitExpression(expression.callee.object, context)}`;
  return `{ let ${sharedBinding ? 'mut ' : ''}${receiverName} = ${receiver}; if ${receiverName}.is_empty() { None } else { Some(${receiverName}.remove(0)) } }`;
}

function emitOptionalElementExpressionRust(
  expression: Readonly<Extract<IrExpression, { kind: 'element' }>>,
  context: EmitContext,
): string {
  const semantics = expression.semantics.optionalChain;
  if (!semantics) emissionError(context, 'optional element access lacks neutral optional-chain evidence');
  if (semantics.receiverNullish === 'excluded') {
    return emitRequiredElementExpressionRust(expression, context);
  }
  const receiver = getIrTypeOptionalPayloadRust(semantics.receiverType, 'optional element receiver', context);
  const object = emitExpression(expression.object, context);
  const value = 'optional_chain_value';
  if (receiver.kind === 'tuple') {
    const index = getElementAccessTupleIndexRust(expression, context);
    const operation = receiver.elements[index]?.optional ? 'and_then' : 'map';
    return `${object}.as_ref().${operation}(|${value}| ${value}.${String(index)}.clone())`;
  }
  if (receiver.kind === 'array') {
    return `${object}.as_ref().and_then(|${value}| ${emitGuardedArrayGetRust(value, expression.index, context)})`;
  }
  emissionError(context, 'optional element access requires array or fixed-tuple receiver evidence');
}

function emitOptionalPropertyExpressionRust(
  expression: Readonly<Extract<IrExpression, { kind: 'property' }>>,
  context: EmitContext,
): string {
  const semantics = expression.optionalChain;
  if (!semantics) emissionError(context, 'optional property access lacks neutral optional-chain evidence');
  const object = emitExpression(expression.object, context);
  const property = safeRustValueName(expression.name);
  // A source length is a value projection, not a field: the ambient table decides how the target
  // spells it, and the optional chain maps that same projection over the receiver's absence.
  const ambientProjection = createRustOptionalAmbientPropertyProjectionRust(expression);
  const projectedValue = (receiver: string): string =>
    ambientProjection ? ambientProjection(receiver) : `${receiver}.${property}.clone()`;
  if (semantics.receiverNullish === 'excluded') {
    // An ordinary element receiver carries the absence the chain short-circuits on, so the read maps
    // over its Option. A direct element place keeps the copy read the source wrote.
    if (isIrExpressionOptionShapedRust(expression.object, context)) {
      const operation = isNullableType(semantics.valueType) ? 'and_then' : 'map';
      return `${object}.as_ref().${operation}(|optional_chain_value| ${projectedValue('optional_chain_value')})`;
    }
    if (ambientProjection) return ambientProjection(object);
    // Indexing yields a place the caller does not own, so the field read out of it is a copy.
    const owned = expression.object.kind === 'element' ? '.clone()' : '';
    return `${object}${isAmbientIdentifier(expression.object) ? '::' : '.'}${property}${owned}`;
  }
  getIrTypeOptionalPayloadRust(semantics.receiverType, 'optional property receiver', context);
  const operation = isNullableType(semantics.valueType) ? 'and_then' : 'map';
  return `${object}.as_ref().${operation}(|optional_chain_value| ${projectedValue('optional_chain_value')})`;
}

function createRustOptionalAmbientPropertyProjectionRust(
  expression: Readonly<Extract<IrExpression, { kind: 'property' }>>,
): ((receiver: string) => string) | undefined {
  const binding = expression.member ? getCompilerRustAmbientMemberBinding(expression.member) : undefined;
  if (binding?.kind === 'countingMethod') {
    return (receiver) => `(${receiver}.${binding.targetName}() as f64)`;
  }
  if (binding?.kind === 'codeUnitLength') {
    return (receiver) => `(${receiver}.${binding.targetName}().count() as f64)`;
  }
  return undefined;
}

function emitRequiredElementExpressionRust(
  expression: Readonly<Extract<IrExpression, { kind: 'element' }>>,
  context: EmitContext,
): string {
  const closedSelection = emitClosedKeyElementSelectionRust(expression, context);
  if (closedSelection) return closedSelection;
  if (expression.semantics.receivers.includes('object')) {
    emissionError(
      context,
      'computed object access requires JavaScript property-key coercion lowering',
      'rust-computed-object-access-unsupported',
    );
  }
  if (expression.semantics.receivers.includes('tuple')) {
    const index = getElementAccessTupleIndexRust(expression, context);
    return `${emitExpression(expression.object, context)}.${String(index)}`;
  }
  if (hasOnlyOrdinaryArrayReceiverRust(expression)) {
    if (context.arrayElementOptionReads.has(expression)) return emitArrayElementOptionRust(expression, context);
    if (context.arrayElementProofKinds.has(expression)) {
      return `${emitSharedReferenceReceiverRust(expression.object, false, context)}[${emitIndexOperandRust(expression.index, context)}]`;
    }
    if (!context.arrayElementPlaces.has(expression)) {
      emissionError(
        context,
        'ordinary array element read can be absent, but this use has no Rust Option carrier',
        'rust-array-index-result-absence-unrepresented',
        'target-runtime',
      );
    }
  }
  assertRustElementReceiverIsNotUnionRust(expression, context);
  return `${emitExpression(expression.object, context)}[${emitExpression(expression.index, context)} as usize]`;
}

// Both closed-key reads and writes need the same proof that the receiver has represented record storage
// and that every finite key names a concrete member. Keeping that proof shared prevents the assignment
// lane from accepting a place that the read lane would reject.
function getClosedKeyElementSelectionsRust(
  expression: Readonly<Extract<IrExpression, { kind: 'element' }>>,
  context: EmitContext,
): readonly Readonly<{ key: string; property: IrObjectTypeProperty }>[] | undefined {
  const keys = expression.semantics.closedKeys;
  if (!keys) return undefined;

  let objectType = inferIrExpressionTypeRust(expression.object, context);
  if (
    objectType?.kind === 'union' &&
    'presence' in expression.object &&
    expression.object.presence === 'narrowedPresent'
  ) {
    const present = objectType.types.filter((member) => member.kind !== 'null' && member.kind !== 'undefined');
    if (present.length === 1) objectType = present[0];
  }
  const properties = objectType ? getIrObjectTypePropertiesRust(objectType, context) : undefined;
  if (!objectType || !properties) {
    emissionError(
      context,
      'closed-key element access requires represented Rust object storage',
      'rust-closed-key-selection-unsupported',
    );
  }

  const members = new Map(
    properties
      .filter((property) => !property.computedKey && !property.phantom)
      .map((property) => [property.name, property] as const),
  );
  const selections = keys.map((key) => ({ key, property: members.get(key) }));
  const absent = selections.find((selection) => !selection.property);
  if (absent) {
    emissionError(
      context,
      `closed key ${absent.key} is not a represented Rust object member`,
      'rust-closed-key-selection-unsupported',
    );
  }
  return selections as readonly Readonly<{ key: string; property: IrObjectTypeProperty }>[];
}

function getClosedKeyElementStorageTypeRust(property: Readonly<IrObjectTypeProperty>, context: EmitContext): string {
  const emitted = emitType(property.type, context);
  return property.optional ? `Option<${emitted}>` : emitted;
}

// Rust records have no string subscript, so select the represented field explicitly while evaluating
// the receiver and key once, in source order. Borrowing the receiver keeps the selection from moving a
// source binding; the selected field is cloned into the expression's owned result.
function emitClosedKeyElementSelectionRust(
  expression: Readonly<Extract<IrExpression, { kind: 'element' }>>,
  context: EmitContext,
): string | undefined {
  const selections = getClosedKeyElementSelectionsRust(expression, context);
  if (!selections) return undefined;

  const memberTypes = selections.map(({ property }) => getClosedKeyElementStorageTypeRust(property, context));
  const distinctTypes = [...new Set(memberTypes)];
  if (distinctTypes.length !== 1) {
    emissionError(
      context,
      `closed-key selection over ${String(distinctTypes.length)} member types requires one Rust representation`,
      'rust-closed-key-selection-unsupported',
    );
  }

  const receiver = getGeneratedTargetNameRust('selection_receiver', context);
  const selectionKey = getGeneratedTargetNameRust('selection_key', context);
  const branches = selections.map(
    ({ key, property }) => `${JSON.stringify(key)} => ${receiver}.${safeRustValueName(property.name)}.clone(),`,
  );
  return `{ let ${receiver} = &${emitExpression(expression.object, context)}; let ${selectionKey} = &${emitExpression(expression.index, context)}; match ${selectionKey}.as_str() { ${branches.join(' ')} _ => unreachable!("Flight finite-key selection reached no member"), } }`;
}

// An element write through a finite key is a dispatch, not an assignment to the read selection's
// result. The direct binding requirement is the place evidence: ownership analysis makes a local
// binding mutable or a parameter `&mut`, and each match arm then names one real field. A Copy value is
// evaluated once after the key and can both enter the selected field and remain the assignment result.
function emitClosedKeyElementWriteRust(
  expression: Readonly<Extract<IrExpression, { kind: 'assignment' }>>,
  context: EmitContext,
): string | undefined {
  if (expression.left.kind !== 'element' || !expression.left.semantics.closedKeys) {
    return undefined;
  }
  if (expression.operator !== '=') {
    emissionError(
      context,
      `closed-key write operator ${expression.operator} requires branchwise Rust read/modify/write lowering`,
      'rust-closed-key-write-operator-unrepresented',
    );
  }
  const selections = getClosedKeyElementSelectionsRust(expression.left, context)!;
  const distinctStorageTypes = [
    ...new Set(selections.map(({ property }) => getClosedKeyElementStorageTypeRust(property, context))),
  ];
  if (distinctStorageTypes.length !== 1) {
    emissionError(
      context,
      `closed-key selection over ${String(distinctStorageTypes.length)} member types requires one Rust representation`,
      'rust-closed-key-selection-unsupported',
    );
  }

  const receiver = expression.left.object;
  const binding =
    receiver.kind === 'identifier' && receiver.reference.kind === 'binding' ? receiver.reference : undefined;
  if (
    !binding ||
    (!context.referentMutatedBindingIds.has(binding.binding.id) &&
      !context.referentMutatedParameterIds.has(binding.binding.id)) ||
    context.cellWrappedBindingIds.has(binding.binding.id) ||
    context.refCellWrappedBindingIds.has(binding.binding.id) ||
    context.sharedArrayBindingIds.has(binding.binding.id) ||
    context.sharedClassBindingIds.has(binding.binding.id) ||
    context.sharedMapBindingIds.has(binding.binding.id) ||
    context.sharedSetBindingIds.has(binding.binding.id)
  ) {
    emissionError(
      context,
      'closed-key write requires one direct mutable Rust object binding; the finite key set identifies members but does not make this receiver an assignable place',
      'rust-closed-key-write-place-unrepresented',
    );
  }
  const readonly = selections.find(({ property }) => property.readonly);
  if (readonly) {
    emissionError(
      context,
      `closed-key write selects readonly member ${readonly.key}`,
      'rust-closed-key-write-place-unrepresented',
      'source-portability',
    );
  }

  const valueType = inferIrExpressionTypeRust(expression.right, context);
  if (!valueType || !isIrTypeCopyValueRust(valueType)) {
    emissionError(
      context,
      'closed-key write requires one Copy Rust value representation so the assigned value remains the assignment result',
      'rust-closed-key-write-value-unrepresented',
    );
  }
  const valueTarget = emitType(valueType, context);
  const selectionKey = getGeneratedTargetNameRust('selection_key', context);
  const assignmentValue = getGeneratedTargetNameRust('assignment_value', context);
  const assignments = selections.map(({ key, property }) => {
    const storageTarget = getClosedKeyElementStorageTypeRust(property, context);
    const fieldValue =
      valueTarget === storageTarget
        ? assignmentValue
        : storageTarget === `Option<${valueTarget}>`
          ? `Some(${assignmentValue})`
          : emissionError(
              context,
              `closed-key write value representation ${valueTarget} is not assignable to member ${key} storage ${storageTarget}`,
              'rust-closed-key-write-value-unrepresented',
            );
    return `${JSON.stringify(key)} => ${emitIdentifierReferenceRust(binding, context)}.${safeRustValueName(property.name)} = ${fieldValue},`;
  });
  return `{ let ${selectionKey} = ${normalizeSourceTextGrouping(emitExpression(expression.left.index, context))}.clone(); let ${assignmentValue} = ${emitOwnedOperandRust(expression.right, context)}; match ${selectionKey}.as_str() { ${assignments.join(' ')} _ => unreachable!("Flight finite-key write reached no member"), }; ${assignmentValue} }`;
}

function getIrTypeOptionalPayloadRust(type: Readonly<IrType>, subject: string, context: EmitContext): Readonly<IrType> {
  const resolved = resolveIrTypeAliasValueRust(type, context, new Set());
  if (resolved.kind !== 'union') emissionError(context, `${subject} requires one concrete Rust Option payload`);
  const concrete = resolved.types.filter((member) => member.kind !== 'null' && member.kind !== 'undefined');
  if (concrete.length !== 1) emissionError(context, `${subject} requires one concrete Rust Option payload`);
  return concrete[0]!;
}

function emitSharedClassCarrierTypeRust(
  type: Readonly<IrType>,
  representation: RustSharedClassRepresentation,
  context: EmitContext,
): string {
  const payload = getRustSharedClassPayloadTypeRust(type, representation, context);
  if (!getIrClassDeclarationLocationForTypeRust(payload, context)) {
    return emissionRuleError(
      context,
      'planned shared class carrier lacks one exact named class payload',
      'rust-reference-shared-class-type-unrepresented',
    );
  }
  const carrier = `Rc<RefCell<${emitType(payload, context)}>>`;
  return representation === 'shared-ref-cell-class' ? carrier : `Option<${carrier}>`;
}

function getRustSharedClassPayloadTypeRust(
  type: Readonly<IrType>,
  representation: RustSharedClassRepresentation,
  context: EmitContext,
): Readonly<IrType> {
  const resolved = resolveIrTypeAliasValueRust(type, context, new Set());
  return representation === 'shared-ref-cell-class'
    ? resolved
    : getIrTypeOptionalPayloadRust(resolved, 'optional shared class carrier', context);
}

function getRustSharedClassTypeRepresentationRust(
  type: Readonly<IrType> | undefined,
  context: EmitContext,
): RustSharedClassRepresentation | undefined {
  if (!type) return undefined;
  const resolved = resolveIrTypeAliasValueRust(type, context, new Set());
  if (getIrClassDeclarationLocationForTypeRust(resolved, context)) return 'shared-ref-cell-class';
  if (resolved.kind !== 'union') return undefined;
  const sentinels = resolved.types.filter(
    (member): member is Extract<IrType, { kind: 'null' | 'undefined' }> =>
      member.kind === 'null' || member.kind === 'undefined',
  );
  const payloads = resolved.types.filter((member) => member.kind !== 'null' && member.kind !== 'undefined');
  if (sentinels.length !== 1 || payloads.length !== 1) return undefined;
  if (!getIrClassDeclarationLocationForTypeRust(payloads[0], context)) return undefined;
  return sentinels[0]!.kind === 'null'
    ? 'optional-null-shared-ref-cell-class'
    : 'optional-undefined-shared-ref-cell-class';
}

function getIrSharedClassSentinelExpressionRust(expression: Readonly<IrExpression>): 'null' | 'undefined' | undefined {
  if (expression.kind === 'literal' && expression.value === null) return 'null';
  if (expression.kind === 'undefinedValue') return 'undefined';
  if (
    expression.kind === 'identifier' &&
    expression.reference.kind === 'ambient' &&
    expression.reference.name === 'undefined'
  ) {
    return 'undefined';
  }
  return undefined;
}

function getRustOptionalSharedClassSentinel(
  representation: RustSharedClassRepresentation,
): 'null' | 'undefined' | undefined {
  if (representation === 'optional-null-shared-ref-cell-class') return 'null';
  if (representation === 'optional-undefined-shared-ref-cell-class') return 'undefined';
  return undefined;
}

function isRustOptionalSharedClassRepresentation(
  representation: CompilerRustReferenceRepresentation | undefined,
): representation is RustOptionalSharedClassRepresentation {
  return (
    representation === 'optional-null-shared-ref-cell-class' ||
    representation === 'optional-undefined-shared-ref-cell-class'
  );
}

function emitObjectRestExpressionRust(
  expression: Readonly<Extract<IrExpression, { kind: 'objectRest' }>>,
  context: EmitContext,
): string {
  if (expression.excluded.some((key) => key.kind === 'computed')) {
    emissionError(context, 'computed object rest requires Rust property-key and record projection lowering');
  }
  const properties = getIrObjectRestPropertiesRust(expression, context);
  if (!properties) emissionError(context, 'object rest requires closed residual-record type evidence');
  const shape = createIrObjectTypeShapeIdentity(properties);
  const existing = context.objectRestRecords.get(shape);
  const recordName = existing?.name ?? getGeneratedTargetNameRust('ObjectRestRecord', context);
  if (!existing) context.objectRestRecords.set(shape, { name: recordName, properties });
  const object = emitExpression(expression.object, context);
  const fields = properties.map((property) => {
    const name = safeRustValueName(property.name);
    return {
      initializer: `${name}: ${object}.${name}.clone(),`,
    };
  });
  return `${recordName} { ${fields.map((field) => field.initializer).join(' ')} }`;
}

function getIrObjectRestPropertiesRust(
  expression: Readonly<Extract<IrExpression, { kind: 'objectRest' }>>,
  context: EmitContext,
): readonly IrObjectTypeProperty[] | undefined {
  const explicit = getIrObjectTypePropertiesRust(expression.type, context);
  if (explicit) return explicit;
  if (expression.object.reference.kind !== 'binding') return undefined;
  const sourceType = context.bindingTypes.get(expression.object.reference.binding.id);
  if (!sourceType) return undefined;
  const sourceProperties = getIrObjectTypePropertiesRust(sourceType, context);
  if (!sourceProperties) return undefined;
  const excluded = new Set(expression.excluded.flatMap((key) => (key.kind === 'named' ? [key.name] : [])));
  return sourceProperties.filter((property) => !excluded.has(property.name));
}

function emitObjectExpressionRust(
  expression: Readonly<Extract<IrExpression, { kind: 'object' }>>,
  context: EmitContext,
): string {
  if (expression.members.some((member) => member.kind === 'getAccessor')) {
    emissionError(context, 'object getters require target-specific accessor lowering');
  }
  const target = emitType(expression.type, context);
  const properties = getIrObjectConstructionPropertiesRust(expression.type, context);
  const members = expression.members.filter(
    (member): member is Extract<IrObjectMember, { kind: 'property' }> => member.kind === 'property',
  );
  const names = new Set<string>();
  const fields = members.map((member) => {
    names.add(member.name);
    const property = properties?.find((candidate) => candidate.name === member.name);
    if (property && hasRustCallableOverloadTypeRust(property.type)) {
      emissionRuleError(
        context,
        'constructing an overloaded callable property requires source-level carrier construction lowering; receive the carrier or construct it through a declared factory instead',
        'rust-overloaded-callable-construction-unrepresented',
      );
    }
    const value = emitExpression(member.value, context);
    return `${safeRustValueName(member.name)}: ${property?.optional ? `Some(${value})` : value},`;
  });
  for (const property of properties ?? []) {
    if (names.has(property.name)) continue;
    fields.push(`${safeRustValueName(property.name)}: None,`);
  }
  return `${target} { ${fields.join(' ')} }`;
}

function inferIrExpressionTypeRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
): Readonly<IrType> | undefined {
  switch (expression.kind) {
    case 'literal':
      if (expression.value === null) return { kind: 'null' };
      return typeof expression.value === 'string'
        ? { kind: 'primitive', name: 'string' }
        : typeof expression.value === 'number'
          ? { kind: 'primitive', name: 'number' }
          : { kind: 'primitive', name: 'boolean' };
    case 'cast':
      return expression.type;
    case 'call':
      return expression.semantics.resultType;
    case 'assignment':
      return expression.left.kind === 'property' ? expression.left.type : undefined;
    case 'identifier':
      return expression.reference.kind === 'binding'
        ? context.bindingTypes.get(expression.reference.binding.id)
        : undefined;
    case 'binary':
    case 'unary': {
      const domain = expression.semantics.result;
      return domain === 'bigint' ||
        domain === 'boolean' ||
        domain === 'number' ||
        domain === 'string' ||
        domain === 'symbol'
        ? { kind: 'primitive', name: domain }
        : domain === 'null'
          ? { kind: 'null' }
          : domain === 'undefined'
            ? { kind: 'undefined' }
            : undefined;
    }
    case 'object':
      return expression.type;
    case 'property': {
      const retainedField = getIrClassRetainedFieldProjectionRust(expression, context);
      if (retainedField) return retainedField.field.type;
      const binding = expression.member ? getCompilerRustAmbientMemberBinding(expression.member) : undefined;
      return binding?.kind === 'countingMethod' || binding?.kind === 'codeUnitLength'
        ? { kind: 'primitive', name: 'number' }
        : undefined;
    }
    default:
      return undefined;
  }
}

function hasSameRustRepresentationAsType(
  expression: Readonly<IrExpression>,
  targetType: Readonly<IrType>,
  context: EmitContext,
): boolean {
  const sourceType = inferIrExpressionTypeRust(expression, context);
  return sourceType !== undefined && emitType(sourceType, context) === emitType(targetType, context);
}

function hasIrTypeGeneralUnionCarrierRust(
  type: Readonly<IrType>,
  context: EmitContext,
  module: Readonly<IrModule> = context.module,
  resolving: ReadonlySet<string> = new Set(),
): boolean {
  if (type.kind === 'union') {
    const concrete = type.types.filter((member) => member.kind !== 'null' && member.kind !== 'undefined');
    if (hasIrTypeNullMemberRust(type) && hasIrTypeUndefinedMemberRust(type)) return true;
    if (concrete.length === 1 && concrete.length !== type.types.length) return false;
    if (getIrUnionPrimitiveDomainRust(concrete, context)) return false;
    return getOrCreatePrimitiveUnionEnumRust(concrete, context) === undefined;
  }
  if (
    type.kind !== 'named' ||
    type.reference.kind !== 'binding' ||
    type.reference.path.length > 0 ||
    type.reference.binding.space !== 'type' ||
    type.reference.binding.kind === 'typeParameter'
  ) {
    return false;
  }
  const location = getIrNamedTypeDeclarationLocationRust(type.reference.binding, context, module);
  if (location?.declaration.kind !== 'typeAlias') return false;
  const key = `${location.module.packageName}\0${location.module.source}\0${location.declaration.binding.id}`;
  if (resolving.has(key)) return false;
  const typeContext: EmitContext = { ...context, activeTypeParameters: location.declaration.typeParameters };
  if (location.declaration.type.kind === 'union') {
    const declared = location.declaration.type;
    if (getIrUnionTypeStringLiteralValues(declared)) return false;
    if (getIrUnionTypeMemberRecordsRust(declared, typeContext)) return false;
    if (
      !hasIrTypeNullMemberRust(declared) &&
      !hasIrTypeUndefinedMemberRust(declared) &&
      !getIrUnionPrimitiveDomainRust(declared.types, typeContext)
    ) {
      return true;
    }
  }
  try {
    const plan = createIrTypeParameterSubstitutionPlan(location.declaration.typeParameters, type.typeArguments);
    const resolved = resolveIrTypeStructuralSubstitution(location.declaration.type, plan);
    return hasIrTypeGeneralUnionCarrierRust(resolved, context, location.module, new Set(resolving).add(key));
  } catch (error) {
    if (isCompilerStructuralTypeSubstitutionFailure(error)) return false;
    throw error;
  }
}

function getIrObjectConstructionPropertiesRust(
  type: Readonly<IrType>,
  context: EmitContext,
): readonly IrObjectTypeProperty[] | undefined {
  return getIrObjectTypePropertiesRust(type, context);
}

function getIrObjectTypeTargetNameRust(properties: readonly IrObjectTypeProperty[], context: EmitContext): string {
  const shape = createIrObjectTypeShapeIdentity(properties);
  const existing = context.anonymousObjectRecords.get(shape);
  if (existing) return existing.name;
  const name = getGeneratedTargetNameRust('AnonymousObjectRecord', context);
  context.anonymousObjectRecords.set(shape, { name, properties });
  return name;
}

function getOrCreateCallableObjectRecordRust(
  type: Readonly<Extract<IrType, { kind: 'intersection' }>>,
  context: EmitContext,
): RustCallableObjectRecord | undefined {
  const callables = type.types.filter(
    (member): member is Extract<IrType, { kind: 'function' }> => member.kind === 'function',
  );
  if (callables.length !== 1) return undefined;
  const callable = callables[0]!;
  if (callable.typeParameters.length > 0) {
    emissionError(context, 'generic callable-object intersections require Rust monomorphization');
  }
  const shapes = type.types
    .filter((member) => member !== callable)
    .map((member) => getIrObjectTypePropertiesRust(member, context));
  if (shapes.length === 0 || shapes.some((shape) => !shape)) return undefined;
  const properties = mergeIrObjectTypePropertiesRust(shapes.flatMap((shape) => shape!));
  if (!properties) return undefined;
  const key = JSON.stringify({
    callable,
    parameters: context.activeTypeParameters.map((parameter) => parameter.binding.id),
    shape: createIrObjectTypeShapeIdentity(properties),
  });
  const existing = context.callableObjectRecords.get(key);
  if (existing) return existing;
  context.needsRcImport.add('Rc');
  const record: RustCallableObjectRecord = {
    callable: {
      parameters: callable.parameters.map((parameter) => {
        const emitted = emitType(parameter.type, context);
        return parameter.optional ? `Option<${emitted}>` : emitted;
      }),
      returns: emitType(callable.returns, context),
    },
    fields: properties.map((property) => ({
      name: safeRustValueName(property.name),
      optional: property.optional,
      rustType: emitType(property.type, context),
    })),
    name: getGeneratedTargetNameRust('AnonymousCallableObject', context),
    typeParameters: context.activeTypeParameters,
  };
  context.callableObjectRecords.set(key, record);
  return record;
}

interface RustCallableOverloadRecord {
  readonly fields: readonly Readonly<{ parameters: readonly string[]; returns: string }>[];
  readonly name: string;
}

const rustObjectEnumerationMembers: ReadonlySet<string> = new Set(['entries', 'keys', 'values']);

// A structural diagnostic may point at a member or a nested literal inside the argument rather than
// the argument node itself. Any prefix that resolves to the exempt argument means the diagnostic is
// inside a literal whose Object call owns the refusal.
function isRustAmbientObjectArgumentPathRust(
  module: Readonly<IrModule>,
  expressions: ReadonlySet<Readonly<IrExpression>>,
  path: readonly (number | string)[],
): boolean {
  for (let length = path.length; length >= 0; length -= 1) {
    const value = getIrModuleTraversalPathValue(module, path.slice(0, length));
    if (typeof value === 'object' && value !== null && expressions.has(value as Readonly<IrExpression>)) return true;
  }
  return false;
}

function collectRustAmbientObjectArgumentExpressionsRust(
  module: Readonly<IrModule>,
): ReadonlySet<Readonly<IrExpression>> {
  const expressions = new Set<Readonly<IrExpression>>();
  analyzeIrModuleTraversal(module, {
    expression(expression) {
      if (
        expression.kind !== 'call' ||
        expression.callee.kind !== 'property' ||
        expression.callee.object.kind !== 'identifier' ||
        expression.callee.object.reference.kind !== 'ambient' ||
        expression.callee.object.reference.name !== 'Object'
      ) {
        return;
      }
      for (const argument of expression.arguments) {
        if (argument.kind === 'object') expressions.add(argument);
      }
    },
  });
  return expressions;
}

function isRustObjectEnumerationCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>>,
): expression is Readonly<Extract<IrExpression, { kind: 'call' }>> &
  Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }> {
  return (
    expression.callee.kind === 'property' &&
    expression.callee.object.kind === 'identifier' &&
    expression.callee.object.reference.kind === 'ambient' &&
    expression.callee.object.reference.name === 'Object' &&
    rustObjectEnumerationMembers.has(expression.callee.name)
  );
}

// Object.keys over a direct object literal is the whole represented surface: the literal's own
// syntactic order is the JavaScript insertion order, every property value is still evaluated exactly
// once, and the keys the runtime would return are known to the compiler. Every other Object use needs
// a runtime named-properties view and refuses deterministically.
function emitRustObjectEnumerationCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>> &
    Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }>,
  context: EmitContext,
): string {
  const member = expression.callee.name;
  if (member !== 'keys') {
    return emissionRuleError(
      context,
      `Object.${member} over a closed object requires an exact erased result carrier this compiler does not represent; only Object.keys is supported`,
      'rust-object-enumeration-member-unrepresented',
    );
  }
  const signature = expression.semantics.signature;
  if (
    expression.optional ||
    expression.callee.optional ||
    expression.semantics.optionalChain !== undefined ||
    expression.callee.optionalChain !== undefined ||
    expression.semantics.defaultParameters !== undefined ||
    expression.semantics.optionalParameters !== undefined ||
    signature === undefined ||
    signature.providedArgumentCount === 'dynamic' ||
    signature.providedArgumentCount !== 1 ||
    expression.arguments.length !== 1 ||
    expression.arguments.some((argument) => argument.kind === 'spread')
  ) {
    emissionRuleError(
      context,
      'Object.keys requires one direct object literal argument with fixed arity',
      'rust-object-enumeration-invocation-unrepresented',
    );
  }
  const argument = expression.arguments[0]!;
  if (argument.kind !== 'object') {
    return emissionRuleError(
      context,
      'Object.keys over a non-literal value needs runtime property reflection; pass a direct object literal or use a closed key plan',
      'rust-object-enumeration-argument-unrepresented',
    );
  }
  const result = resolveIrTypeAliasValueRust(expression.semantics.resultType, context, new Set());
  if (
    result.kind !== 'array' ||
    getRustDensePrimitiveArrayCarrierDomainRust(result.element, context) !== 'string' ||
    emitType(result.element, context) !== 'String'
  ) {
    emissionRuleError(
      context,
      'Object.keys requires the exact mutable Rust Vec<String> result carrier',
      'rust-object-enumeration-result-carrier-unrepresented',
    );
  }
  const seen = new Set<string>();
  const names: string[] = [];
  const evaluations: string[] = [];
  for (const candidate of argument.members) {
    if (candidate.kind !== 'property') {
      emissionRuleError(
        context,
        'Object.keys over an object literal requires plain named properties; computed, symbol, spread, and getter members have no static key order',
        'rust-object-enumeration-literal-shape-unrepresented',
      );
    }
    const name = candidate.name;
    if (name === '__proto__' || isRustJavaScriptArrayIndexKey(name) || seen.has(name)) {
      emissionRuleError(
        context,
        `Object.keys over an object literal cannot represent member ${name}: it is a prototype setter, an array-index-like key that JavaScript reorders, or a duplicate key`,
        'rust-object-enumeration-literal-shape-unrepresented',
      );
    }
    seen.add(name);
    names.push(name);
    evaluations.push(`let _ = ${emitOwnedOperandRust(candidate.value, context)};`);
  }
  const keys =
    names.length === 0
      ? 'Vec::<String>::new()'
      : `vec![${names.map((name) => `${JSON.stringify(name)}.to_owned()`).join(', ')}]`;
  return evaluations.length === 0 ? keys : `{ ${evaluations.join(' ')} ${keys} }`;
}

function isRustJavaScriptArrayIndexKey(name: string): boolean {
  if (!/^(?:0|[1-9][0-9]*)$/u.test(name)) return false;
  return Number(name) < 0xffff_ffff;
}

function isRustCallableFunctionTypeRust(
  type: Readonly<IrType>,
): type is Readonly<Extract<IrType, { kind: 'function' }>> {
  return type.kind === 'function';
}

function hasRustCallableOverloadTypeRust(type: Readonly<IrType>): boolean {
  return type.kind === 'intersection' && type.types.filter(isRustCallableFunctionTypeRust).length > 1;
}

// A closed, arity-distinct overload set is representable: one callable field per declaration-order
// signature means the checker's resolved arity selects exactly one field. Everything the checker
// cannot distinguish this way stays on the existing representation refusals.
function validateRustCallableOverloadTypeRust(
  type: Readonly<Extract<IrType, { kind: 'intersection' }>>,
  context: EmitContext,
): readonly Readonly<Extract<IrType, { kind: 'function' }>>[] {
  const callables = type.types.filter(isRustCallableFunctionTypeRust);
  if (callables.length !== type.types.length) {
    emissionRuleError(
      context,
      'overloaded callable values require every intersection member to be a call signature',
      'rust-overloaded-callable-representation-unrepresented',
    );
  }
  if (context.activeTypeParameters.length > 0 || callables.some((callable) => callable.typeParameters.length > 0)) {
    emissionRuleError(
      context,
      'overloaded callable values require closed non-generic signature sets before Rust emission',
      'rust-overloaded-callable-representation-unrepresented',
    );
  }
  if (callables.some((callable) => callable.parameters.some((parameter) => parameter.optional || parameter.rest))) {
    emissionRuleError(
      context,
      'overloaded callable values require fixed required parameters; optional or rest overloads need source-level adaptation',
      'rust-overloaded-callable-representation-unrepresented',
    );
  }
  const parameterCounts = callables.map((callable) => callable.parameters.length);
  if (new Set(parameterCounts).size !== parameterCounts.length) {
    emissionRuleError(
      context,
      'overloaded callable values require distinct parameter counts; same-arity dispatch needs checker-selected signature evidence',
      'rust-overloaded-callable-representation-unrepresented',
    );
  }
  return callables;
}

function getOrCreateCallableOverloadRecordRust(
  type: Readonly<Extract<IrType, { kind: 'intersection' }>>,
  context: EmitContext,
): RustCallableOverloadRecord {
  const callables = validateRustCallableOverloadTypeRust(type, context);
  const key = normalizeCompilerStructuralValueCanonical(type);
  const existing = context.callableOverloadRecords.get(key);
  if (existing) return existing;
  context.needsRcImport.add('Rc');
  const record: RustCallableOverloadRecord = {
    fields: callables.map((callable) => ({
      parameters: callable.parameters.map((parameter) => emitType(parameter.type, context)),
      returns: emitType(callable.returns, context),
    })),
    name: getGeneratedTargetNameRust('AnonymousCallableOverloads', context),
  };
  context.callableOverloadRecords.set(key, record);
  return record;
}

function emitCallableOverloadRecordRust(record: Readonly<RustCallableOverloadRecord>): string[] {
  return [
    '#[derive(Clone)]',
    `pub struct ${record.name} {`,
    ...record.fields.map(
      (field, index) =>
        `  pub overload_${String(index)}: Rc<dyn Fn(${field.parameters.join(', ')}) -> ${field.returns}>,`,
    ),
    '}',
  ];
}

function getRustCallableOverloadPropertyTypeRust(
  property: Readonly<Extract<IrExpression, { kind: 'property' }>>,
  context: EmitContext,
): Readonly<Extract<IrType, { kind: 'intersection' }>> | undefined {
  const objectType = inferIrExpressionTypeRust(property.object, context);
  if (!objectType) return undefined;
  const propertyType = getRustCallableOverloadMemberTypeRust(objectType, property.name, context, new Set());
  return propertyType && hasRustCallableOverloadTypeRust(propertyType)
    ? (propertyType as Readonly<Extract<IrType, { kind: 'intersection' }>>)
    : undefined;
}

// The general property resolver requires a type-space binding, while an imported interface can carry
// a value-space import binding. Follow the import to the declaring interface for the carrier shape;
// the declaration itself is the authority either way.
function getRustCallableOverloadMemberTypeRust(
  objectType: Readonly<IrType>,
  memberName: string,
  context: EmitContext,
  resolving: ReadonlySet<string>,
): Readonly<IrType> | undefined {
  const resolved = resolveIrTypeAliasValueRust(objectType, context, new Set()) ?? objectType;
  const viaProperties = getIrObjectTypePropertiesRust(resolved, context)?.find(
    (candidate) => candidate.name === memberName,
  )?.type;
  if (viaProperties) return viaProperties;
  if (resolved.kind !== 'named' || resolved.reference.kind !== 'binding') return undefined;
  const location = getIrNamedTypeDeclarationLocationRust(
    resolved.reference.binding as Readonly<IrTypeBindingIdentity>,
    context,
    context.module,
  );
  if (!location) return undefined;
  const key = `${location.module.packageName}\0${location.module.source}\0${location.declaration.binding.id}`;
  if (resolving.has(key)) return undefined;
  const nextResolving = new Set(resolving).add(key);
  if (location.declaration.kind === 'typeAlias') {
    return getRustCallableOverloadMemberTypeRust(location.declaration.type, memberName, context, nextResolving);
  }
  return location.declaration.properties.find((candidate) => candidate.name === memberName)?.type;
}

function isRustCallableOverloadPropertyRust(expression: Readonly<IrExpression>, context: EmitContext): boolean {
  return (
    expression.kind === 'property' &&
    expression.member === undefined &&
    getRustCallableOverloadPropertyTypeRust(expression, context) !== undefined
  );
}

function isRustCallableOverloadCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>>,
  context: EmitContext,
): expression is Readonly<Extract<IrExpression, { kind: 'call' }>> &
  Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }> {
  if (expression.callee.kind === 'identifier') {
    const calleeType = inferIrExpressionTypeRust(expression.callee, context);
    if (calleeType && hasRustCallableOverloadTypeRust(calleeType)) {
      emissionRuleError(
        context,
        'calling an overloaded callable through a local binding requires checker-selected dispatch; call the property directly',
        'rust-overloaded-callable-dispatch-unproven',
      );
    }
    return false;
  }
  if (expression.callee.kind !== 'property' || expression.callee.member !== undefined) return false;
  return getRustCallableOverloadPropertyTypeRust(expression.callee, context) !== undefined;
}

function emitRustCallableOverloadCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>> &
    Readonly<{ callee: Extract<IrExpression, { kind: 'property' }> }>,
  context: EmitContext,
): string {
  const propertyType = getRustCallableOverloadPropertyTypeRust(expression.callee, context);
  if (!propertyType) {
    return emissionRuleError(
      context,
      'overloaded callable dispatch requires the property carrier type in this compilation',
      'rust-overloaded-callable-dispatch-unproven',
    );
  }
  const callables = validateRustCallableOverloadTypeRust(propertyType, context);
  const signature = expression.semantics.signature;
  if (
    expression.optional ||
    expression.callee.optional ||
    expression.semantics.optionalChain !== undefined ||
    expression.callee.optionalChain !== undefined ||
    expression.semantics.defaultParameters !== undefined ||
    expression.semantics.optionalParameters !== undefined ||
    (signature !== undefined &&
      (signature.providedArgumentCount === 'dynamic' || signature.providedArgumentCount !== signature.parameterCount))
  ) {
    emissionRuleError(
      context,
      `overloaded callable property ${expression.callee.name} requires one checker-resolved fixed-arity call`,
      'rust-overloaded-callable-dispatch-unproven',
    );
  }
  // An imported interface call can be lowered without checker signature evidence. The slice's
  // fixed required parameters and distinct arities make the syntactic argument count the same
  // selection the checker would record, so it is exact here; a spread still refuses.
  const parameterCount =
    signature === undefined
      ? expression.arguments.some((argument) => argument.kind === 'spread')
        ? emissionRuleError(
            context,
            `overloaded callable property ${expression.callee.name} requires a fixed argument count`,
            'rust-overloaded-callable-dispatch-unproven',
          )
        : expression.arguments.length
      : signature.parameterCount;
  const index = callables.findIndex((callable) => callable.parameters.length === parameterCount);
  if (index < 0) {
    return emissionRuleError(
      context,
      `overloaded callable property ${expression.callee.name} has no declared overload taking ${String(parameterCount)} fixed argument(s)`,
      'rust-overloaded-callable-dispatch-unproven',
    );
  }
  const receiver = emitExpression(expression.callee.object, context);
  const field = safeRustValueName(expression.callee.name);
  const arguments_ = emitCallArgumentsRust(expression, context);
  return `${receiver}.${field}.overload_${String(index)}(${arguments_.join(', ')})`;
}

function emitCallableObjectRecordRust(record: Readonly<RustCallableObjectRecord>, context: EmitContext): string[] {
  const parameters = record.callable.parameters.join(', ');
  const signature = `dyn Fn(${parameters}) -> ${record.callable.returns}`;
  const typeParameters = emitTypeParameters(record.typeParameters, context);
  const typeArguments = emitTypeArguments(record.typeParameters, context);
  return [
    '#[derive(Clone)]',
    `pub struct ${record.name}${typeParameters} {`,
    `  pub callback: Rc<${signature}>,`,
    ...record.fields.map(
      (field) => `  pub ${field.name}: ${field.optional ? `Option<${field.rustType}>` : field.rustType},`,
    ),
    '}',
    '',
    `impl${typeParameters} std::ops::Deref for ${record.name}${typeArguments} {`,
    `  type Target = ${signature};`,
    '',
    '  fn deref(&self) -> &Self::Target {',
    '    self.callback.as_ref()',
    '  }',
    '}',
  ];
}

// A value Rust moves is invalidated at the site that consumes it, so a binding the source still
// needs afterwards is cloned into the consuming position rather than handed over. Every emitted
// record derives `Clone`, so this is always available. The election is per binding rather than per
// use, so the last consumption clones as well: correct, at the cost of one copy the source did not
// need, and a binding consumed once is left to move.
function emitOwnedOperandRust(expression: Readonly<IrExpression>, context: EmitContext): string {
  const nominalExtraction =
    expression.kind === 'identifier' ? emitRustNominalArmExtractionRust(expression, context) : undefined;
  const source = nominalExtraction ?? emitExpression(expression, context);
  // The arm projection already borrows the carrier and clones the selected payload. Treating the
  // source binding as moved would clone that new owned payload a second time.
  if (nominalExtraction) return source;
  // A string constant read already produced a fresh owned String in its adaptation.
  if (
    expression.kind === 'identifier' &&
    expression.reference.kind === 'binding' &&
    context.stringConstantReadBindingIds.has(expression.reference.binding.id)
  ) {
    return source;
  }
  if (
    expression.kind === 'identifier' &&
    expression.reference.kind === 'binding' &&
    context.movedBindingIds.has(expression.reference.binding.id)
  ) {
    if (context.deepCloneUnsafeBindingIds.has(expression.reference.binding.id)) {
      emissionError(
        context,
        `binding ${expression.reference.binding.name} requires a deep Rust clone that would split source shared identity`,
        'rust-shared-identity-deep-clone-unrepresented',
      );
    }
    return `${source}.clone()`;
  }
  if (
    expression.kind === 'element' &&
    !expression.optional &&
    expression.semantics.receivers.includes('array') &&
    !context.arrayElementOptionReads.has(expression)
  )
    return `${source}.clone()`;
  return source;
}

function emitAwaitOperandRust(expression: Readonly<IrExpression>, context: EmitContext): string {
  return expression.kind === 'call' && isIrNativeAsyncFunctionCallRust(expression, context)
    ? emitOwnedOperandRust(expression, { ...context, allowedNativeFutureCall: expression })
    : emitOwnedOperandRust(expression, context);
}

function emitAwaitExpressionRust(expression: Readonly<IrExpression>, context: EmitContext): string {
  if (expression.kind === 'cast' && canIrExpressionDenoteTaskRust(expression, context)) {
    return emitAwaitExpressionRust(expression.expression, context);
  }
  if (expression.kind === 'conditional' && canIrExpressionDenoteTaskRust(expression, context)) {
    return `if ${emitExpression(expression.condition, context)} { ${emitAwaitExpressionRust(expression.whenTrue, context)} } else { ${emitAwaitExpressionRust(expression.whenFalse, context)} }`;
  }
  return `${emitAwaitOperandRust(expression, context)}.await`;
}

function emitReturnedUnionArrayElementReadRust(
  expression: Readonly<IrExpression>,
  targetType: Readonly<IrType>,
  context: EmitContext,
): string | undefined {
  if (
    expression.kind !== 'element' ||
    expression.object.kind !== 'identifier' ||
    expression.object.reference.kind !== 'binding'
  ) {
    return undefined;
  }
  const receiverType = context.bindingTypes.get(expression.object.reference.binding.id);
  if (!receiverType || !hasIrUnionArrayElementReadCandidateRust(receiverType, context)) return undefined;
  if (
    normalizeCompilerStructuralValueCanonical(receiverType) !==
    normalizeCompilerStructuralValueCanonical(expression.semantics.optionalChain?.receiverType ?? receiverType)
  ) {
    emissionRuleError(
      context,
      'a union-array element read requires exact receiver type evidence at the direct return',
      'rust-union-array-element-read-evidence-unrepresented',
    );
  }
  const indexType = inferIrExpressionTypeRust(expression.index, context);
  const resolvedIndex = indexType ? resolveIrTypeAliasValueRust(indexType, context, new Set()) : undefined;
  if (expression.semantics.key !== 'number' || resolvedIndex?.kind !== 'primitive' || resolvedIndex.name !== 'number') {
    emissionRuleError(
      context,
      'a union-array element read requires one proven numeric index expression',
      'rust-union-array-element-read-evidence-unrepresented',
    );
  }

  const receiver = createRustUnionArrayElementReceiverPlanRust(receiverType, context);
  if (receiver.absence !== expression.optional) {
    emissionRuleError(
      context,
      'a union-array element read requires optional syntax exactly when its represented receiver admits absence',
      'rust-union-array-element-read-evidence-unrepresented',
    );
  }
  const result = createRustUnionArrayElementResultPlanRust(targetType, context);
  if (receiver.absence && !result.absence) {
    emissionRuleError(
      context,
      'an optional union-array element read requires a declared undefined result alternative',
      'rust-union-array-element-read-result-unrepresented',
    );
  }
  if (!result.absence) {
    emissionError(
      context,
      'ordinary array element read can be absent, but this use has no Rust Option carrier',
      'rust-array-index-result-absence-unrepresented',
      'target-runtime',
    );
  }

  const matched = receiver.variants.map((variant) => {
    const matches = result.variants.filter((candidate) =>
      candidate.sourceAlternatives.some((alternative) =>
        areIrContextualCallableParameterAlternativesExactRust(variant.element, alternative, context),
      ),
    );
    if (matches.length !== 1) {
      emissionRuleError(
        context,
        'each union-array element alternative must have exactly one represented result variant',
        'rust-union-array-element-read-result-unrepresented',
      );
    }
    return { receiver: variant, result: matches[0]! };
  });
  if (
    new Set(matched.map(({ result: variant }) => `${variant.owner}::${variant.name}`)).size !== result.variants.length
  ) {
    emissionRuleError(
      context,
      'the declared union-array element result must contain exactly the receiver element alternatives',
      'rust-union-array-element-read-result-unrepresented',
    );
  }

  const receiverName = getGeneratedTargetNameRust('union_array_receiver', context);
  const valueName = getGeneratedTargetNameRust('union_array_value', context);
  const indexName = getGeneratedTargetNameRust('union_array_index', context);
  const carrierName = getGeneratedTargetNameRust('union_array_values', context);
  const elementName = getGeneratedTargetNameRust('union_array_element', context);
  const arms = matched.map(
    ({ receiver: variant, result: resultVariant }) =>
      `${receiver.owner}::${variant.name}(${carrierName}) => ${carrierName}.get(${indexName} as usize).cloned().map(|${elementName}| ${resultVariant.owner}::${resultVariant.name}(${elementName})),`,
  );
  const guarded = `if ${indexName}.is_finite() && ${indexName} >= 0.0 && ${indexName}.fract() == 0.0 && ${indexName} < 4294967295.0 { match ${valueName} { ${arms.join(' ')} } } else { None }`;
  const index = emitExpression(expression.index, context);
  const projected = receiver.absence
    ? `match ${receiverName}.as_ref() { Some(${valueName}) => { let ${indexName}: f64 = ${index}; ${guarded} } None => None, }`
    : `{ let ${valueName} = ${receiverName}; let ${indexName}: f64 = ${index}; ${guarded} }`;
  const read = `{ let ${receiverName} = &${emitExpression(expression.object, context)}; ${projected} }`;
  return read;
}

function hasIrUnionArrayElementReadCandidateRust(type: Readonly<IrType>, context: EmitContext): boolean {
  const resolved = resolveIrTypeAliasValueRust(type, context, new Set());
  if (resolved.kind !== 'union') return false;
  const countArrays = (candidate: Readonly<IrType>): number => {
    const alternative = resolveIrTypeAliasValueRust(candidate, context, new Set());
    return alternative.kind === 'union'
      ? alternative.types.reduce((count, member) => count + countArrays(member), 0)
      : alternative.kind === 'array'
        ? 1
        : 0;
  };
  return countArrays(resolved) >= 2;
}

function createRustUnionArrayElementReceiverPlanRust(
  type: Readonly<IrType>,
  context: EmitContext,
): RustUnionArrayElementReceiverPlan {
  const named = createRustUnionRepresentationPlanForTypeRust(type, context);
  if (named.kind === 'nominalEnum' && named.sentinels.kind === 'none') {
    const variants = named.valueVariants.map((variant) => {
      if (variant.resolvedType.kind !== 'array') {
        emissionRuleError(
          context,
          'every represented union-array receiver alternative must be an ordinary array',
          'rust-union-array-element-read-receiver-unrepresented',
        );
      }
      assertRustUnionArrayElementValueRust(variant.resolvedType.element, context);
      return { element: variant.resolvedType.element, name: variant.name };
    });
    if (variants.length < 2 || named.owner.typeArguments.length > 0) {
      emissionRuleError(
        context,
        'a union-array receiver requires one monomorphic enum owner with at least two array alternatives',
        'rust-union-array-element-read-receiver-unrepresented',
      );
    }
    return { absence: false, owner: emitType(named.owner, context), variants };
  }
  if (named.kind === 'nominalEnum' && named.sentinels.kind === 'distinct') {
    emissionRuleError(
      context,
      'a union-array receiver with both null and undefined has no single Rust absence channel',
      'rust-union-array-element-read-dual-sentinel-unrepresented',
    );
  }

  const resolved = resolveIrTypeAliasValueRust(type, context, new Set());
  if (resolved.kind !== 'union' || resolved.types.some((member) => member.kind === 'union')) {
    emissionRuleError(
      context,
      'a union-array receiver requires one exact represented union owner',
      'rust-union-array-element-read-receiver-unrepresented',
    );
  }
  const hasNull = resolved.types.some((member) => member.kind === 'null');
  const hasUndefined = resolved.types.some((member) => member.kind === 'undefined');
  if (hasNull && hasUndefined) {
    emissionRuleError(
      context,
      'a union-array receiver with both null and undefined has no single Rust absence channel',
      'rust-union-array-element-read-dual-sentinel-unrepresented',
    );
  }
  const concrete = resolved.types.filter((member) => member.kind !== 'null' && member.kind !== 'undefined');
  if (concrete.length === 1) {
    const inner = createRustUnionRepresentationPlanForTypeRust(concrete[0]!, context);
    if (inner.kind === 'nominalEnum' && inner.sentinels.kind === 'none') {
      const variants = inner.valueVariants.map((variant) => {
        if (variant.resolvedType.kind !== 'array') {
          emissionRuleError(
            context,
            'every represented union-array receiver alternative must be an ordinary array',
            'rust-union-array-element-read-receiver-unrepresented',
          );
        }
        assertRustUnionArrayElementValueRust(variant.resolvedType.element, context);
        return { element: variant.resolvedType.element, name: variant.name };
      });
      if (variants.length >= 2 && inner.owner.typeArguments.length === 0) {
        return { absence: hasNull || hasUndefined, owner: emitType(inner.owner, context), variants };
      }
    }
  }
  const represented = concrete.filter((member) => member.kind !== 'never');
  const arrays = represented.map((member) => resolveIrTypeAliasValueRust(member, context, new Set()));
  if (arrays.length < 2 || arrays.some((member) => member.kind !== 'array')) {
    emissionRuleError(
      context,
      'every represented union-array receiver alternative must be an ordinary array',
      'rust-union-array-element-read-receiver-unrepresented',
    );
  }
  const union = getOrCreateAnonymousUnionEnumRust(concrete, context);
  if (union.variants.length !== arrays.length || union.variants.some((variant) => variant.kind !== 'tuple')) {
    emissionRuleError(
      context,
      'a union-array receiver requires tuple variants under one canonical Rust owner',
      'rust-union-array-element-read-receiver-unrepresented',
    );
  }
  const variants = arrays.map((array, index) => {
    if (array.kind !== 'array') {
      emissionRuleError(
        context,
        'every represented union-array receiver alternative must be an ordinary array',
        'rust-union-array-element-read-receiver-unrepresented',
      );
    }
    assertRustUnionArrayElementValueRust(array.element, context);
    return { element: array.element, name: union.variants[index]!.name };
  });
  return { absence: hasNull || hasUndefined, owner: union.name, variants };
}

function createRustUnionArrayElementResultPlanRust(
  type: Readonly<IrType>,
  context: EmitContext,
): RustUnionArrayElementResultPlan {
  const named = createRustUnionRepresentationPlanForTypeRust(type, context);
  if (named.kind === 'nominalEnum' && named.sentinels.kind === 'none') {
    if (named.owner.typeArguments.length > 0) {
      emissionRuleError(
        context,
        'a union-array element result requires one monomorphic canonical owner',
        'rust-union-array-element-read-result-unrepresented',
      );
    }
    return {
      absence: false,
      variants: named.valueVariants.map((variant) => ({
        name: variant.name,
        owner: emitType(named.owner, context),
        sourceAlternatives: variant.sourceAlternatives,
      })),
    };
  }
  if (named.kind === 'nominalEnum' && named.sentinels.kind === 'distinct') {
    emissionRuleError(
      context,
      'a union-array element result with both null and undefined has no unambiguous absence construction',
      'rust-union-array-element-read-dual-sentinel-unrepresented',
    );
  }

  const resolved = resolveIrTypeAliasValueRust(type, context, new Set());
  if (resolved.kind !== 'union' || resolved.types.some((member) => member.kind === 'union')) {
    emissionRuleError(
      context,
      'a union-array element result requires one exact represented union owner',
      'rust-union-array-element-read-result-unrepresented',
    );
  }
  const hasNull = resolved.types.some((member) => member.kind === 'null');
  const hasUndefined = resolved.types.some((member) => member.kind === 'undefined');
  if (hasNull && hasUndefined) {
    emissionRuleError(
      context,
      'a union-array element result with both null and undefined has no unambiguous absence construction',
      'rust-union-array-element-read-dual-sentinel-unrepresented',
    );
  }
  if (hasNull || (!hasUndefined && (hasIrTypeNullMemberRust(type) || hasIrTypeUndefinedMemberRust(type)))) {
    emissionRuleError(
      context,
      'a union-array element result must use undefined as its single represented absence',
      'rust-union-array-element-read-result-unrepresented',
    );
  }
  const concrete = resolved.types.filter((member) => member.kind !== 'null' && member.kind !== 'undefined');
  if (concrete.length === 1) {
    const inner = createRustUnionRepresentationPlanForTypeRust(concrete[0]!, context);
    if (inner.kind === 'nominalEnum' && inner.sentinels.kind === 'none' && inner.owner.typeArguments.length === 0) {
      return {
        absence: hasUndefined,
        variants: inner.valueVariants.map((variant) => ({
          name: variant.name,
          owner: emitType(inner.owner, context),
          sourceAlternatives: variant.sourceAlternatives,
        })),
      };
    }
  }
  const represented = concrete.filter((member) => member.kind !== 'never');
  if (represented.length < 2) {
    emissionRuleError(
      context,
      'a union-array element result requires at least two exact represented value alternatives',
      'rust-union-array-element-read-result-unrepresented',
    );
  }
  const primitive = getOrCreatePrimitiveUnionEnumRust(concrete, context);
  if (primitive) {
    const variants = represented.map((alternative) => {
      const resolvedAlternative = resolveIrTypeAliasValueRust(alternative, context, new Set());
      const variant =
        resolvedAlternative.kind === 'primitive'
          ? primitive.variants.find((candidate) => candidate.primitiveKind === resolvedAlternative.name)
          : undefined;
      if (!variant) {
        emissionRuleError(
          context,
          'a union-array element result alternative has no exact primitive enum variant',
          'rust-union-array-element-read-result-unrepresented',
        );
      }
      return { name: variant.variantName, owner: primitive.name, sourceAlternatives: [alternative] };
    });
    return { absence: hasUndefined, variants };
  }
  const union = getOrCreateAnonymousUnionEnumRust(concrete, context);
  if (union.variants.length !== represented.length || union.variants.some((variant) => variant.kind !== 'tuple')) {
    emissionRuleError(
      context,
      'a union-array element result requires tuple variants under one canonical Rust owner',
      'rust-union-array-element-read-result-unrepresented',
    );
  }
  return {
    absence: hasUndefined,
    variants: represented.map((alternative, index) => ({
      name: union.variants[index]!.name,
      owner: union.name,
      sourceAlternatives: [alternative],
    })),
  };
}

function assertRustUnionArrayElementValueRust(type: Readonly<IrType>, context: EmitContext): void {
  const resolved = resolveIrTypeAliasValueRust(type, context, new Set());
  if (
    resolved.kind === 'primitive' &&
    (resolved.name === 'boolean' || resolved.name === 'number' || resolved.name === 'string')
  ) {
    return;
  }
  emissionRuleError(
    context,
    'union-array element projection refuses identity-valued or otherwise non-value-safe elements',
    'rust-union-array-element-read-identity-unrepresented',
  );
}

function emitReturnedExpressionRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
  ownForDeferredCleanup = false,
): string {
  const returnedUnion = getIrExpressionTaggedUnionRust(expression, context);
  const declaredReturn = context.enclosingReturnType;
  if (returnedUnion !== undefined && declaredReturn?.kind === 'named' && declaredReturn.reference.kind === 'binding') {
    const declaredName = getBindingTargetNameRust(declaredReturn.reference.binding, context);
    if (declaredName !== returnedUnion) {
      emissionRuleError(
        context,
        `returning ${returnedUnion} where ${declaredName} is declared needs an alternative-by-alternative remap, which this emission does not invent. Return the declared union type from where the value is produced, or convert it explicitly in source`,
        'rust-union-remap-unsupported',
      );
    }
  }
  const source = ownForDeferredCleanup
    ? emitOwnedOperandRust(expression, context)
    : emitExpression(expression, context);
  if (
    !ownForDeferredCleanup &&
    expression.kind === 'element' &&
    !expression.optional &&
    expression.semantics.receivers.includes('array') &&
    !context.arrayElementOptionReads.has(expression)
  )
    return `${source}.clone()`;
  if (context.enclosingReturnType?.kind === 'function' && expression.kind === 'function') {
    context.needsRcImport.add('Rc');
    return emitCellCloneBlockRust(`Rc::new(move ${source})`, expression, context);
  }
  return source;
}

// A deferred return still evaluates and owns exactly the value an immediate return would have
// carried. Keeping the contextual conversions here lets cleanup delay control flow without creating
// a second representation path for unions, shared classes, or async task adoption.
function emitContextualReturnValueRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
  ownForDeferredCleanup = false,
): string {
  if (context.returnsSharedArray) {
    if (!context.enclosingReturnType) {
      return emissionRuleError(
        context,
        'owned shared array return has no enclosing exact array type',
        'rust-reference-shared-array-use-unrepresented',
      );
    }
    return emitOwnedSharedArrayCarrierExpressionRust(expression, context.enclosingReturnType, context);
  }
  if (context.sharedClassReturnRepresentation) {
    return emitSharedClassCarrierExpressionRust(expression, context.sharedClassReturnRepresentation, context);
  }
  if (
    !context.returnsAbsent &&
    expression.kind === 'identifier' &&
    expression.reference.kind === 'binding' &&
    expression.presence !== 'narrowedPresent' &&
    context.nullableBindingIds.has(expression.reference.binding.id)
  ) {
    emissionError(context, 'returning a nullable binding requires Rust narrowing evidence');
  }
  if (
    !context.nativeAsyncFunction &&
    expression.kind === 'call' &&
    context.adaptedNativeFutureReturnCalls.has(expression)
  ) {
    return emitExactNativeFutureTaskAdapterRust(expression, context);
  }
  if (context.enclosingReturnType) {
    assertIrAsyncReturnedExpressionCarrierRust(expression, context);
    const adoptedTask = emitAsyncTaskAdoptionRust(expression, context);
    if (adoptedTask) return adoptedTask;
    const unionArrayElementRead = emitReturnedUnionArrayElementReadRust(
      expression,
      context.enclosingReturnType,
      context,
    );
    if (unionArrayElementRead) return unionArrayElementRead;
    const dualSentinelUnion = resolveDualSentinelUnionEnumRust(context.enclosingReturnType, context);
    if (dualSentinelUnion) {
      const wrapped = emitDualSentinelUnionConstructionRust(expression, dualSentinelUnion, context);
      if (wrapped) return wrapped;
    }
    const numericEnum = getIrTypeNumericEnumNamespaceNameRust(context.enclosingReturnType, context);
    if (numericEnum) {
      const expressionEnum = getIrExpressionNumericEnumNamespaceNameRust(expression, context);
      const emitted = emitReturnedExpressionRust(expression, context, ownForDeferredCleanup);
      return expressionEnum === numericEnum ? emitted : `${numericEnum}((${emitted}) as i32)`;
    }
    const targetEnum = resolvePrimitiveUnionEnumRust(context.enclosingReturnType, context);
    if (targetEnum) {
      if (
        expression.kind === 'identifier' &&
        expression.reference.kind === 'binding' &&
        context.primitiveUnionBindingIds.get(expression.reference.binding.id) === targetEnum.name
      ) {
        return ownForDeferredCleanup
          ? emitOwnedOperandRust(expression, context)
          : emitIdentifierReferenceRust(expression.reference, context);
      }
      const wrapped = emitPrimitiveUnionConstructionRust(expression, targetEnum, context);
      if (wrapped) return wrapped;
    }
    const callableUnion = emitContextualCallableUnionConstructionRust(expression, context.enclosingReturnType, context);
    if (callableUnion) return callableUnion;
    const nominalUnion = emitExactContextualGeneralUnionConstructionRust(
      expression,
      context.enclosingReturnType,
      context,
    );
    if (nominalUnion) return nominalUnion;
    if (
      hasIrTypeGeneralUnionCarrierRust(context.enclosingReturnType, context) &&
      !hasSameRustRepresentationAsType(expression, context.enclosingReturnType, context)
    ) {
      emissionError(
        context,
        'returning a contextual general union alternative requires represented Rust enum construction',
        'rust-contextual-general-union-construction-unrepresented',
      );
    }
  }
  return emitReturnedExpressionRust(expression, context, ownForDeferredCleanup);
}

function emitContextualOwnedReturnValueRust(expression: Readonly<IrExpression>, context: EmitContext): string {
  return emitContextualReturnValueRust(expression, context, true);
}

function emitSharedClassCarrierExpressionRust(
  expression: Readonly<IrExpression>,
  targetRepresentation: RustSharedClassRepresentation,
  context: EmitContext,
): string {
  context.needsRcImport.add('Rc');
  context.needsRefCellImport.add('RefCell');
  if (expression.kind === 'conditional') {
    const condition = normalizeSourceTextGrouping(emitExpression(expression.condition, context));
    const whenTrue = emitSharedClassCarrierExpressionRust(expression.whenTrue, targetRepresentation, context);
    const whenFalse = emitSharedClassCarrierExpressionRust(expression.whenFalse, targetRepresentation, context);
    return `if ${condition} { ${whenTrue} } else { ${whenFalse} }`;
  }
  if (expression.kind === 'assignment') {
    const replacement = getIrExactWritableRetainedClassFieldReplacementPlanRust(expression, context);
    if (replacement) {
      const carrier = emitExpression(expression, context);
      return targetRepresentation === 'shared-ref-cell-class' ? carrier : `Some(${carrier})`;
    }
  }
  const sentinel = getIrSharedClassSentinelExpressionRust(expression);
  if (sentinel) {
    if (getRustOptionalSharedClassSentinel(targetRepresentation) !== sentinel) {
      emissionRuleError(
        context,
        `shared class ${sentinel} value does not match the selected Rust optional carrier`,
        'rust-reference-shared-class-return-unrepresented',
      );
    }
    return 'None';
  }
  const sourceRepresentation = getRustSharedClassExpressionRepresentationRust(expression, context);
  let carrier: string;
  if (expression.kind === 'new') {
    carrier = `Rc::new(RefCell::new(${emitExpression(expression, context)}))`;
  } else if (expression.kind === 'property') {
    const projected = emitRetainedClassFieldCarrierRust(expression, context, targetRepresentation);
    if (!projected) {
      return emissionRuleError(
        context,
        'class-valued field carrier requires one exact readonly retained field and compatible sentinel evidence',
        'rust-reference-shared-class-return-unrepresented',
      );
    }
    return projected;
  } else if (expression.kind === 'identifier' && expression.reference.kind === 'binding' && sourceRepresentation) {
    const source = getBindingTargetNameRust(expression.reference.binding, context);
    if (isRustOptionalSharedClassRepresentation(sourceRepresentation)) {
      if (targetRepresentation === sourceRepresentation) return `${source}.clone()`;
      if (targetRepresentation === 'shared-ref-cell-class' && expression.presence === 'narrowedPresent') {
        return `Rc::clone(${source}.as_ref().unwrap())`;
      }
      return emissionRuleError(
        context,
        'optional shared class carrier cannot enter a different or required carrier without exact narrowing',
        'rust-reference-shared-class-return-unrepresented',
      );
    }
    carrier = `Rc::clone(&${source})`;
  } else if (expression.kind === 'call' && sourceRepresentation) {
    if (isRustOptionalSharedClassRepresentation(sourceRepresentation)) {
      if (targetRepresentation === sourceRepresentation) return emitExpression(expression, context);
      if (targetRepresentation === 'shared-ref-cell-class' && expression.presence === 'narrowedPresent') {
        return `${normalizeSourceTextGrouping(emitExpression(expression, context))}.unwrap()`;
      }
      return emissionRuleError(
        context,
        'optional shared class call result cannot enter a different or required carrier',
        'rust-reference-shared-class-return-unrepresented',
      );
    }
    carrier = emitExpression(expression, context);
  } else {
    return emissionRuleError(
      context,
      'shared class return expression is outside the exact constructed, local-alias, or selected carrier',
      'rust-reference-shared-class-return-unrepresented',
    );
  }
  return targetRepresentation === 'shared-ref-cell-class' ? carrier : `Some(${carrier})`;
}

function emitSharedClassIdentityComparisonRust(
  expression: Readonly<Extract<IrExpression, { kind: 'binary' }>>,
  context: EmitContext,
): string | undefined {
  if (
    expression.operator !== '==' &&
    expression.operator !== '===' &&
    expression.operator !== '!=' &&
    expression.operator !== '!=='
  ) {
    return undefined;
  }
  const leftRepresentation = getRustSharedClassExpressionRepresentationRust(expression.left, context);
  const rightRepresentation = getRustSharedClassExpressionRepresentationRust(expression.right, context);
  if (!leftRepresentation || !rightRepresentation) return undefined;
  const leftType = getIrSharedClassIdentityExpressionTypeRust(expression.left, context);
  const rightType = getIrSharedClassIdentityExpressionTypeRust(expression.right, context);
  const leftOwner = leftType
    ? getIrClassTypeIdentityRust(getRustSharedClassPayloadTypeRust(leftType, leftRepresentation, context), context)
    : undefined;
  const rightOwner = rightType
    ? getIrClassTypeIdentityRust(getRustSharedClassPayloadTypeRust(rightType, rightRepresentation, context), context)
    : undefined;
  if (!leftOwner || leftOwner !== rightOwner) return undefined;
  context.needsRcImport.add('Rc');
  const leftName = getGeneratedTargetNameRust('identity_left', context);
  const rightName = getGeneratedTargetNameRust('identity_right', context);
  if (leftRepresentation === 'shared-ref-cell-class' && rightRepresentation === 'shared-ref-cell-class') {
    const left = emitSharedClassIdentityCarrierReferenceRust(expression.left, context);
    const right = emitSharedClassIdentityCarrierReferenceRust(expression.right, context);
    if (!left || !right) return undefined;
    const comparison = `Rc::ptr_eq(${leftName}, ${rightName})`;
    return `{ let ${leftName} = ${left}; let ${rightName} = ${right}; ${expression.operator === '!=' || expression.operator === '!==' ? `!${comparison}` : comparison} }`;
  }
  const left = emitSharedClassCarrierExpressionRust(expression.left, leftRepresentation, context);
  const right = emitSharedClassCarrierExpressionRust(expression.right, rightRepresentation, context);
  let comparison: string;
  if (leftRepresentation === 'shared-ref-cell-class') {
    comparison = `match &${rightName} { Some(${rightName}_value) => Rc::ptr_eq(&${leftName}, ${rightName}_value), None => false }`;
  } else if (rightRepresentation === 'shared-ref-cell-class') {
    comparison = `match &${leftName} { Some(${leftName}_value) => Rc::ptr_eq(${leftName}_value, &${rightName}), None => false }`;
  } else {
    const sameSentinel = leftRepresentation === rightRepresentation;
    comparison = `match (&${leftName}, &${rightName}) { (Some(${leftName}_value), Some(${rightName}_value)) => Rc::ptr_eq(${leftName}_value, ${rightName}_value), (None, None) => ${String(sameSentinel)}, _ => false }`;
  }
  const result = expression.operator === '!=' || expression.operator === '!==' ? `!(${comparison})` : comparison;
  return `{ let ${leftName} = ${left}; let ${rightName} = ${right}; ${result} }`;
}

function emitSharedClassIdentityCarrierReferenceRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
): string | undefined {
  if (
    expression.kind === 'assignment' &&
    getIrExactWritableRetainedClassFieldReplacementPlanRust(expression, context)
  ) {
    return `&${normalizeSourceTextGrouping(emitExpression(expression, context))}`;
  }
  if (
    expression.kind === 'identifier' &&
    expression.reference.kind === 'binding' &&
    context.sharedClassBindingIds.has(expression.reference.binding.id)
  ) {
    return `&${emitIdentifierReferenceRust(expression.reference, context)}`;
  }
  if (expression.kind === 'property') {
    const projected = emitRetainedClassFieldCarrierRust(expression, context);
    return projected ? `&${normalizeSourceTextGrouping(projected)}` : undefined;
  }
  if (isIrSharedClassReturnCallRust(expression, context)) return `&${emitExpression(expression, context)}`;
  if (expression.kind !== 'new') return undefined;
  context.needsRcImport.add('Rc');
  context.needsRefCellImport.add('RefCell');
  return `&Rc::new(RefCell::new(${emitExpression(expression, context)}))`;
}

function getIrSharedClassIdentityExpressionTypeRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
): Readonly<IrType> | undefined {
  if (expression.kind !== 'new') return inferIrExpressionTypeRust(expression, context);
  if (expression.callee.kind !== 'identifier' || expression.callee.reference.kind !== 'binding') return undefined;
  return {
    kind: 'named',
    reference: { binding: expression.callee.reference.binding, kind: 'binding', path: [] },
    typeArguments: [],
  };
}

function getIrClassTypeIdentityRust(type: Readonly<IrType>, context: EmitContext): string | undefined {
  if (
    type.kind !== 'named' ||
    type.typeArguments.length > 0 ||
    type.reference.kind !== 'binding' ||
    type.reference.path.length > 0
  ) {
    return undefined;
  }
  const typeBinding = type.reference.binding;
  const modules = [context.module, ...context.sourceModules];
  const declarationModule = modules.find((module) =>
    module.declarations.some((candidate) => candidate.kind === 'class' && candidate.binding.id === typeBinding.id),
  );
  const local = declarationModule?.declarations.find(
    (candidate) => candidate.kind === 'class' && candidate.binding.id === typeBinding.id,
  );
  if (local?.kind === 'class' && declarationModule) {
    return `${declarationModule.packageName}\0${declarationModule.source}\0${local.binding.id}`;
  }
  const importer = modules.find((module) =>
    module.imports.some((item) => item.bindings.some((binding) => binding.binding.id === typeBinding.id)),
  );
  const imported = importer?.imports
    .flatMap((item) => item.bindings.map((binding) => ({ binding, specifier: item.specifier })))
    .find(({ binding }) => binding.binding.id === typeBinding.id);
  if (!imported || imported.binding.imported === '*' || imported.binding.imported === 'default') return undefined;
  const target = resolveImportModuleRust(imported.specifier, imported.binding.imported, context, importer);
  const declaration = target?.declarations.find(
    (candidate) =>
      candidate.kind === 'class' && candidate.exported && candidate.binding.name === imported.binding.imported,
  );
  return declaration?.kind === 'class' && target
    ? `${target.packageName}\0${target.source}\0${declaration.binding.id}`
    : undefined;
}

function emitContextualCallableUnionConstructionRust(
  expression: Readonly<IrExpression>,
  targetType: Readonly<IrType>,
  context: EmitContext,
): string | undefined {
  const plan = createRustUnionRepresentationPlanForTypeRust(targetType, context);
  if (plan.kind === 'refused' || plan.sentinels.kind !== 'none') return undefined;
  const ownerLocation =
    plan.owner.reference.kind === 'binding' && plan.owner.reference.binding.space === 'type'
      ? getIrNamedTypeDeclarationLocationRust(plan.owner.reference.binding, context, context.module)
      : undefined;
  if (
    plan.owner.typeArguments.length > 0 ||
    ownerLocation?.declaration.kind !== 'typeAlias' ||
    ownerLocation.declaration.typeParameters.length > 0
  ) {
    return undefined;
  }
  const callableVariants = plan.valueVariants.filter(
    (variant): variant is typeof variant & { readonly resolvedType: Extract<IrType, { kind: 'function' }> } =>
      variant.resolvedType.kind === 'function',
  );
  if (callableVariants.length !== 1) return undefined;
  const variant = callableVariants[0]!;
  const sourceType = inferIrExpressionTypeRust(expression, context);
  const source = sourceType ? resolveIrCallableTypeRust(sourceType, context, new Set()) : undefined;
  const target = variant.resolvedType;
  if (
    !source ||
    source.typeParameters.length > 0 ||
    target.typeParameters.length > 0 ||
    source.parameters.length !== 1 ||
    target.parameters.length !== 1 ||
    source.parameters[0]!.rest ||
    target.parameters[0]!.rest ||
    !isIrVoidTypeRust(source.returns, context, new Set()) ||
    !isIrVoidTypeRust(target.returns, context, new Set())
  ) {
    return undefined;
  }

  const sourceParameter = source.parameters[0]!;
  const targetParameter = target.parameters[0]!;
  const sourceStorage = emitFunctionTypeParameterRust(sourceParameter, context);
  const targetStorage = emitFunctionTypeParameterRust(targetParameter, context);
  const owner = emitType(plan.owner, context);
  const ownedSource = emitOwnedOperandRust(expression, context);
  if (sourceStorage === targetStorage) return `${owner}::${variant.name}(${ownedSource})`;
  const argumentName = getGeneratedTargetNameRust('contextual_callable_argument0', context);
  const adaptedArgument = emitContextualCallableParameterConstructionRust(
    argumentName,
    targetParameter,
    sourceParameter,
    context,
  );
  if (!adaptedArgument) return undefined;

  context.needsRcImport.add('Rc');
  const sourceName = getGeneratedTargetNameRust('contextual_callable', context);
  return `{ let ${sourceName} = ${ownedSource}; ${owner}::${variant.name}(Rc::new(move |${argumentName}: ${targetStorage}| ${sourceName}(${adaptedArgument}))) }`;
}

function emitContextualCallableParameterConstructionRust(
  value: string,
  target: Readonly<{ optional: boolean; rest: boolean; type: IrType }>,
  source: Readonly<{ optional: boolean; rest: boolean; type: IrType }>,
  context: EmitContext,
): string | undefined {
  if (target.optional || target.rest || source.rest) return undefined;
  if (isIrRequiredNumberParameterRust(target, context) && isIrOptionalNumberParameterRust(source, context)) {
    return `Some(${value})`;
  }
  if (source.optional) return undefined;

  const named = createRustUnionRepresentationPlanForTypeRust(source.type, context);
  if (named.kind === 'nominalEnum') {
    if (named.sentinels.kind !== 'none') return undefined;
    const matches = named.valueVariants.filter((candidate) =>
      candidate.sourceAlternatives.some((alternative) =>
        areIrContextualCallableParameterAlternativesExactRust(target.type, alternative, context),
      ),
    );
    if (matches.length !== 1) return undefined;
    const match = matches[0]!;
    if (!isIrContextualCallableParameterPayloadRust(match.sourceAlternative, context)) return undefined;
    return `${emitType(named.owner, context)}::${match.name}(${value})`;
  }

  if (source.type.kind !== 'union' || source.type.types.some((member) => member.kind === 'union')) {
    return undefined;
  }
  const sourceTypes = source.type.types.filter((member) => member.kind !== 'never');
  if (sourceTypes.some((member) => isIrContextualCallableParameterErasedRust(member, context))) return undefined;
  const matches = sourceTypes.filter(
    (member) =>
      member.kind !== 'null' &&
      member.kind !== 'undefined' &&
      areIrContextualCallableParameterAlternativesExactRust(target.type, member, context),
  );
  if (matches.length !== 1) return undefined;
  const match = matches[0]!;
  if (!isIrContextualCallableParameterPayloadRust(match, context)) return undefined;

  const hasNull = sourceTypes.some((member) => member.kind === 'null');
  const hasUndefined = sourceTypes.some((member) => member.kind === 'undefined');
  const concrete = source.type.types.filter((member) => member.kind !== 'null' && member.kind !== 'undefined');
  if (hasNull !== hasUndefined && concrete.filter((member) => member.kind !== 'never').length === 1) {
    return `Some(${value})`;
  }
  const primitive = hasNull && hasUndefined ? undefined : getOrCreatePrimitiveUnionEnumRust(concrete, context);
  if (primitive) {
    const resolved = resolveIrTypeAliasValueRust(match, context, new Set());
    if (resolved.kind !== 'primitive') return undefined;
    const variant = primitive.variants.find((candidate) => candidate.primitiveKind === resolved.name);
    if (!variant) return undefined;
    const construction = `${primitive.name}::${variant.variantName}(${value})`;
    return hasNull || hasUndefined ? `Some(${construction})` : construction;
  }

  const carrierTypes = hasNull && hasUndefined ? source.type.types : concrete;
  const union = getOrCreateAnonymousUnionEnumRust(carrierTypes, context);
  const matchIndex = carrierTypes.filter((member) => member.kind !== 'never').indexOf(match);
  const unionVariant = matchIndex < 0 ? undefined : union.variants[matchIndex];
  if (unionVariant?.kind !== 'tuple') return undefined;
  const construction = `${union.name}::${unionVariant.name}(${value})`;
  return hasNull !== hasUndefined ? `Some(${construction})` : construction;
}

function areIrContextualCallableParameterAlternativesExactRust(
  left: Readonly<IrType>,
  right: Readonly<IrType>,
  context: EmitContext,
): boolean {
  const resolvedLeft = resolveIrTypeAliasValueRust(left, context, new Set());
  const resolvedRight = resolveIrTypeAliasValueRust(right, context, new Set());
  return (
    normalizeCompilerStructuralValueCanonical(resolvedLeft) === normalizeCompilerStructuralValueCanonical(resolvedRight)
  );
}

function createRustUnionRepresentationPlanForTypeRust(type: Readonly<IrType>, context: EmitContext) {
  return createRustUnionRepresentationPlan(type, {
    resolveAliasTarget(reference) {
      return resolveIrTypeAliasTargetRust(reference, context);
    },
    resolveVariantName(alternative) {
      return getGeneralUnionVariantNameRust(alternative, context);
    },
  });
}

// Option has only one absence channel. A named dual-sentinel union therefore owns one enum directly:
// the two semantic unit arms reserve their exact names before record arms are allocated, and every
// construction site can qualify the same canonical alias instead of sharing a lazy structural enum.
function createRustDualSentinelNominalEnumPlanRust(
  type: Readonly<IrType>,
  context: EmitContext,
): RustDualSentinelNominalEnumPlan | undefined {
  const union = createRustUnionRepresentationPlanForTypeRust(type, context);
  if (union.kind !== 'nominalEnum' || union.sentinels.kind !== 'distinct' || union.owner.typeArguments.length > 0) {
    return undefined;
  }
  const ownerIdentity = getIrNamedTypeIdentityRust(union.owner, context);
  const declaration = ownerIdentity?.location.declaration;
  if (
    !ownerIdentity ||
    declaration?.kind !== 'typeAlias' ||
    declaration.typeParameters.length > 0 ||
    declaration.type.kind !== 'union'
  ) {
    return undefined;
  }
  const shape = getIrDualSentinelUnionShapeRust(declaration.type);
  if (!shape) return undefined;
  const members = getIrUnionTypeMemberRecordsRust(shape.payloadType, context);
  if (!members || members.length !== union.valueVariants.length) return undefined;
  const memberIdentities = members.map((member) =>
    getIrExactNominalRecordIdentityRust(member.sourceAlternative, context),
  );
  if (
    memberIdentities.some((identity) => identity === undefined) ||
    new Set(memberIdentities.map((identity) => identity?.key)).size !== memberIdentities.length
  ) {
    return undefined;
  }
  const occupiedVariantNames = new Set(['Null', 'Undefined']);
  const valueVariants = union.valueVariants.map((variant) => {
    const identity = getIrExactNominalRecordIdentityRust(variant.sourceAlternative, context);
    const matches = identity
      ? members.filter(
          (member) => getIrExactNominalRecordIdentityRust(member.sourceAlternative, context)?.key === identity.key,
        )
      : [];
    if (matches.length !== 1) return undefined;
    const match = matches[0]!;
    return {
      name: allocateRustUnionVariantName(
        getGeneralUnionVariantNameRust(match.sourceAlternative, context),
        occupiedVariantNames,
      ),
      rustType: match.targetName,
      sourceAlternative: variant.sourceAlternative,
      sourceAlternatives: variant.sourceAlternatives,
    };
  });
  if (valueVariants.some((variant) => variant === undefined)) return undefined;
  return {
    kind: 'dualSentinelNominalEnum',
    nullVariantName: 'Null',
    owner: union.owner,
    ownerIdentity,
    undefinedVariantName: 'Undefined',
    valueVariants: valueVariants as RustDualSentinelNominalEnumPlan['valueVariants'],
  };
}

function createRustDiscriminatedNominalEnumPlanRust(
  type: Readonly<IrType>,
  tagName: string,
  context: EmitContext,
): RustDiscriminatedNominalEnumPlan | undefined {
  const union = createRustUnionRepresentationPlanForTypeRust(type, context);
  if (
    union.kind !== 'nominalEnum' ||
    union.sentinels.kind !== 'none' ||
    union.owner.typeArguments.length > 0 ||
    union.valueVariants.length !== 2
  ) {
    return undefined;
  }
  const ownerIdentity = getIrNamedTypeIdentityRust(union.owner, context);
  const declaration = ownerIdentity?.location.declaration;
  if (
    !ownerIdentity ||
    declaration?.kind !== 'typeAlias' ||
    declaration.typeParameters.length > 0 ||
    declaration.type.kind !== 'union' ||
    declaration.type.types.length !== 2
  ) {
    return undefined;
  }
  const members = getIrUnionTypeMemberRecordsRust(declaration.type, context);
  if (!members || members.length !== 2) return undefined;
  const valueVariants = members.map((member) => {
    const identity = getIrExactNominalRecordIdentityRust(member.sourceAlternative, context);
    const property = member.properties.find((candidate) => candidate.name === tagName);
    const plannedMatches = identity
      ? union.valueVariants.filter(
          (variant) => getIrExactNominalRecordIdentityRust(variant.sourceAlternative, context)?.key === identity.key,
        )
      : [];
    if (
      !identity ||
      plannedMatches.length !== 1 ||
      !property ||
      property.computedKey !== undefined ||
      property.optional ||
      !property.readonly ||
      property.phantom === true ||
      property.role !== undefined ||
      property.type.kind !== 'literal' ||
      typeof property.type.value !== 'string'
    ) {
      return undefined;
    }
    return {
      identity,
      name: member.variantName,
      sourceAlternative: member.sourceAlternative,
      tagValue: property.type.value,
    };
  });
  if (
    valueVariants.some((variant) => variant === undefined) ||
    new Set(valueVariants.map((variant) => variant?.identity.key)).size !== 2 ||
    new Set(valueVariants.map((variant) => variant?.tagValue)).size !== 2
  ) {
    return undefined;
  }
  return {
    kind: 'discriminatedNominalEnum',
    owner: union.owner,
    ownerIdentity,
    tagName,
    valueVariants: valueVariants as RustDiscriminatedNominalEnumPlan['valueVariants'],
  };
}

function allocateRustUnionVariantName(preferredName: string, occupied: Set<string>): string {
  let name = preferredName;
  for (let suffix = 2; occupied.has(name); suffix += 1) name = `${preferredName}${String(suffix)}`;
  occupied.add(name);
  return name;
}

function createRustOptionalGeneratedEnumPlanRust(
  type: Readonly<IrType>,
  context: EmitContext,
): RustOptionalGeneratedEnumPlan | undefined {
  const union = createRustUnionRepresentationPlanForTypeRust(type, context);
  if (union.kind !== 'nominalEnum' || union.sentinels.kind !== 'optional' || union.owner.typeArguments.length > 0) {
    return undefined;
  }
  const ownerIdentity = getIrNamedTypeIdentityRust(union.owner, context);
  const declaration = ownerIdentity?.location.declaration;
  if (
    !ownerIdentity ||
    declaration?.kind !== 'typeAlias' ||
    declaration.typeParameters.length > 0 ||
    declaration.type.kind !== 'union'
  ) {
    return undefined;
  }
  const shape = getIrSingleSentinelUnionShapeRust(declaration.type);
  if (!shape || shape.absence !== union.sentinels.sentinel) return undefined;
  const members = getIrUnionTypeMemberRecordsRust(shape.payloadType, context);
  if (!members || members.length !== union.valueVariants.length) return undefined;
  const valueVariants = union.valueVariants.map((variant) => {
    const identity = getIrExactNominalRecordIdentityRust(variant.sourceAlternative, context);
    const matches = identity
      ? members.filter(
          (member) => getIrExactNominalRecordIdentityRust(member.sourceAlternative, context)?.key === identity.key,
        )
      : [];
    return matches.length === 1
      ? {
          name: matches[0]!.variantName,
          sourceAlternative: variant.sourceAlternative,
          sourceAlternatives: variant.sourceAlternatives,
        }
      : undefined;
  });
  if (valueVariants.some((variant) => variant === undefined)) return undefined;
  const allocationKey = getRustOptionalGeneratedEnumAllocationKey(
    ownerIdentity.location.module,
    declaration.binding.id,
  );
  const payloadOwner = context.optionalGeneratedEnumAllocations.get(allocationKey);
  if (!payloadOwner) return undefined;
  return {
    absence: shape.absence,
    kind: 'optionalGeneratedEnum',
    owner: union.owner,
    ownerIdentity,
    payloadOwner,
    payloadType: shape.payloadType,
    valueVariants: valueVariants as RustOptionalGeneratedEnumPlan['valueVariants'],
  };
}

function emitRustOptionalGeneratedEnumOwnerRust(
  allocation: Readonly<RustOptionalGeneratedEnumAllocation>,
  context: EmitContext,
): string {
  if (isRustCompilerModuleIdentityEqual(allocation.module, context.module)) return allocation.name;
  const base =
    allocation.module.packageName === context.module.packageName
      ? 'crate'
      : convertPackageNameToRustCrateName(allocation.module.packageName).replaceAll('-', '_');
  return `${formatRustModuleCratePathRust(getRustModulePathRust(allocation.module, context.sourceModules), base)}::${allocation.name}`;
}

interface RustExactNominalTypeIdentity {
  readonly key: string;
  readonly location: RustNamedTypeDeclarationLocation;
}

// Contextual unions get one construction boundary for returns, stores, calls, and assertions. A
// single payload plus one sentinel is the Option carrier Rust already uses, and must be claimed
// before nominal-enum construction. Both paths require exact representation evidence; evaluating an
// unproved expression first lets its narrower emitter retain refusal ownership without leaking the
// raw result into a different carrier.
function emitExactContextualGeneralUnionConstructionRust(
  expression: Readonly<IrExpression>,
  targetType: Readonly<IrType>,
  context: EmitContext,
  ownership: 'direct' | 'owned' = 'owned',
): string | undefined {
  const singlePayloadOption = getIrSinglePayloadOptionShapeRust(targetType, context);
  if (expression.kind === 'cast') {
    const assertedSource = inferIrExpressionTypeRust(expression.expression, context);
    // Cast emission already owns the checked carrier conversion. Contextual construction is invoked
    // again there with the cast operand, so claiming the outer cast would either double-construct it
    // or replace its narrower refusal.
    if (
      singlePayloadOption ||
      (assertedSource && resolveIrCastUnionTypeRust(assertedSource, context).kind === 'union')
    ) {
      return undefined;
    }
  }
  if (singlePayloadOption) {
    // Reference planning has already selected an Rc/RefCell/borrowed carrier for this expression.
    // Its dedicated return, local, store, or argument lane must emit or refuse that carrier before
    // ordinary value-to-Option construction is considered.
    if (isIrExpressionReferencePlannedRust(expression, context)) {
      refuseRustContextualGeneralUnionConstructionRust(context);
    }
    const emitOperand = ownership === 'owned' ? emitOwnedOperandRust : emitExpression;
    const sourceType = getIrExpressionExactContextualConstructionTypeRust(expression, context);
    const hasTargetRepresentation =
      sourceType !== undefined && emitType(sourceType, context) === emitType(targetType, context);
    const hasPayloadRepresentation =
      sourceType !== undefined && emitType(sourceType, context) === emitType(singlePayloadOption.payloadType, context);
    const sentinel = getIrSharedClassSentinelExpressionRust(expression);
    if (sentinel) return 'None';
    if (hasTargetRepresentation) return emitOperand(expression, context);
    if (isIrExpressionOptionShapedRust(expression, context)) {
      return emitOperand(expression, context);
    }
    if (hasPayloadRepresentation) {
      return `Some(${emitOperand(expression, context)})`;
    }
    emitOperand(expression, context);
    refuseRustContextualGeneralUnionConstructionRust(context);
  }
  const plan = createRustUnionRepresentationPlanForTypeRust(targetType, context);
  const candidate = hasIrTypeContextualGeneralUnionCandidateRust(targetType, plan, context);
  if (plan.kind !== 'nominalEnum') {
    if (candidate) refuseRustContextualGeneralUnionConstructionRust(context);
    return undefined;
  }
  if (!candidate) return undefined;
  const ownerIdentity = getIrNamedTypeIdentityRust(plan.owner, context);
  const dualSentinelNominalEnum =
    plan.sentinels.kind === 'distinct' ? createRustDualSentinelNominalEnumPlanRust(targetType, context) : undefined;
  const optionalGeneratedEnum =
    plan.sentinels.kind === 'optional' ? createRustOptionalGeneratedEnumPlanRust(targetType, context) : undefined;
  if ((dualSentinelNominalEnum || optionalGeneratedEnum) && context.nativeAsyncFunction) {
    refuseRustContextualGeneralUnionConstructionRust(context);
  }
  if (
    (plan.sentinels.kind === 'distinct' && !dualSentinelNominalEnum) ||
    (plan.sentinels.kind === 'optional' && !optionalGeneratedEnum) ||
    plan.owner.typeArguments.length > 0 ||
    !ownerIdentity ||
    ownerIdentity.location.declaration.kind !== 'typeAlias' ||
    ownerIdentity.location.declaration.typeParameters.length > 0
  ) {
    refuseRustContextualGeneralUnionConstructionRust(context);
  }

  const inferredSource = inferIrExpressionTypeRust(expression, context);
  const sourceOwnerIdentity = inferredSource ? getIrNamedTypeIdentityRust(inferredSource, context) : undefined;
  if (
    sourceOwnerIdentity?.key === ownerIdentity.key &&
    (expression.kind === 'call' ||
      expression.kind === 'cast' ||
      expression.kind === 'identifier' ||
      expression.kind === 'property')
  ) {
    return expression.kind === 'identifier'
      ? emitRustNominalUnionRawOwnedBindingRust(expression, context)
      : emitOwnedOperandRust(expression, context);
  }

  const sentinel = getIrSharedClassSentinelExpressionRust(expression);
  if (sentinel) {
    if (dualSentinelNominalEnum) {
      const variant =
        sentinel === 'null' ? dualSentinelNominalEnum.nullVariantName : dualSentinelNominalEnum.undefinedVariantName;
      return `${emitType(dualSentinelNominalEnum.owner, context)}::${variant}`;
    }
    if (optionalGeneratedEnum?.absence === sentinel) return 'None';
    refuseRustContextualGeneralUnionConstructionRust(context);
  }

  const sourceType = getIrExpressionExactNominalRecordTypeRust(expression, context);
  const sourceIdentity = sourceType ? getIrExactNominalRecordIdentityRust(sourceType, context) : undefined;
  if (!sourceIdentity || isIrExpressionReferencePlannedRust(expression, context)) {
    refuseRustContextualGeneralUnionConstructionRust(context);
  }
  const variants = dualSentinelNominalEnum?.valueVariants ?? optionalGeneratedEnum?.valueVariants ?? plan.valueVariants;
  const matches = variants.filter(
    (variant) => getIrExactNominalRecordIdentityRust(variant.sourceAlternative, context)?.key === sourceIdentity.key,
  );
  if (matches.length !== 1) refuseRustContextualGeneralUnionConstructionRust(context);
  const match = matches[0]!;
  const payload = emitExactNominalGeneralUnionPayloadRust(expression, sourceIdentity, context);
  const constructed = optionalGeneratedEnum
    ? `${emitRustOptionalGeneratedEnumOwnerRust(optionalGeneratedEnum.payloadOwner, context)}::${match.name}(${payload})`
    : `${emitType(dualSentinelNominalEnum?.owner ?? plan.owner, context)}::${match.name}(${payload})`;
  return optionalGeneratedEnum ? `Some(${constructed})` : constructed;
}

function emitExactNominalGeneralUnionPayloadRust(
  expression: Readonly<IrExpression>,
  identity: Readonly<RustExactNominalTypeIdentity>,
  context: EmitContext,
): string {
  if (expression.kind === 'cast') {
    const operandType = getIrExpressionExactNominalRecordTypeRust(expression.expression, context);
    const operandIdentity = operandType ? getIrExactNominalRecordIdentityRust(operandType, context) : undefined;
    if (operandIdentity?.key === identity.key) return emitOwnedOperandRust(expression.expression, context);
  }
  return emitOwnedOperandRust(expression, context);
}

function getIrExpressionExactNominalRecordTypeRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
): Readonly<IrType> | undefined {
  switch (expression.kind) {
    case 'call':
      return expression.semantics.resultType;
    case 'cast': {
      // An assertion may preserve an already-proved nominal identity, but it may not manufacture
      // one for a fresh structural literal. That would turn a checker claim into an enum-arm choice.
      if (expression.expression.kind === 'object') return undefined;
      const assertedIdentity = getIrExactNominalRecordIdentityRust(expression.type, context);
      const operandType = getIrExpressionExactNominalRecordTypeRust(expression.expression, context);
      const operandIdentity = operandType ? getIrExactNominalRecordIdentityRust(operandType, context) : undefined;
      return assertedIdentity && operandIdentity?.key === assertedIdentity.key ? expression.type : undefined;
    }
    case 'identifier':
      return expression.reference.kind === 'binding'
        ? context.bindingTypes.get(expression.reference.binding.id)
        : undefined;
    case 'object':
      return expression.type;
    case 'property':
      return expression.structuralAccess ? undefined : expression.type;
    default:
      return undefined;
  }
}

function getIrExpressionExactContextualConstructionTypeRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
): Readonly<IrType> | undefined {
  return expression.kind === 'cast' || expression.kind === 'object' || expression.kind === 'property'
    ? getIrExpressionExactNominalRecordTypeRust(expression, context)
    : inferIrExpressionTypeRust(expression, context);
}

function getIrExactNominalRecordIdentityRust(
  type: Readonly<IrType>,
  context: EmitContext,
): RustExactNominalTypeIdentity | undefined {
  const identity = getIrNamedTypeIdentityRust(type, context);
  if (!identity) return undefined;
  const declaration = identity.location.declaration;
  return (declaration.kind === 'interface' && declaration.typeParameters.length === 0) ||
    (declaration.kind === 'typeAlias' && declaration.typeParameters.length === 0 && declaration.type.kind === 'object')
    ? identity
    : undefined;
}

function getIrNamedTypeIdentityRust(
  type: Readonly<IrType>,
  context: EmitContext,
): RustExactNominalTypeIdentity | undefined {
  if (
    type.kind !== 'named' ||
    type.reference.kind !== 'binding' ||
    type.reference.binding.space !== 'type' ||
    type.reference.path.length > 0 ||
    type.typeArguments.length > 0
  ) {
    return undefined;
  }
  const locations = getIrNamedTypeDeclarationLocationsRust(type.reference.binding, context, context.module, new Set());
  if (locations.length !== 1) return undefined;
  const location = locations[0]!;
  return {
    key: `${location.module.packageName}\0${path.posix.normalize(location.module.source)}\0${location.declaration.binding.id}`,
    location,
  };
}

function hasIrTypeContextualGeneralUnionCandidateRust(
  type: Readonly<IrType>,
  plan: ReturnType<typeof createRustUnionRepresentationPlanForTypeRust>,
  context: EmitContext,
): boolean {
  if (plan.kind === 'nominalEnum') {
    return plan.valueVariants.some((variant) => variant.sourceAlternative.kind === 'named');
  }
  if (type.kind === 'union') {
    const values = flattenIrUnionTypesRust(type.types).filter(
      (member) => member.kind !== 'never' && member.kind !== 'null' && member.kind !== 'undefined',
    );
    return values.length >= 2 && values.some((member) => member.kind === 'named');
  }
  if (type.kind !== 'named' || type.reference.kind !== 'binding' || type.reference.binding.space !== 'type') {
    return false;
  }
  return getIrNamedTypeDeclarationLocationsRust(type.reference.binding, context, context.module, new Set()).some(
    (location) => {
      if (location.declaration.kind !== 'typeAlias' || location.declaration.type.kind !== 'union') return false;
      const values = flattenIrUnionTypesRust(location.declaration.type.types).filter(
        (member) => member.kind !== 'never' && member.kind !== 'null' && member.kind !== 'undefined',
      );
      return values.length >= 2 && values.some((member) => member.kind === 'named');
    },
  );
}

function isIrExpressionReferencePlannedRust(expression: Readonly<IrExpression>, context: EmitContext): boolean {
  const bindingId =
    expression.kind === 'identifier' && expression.reference.kind === 'binding'
      ? expression.reference.binding.id
      : expression.kind === 'property' &&
          expression.object.kind === 'identifier' &&
          expression.object.reference.kind === 'binding'
        ? expression.object.reference.binding.id
        : undefined;
  return bindingId !== undefined && isRustBindingReferencePlannedRust(bindingId, context);
}

function isIrExpressionClosureCapturedRust(expression: Readonly<IrExpression>, context: EmitContext): boolean {
  if (expression.kind !== 'identifier' || expression.reference.kind !== 'binding') return false;
  const bindingId = expression.reference.binding.id;
  return [...context.closureEvidenceByExpression.values()].some((closure) =>
    closure.captures.some((capture) => capture.binding.id === bindingId),
  );
}

function isRustBindingReferencePlannedRust(bindingId: string, context: EmitContext): boolean {
  return (
    context.cellWrappedBindingIds.has(bindingId) ||
    context.refCellWrappedBindingIds.has(bindingId) ||
    context.sharedArrayBindingIds.has(bindingId) ||
    context.sharedClassBindingRepresentations.has(bindingId) ||
    context.sharedMapBindingIds.has(bindingId) ||
    context.sharedSetBindingIds.has(bindingId)
  );
}

function refuseRustContextualGeneralUnionConstructionRust(context: EmitContext): never {
  emissionRuleError(
    context,
    'contextual general-union construction requires one non-generic named owner and one exact declared record alternative; structural, mismatched-absence, generic, reference-planned, ambiguous, and anonymous carriers do not select an enum arm',
    'rust-contextual-general-union-construction-unrepresented',
  );
}

function isIrContextualCallableParameterErasedRust(type: Readonly<IrType>, context: EmitContext): boolean {
  const resolved = resolveIrTypeAliasValueRust(type, context, new Set());
  return resolved.kind === 'unknown';
}

function isIrContextualCallableParameterPayloadRust(type: Readonly<IrType>, context: EmitContext): boolean {
  const resolved = resolveIrTypeAliasValueRust(type, context, new Set());
  if (resolved.kind === 'primitive') {
    return resolved.name === 'boolean' || resolved.name === 'number' || resolved.name === 'string';
  }
  if (
    resolved.kind !== 'named' ||
    resolved.reference.kind !== 'binding' ||
    resolved.reference.binding.space !== 'type' ||
    resolved.reference.path.length > 0 ||
    resolved.typeArguments.length > 0
  ) {
    return false;
  }
  const location = getIrNamedTypeDeclarationLocationRust(resolved.reference.binding, context, context.module);
  return location?.declaration.kind === 'interface' && location.declaration.typeParameters.length === 0;
}

function isIrOptionalNumberParameterRust(
  parameter: Readonly<{ optional: boolean; rest: boolean; type: IrType }>,
  context: EmitContext,
): boolean {
  if (parameter.rest) return false;
  const resolved = resolveIrTypeAliasValueRust(parameter.type, context, new Set());
  if (parameter.optional) return resolved.kind === 'primitive' && resolved.name === 'number';
  if (resolved.kind !== 'union') return false;
  const members = flattenIrUnionTypesRust(resolved.types).map((member) =>
    resolveIrTypeAliasValueRust(member, context, new Set()),
  );
  return (
    members.length === 2 &&
    members.some((member) => member.kind === 'undefined') &&
    members.some((member) => member.kind === 'primitive' && member.name === 'number')
  );
}

function isIrRequiredNumberParameterRust(
  parameter: Readonly<{ optional: boolean; rest: boolean; type: IrType }>,
  context: EmitContext,
): boolean {
  if (parameter.optional || parameter.rest) return false;
  const resolved = resolveIrTypeAliasValueRust(parameter.type, context, new Set());
  return resolved.kind === 'primitive' && resolved.name === 'number';
}

function isIrVoidTypeRust(type: Readonly<IrType>, context: EmitContext, resolving: ReadonlySet<string>): boolean {
  const resolved = resolveIrTypeAliasValueRust(type, context, resolving);
  return resolved.kind === 'primitive' && resolved.name === 'void';
}

function resolveIrCallableTypeRust(
  type: Readonly<IrType>,
  context: EmitContext,
  resolving: ReadonlySet<string>,
): Readonly<Extract<IrType, { kind: 'function' }>> | undefined {
  const resolved = resolveIrTypeAliasValueRust(type, context, resolving);
  return resolved.kind === 'function' ? resolved : undefined;
}

function resolveIrTypeAliasTargetRust(
  type: Readonly<IrTypeReference>,
  context: EmitContext,
): Readonly<IrType> | undefined {
  if (
    type.reference.kind !== 'binding' ||
    type.reference.path.length > 0 ||
    type.reference.binding.space !== 'type' ||
    type.reference.binding.kind === 'typeParameter'
  ) {
    return undefined;
  }
  const location = getIrNamedTypeDeclarationLocationRust(type.reference.binding, context, context.module);
  if (location?.declaration.kind !== 'typeAlias') return undefined;
  try {
    const substitution = createIrTypeParameterSubstitutionPlan(location.declaration.typeParameters, type.typeArguments);
    return resolveIrTypeStructuralSubstitution(location.declaration.type, substitution);
  } catch (error) {
    if (isCompilerStructuralTypeSubstitutionFailure(error)) return undefined;
    throw error;
  }
}

function resolveIrTypeAliasValueRust(
  type: Readonly<IrType>,
  context: EmitContext,
  resolving: ReadonlySet<string>,
): Readonly<IrType> {
  if (type.kind !== 'named' || type.reference.kind !== 'binding') return type;
  const key = type.reference.binding.id;
  if (resolving.has(key)) return type;
  const target = resolveIrTypeAliasTargetRust(type, context);
  return target ? resolveIrTypeAliasValueRust(target, context, new Set(resolving).add(key)) : type;
}

function collectRustModuleExportBindingIds(module: Readonly<IrModule>): ReadonlySet<string> {
  return new Set(module.exports.flatMap((entry) => (entry.kind === 'local' ? [entry.binding.id] : [])));
}

// A declaration the module exports through `export { name }` is as public as one written `export name`.
// The IR records the local export entry instead of a second exported flag on the declaration, so every
// visibility gate asks this rather than the flag alone.
function isRustDeclarationExportedRust(
  declaration: Readonly<{ binding: Readonly<IrBindingIdentity | IrTypeBindingIdentity>; exported: boolean }>,
  context: EmitContext,
): boolean {
  return declaration.exported || context.moduleExportBindingIds.has(declaration.binding.id);
}

function collectIrModuleApiReferencedBindingIdsRust(
  module: Readonly<IrModule>,
  moduleExportBindingIds: ReadonlySet<string>,
): ReadonlySet<string> {
  const ids = new Set<string>();
  function collectFromType(type: Readonly<IrType>): void {
    switch (type.kind) {
      case 'named':
        if (type.reference.kind === 'binding') ids.add(type.reference.binding.id);
        for (const arg of type.typeArguments) collectFromType(arg);
        break;
      case 'array':
        collectFromType(type.element);
        break;
      case 'conditionalFacet':
        collectFromType(type.check);
        collectFromType(type.facet);
        break;
      case 'function':
        for (const parameter of type.parameters) collectFromType(parameter.type);
        collectFromType(type.returns);
        break;
      case 'intersection':
      case 'union':
        for (const member of type.types) collectFromType(member);
        break;
      case 'object':
        for (const property of type.properties) collectFromType(property.type);
        break;
      case 'tuple':
        for (const element of type.elements) collectFromType(element.type);
        break;
      case 'indexedAccess':
        collectFromType(type.object);
        collectFromType(type.index);
        break;
      case 'keyof':
        collectFromType(type.type);
        break;
    }
  }
  for (const declaration of module.declarations) {
    if (!declaration.exported && !('binding' in declaration && moduleExportBindingIds.has(declaration.binding.id))) {
      continue;
    }
    if (declaration.kind === 'function') {
      for (const parameter of declaration.parameters) collectFromType(parameter.type);
      collectFromType(declaration.returns);
    } else if (declaration.kind === 'class') {
      for (const field of declaration.fields) if (field.visibility === 'public') collectFromType(field.type);
      for (const method of declaration.methods) {
        if (method.visibility !== 'public') continue;
        for (const parameter of method.parameters) collectFromType(parameter.type);
        collectFromType(method.returns);
      }
    }
  }
  return ids;
}

function collectIrModuleArrayElementBindingIdsRust(module: Readonly<IrModule>): ReadonlySet<string> {
  const candidates = new Set<string>();
  const coalesceTargets = new Set<string>();
  analyzeIrModuleTraversal(module, {
    variable(variable) {
      if (
        'binding' in variable &&
        variable.initializer?.kind === 'element' &&
        !variable.initializer.optional &&
        variable.initializer.semantics.receivers.includes('array')
      ) {
        candidates.add(variable.binding.id);
      }
      return undefined;
    },
    expression(expression) {
      if (
        expression.kind === 'binary' &&
        expression.operator === '??' &&
        expression.left.kind === 'identifier' &&
        expression.left.reference.kind === 'binding'
      ) {
        coalesceTargets.add(expression.left.reference.binding.id);
      }
      return undefined;
    },
  });
  const ids = new Set<string>();
  for (const id of candidates) {
    if (coalesceTargets.has(id)) ids.add(id);
  }
  return ids;
}

function collectIrModuleBindingTypesRust(module: Readonly<IrModule>): ReadonlyMap<string, Readonly<IrType>> {
  const result = new Map<string, Readonly<IrType>>();
  analyzeIrModuleTraversal(module, {
    parameter(parameter) {
      result.set(parameter.binding.id, parameter.type);
    },
    variable(variable) {
      if ('binding' in variable && variable.type) {
        result.set(variable.binding.id, variable.type);
      }
    },
  });
  return result;
}

function collectRustDiscriminatedNominalUnionAliasBindingIds(module: Readonly<IrModule>): ReadonlySet<string> {
  const result = new Set<string>();
  analyzeIrModuleTraversal(module, {
    variable(variable) {
      if (
        'binding' in variable &&
        variable.initializer?.kind === 'identifier' &&
        variable.initializer.reference.kind === 'binding'
      ) {
        result.add(variable.binding.id);
      }
    },
  });
  return result;
}

function collectRustDiscriminatedNominalUnionEligibleSwitchOriginsRust(
  module: Readonly<IrModule>,
): ReadonlySet<string> {
  const result = new Set<string>();
  analyzeIrModuleTraversal(module, {
    statement(statement) {
      if (statement.kind !== 'switch') return;
      const origin = getRustDiscriminatedNominalUnionSwitchOriginRust(statement);
      if (
        origin &&
        statement.cases.every((switchCase) => {
          const completion = getIrSwitchCaseCompletion(switchCase, statement.label?.id);
          return completion.kind === 'abrupt' || completion.kind === 'localBreak';
        })
      ) {
        result.add(origin);
      }
    },
  });
  return result;
}

function getRustDiscriminatedNominalUnionSwitchOriginRust(
  statement: Readonly<Extract<IrStatement, { kind: 'switch' }>>,
): string | undefined {
  const origin = statement.origin;
  return origin
    ? JSON.stringify([
        origin.packageName,
        normalizePathPortable(origin.source),
        origin.line,
        origin.column,
        origin.fingerprint,
      ])
    : undefined;
}

function collectIrModuleAssignableBindingIdsRust(module: Readonly<IrModule>): ReadonlySet<string> {
  const result = new Set<string>();
  analyzeIrModuleTraversal(module, {
    parameter(parameter) {
      result.add(parameter.binding.id);
    },
    variable(variable) {
      if ('binding' in variable && variable.mutable) result.add(variable.binding.id);
    },
  });
  return result;
}

// `unknown` has no single native Rust representation. A binding used exclusively through one
// explicit source assertion does, however: the Rust API can expose that asserted type directly and
// erase the assertion. Any unasserted use or disagreement leaves the binding opaque, so this never
// guesses a dynamic conversion that the source did not perform.
function collectAssertedUnknownBindingTypesRust(
  module: Readonly<IrModule>,
  bindingTypes: ReadonlyMap<string, Readonly<IrType>>,
): ReadonlyMap<string, Readonly<IrType>> {
  const candidates = new Map<string, Readonly<IrType>>();
  const disqualified = new Set<string>();
  const parameters = new Set<string>();
  analyzeIrModuleTraversal(module, {
    parameter(parameter) {
      if (parameter.type.kind === 'unknown') parameters.add(parameter.binding.id);
    },
  });
  analyzeIrModuleTraversal(module, {
    expression(expression, path) {
      if (expression.kind !== 'identifier' || expression.reference.kind !== 'binding') return;
      const id = expression.reference.binding.id;
      if (!parameters.has(id) || bindingTypes.get(id)?.kind !== 'unknown') return;
      const parent = path.length > 0 ? getIrModuleTraversalPathValue(module, path.slice(0, -1)) : undefined;
      const asserted =
        parent &&
        typeof parent === 'object' &&
        'kind' in parent &&
        parent.kind === 'cast' &&
        'expression' in parent &&
        parent.expression === expression &&
        'type' in parent &&
        isIrTypeAssertedUnknownRepresentationRust(parent.type)
          ? parent.type
          : undefined;
      if (!asserted) {
        disqualified.add(id);
        return;
      }
      const existing = candidates.get(id);
      if (existing && !areIrAssertedUnknownRepresentationsEqualRust(existing, asserted)) {
        disqualified.add(id);
        return;
      }
      candidates.set(id, asserted);
    },
  });
  for (const id of disqualified) candidates.delete(id);
  return candidates;
}

function isIrTypeAssertedUnknownRepresentationRust(type: unknown): type is Readonly<IrType> {
  if (!type || typeof type !== 'object' || !('kind' in type) || type.kind !== 'primitive') return false;
  return 'name' in type && (type.name === 'boolean' || type.name === 'number' || type.name === 'string');
}

function areIrAssertedUnknownRepresentationsEqualRust(left: Readonly<IrType>, right: Readonly<IrType>): boolean {
  return left.kind === 'primitive' && right.kind === 'primitive' && left.name === right.name;
}

function resolvePrimitiveUnionEnumRust(type: Readonly<IrType>, context: EmitContext): PrimitiveUnionEnum | undefined {
  if (type.kind !== 'union') return undefined;
  const concrete = type.types.filter((t) => t.kind !== 'null' && t.kind !== 'undefined');
  if (concrete.length < 2) return undefined;
  return getOrCreatePrimitiveUnionEnumRust(concrete, context);
}

function resolveDualSentinelUnionEnumRust(
  type: Readonly<IrType>,
  context: EmitContext,
): RustAnonymousUnionEnum | undefined {
  return type.kind === 'union' && hasIrTypeNullMemberRust(type) && hasIrTypeUndefinedMemberRust(type)
    ? getOrCreateAnonymousUnionEnumRust(type.types, context)
    : undefined;
}

function getIrExpressionDualSentinelUnionRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
): RustAnonymousUnionEnum | undefined {
  if (expression.kind !== 'identifier' || expression.reference.kind !== 'binding') return undefined;
  const type = context.bindingTypes.get(expression.reference.binding.id);
  return type ? resolveDualSentinelUnionEnumRust(type, context) : undefined;
}

function getIrExpressionDualSentinelCarrierRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
): RustDualSentinelCarrierView | undefined {
  if (expression.kind !== 'identifier' || expression.reference.kind !== 'binding') return undefined;
  const type = context.bindingTypes.get(expression.reference.binding.id);
  if (!type) return undefined;
  const nominal = createRustDualSentinelNominalEnumPlanRust(type, context);
  if (nominal) {
    return {
      name: emitType(nominal.owner, context),
      nullVariantName: nominal.nullVariantName,
      undefinedVariantName: nominal.undefinedVariantName,
    };
  }
  const anonymous = resolveDualSentinelUnionEnumRust(type, context);
  return anonymous ? { name: anonymous.name, nullVariantName: 'Null', undefinedVariantName: 'Undefined' } : undefined;
}

function emitRustNominalUnionRawCarrierRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
): string | undefined {
  if (expression.kind !== 'identifier' || expression.reference.kind !== 'binding') return undefined;
  const declaredType = context.bindingTypes.get(expression.reference.binding.id);
  if (!declaredType) return undefined;
  const representation = createRustUnionRepresentationPlanForTypeRust(declaredType, context);
  if (
    representation.kind !== 'nominalEnum' ||
    !hasIrTypeContextualGeneralUnionCandidateRust(declaredType, representation, context)
  ) {
    return undefined;
  }
  const bindingId = expression.reference.binding.id;
  const moduleState = context.moduleStateBindings.get(bindingId);
  if (moduleState) return `${moduleState.readName}()`;
  const target = emitIdentifierReferenceRust(expression.reference, context);
  if (context.cellWrappedBindingIds.has(bindingId)) return `${target}.get()`;
  if (context.refCellWrappedBindingIds.has(bindingId)) return `${target}.borrow().clone()`;
  if (
    context.sharedArrayBindingIds.has(bindingId) ||
    context.sharedClassBindingIds.has(bindingId) ||
    context.sharedMapBindingIds.has(bindingId) ||
    context.sharedSetBindingIds.has(bindingId)
  ) {
    return `${target}.borrow().clone()`;
  }
  return target;
}

function emitRustNominalUnionRawOwnedBindingRust(
  expression: Readonly<Extract<IrExpression, { kind: 'identifier' }>>,
  context: EmitContext,
): string {
  if (expression.reference.kind !== 'binding') return emitExpression(expression, context);
  const source = emitRustNominalUnionRawCarrierRust(expression, context);
  if (!source) return emitExpression(expression, context);
  const direct = emitIdentifierReferenceRust(expression.reference, context);
  if (source !== direct) return source;
  if (!context.movedBindingIds.has(expression.reference.binding.id)) return source;
  if (context.deepCloneUnsafeBindingIds.has(expression.reference.binding.id)) {
    emissionError(
      context,
      `binding ${expression.reference.binding.name} requires a deep Rust clone that would split source shared identity`,
      'rust-shared-identity-deep-clone-unrepresented',
    );
  }
  return `${source}.clone()`;
}

function getRustDiscriminatedNominalUnionIfElsePlanRust(
  statement: Readonly<Extract<IrStatement, { kind: 'if' }>>,
  context: EmitContext,
): RustDiscriminatedNominalUnionIfElsePlan | undefined {
  if (!statement.otherwise) return undefined;
  const condition = statement.condition;
  if (condition.kind !== 'binary') return undefined;
  const evidence = condition.semantics.unionMemberTest;
  const property = condition.left.kind === 'property' ? condition.left : undefined;
  const subject = property?.object.kind === 'identifier' ? property.object : undefined;
  const rejectedSubject =
    condition.left.kind === 'element' && condition.left.object.kind === 'identifier'
      ? condition.left.object
      : undefined;
  const syntacticReference = subject?.reference ?? rejectedSubject?.reference;
  const syntacticBinding = syntacticReference?.kind === 'binding' ? syntacticReference.binding : undefined;
  const testedBinding = evidence?.binding ?? syntacticBinding;
  if (!testedBinding) return undefined;
  const declaredType = context.bindingTypes.get(testedBinding.id);
  if (!declaredType) return undefined;
  const representation = createRustUnionRepresentationPlanForTypeRust(declaredType, context);
  if (
    representation.kind !== 'nominalEnum' ||
    representation.sentinels.kind !== 'none' ||
    !hasIrTypeContextualGeneralUnionCandidateRust(declaredType, representation, context)
  ) {
    return undefined;
  }
  const literal =
    condition.right.kind === 'literal' && typeof condition.right.value === 'string' ? condition.right : undefined;
  const operatorResult = condition.operator === '===' ? true : condition.operator === '!==' ? false : undefined;
  if (
    context.discriminatedNominalUnionBranch !== undefined ||
    !evidence ||
    !property ||
    property.optional ||
    property.optionalChain !== undefined ||
    property.namespaceMember !== undefined ||
    property.structuralAccess !== undefined ||
    !subject ||
    subject.reference.kind !== 'binding' ||
    subject.reference.binding.id !== evidence.binding.id ||
    !literal ||
    operatorResult === undefined ||
    evidence.whenResult !== operatorResult ||
    context.nativeAsyncFunction ||
    context.discriminatedNominalUnionAliasBindingIds.has(testedBinding.id) ||
    context.moduleStateBindings.has(testedBinding.id) ||
    isRustBindingReferencePlannedRust(testedBinding.id, context) ||
    context.reboundBindingIds.has(testedBinding.id) ||
    context.referentMutatedBindingIds.has(testedBinding.id)
  ) {
    refuseRustDiscriminatedNominalArmExtractionRust(context);
  }
  const plan = createRustDiscriminatedNominalEnumPlanRust(declaredType, property.name, context);
  if (!plan) refuseRustDiscriminatedNominalArmExtractionRust(context);
  const evidenceIdentity = getIrExactNominalRecordIdentityRust(evidence.member, context);
  const literalMatches = plan.valueVariants.filter((variant) => variant.tagValue === literal.value);
  const evidenceMatches = evidenceIdentity
    ? plan.valueVariants.filter((variant) => variant.identity.key === evidenceIdentity.key)
    : [];
  if (
    !evidenceIdentity ||
    literalMatches.length !== 1 ||
    evidenceMatches.length !== 1 ||
    literalMatches[0]!.identity.key !== evidenceMatches[0]!.identity.key
  ) {
    refuseRustDiscriminatedNominalArmExtractionRust(context);
  }
  const selected = evidenceMatches[0]!;
  const complement = plan.valueVariants.find((variant) => variant.identity.key !== selected.identity.key);
  if (!complement) refuseRustDiscriminatedNominalArmExtractionRust(context);
  const matchingBranch = {
    bindingId: evidence.binding.id,
    direct: true,
    expectedIdentityKey: selected.identity.key,
    ownerIdentityKey: plan.ownerIdentity.key,
    tagName: plan.tagName,
  } as const;
  const complementBranch = {
    bindingId: evidence.binding.id,
    direct: true,
    expectedIdentityKey: complement.identity.key,
    ownerIdentityKey: plan.ownerIdentity.key,
    tagName: plan.tagName,
  } as const;
  const owner = emitType(plan.owner, context);
  const test = `matches!(&${getBindingTargetNameRust(evidence.binding, context)}, ${owner}::${selected.name}(_))`;
  return {
    consequent: evidence.whenResult ? matchingBranch : complementBranch,
    otherwise: evidence.whenResult ? complementBranch : matchingBranch,
    test: evidence.whenResult ? test : `!${test}`,
  };
}

function getRustDiscriminatedNominalUnionGuardTestBindingRust(
  statement: Readonly<Extract<IrStatement, { kind: 'if' }>>,
  context: EmitContext,
): Readonly<IrBindingIdentity> | undefined {
  if (statement.otherwise || context.discriminatedNominalUnionBranch !== undefined) return undefined;
  const condition = statement.condition;
  if (condition.kind !== 'binary') return undefined;
  const evidence = condition.semantics.unionMemberTest;
  const property = condition.left.kind === 'property' ? condition.left : undefined;
  const subject = property?.object.kind === 'identifier' ? property.object : undefined;
  const literal =
    condition.right.kind === 'literal' && typeof condition.right.value === 'string' ? condition.right : undefined;
  const operatorResult = condition.operator === '===' ? true : condition.operator === '!==' ? false : undefined;
  if (
    !evidence ||
    !property ||
    property.optional ||
    property.optionalChain !== undefined ||
    property.namespaceMember !== undefined ||
    property.structuralAccess !== undefined ||
    !subject ||
    subject.reference.kind !== 'binding' ||
    subject.reference.binding.id !== evidence.binding.id ||
    getIrExpressionTaggedUnionRust(subject, context) === undefined ||
    !literal ||
    operatorResult === undefined ||
    evidence.whenResult !== operatorResult
  ) {
    return undefined;
  }
  return evidence.binding;
}

function getRustDiscriminatedNominalUnionSwitchPlanRust(
  statement: Readonly<Extract<IrStatement, { kind: 'switch' }>>,
  context: EmitContext,
): RustDiscriminatedNominalUnionSwitchPlan | undefined {
  const property = statement.expression.kind === 'property' ? statement.expression : undefined;
  const subject = property?.object.kind === 'identifier' ? property.object : undefined;
  const rejectedSubject =
    statement.expression.kind === 'element' && statement.expression.object.kind === 'identifier'
      ? statement.expression.object
      : undefined;
  const syntacticReference = subject?.reference ?? rejectedSubject?.reference;
  const syntacticBinding = syntacticReference?.kind === 'binding' ? syntacticReference.binding : undefined;
  const evidenceBinding = statement.cases.find((switchCase) => switchCase.unionMemberTest)?.unionMemberTest?.binding;
  const testedBinding = evidenceBinding ?? syntacticBinding;
  if (!testedBinding) return undefined;
  const declaredType = context.bindingTypes.get(testedBinding.id);
  if (!declaredType) return undefined;
  const representation = createRustUnionRepresentationPlanForTypeRust(declaredType, context);
  if (
    representation.kind !== 'nominalEnum' ||
    representation.sentinels.kind !== 'none' ||
    !hasIrTypeContextualGeneralUnionCandidateRust(declaredType, representation, context)
  ) {
    return undefined;
  }
  const origin = getRustDiscriminatedNominalUnionSwitchOriginRust(statement);
  if (
    context.discriminatedNominalUnionBranch !== undefined ||
    !origin ||
    !context.discriminatedNominalUnionEligibleSwitchOrigins.has(origin) ||
    statement.subjectDomain !== 'string' ||
    statement.cases.length !== 2 ||
    statement.cases.some((switchCase) => !switchCase.expression) ||
    !property ||
    property.optional ||
    property.optionalChain !== undefined ||
    property.namespaceMember !== undefined ||
    property.structuralAccess !== undefined ||
    !subject ||
    subject.reference.kind !== 'binding' ||
    subject.reference.binding.id !== testedBinding.id ||
    context.nativeAsyncFunction ||
    context.discriminatedNominalUnionAliasBindingIds.has(testedBinding.id) ||
    context.moduleStateBindings.has(testedBinding.id) ||
    isRustBindingReferencePlannedRust(testedBinding.id, context) ||
    context.reboundBindingIds.has(testedBinding.id) ||
    context.referentMutatedBindingIds.has(testedBinding.id) ||
    statement.cases.some(hasRustDiscriminatedNominalUnionSwitchCaseBoundaryRust)
  ) {
    refuseRustDiscriminatedNominalArmExtractionRust(context);
  }
  const plan = createRustDiscriminatedNominalEnumPlanRust(declaredType, property.name, context);
  if (!plan) refuseRustDiscriminatedNominalArmExtractionRust(context);
  const casePlans = statement.cases.map((switchCase) => {
    const expression = switchCase.expression!;
    const literal =
      expression.kind === 'literal' && typeof expression.value === 'string' ? expression.value : undefined;
    const evidence = switchCase.unionMemberTest;
    const evidenceIdentity = evidence ? getIrExactNominalRecordIdentityRust(evidence.member, context) : undefined;
    const matches =
      literal !== undefined && evidenceIdentity
        ? plan.valueVariants.filter(
            (variant) => variant.tagValue === literal && variant.identity.key === evidenceIdentity.key,
          )
        : [];
    if (
      !evidence ||
      evidence.whenResult !== true ||
      evidence.binding.id !== testedBinding.id ||
      !evidenceIdentity ||
      matches.length !== 1 ||
      !hasRustDiscriminatedNominalUnionSwitchCaseNarrowingRust(
        switchCase,
        testedBinding.id,
        evidenceIdentity.key,
        context,
      )
    ) {
      refuseRustDiscriminatedNominalArmExtractionRust(context);
    }
    const variant = matches[0]!;
    return {
      branch: {
        bindingId: evidence.binding.id,
        direct: true,
        expectedIdentityKey: evidenceIdentity.key,
        ownerIdentityKey: plan.ownerIdentity.key,
        tagName: plan.tagName,
      },
      switchCase,
      variantName: variant.name,
    } satisfies RustDiscriminatedNominalUnionSwitchCasePlan;
  });
  if (
    casePlans.length !== 2 ||
    new Set(casePlans.map((casePlan) => casePlan.branch.expectedIdentityKey)).size !== 2 ||
    plan.valueVariants.some(
      (variant) => !casePlans.some((casePlan) => casePlan.branch.expectedIdentityKey === variant.identity.key),
    )
  ) {
    refuseRustDiscriminatedNominalArmExtractionRust(context);
  }
  return {
    binding: testedBinding,
    cases: [casePlans[0]!, casePlans[1]!],
    owner: plan.owner,
  };
}

function hasRustDiscriminatedNominalUnionSwitchCaseBoundaryRust(switchCase: Readonly<IrSwitchCase>): boolean {
  let found = false;
  for (const statement of switchCase.statements) {
    analyzeIrStatementSubtreeTraversal(statement, {
      expression(expression) {
        found ||=
          expression.kind === 'await' ||
          expression.kind === 'conditional' ||
          expression.kind === 'function' ||
          (expression.kind === 'binary' &&
            (expression.operator === '&&' || expression.operator === '||' || expression.operator === '??'));
      },
      statement(nested) {
        found ||=
          (nested.kind === 'block' && nested.label !== undefined) ||
          nested.kind === 'do' ||
          nested.kind === 'for' ||
          nested.kind === 'forIn' ||
          nested.kind === 'forOf' ||
          nested.kind === 'if' ||
          nested.kind === 'switch' ||
          nested.kind === 'throw' ||
          nested.kind === 'try' ||
          nested.kind === 'while';
      },
    });
  }
  return found;
}

function hasRustDiscriminatedNominalUnionSwitchCaseNarrowingRust(
  switchCase: Readonly<IrSwitchCase>,
  bindingId: string,
  expectedIdentityKey: string,
  context: EmitContext,
): boolean {
  let valid = true;
  for (const statement of switchCase.statements) {
    analyzeIrStatementSubtreeTraversal(statement, {
      expression(expression) {
        if (
          expression.kind !== 'identifier' ||
          expression.reference.kind !== 'binding' ||
          expression.reference.binding.id !== bindingId
        ) {
          return;
        }
        const identity = expression.narrowedType
          ? getIrExactNominalRecordIdentityRust(expression.narrowedType, context)
          : undefined;
        valid &&= identity?.key === expectedIdentityKey;
      },
    });
  }
  return valid;
}

function refuseRustDiscriminatedNominalUnionMemberTestIfCandidateRust(
  evidence: Readonly<IrUnionMemberTestEvidence>,
  context: EmitContext,
): void {
  const declaredType = context.bindingTypes.get(evidence.binding.id);
  if (!declaredType) return;
  const representation = createRustUnionRepresentationPlanForTypeRust(declaredType, context);
  if (
    representation.kind === 'nominalEnum' &&
    representation.sentinels.kind === 'none' &&
    hasIrTypeContextualGeneralUnionCandidateRust(declaredType, representation, context) &&
    context.discriminatedNominalUnionGuardTestBindingId !== evidence.binding.id
  ) {
    refuseRustDiscriminatedNominalArmExtractionRust(context);
  }
}

function emitRustDiscriminatedNominalArmExtractionRust(
  expression: Readonly<Extract<IrExpression, { kind: 'identifier' }>>,
  context: EmitContext,
): string | undefined {
  if (expression.reference.kind !== 'binding') return undefined;
  const bindingId = expression.reference.binding.id;
  const declaredType = context.bindingTypes.get(bindingId);
  if (!declaredType) return undefined;
  const representation = createRustUnionRepresentationPlanForTypeRust(declaredType, context);
  if (
    representation.kind !== 'nominalEnum' ||
    representation.sentinels.kind !== 'none' ||
    !hasIrTypeContextualGeneralUnionCandidateRust(declaredType, representation, context)
  ) {
    return undefined;
  }
  const branch = context.discriminatedNominalUnionBranch;
  const hasNarrowingEvidence = expression.narrowedType !== undefined || expression.narrowedMember !== undefined;
  if (!branch || branch.bindingId !== bindingId) {
    if (hasNarrowingEvidence) refuseRustDiscriminatedNominalArmExtractionRust(context);
    return undefined;
  }
  if (!branch.direct || !expression.narrowedType) refuseRustDiscriminatedNominalArmExtractionRust(context);
  const plan = createRustDiscriminatedNominalEnumPlanRust(declaredType, branch.tagName, context);
  const narrowedIdentity = getIrExactNominalRecordIdentityRust(expression.narrowedType, context);
  const matches =
    plan && narrowedIdentity
      ? plan.valueVariants.filter((variant) => variant.identity.key === narrowedIdentity.key)
      : [];
  if (
    !plan ||
    plan.ownerIdentity.key !== branch.ownerIdentityKey ||
    !narrowedIdentity ||
    narrowedIdentity.key !== branch.expectedIdentityKey ||
    matches.length !== 1 ||
    context.moduleStateBindings.has(bindingId) ||
    isIrExpressionReferencePlannedRust(expression, context) ||
    context.reboundBindingIds.has(bindingId) ||
    context.referentMutatedBindingIds.has(bindingId) ||
    context.deepCloneUnsafeBindingIds.has(bindingId) ||
    !isIrDualSentinelNominalArmCloneSafeRust(expression.narrowedType, context, new Set())
  ) {
    refuseRustDiscriminatedNominalArmExtractionRust(context);
  }
  const target = emitIdentifierReferenceRust(expression.reference, context);
  const owner = emitType(plan.owner, context);
  return `match &${target} { ${owner}::${matches[0]!.name}(value) => value.clone(), _ => unreachable!() }`;
}

function emitRustNominalArmExtractionRust(
  expression: Readonly<Extract<IrExpression, { kind: 'identifier' }>>,
  context: EmitContext,
): string | undefined {
  return (
    emitRustDualSentinelNominalArmExtractionRust(expression, context) ??
    emitRustDiscriminatedNominalArmExtractionRust(expression, context)
  );
}

function emitRustDualSentinelNominalArmExtractionRust(
  expression: Readonly<Extract<IrExpression, { kind: 'identifier' }>>,
  context: EmitContext,
): string | undefined {
  const hasNarrowingEvidence =
    expression.presence === 'narrowedPresent' ||
    expression.narrowedType !== undefined ||
    expression.narrowedMember !== undefined;
  if (expression.reference.kind !== 'binding') {
    if (hasNarrowingEvidence) refuseRustDualSentinelNominalArmExtractionRust(context);
    return undefined;
  }
  const bindingId = expression.reference.binding.id;
  const declaredType = context.bindingTypes.get(bindingId);
  if (!declaredType) return undefined;
  const representation = createRustUnionRepresentationPlanForTypeRust(declaredType, context);
  if (
    representation.kind !== 'nominalEnum' ||
    representation.sentinels.kind !== 'distinct' ||
    !hasIrTypeContextualGeneralUnionCandidateRust(declaredType, representation, context)
  ) {
    return undefined;
  }
  if (!hasNarrowingEvidence) return undefined;
  const plan = createRustDualSentinelNominalEnumPlanRust(declaredType, context);
  if (
    !plan ||
    expression.presence !== 'narrowedPresent' ||
    !expression.narrowedType ||
    context.moduleStateBindings.has(bindingId) ||
    isIrExpressionReferencePlannedRust(expression, context) ||
    context.deepCloneUnsafeBindingIds.has(bindingId)
  ) {
    refuseRustDualSentinelNominalArmExtractionRust(context);
  }
  const narrowedIdentity = getIrExactNominalRecordIdentityRust(expression.narrowedType, context);
  const matches = narrowedIdentity
    ? plan.valueVariants.filter(
        (variant) =>
          getIrExactNominalRecordIdentityRust(variant.sourceAlternative, context)?.key === narrowedIdentity.key,
      )
    : [];
  if (
    !narrowedIdentity ||
    matches.length !== 1 ||
    !isIrDualSentinelNominalArmCloneSafeRust(expression.narrowedType, context, new Set())
  ) {
    refuseRustDualSentinelNominalArmExtractionRust(context);
  }
  const target = emitIdentifierReferenceRust(expression.reference, context);
  const owner = emitType(plan.owner, context);
  return `match &${target} { ${owner}::${matches[0]!.name}(value) => value.clone(), _ => unreachable!() }`;
}

function emitRustDualSentinelNominalUnionMemberTestRust(
  evidence: Readonly<IrUnionMemberTestEvidence>,
  context: EmitContext,
): string | undefined {
  const declaredType = context.bindingTypes.get(evidence.binding.id);
  if (!declaredType) return undefined;
  const representation = createRustUnionRepresentationPlanForTypeRust(declaredType, context);
  if (
    representation.kind !== 'nominalEnum' ||
    representation.sentinels.kind !== 'distinct' ||
    !hasIrTypeContextualGeneralUnionCandidateRust(declaredType, representation, context)
  ) {
    return undefined;
  }
  const plan = createRustDualSentinelNominalEnumPlanRust(declaredType, context);
  if (
    !plan ||
    context.moduleStateBindings.has(evidence.binding.id) ||
    isRustBindingReferencePlannedRust(evidence.binding.id, context)
  ) {
    refuseRustDualSentinelNominalArmExtractionRust(context);
  }
  const variantName =
    evidence.member.kind === 'null'
      ? plan.nullVariantName
      : evidence.member.kind === 'undefined'
        ? plan.undefinedVariantName
        : (() => {
            const memberIdentity = getIrExactNominalRecordIdentityRust(evidence.member, context);
            const matches = memberIdentity
              ? plan.valueVariants.filter(
                  (variant) =>
                    getIrExactNominalRecordIdentityRust(variant.sourceAlternative, context)?.key === memberIdentity.key,
                )
              : [];
            if (matches.length !== 1) refuseRustDualSentinelNominalArmExtractionRust(context);
            return matches[0]!.name;
          })();
  const owner = emitType(plan.owner, context);
  const payload = evidence.member.kind === 'null' || evidence.member.kind === 'undefined' ? '' : '(_)';
  const test = `matches!(&${getBindingTargetNameRust(evidence.binding, context)}, ${owner}::${variantName}${payload})`;
  return evidence.whenResult ? test : `!${test}`;
}

function isIrDualSentinelNominalArmCloneSafeRust(
  type: Readonly<IrType>,
  context: EmitContext,
  resolving: ReadonlySet<string>,
): boolean {
  switch (type.kind) {
    case 'literal':
    case 'never':
    case 'null':
    case 'primitive':
    case 'undefined':
      return true;
    case 'tuple':
      return type.elements.every((element) =>
        isIrDualSentinelNominalArmCloneSafeRust(element.type, context, resolving),
      );
    case 'union':
      return type.types.every((member) => isIrDualSentinelNominalArmCloneSafeRust(member, context, resolving));
    case 'named': {
      const identity = getIrExactNominalRecordIdentityRust(type, context);
      if (identity) {
        if (resolving.has(identity.key)) return false;
        const declaration = identity.location.declaration;
        const properties =
          declaration.kind === 'interface'
            ? declaration.properties
            : declaration.kind === 'typeAlias' && declaration.type.kind === 'object'
              ? declaration.type.properties
              : undefined;
        return Boolean(
          properties?.every((property) =>
            isIrDualSentinelNominalArmCloneSafeRust(property.type, context, new Set(resolving).add(identity.key)),
          ),
        );
      }
      const alias = getIrNamedTypeIdentityRust(type, context);
      if (!alias || alias.location.declaration.kind !== 'typeAlias' || resolving.has(alias.key)) return false;
      return isIrDualSentinelNominalArmCloneSafeRust(
        alias.location.declaration.type,
        context,
        new Set(resolving).add(alias.key),
      );
    }
    case 'array':
    case 'conditionalFacet':
    case 'function':
    case 'indexedAccess':
    case 'intersection':
    case 'keyof':
    case 'object':
    case 'typeOf':
    case 'unknown':
      return false;
  }
}

function refuseRustDualSentinelNominalArmExtractionRust(context: EmitContext): never {
  emissionRuleError(
    context,
    'dual-sentinel nominal arm extraction requires one stable direct binding, present evidence, one exact non-generic named record arm, and value-safe clone ownership',
    'rust-dual-sentinel-nominal-arm-extraction-unrepresented',
  );
}

function refuseRustDiscriminatedNominalArmExtractionRust(context: EmitContext): never {
  emissionRuleError(
    context,
    'discriminated nominal arm extraction requires one stable direct binding, explicit exhaustive two-branch literal-tag control flow over exactly two non-generic named record arms, exact branch-local checker evidence, and value-safe clone ownership',
    'rust-discriminated-nominal-arm-extraction-unrepresented',
  );
}

function emitDualSentinelUnionConstructionRust(
  expression: Readonly<IrExpression>,
  targetEnum: RustAnonymousUnionEnum,
  context: EmitContext,
): string | undefined {
  if (expression.kind === 'conditional') {
    const condition = emitExpression(expression.condition, context);
    const whenTrue = emitDualSentinelUnionConstructionRust(expression.whenTrue, targetEnum, context);
    const whenFalse = emitDualSentinelUnionConstructionRust(expression.whenFalse, targetEnum, context);
    return whenTrue && whenFalse ? `if ${condition} { ${whenTrue} } else { ${whenFalse} }` : undefined;
  }
  if (expression.kind === 'literal' && expression.value === null) return `${targetEnum.name}::Null`;
  if (
    expression.kind === 'undefinedValue' ||
    (expression.kind === 'identifier' &&
      expression.reference.kind === 'ambient' &&
      expression.reference.name === 'undefined')
  ) {
    return `${targetEnum.name}::Undefined`;
  }
  const sourceUnion = getIrExpressionDualSentinelUnionRust(expression, context);
  if (sourceUnion?.name === targetEnum.name) return emitOwnedOperandRust(expression, context);
  const payloads = targetEnum.variants.filter(
    (variant): variant is Extract<RustGeneralUnionVariant, { kind: 'tuple' }> => variant.kind === 'tuple',
  );
  if (payloads.length === 1) {
    return `${targetEnum.name}::${payloads[0]!.name}(${emitOwnedOperandRust(expression, context)})`;
  }
  const primitiveKind = inferIrExpressionPrimitiveKindRust(expression, context);
  const preferred = primitiveKind
    ? getGeneralUnionVariantNameRust({ kind: 'primitive', name: primitiveKind }, context)
    : undefined;
  const payload = preferred ? payloads.find((variant) => variant.name === preferred) : undefined;
  return payload ? `${targetEnum.name}::${payload.name}(${emitOwnedOperandRust(expression, context)})` : undefined;
}

function inferIrExpressionPrimitiveKindRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
): 'boolean' | 'number' | 'string' | undefined {
  switch (expression.kind) {
    case 'literal':
      return typeof expression.value === 'string'
        ? 'string'
        : typeof expression.value === 'number'
          ? 'number'
          : typeof expression.value === 'boolean'
            ? 'boolean'
            : undefined;
    case 'template':
      return 'string';
    case 'binary': {
      const result = expression.semantics.result;
      return result === 'string' || result === 'number' || result === 'boolean' ? result : undefined;
    }
    case 'unary': {
      const result = expression.semantics.result;
      return result === 'string' || result === 'number' || result === 'boolean' ? result : undefined;
    }
    case 'call': {
      const resultType = expression.semantics.resultType;
      return resultType.kind === 'primitive' &&
        (resultType.name === 'string' || resultType.name === 'number' || resultType.name === 'boolean')
        ? resultType.name
        : undefined;
    }
    case 'cast':
      return expression.type.kind === 'primitive' &&
        (expression.type.name === 'string' || expression.type.name === 'number' || expression.type.name === 'boolean')
        ? expression.type.name
        : undefined;
    case 'identifier': {
      if (expression.reference.kind !== 'binding') return undefined;
      const bindingType = context.bindingTypes.get(expression.reference.binding.id);
      if (!bindingType || bindingType.kind !== 'primitive') return undefined;
      return bindingType.name === 'string' || bindingType.name === 'number' || bindingType.name === 'boolean'
        ? bindingType.name
        : undefined;
    }
    default:
      return undefined;
  }
}

function emitPrimitiveUnionConstructionRust(
  expression: Readonly<IrExpression>,
  targetEnum: PrimitiveUnionEnum,
  context: EmitContext,
): string | undefined {
  if (expression.kind === 'conditional') {
    const condition = emitExpression(expression.condition, context);
    const whenTrue = emitPrimitiveUnionConstructionRust(expression.whenTrue, targetEnum, context);
    const whenFalse = emitPrimitiveUnionConstructionRust(expression.whenFalse, targetEnum, context);
    if (whenTrue === undefined || whenFalse === undefined) return undefined;
    return `if ${condition} { ${whenTrue} } else { ${whenFalse} }`;
  }
  const emitted = normalizeSourceTextGrouping(emitOwnedOperandRust(expression, context));
  const primitiveKind = inferIrExpressionPrimitiveKindRust(expression, context);
  if (!primitiveKind) return undefined;
  const variant = targetEnum.variants.find((v) => v.primitiveKind === primitiveKind);
  if (!variant) return undefined;
  return `${targetEnum.name}::${variant.variantName}(${emitted})`;
}

function collectCellCapturedBindingIdsRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
): readonly string[] {
  if (
    expression.kind !== 'function' ||
    (context.cellWrappedBindingIds.size === 0 &&
      context.refCellWrappedBindingIds.size === 0 &&
      context.sharedArrayBindingIds.size === 0 &&
      context.sharedClassBindingIds.size === 0 &&
      context.sharedMapBindingIds.size === 0 &&
      context.sharedSetBindingIds.size === 0)
  )
    return [];
  const found = new Set<string>();
  const observer = {
    expression(expr: Readonly<IrExpression>) {
      if (
        expr.kind === 'identifier' &&
        expr.reference.kind === 'binding' &&
        (context.cellWrappedBindingIds.has(expr.reference.binding.id) ||
          context.refCellWrappedBindingIds.has(expr.reference.binding.id) ||
          context.sharedArrayBindingIds.has(expr.reference.binding.id) ||
          context.sharedClassBindingIds.has(expr.reference.binding.id) ||
          context.sharedMapBindingIds.has(expr.reference.binding.id) ||
          context.sharedSetBindingIds.has(expr.reference.binding.id))
      ) {
        found.add(expr.reference.binding.id);
      }
      if (expr.kind === 'function') return false as const;
      return undefined;
    },
  };
  expression.body.forEach((stmt) => analyzeIrStatementSubtreeTraversal(stmt, observer));
  if (expression.expression) analyzeIrExpressionSubtreeTraversal(expression.expression, observer);
  return [...found];
}

function emitCellCloneBlockRust(
  rcExpression: string,
  closureExpression: Readonly<IrExpression>,
  context: EmitContext,
): string {
  const capturedCellIds = collectCellCapturedBindingIdsRust(closureExpression, context);
  if (capturedCellIds.length === 0) return rcExpression;
  const clones = capturedCellIds.map((id) => {
    const name = context.targetNames.get(id) ?? id;
    return `  let ${name} = Rc::clone(&${name});`;
  });
  return `{\n${clones.join('\n')}\n  ${rcExpression}\n}`;
}

function emitClosureWithCellClonesRust(expression: Readonly<IrExpression>, context: EmitContext): string {
  const source = emitExpression(expression, context);
  return emitCellCloneBlockRust(`Rc::new(move ${source})`, expression, context);
}

// A value lent to a callee that mutates through it. An argument that is already a mutable borrow is
// passed as it stands, because Rust reborrows it: taking a reference to it again would hand the
// callee a reference to the reference.
function emitLentOperandRust(expression: Readonly<IrExpression>, context: EmitContext): string {
  if (
    expression.kind === 'identifier' &&
    expression.reference.kind === 'binding' &&
    (context.sharedArrayBindingIds.has(expression.reference.binding.id) ||
      context.sharedClassBindingIds.has(expression.reference.binding.id) ||
      context.sharedMapBindingIds.has(expression.reference.binding.id) ||
      context.sharedSetBindingIds.has(expression.reference.binding.id))
  ) {
    return `&mut *${emitIdentifierReferenceRust(expression.reference, context)}.borrow_mut()`;
  }
  const source = emitExpression(expression, context);
  return expression.kind === 'identifier' &&
    expression.reference.kind === 'binding' &&
    context.referentMutatedParameterIds.has(expression.reference.binding.id)
    ? source
    : `&mut ${source}`;
}

function emitBorrowedClassOperandRust(expression: Readonly<IrExpression>, context: EmitContext): string {
  if (
    expression.kind === 'identifier' &&
    expression.reference.kind === 'binding' &&
    context.sharedClassBindingIds.has(expression.reference.binding.id)
  ) {
    return `&*${emitIdentifierReferenceRust(expression.reference, context)}.borrow()`;
  }
  if (isIrSharedClassReturnCallRust(expression, context)) {
    return `&*${normalizeSourceTextGrouping(emitExpression(expression, context))}.borrow()`;
  }
  const source = emitExpression(expression, context);
  return expression.kind === 'identifier' &&
    expression.reference.kind === 'binding' &&
    context.borrowedClassParameterIds.has(expression.reference.binding.id)
    ? source
    : `&${source}`;
}

function getRustSharedArrayBindingRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
): Readonly<IrBindingIdentity> | undefined {
  return expression.kind === 'identifier' &&
    expression.reference.kind === 'binding' &&
    context.sharedArrayBindingIds.has(expression.reference.binding.id)
    ? expression.reference.binding
    : undefined;
}

function isIrSharedArrayIdentityMethodCallRust(expression: Readonly<IrExpression>, context: EmitContext): boolean {
  return (
    expression.kind === 'call' &&
    (isArrayReverseCallRust(expression) ||
      isArrayCopyWithinCallRust(expression) ||
      isArrayFillCallRust(expression) ||
      isArraySortCallRust(expression)) &&
    getRustSharedArrayBindingRust(expression.callee.object, context) !== undefined
  );
}

function getRustSharedClassBindingRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
): Readonly<IrBindingIdentity> | undefined {
  return expression.kind === 'identifier' &&
    expression.reference.kind === 'binding' &&
    (context.sharedClassBindingRepresentations.has(expression.reference.binding.id) ||
      context.optionalSharedClassParameterRepresentations.has(expression.reference.binding.id))
    ? expression.reference.binding
    : undefined;
}

function isIrSharedClassReturnCallRust(expression: Readonly<IrExpression>, context: EmitContext): boolean {
  return getRustSharedClassReturnCallRepresentationRust(expression, context) === 'shared-ref-cell-class';
}

function getRustSharedClassReturnCallRepresentationRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
): RustSharedClassRepresentation | undefined {
  if (expression.kind !== 'call') return undefined;
  if (expression.callee.kind === 'identifier' && expression.callee.reference.kind === 'binding') {
    const representation = context.sharedClassReturnRepresentations.get(expression.callee.reference.binding.id);
    if (representation) return representation;
  }
  return getIrClassMethodCallParameterPlanRust(expression, context)?.plan.returnClass?.representation;
}

function getRustSharedClassBindingRepresentationRust(
  binding: Readonly<IrBindingIdentity>,
  context: EmitContext,
): RustSharedClassRepresentation | undefined {
  return (
    context.sharedClassBindingRepresentations.get(binding.id) ??
    context.optionalSharedClassParameterRepresentations.get(binding.id)
  );
}

function getRustSharedClassExpressionRepresentationRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
): RustSharedClassRepresentation | undefined {
  if (expression.kind === 'new') return 'shared-ref-cell-class';
  if (
    expression.kind === 'assignment' &&
    getIrExactWritableRetainedClassFieldReplacementPlanRust(expression, context)
  ) {
    return 'shared-ref-cell-class';
  }
  if (expression.kind === 'identifier' && expression.reference.kind === 'binding') {
    return getRustSharedClassBindingRepresentationRust(expression.reference.binding, context);
  }
  const returned = getRustSharedClassReturnCallRepresentationRust(expression, context);
  if (returned) return returned;
  return getRustSharedClassTypeRepresentationRust(inferIrExpressionTypeRust(expression, context), context);
}

function getIrSharedClassFieldRust(
  binding: Readonly<IrBindingIdentity>,
  name: string,
  context: EmitContext,
): Readonly<IrClassField> | undefined {
  return getIrSharedClassDeclarationRust(binding, context)?.fields.find(
    (field) => !field.static && field.name === name,
  );
}

function isIrBorrowedClassFieldNonCopyRust(
  binding: Readonly<IrBindingIdentity>,
  name: string,
  context: EmitContext,
): boolean {
  if (!context.borrowedClassParameterIds.has(binding.id)) return false;
  const field = getIrSharedClassFieldRust(binding, name, context);
  return field !== undefined && !isIrTypeCopyValueRust(field.type);
}

function getIrSharedClassDeclarationRust(
  binding: Readonly<IrBindingIdentity>,
  context: EmitContext,
): Readonly<IrClassDeclaration> | undefined {
  const representation = getRustSharedClassBindingRepresentationRust(binding, context);
  const bindingType = context.bindingTypes.get(binding.id);
  const type =
    bindingType && isRustOptionalSharedClassRepresentation(representation)
      ? getIrTypeOptionalPayloadRust(bindingType, 'optional shared class binding', context)
      : bindingType;
  return getIrSharedClassDeclarationForTypeRust(type, context);
}

function getIrSharedClassDeclarationForTypeRust(
  type: Readonly<IrType> | undefined,
  context: EmitContext,
  module: Readonly<IrModule> = context.module,
): Readonly<IrClassDeclaration> | undefined {
  return getIrClassDeclarationLocationForTypeRust(type, context, module)?.declaration;
}

function getIrClassDeclarationLocationForTypeRust(
  type: Readonly<IrType> | undefined,
  context: EmitContext,
  module: Readonly<IrModule> = context.module,
): Readonly<{ declaration: Readonly<IrClassDeclaration>; module: Readonly<IrModule> }> | undefined {
  if (type?.kind !== 'named' || type.reference.kind !== 'binding' || type.reference.path.length > 0) return undefined;
  const typeBindingId = type.reference.binding.id;
  const local = module.declarations.find(
    (candidate) => candidate.kind === 'class' && candidate.binding.id === typeBindingId,
  );
  if (local?.kind === 'class') return { declaration: local, module };
  const directProvider = context.sourceModules.find((candidateModule) =>
    candidateModule.declarations.some(
      (candidate) => candidate.kind === 'class' && candidate.binding.id === typeBindingId,
    ),
  );
  const directDeclaration = directProvider?.declarations.find(
    (candidate) => candidate.kind === 'class' && candidate.binding.id === typeBindingId,
  );
  if (directDeclaration?.kind === 'class' && directProvider) {
    return { declaration: directDeclaration, module: directProvider };
  }
  const imported = module.imports
    .flatMap((item) => item.bindings.map((candidate) => ({ candidate, specifier: item.specifier })))
    .find(({ candidate }) => candidate.binding.id === typeBindingId);
  if (!imported || imported.candidate.imported === '*' || imported.candidate.imported === 'default') return undefined;
  const target = resolveImportModuleRust(imported.specifier, imported.candidate.imported, context, module);
  const declaration = target?.declarations.find(
    (candidate) =>
      candidate.kind === 'class' && candidate.exported && candidate.binding.name === imported.candidate.imported,
  );
  return declaration?.kind === 'class' && target ? { declaration, module: target } : undefined;
}

function emitAsyncSharedClassMethodCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>>,
  context: EmitContext,
): string | undefined {
  if (expression.callee.kind !== 'property') return undefined;
  const callee = expression.callee;
  const receiverType = getIrSharedClassIdentityExpressionTypeRust(callee.object, context);
  const location = getIrClassDeclarationLocationForTypeRust(receiverType, context, context.module);
  const methods = location?.declaration.methods.filter(
    (method) => !method.static && method.accessor === undefined && method.name === callee.name,
  );
  const method = methods?.length === 1 ? methods[0] : undefined;
  if (!location || !method?.async) return undefined;
  if (!isIrSimpleAsyncMethodOwnerSupportedRust(method, location.declaration)) {
    emissionRuleError(
      context,
      `async method ${location.declaration.binding.name}.${method.name} lacks the exact owned Rc<RefCell<Self>> simple-class carrier`,
      'rust-async-method-owner-carrier-unrepresented',
    );
  }
  if (!isIrSimpleAsyncMethodBodySupportedRust(method, location.declaration)) {
    emissionRuleError(
      context,
      `async method ${location.declaration.binding.name}.${method.name} uses a body outside the short receiver-field borrow carrier`,
      'rust-async-method-body-unrepresented',
    );
  }
  const receiver = callee.object;
  const signature = expression.semantics.signature;
  const exactCall =
    !expression.optional &&
    expression.typeArguments.length === 0 &&
    !callee.optional &&
    !callee.structuralAccess &&
    receiver.kind === 'identifier' &&
    receiver.reference.kind === 'binding' &&
    getRustSharedClassBindingRepresentationRust(receiver.reference.binding, context) === 'shared-ref-cell-class' &&
    expression.arguments.length === method.parameters.length &&
    expression.arguments.every((argument) => argument.kind !== 'spread') &&
    expression.semantics.defaultParameters === undefined &&
    expression.semantics.optionalParameters === undefined &&
    expression.semantics.overloadImplementation === undefined &&
    signature?.providedArgumentCount !== 'dynamic' &&
    signature?.restParameter === undefined &&
    (signature === undefined ||
      (signature.parameterCount === method.parameters.length &&
        signature.providedArgumentCount === expression.arguments.length));
  if (!exactCall || receiver.kind !== 'identifier' || receiver.reference.kind !== 'binding' || !receiverType) {
    emissionRuleError(
      context,
      `async method ${location.declaration.binding.name}.${method.name} requires one exact identifier receiver, fixed owned arguments, and direct non-optional invocation`,
      'rust-async-method-call-unrepresented',
    );
  }
  context.needsRcImport.add('Rc');
  const owner = emitType(receiverType, context);
  const receiverName = emitIdentifierReferenceRust(receiver.reference, context);
  return `${owner}::${getIrClassMethodTargetNameRust(method)}(Rc::clone(&${receiverName})${
    expression.arguments.length > 0 ? `, ${emitCallArgumentsRust(expression, context).join(', ')}` : ''
  })`;
}

function emitSharedClassMethodCallRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>>,
  context: EmitContext,
): string | undefined {
  if (
    expression.optional ||
    expression.typeArguments.length > 0 ||
    expression.callee.kind !== 'property' ||
    expression.callee.optional ||
    expression.callee.structuralAccess
  ) {
    return undefined;
  }
  const callee = expression.callee;
  const binding = getRustSharedClassBindingRust(callee.object, context);
  const returned = isIrSharedClassReturnCallRust(callee.object, context);
  if (!binding && !returned) return undefined;
  const declaration = binding
    ? getIrSharedClassDeclarationRust(binding, context)
    : getIrSharedClassDeclarationForTypeRust(inferIrExpressionTypeRust(callee.object, context), context);
  const methods = declaration?.methods.filter((method) => !method.static && method.name === callee.name);
  const method = methods?.length === 1 ? methods[0] : undefined;
  if (!declaration || !method) return undefined;
  const target = getIrClassMethodTargetNameRust(method);
  const mutable = getIrClassMutatingMethodNamesRust(declaration).has(target);
  const receiver = emitSharedClassBorrowReceiverRust(callee.object, mutable, context);
  if (!receiver) return undefined;
  return `${receiver}.${target}(${emitCallArgumentsRust(expression, context).join(', ')})`;
}

function emitSharedClassBorrowReceiverRust(
  expression: Readonly<IrExpression>,
  mutable: boolean,
  context: EmitContext,
): string | undefined {
  if (expression.kind === 'property' && getIrClassRetainedFieldProjectionRust(expression, context)) {
    const carrier = emitRetainedClassFieldCarrierRust(expression, context, 'shared-ref-cell-class');
    return carrier ? `${normalizeSourceTextGrouping(carrier)}.${mutable ? 'borrow_mut' : 'borrow'}()` : undefined;
  }
  const binding = getRustSharedClassBindingRust(expression, context);
  if (binding) {
    const representation = getRustSharedClassBindingRepresentationRust(binding, context);
    const source = getBindingTargetNameRust(binding, context);
    if (isRustOptionalSharedClassRepresentation(representation)) {
      if (expression.kind !== 'identifier' || expression.presence !== 'narrowedPresent') {
        return emissionRuleError(
          context,
          'optional shared class member access requires exact presence narrowing',
          'rust-reference-shared-class-member-unrepresented',
        );
      }
      return `${source}.as_ref().unwrap().${mutable ? 'borrow_mut' : 'borrow'}()`;
    }
    return `${source}.${mutable ? 'borrow_mut' : 'borrow'}()`;
  }
  if (!isIrSharedClassReturnCallRust(expression, context)) return undefined;
  return `${normalizeSourceTextGrouping(emitExpression(expression, context))}.${mutable ? 'borrow_mut' : 'borrow'}()`;
}

function getRustSharedHashCollectionBindingRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
): Readonly<IrBindingIdentity> | undefined {
  return expression.kind === 'identifier' &&
    expression.reference.kind === 'binding' &&
    (context.sharedMapBindingIds.has(expression.reference.binding.id) ||
      context.sharedSetBindingIds.has(expression.reference.binding.id))
    ? expression.reference.binding
    : undefined;
}

function emitSharedReferenceReceiverRust(
  expression: Readonly<IrExpression>,
  mutable: boolean,
  context: EmitContext,
): string {
  if (!mutable && expression.kind === 'cast') {
    const assertion = getRustReadonlyPrimitiveArrayIdentityAssertionRust(expression, context);
    if (assertion && !assertion.optional) {
      const operand = expression.expression;
      if (operand.kind === 'identifier' && operand.reference.kind === 'binding') {
        const sourceType = context.bindingTypes.get(operand.reference.binding.id);
        const source = sourceType ? getRustOwnedSharedArrayTypeRust(sourceType, context) : undefined;
        if (
          context.sharedArrayBindingIds.has(operand.reference.binding.id) &&
          source?.primitiveName === assertion.primitiveName
        ) {
          return `${emitIdentifierReferenceRust(operand.reference, context)}.borrow()`;
        }
      }
      if (operand.kind === 'call') {
        const callPlan = getIrOwnedSharedArrayCallPlanRust(operand, context);
        const source = callPlan ? getRustOwnedSharedArrayTypeRust(callPlan.declaration.returns, context) : undefined;
        if (callPlan?.returnsSharedArray && source?.primitiveName === assertion.primitiveName) {
          return `${normalizeSourceTextGrouping(emitExpression(operand, context))}.borrow()`;
        }
      }
    }
  }
  const binding =
    getRustSharedArrayBindingRust(expression, context) ?? getRustSharedHashCollectionBindingRust(expression, context);
  return binding
    ? `${getBindingTargetNameRust(binding, context)}.${mutable ? 'borrow_mut' : 'borrow'}()`
    : emitExpression(expression, context);
}

// A closure an iterator adaptor hands a reference to. The source wrote it for the element, so the
// reference is destructured away at the binding — which Rust allows for a value it can copy, and
// which is why an element it cannot copy is refused rather than silently borrowed.
function emitBorrowedElementClosureRust(expression: Readonly<IrExpression> | undefined, context: EmitContext): string {
  if (expression?.kind !== 'function') {
    return emissionError(context, 'filtering requires a closure written where the predicate is passed');
  }
  const parameters = expression.parameters.map((parameter, index) => {
    if (index > 0) return getBindingTargetNameRust(parameter.binding, context);
    if (!isIrTypeCopyValueRust(parameter.type)) {
      emissionError(context, 'filtering an element Rust cannot copy requires a borrowed predicate lowering');
    }
    return `&${getBindingTargetNameRust(parameter.binding, context)}`;
  });
  const body = expression.expression
    ? normalizeSourceTextGrouping(emitExpression(expression.expression, context))
    : `{\n${indentSourceLines(emitStatements(expression.body, context)).join('\n')}\n}`;
  return `|${parameters.join(', ')}| ${body}`;
}

function emitIteratorCallbackWrapperRust(
  expression: Readonly<IrExpression>,
  emittedCallee: string,
  context: EmitContext,
): string {
  const name = getGeneratedTargetNameRust('x', context);
  return `|${name}| ${emittedCallee}(${name})`;
}

function emitArrayPredicatePositionRust(
  receiver: string,
  callback: Readonly<IrExpression> | undefined,
  emittedCallback: string | undefined,
  targetName: string,
  context: EmitContext,
): string {
  let parameterCount: number | undefined;
  if (callback?.kind === 'function') {
    parameterCount = callback.parameters.length;
  } else if (callback?.kind === 'identifier' && callback.reference.kind === 'binding') {
    const callbackType = context.bindingTypes.get(callback.reference.binding.id);
    if (callbackType?.kind === 'function') parameterCount = callbackType.parameters.length;
  }
  if (!callback || !emittedCallback || parameterCount === undefined || parameterCount < 1 || parameterCount > 2) {
    emissionError(context, 'array findIndex requires a statically known one- or two-parameter Rust predicate');
  }
  const index = getGeneratedTargetNameRust('predicate_index', context);
  const element = getGeneratedTargetNameRust('predicate_element', context);
  const arguments_ = [`${element}.clone()`, ...(parameterCount === 2 ? [`${index} as f64`] : [])];
  return `${receiver}.iter().enumerate().${targetName}(|(${index}, ${element})| (${emittedCallback})(${arguments_.join(', ')})).map(|i| i as f64).unwrap_or(-1.0)`;
}

function isIrSelfFieldNonCopyRust(fieldName: string, context: EmitContext): boolean {
  for (const declaration of context.module.declarations) {
    if (declaration.kind !== 'class') continue;
    const field = declaration.fields.find((candidate) => !candidate.static && candidate.name === fieldName);
    if (field) return !isIrTypeCopyValueRust(field.type);
  }
  return false;
}

function isIrTypeCopyValueRust(type: Readonly<IrType>): boolean {
  return type.kind === 'primitive' && (type.name === 'boolean' || type.name === 'number');
}

// An index, in the form Rust counts with. A literal whole number is written as one; anything else is
// a value in the neutral numeric type and has to be converted.
function emitIndexOperandRust(expression: Readonly<IrExpression>, context: EmitContext): string {
  return expression.kind === 'literal' && typeof expression.value === 'number' && Number.isInteger(expression.value)
    ? String(expression.value)
    : `${emitExpression(expression, context)} as usize`;
}

function emitBorrowedNarrowedReceiverRust(object: Readonly<IrExpression>, context: EmitContext): string | undefined {
  if (object.kind !== 'identifier' || object.reference.kind !== 'binding') return undefined;
  if (object.presence !== 'narrowedPresent') return undefined;
  if (!context.nullableBindingIds.has(object.reference.binding.id)) return undefined;
  return `${emitIdentifierReferenceRust(object.reference, context)}.as_ref().unwrap()`;
}

// A value on its way into a binding that can hold nothing. The source language stores a value and an
// absence in one place without saying so; Rust's `Option` says so, and a present value has to be
// wrapped to enter it. A value that is already optional passes through: it is already the shape.
function emitOptionalTargetOperandRust(
  target: Readonly<IrExpression>,
  value: Readonly<IrExpression>,
  context: EmitContext,
): string {
  const source = emitExpression(value, context);
  if (target.kind !== 'identifier' || target.reference.kind !== 'binding') return source;
  if (!context.nullableBindingIds.has(target.reference.binding.id)) return source;
  const alreadyOptional = isIrExpressionOptionShapedRust(value, context);
  return alreadyOptional ? source : `Some(${source})`;
}

// Text in a position Rust borrows rather than owns. A literal is already a `&str` before it is
// owned, so the ownership is simply not taken; anything else is borrowed from the value it names.
function emitBorrowedTextRust(expression: Readonly<IrExpression>, context: EmitContext): string {
  return expression.kind === 'literal' && typeof expression.value === 'string'
    ? JSON.stringify(expression.value)
    : `&${emitExpression(expression, context)}`;
}

// A constructor that does nothing but fill its own fields is a Rust struct literal, which is the one
// constructor shape Rust has. The body must assign every instance field exactly once and read none of
// them back: a field literal cannot see a field the same literal is still building.
function getIrClassConstructorFieldAssignmentsRust(
  declaration: Readonly<IrClassDeclaration>,
  statelessBase: boolean,
): ReadonlyArray<{ name: string; value: Readonly<IrExpression> }> | undefined {
  const constructor = declaration.classConstructor;
  const instanceFields = declaration.fields.filter((field) => !field.static);
  if (!constructor || instanceFields.length === 0) return undefined;
  if (instanceFields.some((field) => field.initializer)) return undefined;
  const assigned: Array<{ name: string; value: Readonly<IrExpression> }> = [];
  for (const statement of constructor.body) {
    // A base that holds no state has nothing to initialize, so the call that would have initialized
    // it does nothing and leaves nothing for the struct literal to say.
    if (statelessBase && isIrStatementSuperConstructorCallRust(statement)) continue;
    if (statement.kind !== 'expression' || statement.expression.kind !== 'assignment') return undefined;
    const { left, operator, right } = statement.expression;
    if (operator !== '=' || left.kind !== 'property' || left.object.kind !== 'identifier') return undefined;
    if (left.object.reference.kind !== 'this' || left.optional) return undefined;
    if (assigned.some((field) => field.name === left.name)) return undefined;
    if (hasIrExpressionThisReferenceRust(right)) return undefined;
    assigned.push({ name: left.name, value: right });
  }
  return assigned.length === instanceFields.length &&
    instanceFields.every((field) => assigned.some((entry) => entry.name === field.name))
    ? assigned
    : undefined;
}

function getIrClassMethodParameterPlanRust(
  method: Readonly<IrClassMethod>,
  declaration: Readonly<IrClassDeclaration>,
  module: Readonly<IrModule>,
  context: EmitContext,
): IrClassMethodParameterPlanRust | undefined {
  const returnRepresentation = getRustSharedClassTypeRepresentationRust(method.returns, context);
  const returnClass = returnRepresentation
    ? ({
        classType: getRustSharedClassPayloadTypeRust(method.returns, returnRepresentation, context),
        representation: returnRepresentation,
      } as const)
    : undefined;
  if (
    method.abstract ||
    method.accessor !== undefined ||
    method.async ||
    method.branded ||
    method.overloads.length > 0 ||
    method.static ||
    method.typeParameters.length > 0 ||
    (!returnClass &&
      (method.returns.kind !== 'primitive' ||
        (method.returns.name !== 'boolean' &&
          method.returns.name !== 'number' &&
          method.returns.name !== 'string' &&
          method.returns.name !== 'void')))
  ) {
    return undefined;
  }
  if (returnClass) {
    const location = getIrClassDeclarationLocationForTypeRust(returnClass.classType, context, module);
    if (!location || !isIrSimpleMethodParameterClassRust(location.declaration)) return undefined;
  }
  const optionalClassParameters = new Map<
    number,
    Readonly<{ classType: Readonly<IrType>; representation: RustOptionalSharedClassRepresentation }>
  >();
  const requiredClassTypes = new Map<number, Readonly<IrType>>();
  for (const [position, parameter] of method.parameters.entries()) {
    if (
      !parameter.initializer &&
      !parameter.optional &&
      !parameter.rest &&
      isIrRequiredPrimitiveTypeRust(parameter.type)
    ) {
      continue;
    }
    if (position !== method.parameters.length - 1 || parameter.initializer || parameter.rest) {
      return undefined;
    }
    const representation = parameter.optional
      ? parameter.type.kind === 'named' && parameter.type.typeArguments.length === 0
        ? 'optional-undefined-shared-ref-cell-class'
        : undefined
      : getRustSharedClassTypeRepresentationRust(parameter.type, context);
    if (
      !representation ||
      (representation !== 'shared-ref-cell-class' && !isRustOptionalSharedClassRepresentation(representation))
    ) {
      return undefined;
    }
    const classType = parameter.optional
      ? parameter.type
      : isRustOptionalSharedClassRepresentation(representation)
        ? getRustSharedClassPayloadTypeRust(parameter.type, representation, context)
        : parameter.type;
    const location = getIrClassDeclarationLocationForTypeRust(classType, context, module);
    if (!location || !isIrSimpleMethodParameterClassRust(location.declaration)) return undefined;
    if (isRustOptionalSharedClassRepresentation(representation)) {
      optionalClassParameters.set(position, { classType, representation });
    } else {
      requiredClassTypes.set(position, classType);
    }
  }
  if (optionalClassParameters.size + requiredClassTypes.size > 1) return undefined;
  const mutatedClassPositions = getIrClassMethodParameterMutationPositionsRust(
    method,
    requiredClassTypes,
    optionalClassParameters,
    returnClass?.representation,
    module,
    context,
  );
  if (!mutatedClassPositions) return undefined;
  const requiredClassParameters = new Map(
    [...requiredClassTypes].map(([position, classType]) => [
      position,
      {
        classType,
        representation: mutatedClassPositions.has(position)
          ? ('mutable-borrowed-class' as const)
          : ('borrowed-class' as const),
      },
    ]),
  );
  return {
    identity: `${module.packageName}\0${module.source}\0${declaration.binding.id}\0${method.name}`,
    mutatedClassPositions,
    optionalClassParameters,
    requiredClassParameters,
    returnClass,
  };
}

function getIrClassMethodParameterMutationPositionsRust(
  method: Readonly<IrClassMethod>,
  requiredClassTypes: ReadonlyMap<number, Readonly<IrType>>,
  optionalClassParameters: IrClassMethodParameterPlanRust['optionalClassParameters'],
  returnRepresentation: RustSharedClassRepresentation | undefined,
  module: Readonly<IrModule>,
  context: EmitContext,
): ReadonlySet<number> | undefined {
  const classParametersById = new Map(
    [
      ...[...requiredClassTypes].map(([position, classType]) => ({
        classType,
        optional: false,
        position,
        representation: undefined,
      })),
      ...[...optionalClassParameters].map(([position, carrier]) => ({
        classType: carrier.classType,
        optional: true,
        position,
        representation: carrier.representation,
      })),
    ].flatMap((record) => {
      const parameter = method.parameters[record.position];
      return parameter ? [[parameter.binding.id, { ...record, parameter }] as const] : [];
    }),
  );
  const mutatedClassPositions = new Set<number>();
  const mutatedOptionalParameterIds = new Set<string>();
  const sentinelCheckedOptionalParameterIds = new Set<string>();
  const allowedReferences = new WeakSet<object>();
  const references: object[] = [];
  const projected = new Set<string>();
  const returnStatement = method.body.at(-1);
  if (
    isRustOptionalSharedClassRepresentation(returnRepresentation) &&
    returnStatement?.kind === 'return' &&
    returnStatement.expression
  ) {
    const localVariables = new Map(
      method.body.flatMap((statement) =>
        statement.kind === 'variable'
          ? statement.declarations.flatMap((variable) =>
              'binding' in variable && !variable.mutable && variable.initializer
                ? [[variable.binding.id, variable.initializer] as const]
                : [],
            )
          : [],
      ),
    );
    const allowReturnedParameter = (
      expression: Readonly<IrExpression>,
      visitingBindings: ReadonlySet<string> = new Set(),
    ): void => {
      if (expression.kind === 'conditional') {
        allowReturnedParameter(expression.whenTrue, visitingBindings);
        allowReturnedParameter(expression.whenFalse, visitingBindings);
        return;
      }
      if (expression.kind !== 'identifier' || expression.reference.kind !== 'binding') return;
      const bindingId = expression.reference.binding.id;
      const record = classParametersById.get(bindingId);
      if (record?.optional) {
        allowedReferences.add(expression);
        projected.add(record.parameter.binding.id);
        return;
      }
      if (visitingBindings.has(bindingId)) return;
      const initializer = localVariables.get(bindingId);
      if (!initializer) return;
      allowReturnedParameter(initializer, new Set(visitingBindings).add(bindingId));
    };
    allowReturnedParameter(returnStatement.expression);
  }
  let supported = true;
  for (const statement of method.body) {
    analyzeIrStatementSubtreeTraversal(statement, {
      expression(expression) {
        if (expression.kind === 'await') {
          supported = false;
          return false;
        }
        if (expression.kind === 'function') {
          if ([...classParametersById].some(([id]) => irExpressionUsesBindingRust(expression, id))) {
            supported = false;
          }
          return false;
        }
        if (expression.kind === 'assignment') {
          const usesClassParameter = [...classParametersById].some(([id]) =>
            irExpressionUsesBindingRust(expression.left, id),
          );
          if (usesClassParameter) {
            const left = expression.left;
            const classTarget =
              left.kind === 'property' &&
              !left.optional &&
              left.structuralAccess === undefined &&
              left.object.kind === 'identifier' &&
              left.object.reference.kind === 'binding'
                ? { bindingId: left.object.reference.binding.id, object: left.object }
                : undefined;
            const record = classTarget ? classParametersById.get(classTarget.bindingId) : undefined;
            const location = record
              ? getIrClassDeclarationLocationForTypeRust(record.classType, context, module)
              : undefined;
            const field =
              left.kind === 'property'
                ? location?.declaration.fields.find((candidate) => !candidate.static && candidate.name === left.name)
                : undefined;
            if (
              !record ||
              (record.optional && classTarget?.object.presence !== 'narrowedPresent') ||
              !field ||
              !isIrRequiredPrimitiveClassFieldRust(field)
            ) {
              supported = false;
            } else {
              mutatedClassPositions.add(record.position);
              if (record.optional) mutatedOptionalParameterIds.add(record.parameter.binding.id);
            }
          }
        }
        if (
          expression.kind === 'unary' &&
          (expression.operator === '++' || expression.operator === '--' || expression.operator === 'delete') &&
          [...classParametersById].some(([id]) => irExpressionUsesBindingRust(expression.operand, id))
        ) {
          supported = false;
        }
        if (expression.kind === 'binary' && (expression.operator === '===' || expression.operator === '!==')) {
          const pairs = [
            [expression.left, expression.right],
            [expression.right, expression.left],
          ] as const;
          for (const [candidate, sentinel] of pairs) {
            const record =
              candidate.kind === 'identifier' && candidate.reference.kind === 'binding'
                ? classParametersById.get(candidate.reference.binding.id)
                : undefined;
            const expectedSentinel = record?.representation
              ? getRustOptionalSharedClassSentinel(record.representation)
              : undefined;
            if (
              record?.optional &&
              expectedSentinel !== undefined &&
              getIrSharedClassSentinelExpressionRust(sentinel) === expectedSentinel
            ) {
              allowedReferences.add(candidate);
              sentinelCheckedOptionalParameterIds.add(record.parameter.binding.id);
            }
          }
        }
        if (
          expression.kind === 'property' &&
          !expression.optional &&
          expression.structuralAccess === undefined &&
          expression.object.kind === 'identifier' &&
          expression.object.reference.kind === 'binding'
        ) {
          const record = classParametersById.get(expression.object.reference.binding.id);
          const location = record
            ? getIrClassDeclarationLocationForTypeRust(record.classType, context, module)
            : undefined;
          const field = location?.declaration.fields.find(
            (candidate) => !candidate.static && candidate.name === expression.name,
          );
          if (
            record &&
            (!record.optional || expression.object.presence === 'narrowedPresent') &&
            field &&
            isIrRequiredPrimitiveClassFieldRust(field)
          ) {
            allowedReferences.add(expression.object);
            projected.add(record.parameter.binding.id);
          }
        }
        if (
          expression.kind === 'identifier' &&
          expression.reference.kind === 'binding' &&
          classParametersById.has(expression.reference.binding.id)
        ) {
          references.push(expression);
        }
        return undefined;
      },
    });
  }
  return supported &&
    references.every((reference) => allowedReferences.has(reference)) &&
    [...classParametersById].every(([id]) => projected.has(id)) &&
    [...mutatedOptionalParameterIds].every((id) => sentinelCheckedOptionalParameterIds.has(id))
    ? mutatedClassPositions
    : undefined;
}

function isIrSimpleMethodParameterClassRust(declaration: Readonly<IrClassDeclaration>): boolean {
  return (
    !declaration.abstract &&
    declaration.extends === undefined &&
    declaration.implements.length === 0 &&
    declaration.typeParameters.length === 0 &&
    declaration.fields.length > 0 &&
    declaration.fields.every(isIrRequiredPrimitiveClassFieldRust)
  );
}

function getIrClassConstructorParameterPlanRust(
  declaration: Readonly<IrClassDeclaration>,
  module: Readonly<IrModule>,
  context: EmitContext,
): IrClassConstructorParameterPlanRust | undefined {
  const constructor = declaration.classConstructor;
  if (!constructor || constructor.overloads.length > 0) return undefined;
  const retainedField = getIrClassRetainedFieldPlanRust(declaration, module, context);
  const parameterKinds = constructor.parameters.map((parameter, position) => {
    if (
      !parameter.initializer &&
      !parameter.optional &&
      !parameter.rest &&
      isIrRequiredPrimitiveTypeRust(parameter.type)
    ) {
      return 'primitive' as const;
    }
    const retainedCarrier = getIrDirectRetainedClassCarrierPlanRust(parameter.type, module, context);
    const retainedLocation = retainedCarrier
      ? getIrClassDeclarationLocationForTypeRust(retainedCarrier.classType, context, module)
      : undefined;
    if (
      retainedField &&
      retainedCarrier &&
      retainedLocation &&
      position === constructor.parameters.length - 1 &&
      !parameter.optional &&
      !parameter.initializer &&
      !parameter.rest &&
      retainedCarrier.representation === retainedField.carrier.representation &&
      isSameIrClassDeclarationLocationRust(retainedLocation, retainedField.payload)
    ) {
      return { carrier: retainedField.carrier, kind: 'retainedClass', location: retainedField.payload } as const;
    }
    const location = getIrClassDeclarationLocationForTypeRust(parameter.type, context, module);
    if (!location) return 'other' as const;
    if (
      parameter.initializer ||
      parameter.rest ||
      parameter.type.kind !== 'named' ||
      parameter.type.typeArguments.length > 0
    ) {
      return undefined;
    }
    if (!isIrSimpleConstructorOwnerDeclarationRust(location.declaration, location.module, context)) return undefined;
    if (!parameter.optional) return { kind: 'class', location } as const;
    return position === constructor.parameters.length - 1 ? ({ kind: 'optionalClass', location } as const) : undefined;
  });
  if (parameterKinds.some((kind) => kind === undefined || kind === 'other')) return undefined;
  const optionalClassPositions = new Set(
    parameterKinds.flatMap((kind, position) =>
      typeof kind === 'object' && kind.kind === 'optionalClass' ? [position] : [],
    ),
  );
  if (optionalClassPositions.size > 1) return undefined;
  const borrowed = new Set(
    parameterKinds.flatMap((kind, position) => (typeof kind === 'object' && kind.kind === 'class' ? [position] : [])),
  );
  const retainedClassParameters = new Map(
    parameterKinds.flatMap((kind, position) =>
      typeof kind === 'object' && kind.kind === 'retainedClass' ? ([[position, kind.carrier]] as const) : [],
    ),
  );
  const usedClassParameters = new Set<number>();
  const fields = declaration.fields.filter((field) => !field.static);
  for (const statement of constructor.body) {
    if (statement.kind !== 'expression' || statement.expression.kind !== 'assignment') return undefined;
    const assignment = statement.expression;
    const left = assignment.left;
    const right = assignment.right;
    if (
      assignment.operator !== '=' ||
      left.kind !== 'property' ||
      left.optional ||
      left.object.kind !== 'identifier' ||
      left.object.reference.kind !== 'this'
    ) {
      return undefined;
    }
    const targetField = fields.find((field) => field.name === left.name);
    if (!targetField || (targetField !== retainedField?.field && !isIrRequiredPrimitiveClassFieldRust(targetField))) {
      return undefined;
    }
    if (right.kind === 'identifier' && right.reference.kind === 'binding') {
      const parameterBindingId = right.reference.binding.id;
      const position = constructor.parameters.findIndex((parameter) => parameter.binding.id === parameterBindingId);
      const kind = parameterKinds[position];
      if (
        position < 0 ||
        kind === undefined ||
        (targetField === retainedField?.field
          ? typeof kind !== 'object' || kind.kind !== 'retainedClass'
          : kind !== 'primitive')
      ) {
        return undefined;
      }
      if (targetField === retainedField?.field) usedClassParameters.add(position);
      continue;
    }
    if (right.kind === 'conditional') {
      if (
        right.condition.kind !== 'binary' ||
        right.condition.operator !== '===' ||
        right.condition.left.kind !== 'identifier' ||
        right.condition.left.reference.kind !== 'binding' ||
        getIrSharedClassSentinelExpressionRust(right.condition.right) !== 'undefined'
      ) {
        return undefined;
      }
      const parameterBindingId = right.condition.left.reference.binding.id;
      const position = constructor.parameters.findIndex((parameter) => parameter.binding.id === parameterBindingId);
      const kind = parameterKinds[position];
      const projection = right.whenFalse;
      const fallbackType = inferIrExpressionTypeRust(right.whenTrue, context);
      if (
        position < 0 ||
        typeof kind !== 'object' ||
        kind.kind !== 'optionalClass' ||
        projection.kind !== 'property' ||
        projection.optional ||
        projection.structuralAccess !== undefined ||
        projection.object.kind !== 'identifier' ||
        projection.object.reference.kind !== 'binding' ||
        projection.object.reference.binding.id !== parameterBindingId ||
        projection.object.presence !== 'narrowedPresent' ||
        fallbackType?.kind !== 'primitive' ||
        targetField.type.kind !== 'primitive' ||
        fallbackType.name !== targetField.type.name ||
        irExpressionUsesBindingRust(right.whenTrue, parameterBindingId)
      ) {
        return undefined;
      }
      const ownerField = kind.location.declaration.fields.find(
        (field) => !field.static && field.name === projection.name,
      );
      if (
        !ownerField ||
        !isIrRequiredPrimitiveClassFieldRust(ownerField) ||
        ownerField.type.kind !== 'primitive' ||
        ownerField.type.name !== targetField.type.name
      ) {
        return undefined;
      }
      usedClassParameters.add(position);
      continue;
    }
    if (
      right.kind !== 'property' ||
      right.optional ||
      right.structuralAccess !== undefined ||
      right.object.kind !== 'identifier' ||
      right.object.reference.kind !== 'binding'
    ) {
      return undefined;
    }
    const parameterBindingId = right.object.reference.binding.id;
    const position = constructor.parameters.findIndex((parameter) => parameter.binding.id === parameterBindingId);
    const kind = parameterKinds[position];
    if (position < 0 || typeof kind !== 'object' || kind.kind !== 'class') return undefined;
    const ownerField = kind.location.declaration.fields.find((field) => !field.static && field.name === right.name);
    if (
      !ownerField ||
      !isIrRequiredPrimitiveClassFieldRust(ownerField) ||
      ownerField.type.kind !== 'primitive' ||
      targetField.type.kind !== 'primitive' ||
      ownerField.type.name !== targetField.type.name
    ) {
      return undefined;
    }
    usedClassParameters.add(position);
  }
  return [...borrowed, ...optionalClassPositions, ...retainedClassParameters.keys()].every((position) =>
    usedClassParameters.has(position),
  )
    ? { borrowedPositions: borrowed, optionalClassPositions, retainedClassParameters }
    : undefined;
}

function isIrRequiredPrimitiveTypeRust(type: Readonly<IrType>): boolean {
  return type.kind === 'primitive' && (type.name === 'boolean' || type.name === 'number' || type.name === 'string');
}

function isIrRequiredPrimitiveClassFieldRust(field: Readonly<IrClassField>): boolean {
  return (
    !field.abstract &&
    !field.branded &&
    !field.declare &&
    !field.optional &&
    !field.static &&
    field.parameterProperty === undefined &&
    isIrRequiredPrimitiveTypeRust(field.type)
  );
}

function getIrClassRetainedFieldPlanRust(
  declaration: Readonly<IrClassDeclaration>,
  module: Readonly<IrModule>,
  context: EmitContext,
  visiting: ReadonlySet<string> = new Set(),
): IrClassRetainedFieldPlanRust | undefined {
  const ownerKey = `${module.packageName}\0${module.source}\0${declaration.binding.id}`;
  if (visiting.has(ownerKey)) return undefined;
  const candidates = declaration.fields.filter((field) => !isIrRequiredPrimitiveClassFieldRust(field));
  if (candidates.length !== 1) return undefined;
  const field = candidates[0]!;
  if (
    field.abstract ||
    field.branded ||
    field.declare ||
    field.initializer ||
    field.optional ||
    field.static ||
    field.parameterProperty !== undefined
  ) {
    return undefined;
  }
  const carrier = getIrDirectRetainedClassCarrierPlanRust(field.type, module, context);
  if (!carrier || (!field.readonly && carrier.representation !== 'shared-ref-cell-class')) return undefined;
  const payload = getIrClassDeclarationLocationForTypeRust(carrier.classType, context, module);
  if (!payload || isSameIrClassDeclarationLocationRust({ declaration, module }, payload)) return undefined;
  const payloadKey = `${payload.module.packageName}\0${payload.module.source}\0${payload.declaration.binding.id}`;
  if (visiting.has(payloadKey)) return undefined;
  if (
    !isIrSimpleConstructorOwnerDeclarationRust(payload.declaration, payload.module, context) ||
    payload.declaration.fields.some((candidate) => !isIrRequiredPrimitiveClassFieldRust(candidate))
  ) {
    return undefined;
  }
  return { carrier, field, module, payload };
}

function getIrDirectRetainedClassCarrierPlanRust(
  type: Readonly<IrType>,
  module: Readonly<IrModule>,
  context: EmitContext,
): IrRetainedClassCarrierPlanRust | undefined {
  if (type.kind === 'named' && type.typeArguments.length === 0) {
    return getIrClassDeclarationLocationForTypeRust(type, context, module)
      ? { classType: type, representation: 'shared-ref-cell-class' }
      : undefined;
  }
  if (type.kind !== 'union' || type.types.length !== 2) return undefined;
  const sentinel = type.types.find(
    (member): member is Extract<IrType, { kind: 'null' | 'undefined' }> =>
      member.kind === 'null' || member.kind === 'undefined',
  );
  const payload = type.types.find((member) => member !== sentinel);
  if (
    !sentinel ||
    !payload ||
    payload.kind !== 'named' ||
    payload.typeArguments.length > 0 ||
    !getIrClassDeclarationLocationForTypeRust(payload, context, module)
  ) {
    return undefined;
  }
  return {
    classType: payload,
    representation:
      sentinel.kind === 'null' ? 'optional-null-shared-ref-cell-class' : 'optional-undefined-shared-ref-cell-class',
  };
}

function getIrClassRetainedFieldProjectionRust(
  expression: Readonly<Extract<IrExpression, { kind: 'property' }>>,
  context: EmitContext,
): IrClassRetainedFieldPlanRust | undefined {
  if (expression.optional || expression.structuralAccess) return undefined;
  let owner: Readonly<{ declaration: Readonly<IrClassDeclaration>; module: Readonly<IrModule> }> | undefined;
  if (expression.object.kind === 'identifier' && expression.object.reference.kind === 'this') {
    owner = context.classMethodOwner ? { declaration: context.classMethodOwner, module: context.module } : undefined;
  } else {
    const ownerType = getIrSharedClassIdentityExpressionTypeRust(expression.object, context);
    const ownerRepresentation = getRustSharedClassExpressionRepresentationRust(expression.object, context);
    if (
      isRustOptionalSharedClassRepresentation(ownerRepresentation) &&
      (!('presence' in expression.object) || expression.object.presence !== 'narrowedPresent')
    ) {
      return undefined;
    }
    const payloadType =
      ownerType && isRustOptionalSharedClassRepresentation(ownerRepresentation)
        ? getRustSharedClassPayloadTypeRust(ownerType, ownerRepresentation, context)
        : ownerType;
    owner = getIrClassDeclarationLocationForTypeRust(payloadType, context, context.module);
  }
  if (!owner) return undefined;
  const plan = getIrClassRetainedFieldPlanRust(owner.declaration, owner.module, context);
  return plan?.field.name === expression.name ? plan : undefined;
}

function emitRetainedClassFieldCarrierRust(
  expression: Readonly<Extract<IrExpression, { kind: 'property' }>>,
  context: EmitContext,
  targetRepresentation?: RustSharedClassRepresentation,
): string | undefined {
  const plan = getIrClassRetainedFieldProjectionRust(expression, context);
  if (!plan) return undefined;
  context.needsRcImport.add('Rc');
  context.needsRefCellImport.add('RefCell');
  const field = safeRustValueName(plan.field.name);
  const sourceRepresentation = plan.carrier.representation;
  const target =
    targetRepresentation ??
    (isRustOptionalSharedClassRepresentation(sourceRepresentation) && expression.presence === 'narrowedPresent'
      ? 'shared-ref-cell-class'
      : sourceRepresentation);
  let projected: string;
  if (expression.object.kind === 'identifier' && expression.object.reference.kind === 'this') {
    projected =
      sourceRepresentation === 'shared-ref-cell-class' ? `Rc::clone(&self.${field})` : `self.${field}.clone()`;
  } else {
    const owner = emitSharedClassBorrowReceiverRust(expression.object, false, context);
    if (!owner) return undefined;
    projected =
      sourceRepresentation === 'shared-ref-cell-class'
        ? `{ Rc::clone(&${owner}.${field}) }`
        : `{ ${owner}.${field}.clone() }`;
  }
  if (sourceRepresentation === target) return projected;
  if (sourceRepresentation === 'shared-ref-cell-class') return `Some(${projected})`;
  if (target === 'shared-ref-cell-class' && expression.presence === 'narrowedPresent') {
    return `${normalizeSourceTextGrouping(projected)}.unwrap()`;
  }
  return undefined;
}

function isSameIrClassDeclarationLocationRust(
  left: Readonly<{ declaration: Readonly<IrClassDeclaration>; module: Readonly<IrModule> }>,
  right: Readonly<{ declaration: Readonly<IrClassDeclaration>; module: Readonly<IrModule> }>,
): boolean {
  return (
    left.module.packageName === right.module.packageName &&
    left.module.source === right.module.source &&
    left.declaration.binding.id === right.declaration.binding.id
  );
}

function isIrSimpleConstructorOwnerDeclarationRust(
  declaration: Readonly<IrClassDeclaration>,
  module: Readonly<IrModule>,
  context: EmitContext,
): boolean {
  return (
    !declaration.abstract &&
    declaration.extends === undefined &&
    declaration.implements.length === 0 &&
    declaration.typeParameters.length === 0 &&
    declaration.fields.length > 0 &&
    declaration.fields.every(isIrRequiredPrimitiveClassFieldRust) &&
    declaration.methods.every(
      (method) => getIrClassMethodParameterPlanRust(method, declaration, module, context) !== undefined,
    )
  );
}

function isIrExactBorrowedClassArgumentRust(
  expression: Readonly<IrExpression>,
  parameterType: Readonly<IrType>,
  parameterModule: Readonly<IrModule>,
  context: EmitContext,
): boolean {
  if (expression.kind === 'call' && !isIrSharedClassReturnCallRust(expression, context)) return false;
  if (expression.kind !== 'identifier' && expression.kind !== 'call' && expression.kind !== 'new') return false;
  const calledFunction =
    expression.kind === 'call' && expression.callee.kind === 'identifier'
      ? getIrReferencedFunctionRust(expression.callee.reference, context)
      : undefined;
  const argumentType = calledFunction?.returns ?? getIrSharedClassIdentityExpressionTypeRust(expression, context);
  const argumentLocation = getIrClassDeclarationLocationForTypeRust(argumentType, context, context.module);
  const parameterLocation = getIrClassDeclarationLocationForTypeRust(parameterType, context, parameterModule);
  return (
    argumentLocation !== undefined &&
    parameterLocation !== undefined &&
    argumentLocation.module.packageName === parameterLocation.module.packageName &&
    argumentLocation.module.source === parameterLocation.module.source &&
    argumentLocation.declaration.binding.id === parameterLocation.declaration.binding.id
  );
}

function isIrExactRetainedClassCarrierArgumentRust(
  expression: Readonly<IrExpression>,
  expected: IrRetainedClassCarrierPlanRust,
  parameterModule: Readonly<IrModule>,
  context: EmitContext,
): boolean {
  const sentinel = getIrSharedClassSentinelExpressionRust(expression);
  if (sentinel) return getRustOptionalSharedClassSentinel(expected.representation) === sentinel;
  if (expression.kind === 'conditional') {
    return (
      isIrExactRetainedClassCarrierArgumentRust(expression.whenTrue, expected, parameterModule, context) &&
      isIrExactRetainedClassCarrierArgumentRust(expression.whenFalse, expected, parameterModule, context)
    );
  }
  const actualRepresentation = getRustSharedClassExpressionRepresentationRust(expression, context);
  if (!actualRepresentation) return false;
  const compatibleRepresentation =
    actualRepresentation === 'shared-ref-cell-class' ||
    actualRepresentation === expected.representation ||
    (expected.representation === 'shared-ref-cell-class' &&
      'presence' in expression &&
      expression.presence === 'narrowedPresent');
  if (!compatibleRepresentation) return false;
  const argumentType = getIrSharedClassIdentityExpressionTypeRust(expression, context);
  if (!argumentType) return false;
  const argumentLocation = getIrClassDeclarationLocationForTypeRust(
    getRustSharedClassPayloadTypeRust(argumentType, actualRepresentation, context),
    context,
    context.module,
  );
  const parameterLocation = getIrClassDeclarationLocationForTypeRust(expected.classType, context, parameterModule);
  return Boolean(
    argumentLocation && parameterLocation && isSameIrClassDeclarationLocationRust(argumentLocation, parameterLocation),
  );
}

function getIrClassCompositionConstructorRust(
  declaration: Readonly<IrClassDeclaration>,
  base: Readonly<IrClassDeclaration>,
):
  | Readonly<{
      superArguments: readonly Readonly<IrExpression>[];
      childFields: ReadonlyArray<{ name: string; value: Readonly<IrExpression> }>;
    }>
  | undefined {
  const constructor = declaration.classConstructor;
  const instanceFields = declaration.fields.filter((field) => !field.static);
  if (!constructor || instanceFields.length === 0) return undefined;
  let superArguments: readonly Readonly<IrExpression>[] | undefined;
  const childFields: Array<{ name: string; value: Readonly<IrExpression> }> = [];
  for (const statement of constructor.body) {
    if (!superArguments && isIrStatementSuperConstructorCallRust(statement)) {
      const call = (statement as { expression: Extract<IrExpression, { kind: 'call' }> }).expression;
      superArguments = call.arguments;
      continue;
    }
    if (statement.kind !== 'expression' || statement.expression.kind !== 'assignment') return undefined;
    const { left, operator, right } = statement.expression;
    if (operator !== '=' || left.kind !== 'property' || left.object.kind !== 'identifier') return undefined;
    if (left.object.reference.kind !== 'this' || left.optional) return undefined;
    if (base.fields.some((field) => !field.static && field.name === left.name)) return undefined;
    if (childFields.some((field) => field.name === left.name)) return undefined;
    if (hasIrExpressionThisReferenceRust(right)) return undefined;
    childFields.push({ name: left.name, value: right });
  }
  if (!superArguments) return undefined;
  return childFields.length === instanceFields.length &&
    instanceFields.every((field) => childFields.some((entry) => entry.name === field.name))
    ? { superArguments, childFields }
    : undefined;
}

function isIrCompositionBaseMemberRust(name: string, base: Readonly<IrClassDeclaration>): boolean {
  return (
    base.fields.some((field) => !field.static && field.name === name) ||
    base.methods.some((method) => !method.static && method.name === name)
  );
}

function isIrStatementSuperConstructorCallRust(statement: Readonly<IrStatement>): boolean {
  return (
    statement.kind === 'expression' &&
    statement.expression.kind === 'call' &&
    statement.expression.callee.kind === 'identifier' &&
    statement.expression.callee.reference.kind === 'super'
  );
}

function collectAsyncTryStatementsRust(
  module: Readonly<IrModule>,
  analysis: Readonly<CompilerAsyncStateMachineAnalysis>,
): ReadonlySet<object> {
  const result = new Set<object>();
  for (const machine of analysis.machines) {
    for (const state of machine.states) {
      for (const step of state.steps) {
        if (step.kind !== 'suspend' || step.rejectState === undefined) continue;
        const tryStatement = getEnclosingTryStatementRust(module, step.path);
        if (tryStatement) result.add(tryStatement);
      }
    }
  }
  return result;
}

function getEnclosingTryStatementRust(
  module: Readonly<IrModule>,
  suspensionPath: CompilerIrTraversalPath,
): object | undefined {
  for (let i = suspensionPath.length - 1; i >= 0; i--) {
    if (suspensionPath[i] === 'tryBody') {
      return getIrModuleTraversalPathValue(module, suspensionPath.slice(0, i)) as object;
    }
  }
  return undefined;
}

function collectIrStatementAsyncTryCompletionEvidenceRust(
  statement: Readonly<IrStatement>,
): RustAsyncTryCompletionEvidence {
  const abruptStatements: Array<Readonly<{ path: CompilerIrTraversalPath; statement: Readonly<IrStatement> }>> = [];
  const nestedFunctionPaths: CompilerIrTraversalPath[] = [];
  const suspensionPaths: CompilerIrTraversalPath[] = [];
  analyzeIrStatementSubtreeTraversal(statement, {
    expression(expression, path_) {
      if (expression.kind === 'await') suspensionPaths.push(path_);
    },
    functionSignature(_signature, path_) {
      nestedFunctionPaths.push(path_);
    },
    statement(candidate, path_) {
      if (
        candidate.kind === 'return' ||
        candidate.kind === 'throw' ||
        candidate.kind === 'break' ||
        candidate.kind === 'continue'
      ) {
        abruptStatements.push({ path: path_, statement: candidate });
      }
      if (candidate.kind === 'forOf' && candidate.await) suspensionPaths.push(path_);
    },
  });
  const isNestedFunctionPath = (path_: CompilerIrTraversalPath): boolean =>
    nestedFunctionPaths.some(
      (functionPath) => functionPath.length < path_.length && isRustTraversalPathPrefix(functionPath, path_),
    );
  return {
    abruptStatements: abruptStatements
      .filter(({ path }) => !isNestedFunctionPath(path))
      .map(({ statement: candidate }) => candidate),
    suspensionCount: suspensionPaths.filter((path_) => !isNestedFunctionPath(path_)).length,
  };
}

function hasIrStatementNestedFinallyRust(statement: Readonly<IrStatement>): boolean {
  const nestedFinallyPaths: CompilerIrTraversalPath[] = [];
  const nestedFunctionPaths: CompilerIrTraversalPath[] = [];
  analyzeIrStatementSubtreeTraversal(statement, {
    functionSignature(_signature, path_) {
      nestedFunctionPaths.push(path_);
    },
    statement(candidate, path_) {
      if (candidate.kind === 'try' && candidate.finallyBody) nestedFinallyPaths.push(path_);
    },
  });
  return nestedFinallyPaths.some(
    (path_) =>
      !nestedFunctionPaths.some(
        (functionPath) => functionPath.length < path_.length && isRustTraversalPathPrefix(functionPath, path_),
      ),
  );
}

function assertIrSynchronousTryFinallyCompletionRust(
  statement: Readonly<Extract<IrStatement, { kind: 'try' }>> & { finallyBody: IrStatement },
  context: EmitContext,
): void {
  const rule = 'rust-sync-try-finally-completion-unrepresented';
  if (statement.catchClause) {
    emissionRuleError(context, 'synchronous try/finally with catch requires a general Rust completion record', rule);
  }
  const regions = [
    { body: statement.tryBody, name: 'protected body' },
    { body: statement.finallyBody, name: 'finalizer' },
  ] as const;
  for (const region of regions) {
    if (hasIrStatementNestedFinallyRust(region.body)) {
      emissionRuleError(context, `synchronous try/finally ${region.name} contains a nested finally`, rule);
    }
    const transfer = collectIrStatementAsyncTryCompletionEvidenceRust(region.body).abruptStatements.find(
      (candidate) => candidate.kind !== 'throw',
    );
    if (!transfer) continue;
    const labeled = (transfer.kind === 'break' || transfer.kind === 'continue') && transfer.target ? 'labeled ' : '';
    emissionRuleError(
      context,
      `synchronous try/finally ${region.name} contains ${labeled}${transfer.kind} control transfer`,
      rule,
    );
  }
}

function isIrCatchBindingReferenceRust(expression: Readonly<IrExpression>, bindingId: string): boolean {
  return expression.kind === 'identifier' &&
    expression.reference.kind === 'binding' &&
    expression.reference.binding.id === bindingId
    ? true
    : expression.kind === 'cast'
      ? isIrCatchBindingReferenceRust(expression.expression, bindingId)
      : false;
}

function assertIrAsyncTaskCatchBindingUsesRust(
  statement: Readonly<Extract<IrStatement, { kind: 'try' }>>,
  context: EmitContext,
): void {
  const catchClause = statement.catchClause;
  const binding = catchClause?.binding;
  if (!binding) return;
  let unsupportedUse: 'identity' | 'member' | undefined;
  analyzeIrStatementSubtreeTraversal(catchClause.body, {
    expression(expression) {
      if (
        expression.kind === 'property' &&
        isIrCatchBindingReferenceRust(expression.object, binding.id) &&
        expression.member?.receiver !== 'string'
      ) {
        unsupportedUse = 'member';
        return false;
      }
      if (expression.kind === 'element' && isIrCatchBindingReferenceRust(expression.object, binding.id)) {
        unsupportedUse = 'member';
        return false;
      }
      if (expression.kind === 'call' && isIrCatchBindingReferenceRust(expression.callee, binding.id)) {
        unsupportedUse = 'identity';
        return false;
      }
      if (
        expression.kind === 'unary' &&
        expression.operator === 'typeof' &&
        isIrCatchBindingReferenceRust(expression.operand, binding.id)
      ) {
        unsupportedUse = 'identity';
        return false;
      }
      if (expression.kind !== 'binary') return undefined;
      const left = isIrCatchBindingReferenceRust(expression.left, binding.id);
      const right = isIrCatchBindingReferenceRust(expression.right, binding.id);
      if (!left && !right) return undefined;
      if (
        expression.operator === '==' ||
        expression.operator === '===' ||
        expression.operator === '!=' ||
        expression.operator === '!==' ||
        expression.operator === 'instanceof' ||
        expression.operator === 'in'
      ) {
        unsupportedUse = 'identity';
        return false;
      }
      return undefined;
    },
  });
  if (!unsupportedUse) return;
  emissionError(
    context,
    `async task catch binding ${binding.name} uses ${unsupportedUse} semantics beyond the runtime String rejection carrier`,
    'rust-runtime-error-carrier-incomplete',
    'target-runtime',
  );
}

function getIrTryProtectedCompletionEvidenceRust(statement: Readonly<Extract<IrStatement, { kind: 'try' }>>): {
  readonly abruptStatements: readonly Readonly<IrStatement>[];
  readonly suspensionCount: number;
} {
  const evidence = [
    collectIrStatementAsyncTryCompletionEvidenceRust(statement.tryBody),
    ...(statement.catchClause ? [collectIrStatementAsyncTryCompletionEvidenceRust(statement.catchClause.body)] : []),
    ...(statement.finallyBody ? [collectIrStatementAsyncTryCompletionEvidenceRust(statement.finallyBody)] : []),
  ];
  return {
    abruptStatements: evidence.flatMap((item) => item.abruptStatements),
    suspensionCount: evidence.reduce((count, item) => count + item.suspensionCount, 0),
  };
}

function assertIrAsyncTryProtectedEvidenceRust(
  statement: Readonly<Extract<IrStatement, { kind: 'try' }>>,
  context: EmitContext,
  supportsTwoSuspensions: boolean,
): void {
  const evidence = getIrTryProtectedCompletionEvidenceRust(statement);
  if (evidence.suspensionCount !== 1 && !(evidence.suspensionCount === 2 && supportsTwoSuspensions)) {
    emissionRuleError(
      context,
      'async try protection requires exactly one direct suspension and no later or neighboring suspension',
      'rust-async-try-completion-unrepresented',
    );
  }
  if (evidence.abruptStatements.some((candidate) => candidate.kind === 'throw')) {
    emissionRuleError(
      context,
      'async try protection with an explicit source throw requires a general completion record',
      'rust-async-try-completion-unrepresented',
    );
  }
}

function getIrDirectStatementsRust(statement: Readonly<IrStatement>): readonly Readonly<IrStatement>[] {
  return statement.kind === 'block' ? statement.statements : [statement];
}

function getIrAsyncTryProtectedTaskReturnStepRust(
  body: Readonly<IrStatement>,
  context: EmitContext,
): RustAsyncTryProtectedTaskReturnStep | undefined {
  if (body.kind === 'block' && body.label) return undefined;
  const tail = getIrDirectStatementsRust(body).at(-1);
  if (
    tail?.kind !== 'return' ||
    !tail.expression ||
    tail.expression.kind === 'await' ||
    !canIrExpressionDenoteProtectedTaskSettlementRust(tail.expression, context)
  ) {
    return undefined;
  }
  return { expression: tail.expression, statement: tail };
}

function getIrAsyncTryDirectAwaitStepRust(statement: Readonly<IrStatement>): RustAsyncTryDirectAwaitStep | undefined {
  if (statement.kind === 'return' && statement.expression?.kind === 'await') {
    return { awaitTarget: statement.expression.expression, kind: 'return' };
  }
  if (statement.kind === 'expression') {
    if (statement.expression.kind === 'await') {
      return { awaitTarget: statement.expression.expression, kind: 'expression' };
    }
    if (statement.expression.kind === 'assignment' && statement.expression.right.kind === 'await') {
      return {
        assignment: statement.expression,
        awaitTarget: statement.expression.right.expression,
        kind: 'assignment',
      };
    }
    return undefined;
  }
  if (statement.kind !== 'variable' || statement.declarations.length !== 1) return undefined;
  const variable = statement.declarations[0]!;
  return 'binding' in variable && variable.initializer?.kind === 'await'
    ? { awaitTarget: variable.initializer.expression, kind: 'variable', variable }
    : undefined;
}

function getAsyncTryTwoAwaitPlanRust(
  statement: Readonly<Extract<IrStatement, { kind: 'try' }>>,
): RustAsyncTryTwoAwaitPlan | undefined {
  if (!statement.catchClause || statement.finallyBody) return undefined;
  const evidence = getIrTryProtectedCompletionEvidenceRust(statement);
  if (evidence.suspensionCount !== 2 || evidence.abruptStatements.length > 0) return undefined;
  const tryStatements = getIrDirectStatementsRust(statement.tryBody);
  const catchStatements = getIrDirectStatementsRust(statement.catchClause.body);
  if (
    !tryStatements.every((candidate) => candidate.kind === 'expression' || candidate.kind === 'variable') ||
    !catchStatements.every((candidate) => candidate.kind === 'expression' || candidate.kind === 'variable')
  ) {
    return undefined;
  }
  const steps = tryStatements.flatMap((candidate, index) => {
    const step = getIrAsyncTryDirectAwaitStepRust(candidate);
    return step ? [{ index, step }] : [];
  });
  if (steps.length !== 2) return undefined;
  const first = steps[0]!;
  const second = steps[1]!;
  return {
    betweenStatements: tryStatements.slice(first.index + 1, second.index),
    first: first.step,
    postStatements: tryStatements.slice(second.index + 1),
    preStatements: tryStatements.slice(0, first.index),
    second: second.step,
  };
}

function getAsyncTryProtectedTaskCatchPlanRust(
  statement: Readonly<Extract<IrStatement, { kind: 'try' }>>,
  context: EmitContext,
): RustAsyncTryProtectedTaskCatchPlan | undefined {
  if (!statement.catchClause || statement.finallyBody) return undefined;
  const step = getIrAsyncTryProtectedTaskReturnStepRust(statement.tryBody, context);
  if (!step) return undefined;

  const tryStatements = getIrDirectStatementsRust(statement.tryBody);
  const catchStatements = getIrDirectStatementsRust(statement.catchClause.body);
  const tryEvidence = collectIrStatementAsyncTryCompletionEvidenceRust(statement.tryBody);
  const catchEvidence = collectIrStatementAsyncTryCompletionEvidenceRust(statement.catchClause.body);
  const catchTail = catchStatements.at(-1);
  const permittedCatchReturn = catchTail?.kind === 'return' ? catchTail : undefined;
  if (
    (statement.catchClause.body.kind === 'block' && statement.catchClause.body.label) ||
    tryEvidence.suspensionCount !== 0 ||
    catchEvidence.suspensionCount !== 0 ||
    !tryStatements
      .slice(0, -1)
      .every((candidate) => candidate.kind === 'expression' || candidate.kind === 'variable') ||
    !areIrAsyncTryStraightLineStatementsRust(catchStatements) ||
    tryEvidence.abruptStatements.some((candidate) => candidate !== step.statement) ||
    catchEvidence.abruptStatements.some((candidate) => candidate !== permittedCatchReturn)
  ) {
    emissionRuleError(
      context,
      'protected bare FlightTask return without finally requires flat synchronous try/catch arms and one exact terminal task return',
      'rust-async-try-completion-unrepresented',
    );
  }
  return { preStatements: tryStatements.slice(0, -1), step };
}

function getIrAsyncTrySourceThrowMessageRust(
  statement: Readonly<IrStatement>,
  context: EmitContext,
): Readonly<IrExpression> | undefined {
  if (
    statement.kind !== 'throw' ||
    statement.expression.kind !== 'new' ||
    statement.expression.callee.kind !== 'identifier' ||
    statement.expression.callee.reference.kind !== 'ambient' ||
    statement.expression.callee.reference.name !== 'Error' ||
    statement.expression.arguments.length !== 1 ||
    statement.expression.typeArguments.length !== 0
  ) {
    return undefined;
  }
  const message = statement.expression.arguments[0]!;
  const type = inferIrExpressionTypeRust(message, context);
  const resolved = type ? resolveIrTypeAliasValueRust(type, context, new Set()) : undefined;
  return resolved?.kind === 'primitive' && resolved.name === 'string' ? message : undefined;
}

function areIrAsyncTryStraightLineStatementsRust(
  statements: readonly Readonly<IrStatement>[],
  allowTerminalThrow = false,
): boolean {
  return statements.every(
    (statement, index) =>
      statement.kind === 'expression' ||
      statement.kind === 'variable' ||
      ((statement.kind === 'return' || (allowTerminalThrow && statement.kind === 'throw')) &&
        index === statements.length - 1),
  );
}

function doesIrExpressionReferenceBindingRust(expression: Readonly<IrExpression>, bindingId: string): boolean {
  let referencesBinding = false;
  analyzeIrExpressionSubtreeTraversal(expression, {
    expression(candidate) {
      if (
        candidate.kind === 'identifier' &&
        candidate.reference.kind === 'binding' &&
        candidate.reference.binding.id === bindingId
      ) {
        referencesBinding = true;
        return false;
      }
      return undefined;
    },
  });
  return referencesBinding;
}

function isIrAsyncTryCatchBindingMutatedRust(statement: Readonly<IrStatement>, bindingId: string): boolean {
  let mutated = false;
  analyzeIrStatementSubtreeTraversal(statement, {
    expression(expression) {
      const target =
        expression.kind === 'assignment'
          ? expression.left
          : expression.kind === 'unary' && (expression.operator === '++' || expression.operator === '--')
            ? expression.operand
            : undefined;
      if (target && doesIrExpressionReferenceBindingRust(target, bindingId)) {
        mutated = true;
        return false;
      }
      return undefined;
    },
  });
  return mutated;
}

function getIrAsyncTryCatchBindingUseFailureRust(
  statement: Readonly<IrStatement>,
  binding: Readonly<IrBindingIdentity>,
): 'alias' | 'capture' | 'mutation' | 'storage' | 'unused' | undefined {
  if (isIrAsyncTryCatchBindingMutatedRust(statement, binding.id)) return 'mutation';

  let failure: 'alias' | 'capture' | 'storage' | undefined;
  let used = false;
  analyzeIrStatementSubtreeTraversal(statement, {
    expression(expression) {
      if (
        expression.kind === 'identifier' &&
        expression.reference.kind === 'binding' &&
        expression.reference.binding.id === binding.id
      ) {
        used = true;
        return undefined;
      }
      if (expression.kind === 'function' && doesIrExpressionReferenceBindingRust(expression, binding.id)) {
        failure ??= 'capture';
        return undefined;
      }
      if (expression.kind === 'assignment' && isIrCatchBindingReferenceRust(expression.right, binding.id)) {
        failure ??= 'storage';
        return undefined;
      }
      if (
        expression.kind === 'array' &&
        expression.elements.some(
          (element) => element !== undefined && isIrCatchBindingReferenceRust(element, binding.id),
        )
      ) {
        failure ??= 'storage';
        return undefined;
      }
      if (
        expression.kind === 'tuple' &&
        expression.elements.some(
          (element) => element.expression && isIrCatchBindingReferenceRust(element.expression, binding.id),
        )
      ) {
        failure ??= 'storage';
        return undefined;
      }
      if (
        expression.kind === 'object' &&
        expression.members.some((member) =>
          member.kind === 'property' || member.kind === 'computedProperty'
            ? isIrCatchBindingReferenceRust(member.value, binding.id)
            : member.kind === 'spread'
              ? isIrCatchBindingReferenceRust(member.expression, binding.id)
              : false,
        )
      ) {
        failure ??= 'storage';
      }
      return undefined;
    },
    variable(variable) {
      if (variable.initializer && isIrCatchBindingReferenceRust(variable.initializer, binding.id)) {
        failure ??= 'alias';
      }
      return undefined;
    },
  });
  return failure ?? (used ? undefined : 'unused');
}

function getIrAsyncTryCatchRethrowBindingRust(
  statement: Readonly<IrStatement> | undefined,
  binding: Readonly<IrBindingIdentity> | undefined,
  catchBody: Readonly<IrStatement> | undefined,
): Readonly<IrBindingIdentity> | undefined {
  if (
    !statement ||
    !binding ||
    statement.kind !== 'throw' ||
    statement.expression.kind !== 'identifier' ||
    statement.expression.reference.kind !== 'binding' ||
    statement.expression.reference.binding.id !== binding.id ||
    !catchBody ||
    isIrAsyncTryCatchBindingMutatedRust(catchBody, binding.id)
  ) {
    return undefined;
  }
  return binding;
}

function getAsyncTryCatchCompletionPlanRust(
  catchClause: Readonly<NonNullable<Extract<IrStatement, { kind: 'try' }>['catchClause']>>,
  evidence: Readonly<RustAsyncTryCompletionEvidence>,
  context: EmitContext,
): RustAsyncTryCatchCompletionPlan {
  const statements = getIrDirectStatementsRust(catchClause.body);
  if (evidence.suspensionCount === 0) {
    const rethrowBinding = getIrAsyncTryCatchRethrowBindingRust(
      statements.at(-1),
      catchClause.binding,
      catchClause.body,
    );
    return {
      kind: 'straight',
      ...(rethrowBinding ? { rethrowBinding } : {}),
      statements,
    };
  }

  const steps = statements.flatMap((candidate, index) => {
    const step = getIrAsyncTryDirectAwaitStepRust(candidate);
    return step ? [{ index, step }] : [];
  });
  const tail = statements.at(-1);
  const rethrowBinding = getIrAsyncTryCatchRethrowBindingRust(tail, catchClause.binding, catchClause.body);
  const permittedCompletion = tail?.kind === 'return' || (tail?.kind === 'throw' && rethrowBinding) ? tail : undefined;
  const bindingUseFailure = catchClause.binding
    ? getIrAsyncTryCatchBindingUseFailureRust(catchClause.body, catchClause.binding)
    : undefined;
  const oneAwait = evidence.suspensionCount === 1 && steps.length === 1;
  const twoAwaits = evidence.suspensionCount === 2 && steps.length === 2 && steps[0]?.step.kind !== 'return';
  if (
    (catchClause.body.kind === 'block' && catchClause.body.label) ||
    (!oneAwait && !twoAwaits) ||
    !areIrAsyncTryStraightLineStatementsRust(statements, true) ||
    evidence.abruptStatements.some((candidate) => candidate !== permittedCompletion) ||
    bindingUseFailure
  ) {
    emissionRuleError(
      context,
      'async protected awaited catch requires one flat handler with one or two direct awaits, a non-return first await when there are two, only Normal/Return or exact unchanged rethrow completion, and either no binding or one used immutable direct String binding',
      'rust-async-try-completion-unrepresented',
    );
  }
  const first = steps[0]!;
  if (twoAwaits) {
    const second = steps[1]!;
    return {
      betweenStatements: statements.slice(first.index + 1, second.index),
      ...(catchClause.binding ? { binding: catchClause.binding } : {}),
      first: first.step as Exclude<RustAsyncTryDirectAwaitStep, Readonly<{ kind: 'return' }>>,
      kind: 'await-two',
      postStatements: statements.slice(second.index + 1),
      preStatements: statements.slice(0, first.index),
      ...(rethrowBinding ? { rethrowBinding } : {}),
      second: second.step,
    };
  }
  return {
    ...(catchClause.binding ? { binding: catchClause.binding } : {}),
    kind: 'await',
    postStatements: statements.slice(first.index + 1),
    preStatements: statements.slice(0, first.index),
    ...(rethrowBinding ? { rethrowBinding } : {}),
    step: first.step,
  };
}

function getAsyncTryCatchAwaitCountRust(plan: Readonly<RustAsyncTryCatchCompletionPlan> | undefined): number {
  if (!plan || plan.kind === 'straight') return 0;
  return plan.kind === 'await-two' ? 2 : 1;
}

function getAsyncTryNoFinallyAwaitCatchCompletionPlanRust(
  statement: Readonly<Extract<IrStatement, { kind: 'try' }>>,
  context: EmitContext,
): RustAsyncTryNoFinallyAwaitCatchCompletionPlan | undefined {
  const catchClause = statement.catchClause;
  if (!catchClause || statement.finallyBody) return undefined;

  const catchEvidence = collectIrStatementAsyncTryCompletionEvidenceRust(catchClause.body);
  if (catchEvidence.suspensionCount === 0) return undefined;

  const tryStatements = getIrDirectStatementsRust(statement.tryBody);
  const protectedTaskReturn = getIrAsyncTryProtectedTaskReturnStepRust(statement.tryBody, context);
  const tryEvidence = collectIrStatementAsyncTryCompletionEvidenceRust(statement.tryBody);
  const trySteps = tryStatements.flatMap((candidate, index) => {
    const step = getIrAsyncTryDirectAwaitStepRust(candidate);
    return step ? [{ index, step }] : [];
  });
  const tryTail = tryStatements.at(-1);
  const terminalTaskReturn = protectedTaskReturn !== undefined && tryEvidence.suspensionCount === 0;
  const terminalReturnAwait =
    tryEvidence.suspensionCount === 1 &&
    trySteps.length === 1 &&
    trySteps[0]?.index === tryStatements.length - 1 &&
    trySteps[0].step.kind === 'return';
  const nonterminalAwait =
    tryEvidence.suspensionCount === 1 && trySteps.length === 1 && trySteps[0]?.step.kind !== 'return';
  const permittedTryCompletion = tryTail?.kind === 'return' ? tryTail : undefined;

  const catchPlan = getAsyncTryCatchCompletionPlanRust(catchClause, catchEvidence, context);
  if (
    (statement.tryBody.kind === 'block' && statement.tryBody.label) ||
    (!terminalTaskReturn && !terminalReturnAwait && !nonterminalAwait) ||
    !areIrAsyncTryStraightLineStatementsRust(tryStatements) ||
    tryEvidence.abruptStatements.some((candidate) => candidate !== permittedTryCompletion)
  ) {
    emissionRuleError(
      context,
      'async try/catch awaited handler requires one flat protected terminal FlightTask return, terminal return-await, or exactly one direct non-return await with only Normal/direct Return completion',
      'rust-async-try-completion-unrepresented',
    );
  }
  if (catchPlan.kind === 'straight') {
    emissionRuleError(
      context,
      'async try/catch awaited handler requires one or two direct catch awaits',
      'rust-async-try-completion-unrepresented',
    );
  }
  return {
    catchPlan,
    ...(terminalTaskReturn ? { protectedTaskReturn } : {}),
    tryStatements,
  };
}

function getAsyncTryFinalizerCompletionPlanRust(
  finallyBody: Readonly<NonNullable<Extract<IrStatement, { kind: 'try' }>['finallyBody']>>,
  evidence: Readonly<RustAsyncTryCompletionEvidence>,
  context: EmitContext,
): RustAsyncTryFinalizerCompletionPlan {
  const statements = getIrDirectStatementsRust(finallyBody);
  if (evidence.suspensionCount === 0) return { kind: 'straight', statements };

  const steps = statements.flatMap((candidate, index) => {
    const step = getIrAsyncTryDirectAwaitStepRust(candidate);
    return step ? [{ index, step }] : [];
  });
  const oneAwait = evidence.suspensionCount === 1 && steps.length === 1 && steps[0]?.step.kind !== 'return';
  const twoAwaits =
    evidence.suspensionCount === 2 &&
    steps.length === 2 &&
    steps[0]?.step.kind !== 'return' &&
    steps[1]?.step.kind !== 'return';
  if (
    (finallyBody.kind === 'block' && finallyBody.label) ||
    (!oneAwait && !twoAwaits) ||
    !statements.every((candidate) => candidate.kind === 'expression' || candidate.kind === 'variable') ||
    evidence.abruptStatements.length > 0
  ) {
    emissionRuleError(
      context,
      'async try/finally awaited finalizer requires one flat finalizer with exactly one or two direct non-return awaits and no abrupt completion',
      'rust-async-try-completion-unrepresented',
    );
  }
  const first = steps[0]!;
  if (twoAwaits) {
    const second = steps[1]!;
    return {
      betweenStatements: statements.slice(first.index + 1, second.index),
      first: first.step as Exclude<RustAsyncTryDirectAwaitStep, Readonly<{ kind: 'return' }>>,
      kind: 'await-two',
      postStatements: statements.slice(second.index + 1),
      preStatements: statements.slice(0, first.index),
      second: second.step as Exclude<RustAsyncTryDirectAwaitStep, Readonly<{ kind: 'return' }>>,
    };
  }
  return {
    kind: 'await',
    postStatements: statements.slice(first.index + 1),
    preStatements: statements.slice(0, first.index),
    step: first.step as Exclude<RustAsyncTryDirectAwaitStep, Readonly<{ kind: 'return' }>>,
  };
}

function getAsyncTryFinalizerAwaitCountRust(plan: Readonly<RustAsyncTryFinalizerCompletionPlan>): number {
  if (plan.kind === 'straight') return 0;
  return plan.kind === 'await-two' ? 2 : 1;
}

function getAsyncTryFinallyCompletionPlanRust(
  statement: Readonly<Extract<IrStatement, { kind: 'try' }>>,
  context: EmitContext,
): RustAsyncTryFinallyCompletionPlan | undefined {
  if (!statement.finallyBody) return undefined;
  const tryStatements = getIrDirectStatementsRust(statement.tryBody);
  const protectedTaskReturn = getIrAsyncTryProtectedTaskReturnStepRust(statement.tryBody, context);
  const tryEvidence = collectIrStatementAsyncTryCompletionEvidenceRust(statement.tryBody);
  const catchEvidence = statement.catchClause
    ? collectIrStatementAsyncTryCompletionEvidenceRust(statement.catchClause.body)
    : undefined;
  const finallyEvidence = collectIrStatementAsyncTryCompletionEvidenceRust(statement.finallyBody);
  const suspensionCount =
    tryEvidence.suspensionCount + (catchEvidence?.suspensionCount ?? 0) + finallyEvidence.suspensionCount;
  if (suspensionCount === 0 && !protectedTaskReturn) return undefined;

  const catchStatements = statement.catchClause ? getIrDirectStatementsRust(statement.catchClause.body) : undefined;
  const finallyStatements = getIrDirectStatementsRust(statement.finallyBody);
  const catchPlan = statement.catchClause
    ? getAsyncTryCatchCompletionPlanRust(statement.catchClause, catchEvidence!, context)
    : undefined;
  const finalizerPlan = getAsyncTryFinalizerCompletionPlanRust(statement.finallyBody, finallyEvidence, context);
  const trySteps = tryStatements.flatMap((candidate) => {
    const step = getIrAsyncTryDirectAwaitStepRust(candidate);
    return step ? [step] : [];
  });
  const tryTail = tryStatements.at(-1);
  const catchTail = catchStatements?.at(-1);
  const protectedThrowMessage = tryTail ? getIrAsyncTrySourceThrowMessageRust(tryTail, context) : undefined;
  const catchRethrowBinding = catchPlan?.rethrowBinding;
  const permittedReturns = new Set(
    [tryTail, catchTail].filter((candidate): candidate is Readonly<IrStatement> => candidate?.kind === 'return'),
  );
  const permittedTryCompletions = new Set([
    ...permittedReturns,
    ...(tryTail?.kind === 'throw' && protectedThrowMessage ? [tryTail] : []),
  ]);
  const permittedCatchCompletions = new Set([
    ...permittedReturns,
    ...(catchTail?.kind === 'throw' && catchRethrowBinding ? [catchTail] : []),
  ]);
  const flatBodies =
    !(statement.tryBody.kind === 'block' && statement.tryBody.label) &&
    !(statement.catchClause?.body.kind === 'block' && statement.catchClause.body.label) &&
    !(statement.finallyBody.kind === 'block' && statement.finallyBody.label) &&
    areIrAsyncTryStraightLineStatementsRust(tryStatements, true) &&
    (catchStatements === undefined || areIrAsyncTryStraightLineStatementsRust(catchStatements, true)) &&
    finallyStatements.every((candidate) => candidate.kind === 'expression' || candidate.kind === 'variable');
  const exactCompletions =
    tryEvidence.abruptStatements.every((candidate) => permittedTryCompletions.has(candidate)) &&
    (catchEvidence?.abruptStatements.every((candidate) => permittedCatchCompletions.has(candidate)) ?? true) &&
    finallyEvidence.abruptStatements.length === 0;
  const exactSuspensions =
    (trySteps.length > 0 ||
      protectedTaskReturn !== undefined ||
      getAsyncTryCatchAwaitCountRust(catchPlan) > 0 ||
      getAsyncTryFinalizerAwaitCountRust(finalizerPlan) > 0) &&
    tryEvidence.suspensionCount === trySteps.length &&
    (catchEvidence?.suspensionCount ?? 0) === getAsyncTryCatchAwaitCountRust(catchPlan) &&
    finallyEvidence.suspensionCount === getAsyncTryFinalizerAwaitCountRust(finalizerPlan);
  if (!flatBodies || !exactCompletions || !exactSuspensions) {
    emissionRuleError(
      context,
      'async try/finally local completion requires flat Normal/Return arms, one terminal protected Error(String) throw, or one terminal throw of the unchanged catch binding, direct protected awaits, at most two direct catch awaits with an optional used immutable String binding, and at most two direct non-return finalizer awaits',
      'rust-async-try-completion-unrepresented',
    );
  }
  return {
    ...(catchPlan ? { catchPlan } : {}),
    finalizerPlan,
    ...(protectedTaskReturn ? { protectedTaskReturn } : {}),
    tryStatements,
  };
}

function getAsyncTryExpressionAwaitPlanRust(
  statement: Readonly<Extract<IrStatement, { kind: 'try' }>>,
  context: EmitContext,
): RustAsyncTryExpressionAwaitPlan | undefined {
  const tryStatements = getIrDirectStatementsRust(statement.tryBody);
  const awaitStatements = tryStatements.flatMap((candidate, index) =>
    candidate.kind === 'expression' && candidate.expression.kind === 'await'
      ? [{ awaitExpression: candidate.expression, index }]
      : [],
  );
  if (awaitStatements.length === 0) return undefined;
  if (awaitStatements.length !== 1 || statement.catchClause === undefined || statement.finallyBody !== undefined) {
    emissionRuleError(
      context,
      'async try expression-await lowering requires one direct expression statement, one catch, and no finally',
      'rust-async-try-completion-unrepresented',
    );
  }
  const selected = awaitStatements[0]!;
  const preStatements = tryStatements.slice(0, selected.index);
  const postStatements = tryStatements.slice(selected.index + 1);
  const catchStatements = getIrDirectStatementsRust(statement.catchClause.body);
  if (
    !areIrAsyncTryStraightLineStatementsRust(preStatements) ||
    !areIrAsyncTryStraightLineStatementsRust(postStatements) ||
    !areIrAsyncTryStraightLineStatementsRust(catchStatements)
  ) {
    emissionRuleError(
      context,
      'async try expression-await lowering requires straight-line arms with at most one final return',
      'rust-async-try-completion-unrepresented',
    );
  }
  const permittedReturns = new Set(
    [postStatements.at(-1), catchStatements.at(-1)].filter(
      (candidate): candidate is Readonly<IrStatement> => candidate?.kind === 'return',
    ),
  );
  const evidence = getIrTryProtectedCompletionEvidenceRust(statement);
  if (evidence.abruptStatements.some((candidate) => !permittedReturns.has(candidate))) {
    emissionRuleError(
      context,
      'async try expression-await lowering cannot preserve this abrupt completion without a general completion record',
      'rust-async-try-completion-unrepresented',
    );
  }
  return {
    awaitTarget: selected.awaitExpression.expression,
    postStatements,
    preStatements,
  };
}

function getAsyncTryVariableAwaitPlanRust(
  statement: Readonly<Extract<IrStatement, { kind: 'try' }>>,
  context: EmitContext,
): RustAsyncTryVariableAwaitPlan | undefined {
  const tryStatements = getIrDirectStatementsRust(statement.tryBody);
  const awaitStatements = tryStatements.flatMap((candidate, index) => {
    if (candidate.kind !== 'variable') return [];
    const awaited = candidate.declarations.filter((variable) => variable.initializer?.kind === 'await');
    return awaited.length > 0 ? [{ awaited, candidate, index }] : [];
  });
  if (awaitStatements.length === 0) return undefined;
  const selected = awaitStatements[0]!;
  if (
    awaitStatements.length !== 1 ||
    selected.awaited.length !== 1 ||
    selected.candidate.declarations.length !== 1 ||
    statement.catchClause === undefined ||
    statement.finallyBody !== undefined
  ) {
    emissionRuleError(
      context,
      'async try variable-await lowering requires one direct declarator, one catch, and no finally',
      'rust-async-try-completion-unrepresented',
    );
  }
  const variable = selected.awaited[0]!;
  if (!('binding' in variable) || variable.initializer?.kind !== 'await') {
    emissionRuleError(
      context,
      'async try variable-await lowering requires one named direct declarator',
      'rust-async-try-completion-unrepresented',
    );
  }
  const preStatements = tryStatements.slice(0, selected.index);
  const postStatements = tryStatements.slice(selected.index + 1);
  const catchStatements = getIrDirectStatementsRust(statement.catchClause.body);
  if (
    !areIrAsyncTryStraightLineStatementsRust(preStatements) ||
    !areIrAsyncTryStraightLineStatementsRust(postStatements) ||
    !areIrAsyncTryStraightLineStatementsRust(catchStatements)
  ) {
    emissionRuleError(
      context,
      'async try variable-await lowering requires straight-line arms with at most one final return',
      'rust-async-try-completion-unrepresented',
    );
  }
  const permittedReturns = new Set(
    [postStatements.at(-1), catchStatements.at(-1)].filter(
      (candidate): candidate is Readonly<IrStatement> => candidate?.kind === 'return',
    ),
  );
  const evidence = getIrTryProtectedCompletionEvidenceRust(statement);
  if (evidence.abruptStatements.some((candidate) => !permittedReturns.has(candidate))) {
    emissionRuleError(
      context,
      'async try variable-await lowering cannot preserve this abrupt completion without a general completion record',
      'rust-async-try-completion-unrepresented',
    );
  }
  return {
    awaitTarget: variable.initializer.expression,
    postStatements,
    preStatements,
    variable,
  };
}

function emitAsyncTrySettledVariableRust(
  variable: Readonly<IrVariable> & Readonly<{ binding: IrBindingIdentity }>,
  context: EmitContext,
  value = '__value',
): string {
  const type = variable.type ?? context.bindingTypes.get(variable.binding.id);
  if (
    !type ||
    context.cellWrappedBindingIds.has(variable.binding.id) ||
    context.refCellWrappedBindingIds.has(variable.binding.id) ||
    context.sharedArrayBindingIds.has(variable.binding.id) ||
    context.sharedClassBindingIds.has(variable.binding.id) ||
    context.sharedMapBindingIds.has(variable.binding.id) ||
    context.sharedSetBindingIds.has(variable.binding.id)
  ) {
    emissionRuleError(
      context,
      'async try awaited declarator requires a direct local Rust value carrier',
      'rust-async-try-completion-unrepresented',
    );
  }
  const mutable =
    variable.mutable || (context.referentMutatedBindingIds.has(variable.binding.id) && !isIrTypeTypedArrayRust(type));
  return `let ${mutable ? 'mut ' : ''}${getBindingTargetNameRust(variable.binding, context)}: ${emitType(type, context)} = ${value};`;
}

function getIrAsyncTrySettledValueTypeRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
): Readonly<IrType> | undefined {
  if (expression.kind === 'cast') {
    return isIrTaskTypeRust(expression.type) ? expression.type.typeArguments[0] : undefined;
  }
  const type = inferIrExpressionTypeRust(expression, context);
  return isIrTaskTypeRust(type) ? type.typeArguments[0] : undefined;
}

function getIrAsyncTryProtectedTaskSettledValueTypeRust(
  expression: Readonly<IrExpression>,
  context: EmitContext,
): Readonly<IrType> | undefined {
  if (expression.kind === 'conditional') {
    const whenTrue = getIrAsyncTryProtectedTaskSettledValueTypeRust(expression.whenTrue, context);
    const whenFalse = getIrAsyncTryProtectedTaskSettledValueTypeRust(expression.whenFalse, context);
    return whenTrue && whenFalse && emitType(whenTrue, context) === emitType(whenFalse, context) ? whenTrue : undefined;
  }
  return getIrAsyncTrySettledValueTypeRust(expression, context);
}

function getIrSingleAbsentValueTypeRust(type: Readonly<IrType>): Readonly<IrType> | undefined {
  if (type.kind !== 'union' || (hasIrTypeNullMemberRust(type) && hasIrTypeUndefinedMemberRust(type))) {
    return undefined;
  }
  const concrete = type.types.filter((member) => member.kind !== 'null' && member.kind !== 'undefined');
  return concrete.length === 1 && concrete.length !== type.types.length ? concrete[0] : undefined;
}

// Settling separates the RHS task evaluation from the write. Only a binding remains the same Rust
// place across that split without evaluating a receiver or key late, and only its elected storage
// carrier tells us whether the fulfilled value is assigned, wrapped, or written through a cell.
function emitAsyncTrySettledAssignmentRust(
  assignment: Readonly<Extract<IrExpression, { kind: 'assignment' }>>,
  context: EmitContext,
  settledValue = '__value',
): string {
  const left = assignment.left;
  if (
    assignment.operator !== '=' ||
    left.kind !== 'identifier' ||
    left.reference.kind !== 'binding' ||
    assignment.right.kind !== 'await'
  ) {
    emissionRuleError(
      context,
      'protected awaited assignment requires one direct binding target and the simple assignment operator',
      'rust-async-protected-assignment-place-unrepresented',
    );
  }

  const binding = left.reference.binding;
  const targetType = context.bindingTypes.get(binding.id);
  const valueType = getIrAsyncTrySettledValueTypeRust(assignment.right.expression, context);
  const cellWrapped = context.cellWrappedBindingIds.has(binding.id);
  const refCellWrapped = context.refCellWrappedBindingIds.has(binding.id);
  const exactWrappedCarrier =
    (!cellWrapped && !refCellWrapped) ||
    (binding.kind === 'variable' &&
      ((cellWrapped &&
        targetType?.kind === 'primitive' &&
        (targetType.name === 'boolean' || targetType.name === 'number')) ||
        (refCellWrapped && targetType?.kind === 'primitive' && targetType.name === 'string')));
  if (
    !targetType ||
    !valueType ||
    !context.assignableBindingIds.has(binding.id) ||
    !exactWrappedCarrier ||
    context.sharedArrayBindingIds.has(binding.id) ||
    context.sharedClassBindingIds.has(binding.id) ||
    context.sharedMapBindingIds.has(binding.id) ||
    context.sharedSetBindingIds.has(binding.id)
  ) {
    emissionRuleError(
      context,
      'protected awaited assignment requires an exact direct Rust binding carrier',
      'rust-async-protected-assignment-place-unrepresented',
    );
  }

  const targetRepresentation = emitType(targetType, context);
  const valueRepresentation = emitType(valueType, context);
  let value = settledValue;
  if (targetRepresentation !== valueRepresentation) {
    const presentType = getIrSingleAbsentValueTypeRust(targetType);
    if (!presentType || emitType(presentType, context) !== valueRepresentation) {
      emissionRuleError(
        context,
        'protected awaited assignment requires an exact represented value or single-absence Option wrapping',
        'rust-async-protected-assignment-place-unrepresented',
      );
    }
    value = `Some(${settledValue})`;
  }

  const name = emitIdentifierReferenceRust(left.reference, context);
  if (cellWrapped) return `${name}.set(${value});`;
  if (refCellWrapped) return `${name}.replace(${value});`;
  return `${name} = ${value};`;
}

function emitAsyncTrySettledStepRust(
  step: RustAsyncTryDirectAwaitStep,
  context: EmitContext,
  value = '__value',
): string[] {
  if (step.kind === 'expression' || step.kind === 'return') return [];
  if (step.kind === 'variable') return [emitAsyncTrySettledVariableRust(step.variable, context, value)];
  return [emitAsyncTrySettledAssignmentRust(step.assignment, context, value)];
}

function emitAsyncTryCompletionReturnTypeRust(context: EmitContext): string {
  if (!context.enclosingReturnType) {
    emissionRuleError(
      context,
      'async try/finally local completion requires one enclosing Rust return type',
      'rust-async-try-completion-unrepresented',
    );
  }
  const type = emitType(context.enclosingReturnType, context);
  return context.returnsSharedClass ? `Rc<RefCell<${type}>>` : type;
}

function emitTaskRejectionPanicRust(error: string, context: EmitContext): string {
  return `${context.options.runtimeCrate ?? 'flight_runtime'}::panic_task_rejection(${error})`;
}

function assertIrAsyncTryReturnAwaitCarrierRust(step: RustAsyncTryDirectAwaitStep, context: EmitContext): void {
  if (step.kind !== 'return') return;
  const valueType = getIrAsyncTrySettledValueTypeRust(step.awaitTarget, context);
  if (
    !valueType ||
    context.returnsSharedClass ||
    emitType(valueType, context) !== emitAsyncTryCompletionReturnTypeRust(context)
  ) {
    emissionRuleError(
      context,
      'protected return-await requires an exact owned Rust function return carrier',
      'rust-async-try-completion-unrepresented',
    );
  }
}

function assertIrAsyncTryProtectedTaskReturnCarrierRust(
  step: Readonly<RustAsyncTryProtectedTaskReturnStep>,
  context: EmitContext,
): void {
  const valueType = getIrAsyncTryProtectedTaskSettledValueTypeRust(step.expression, context);
  if (
    !valueType ||
    context.returnsSharedClass ||
    emitType(valueType, context) !== emitAsyncTryCompletionReturnTypeRust(context)
  ) {
    emissionRuleError(
      context,
      'protected bare FlightTask return requires an exact owned Rust function return carrier',
      'rust-async-try-completion-unrepresented',
    );
  }
}

function assertIrAsyncTrySettledStepCarrierRust(step: RustAsyncTryDirectAwaitStep, context: EmitContext): void {
  if (step.kind === 'return') {
    assertIrAsyncTryReturnAwaitCarrierRust(step, context);
    return;
  }
  const valueType = getIrAsyncTrySettledValueTypeRust(step.awaitTarget, context);
  if (!valueType) {
    emissionRuleError(
      context,
      step.kind === 'expression'
        ? 'protected expression-await requires one direct Flight task settlement'
        : 'protected awaited value requires one direct Flight task settlement',
      'rust-async-try-completion-unrepresented',
    );
  }
  if (step.kind !== 'variable') return;
  const variableType = step.variable.type ?? context.bindingTypes.get(step.variable.binding.id);
  if (!variableType || emitType(variableType, context) !== emitType(valueType, context)) {
    emissionRuleError(
      context,
      'protected awaited declarator requires one exact represented Rust value',
      'rust-async-try-completion-unrepresented',
    );
  }
}

function emitAsyncTryProtectedTaskOperandRust(expression: Readonly<IrExpression>, context: EmitContext): string {
  if (expression.kind === 'cast') return emitAsyncTryProtectedTaskOperandRust(expression.expression, context);
  if (expression.kind === 'conditional') {
    const condition = emitExpression(expression.condition, context);
    const whenTrue = emitAsyncTryProtectedTaskOperandRust(expression.whenTrue, context);
    const whenFalse = emitAsyncTryProtectedTaskOperandRust(expression.whenFalse, context);
    return `(if ${condition} { ${whenTrue} } else { ${whenFalse} })`;
  }
  return emitAsyncTrySettlementOperandRust(expression, context);
}

// A source async free-function call is an opaque, one-shot Rust future while ordinary Promise
// values are FlightTask. Protected completion needs a reusable settlement carrier, so only the exact
// named call shape whose complete owned signature is known is admitted through the runtime adapter.
// Every excluded call/carrier shape still reaches ordinary expression emission and its existing
// stable refusal instead of being silently widened here.
function emitAsyncTrySettlementOperandRust(expression: Readonly<IrExpression>, context: EmitContext): string {
  const carrier = getIrTaskCarrierKindRust(expression, context);
  if (carrier === 'native-future' && isIrProtectedNativeFutureAdapterCallRust(expression, context)) {
    return emitExactNativeFutureTaskAdapterRust(expression, context);
  }
  return emitOwnedOperandRust(expression, context);
}

function emitExactNativeFutureTaskAdapterRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>>,
  context: EmitContext,
): string {
  context.runtimeTypeNames.add('FlightTask');
  const future = emitOwnedOperandRust(expression, { ...context, allowedNativeFutureCall: expression });
  return `FlightTask::from_future(${future})`;
}

function emitAsyncTryProtectedTaskCatchRust(
  statement: Readonly<Extract<IrStatement, { kind: 'try' }>>,
  plan: Readonly<RustAsyncTryProtectedTaskCatchPlan>,
  context: EmitContext,
): string[] {
  assertIrAsyncTryProtectedTaskReturnCarrierRust(plan.step, context);
  const catchClause = statement.catchClause!;
  const catchBinding = catchClause.binding ? getBindingTargetNameRust(catchClause.binding, context) : '_';
  const target = emitAsyncTryProtectedTaskOperandRust(plan.step.expression, context);
  const value = getGeneratedTargetNameRust('try_value', context);
  return [
    ...emitStatements(plan.preStatements, context),
    `match ${target}.settle() {`,
    ...indentSourceLines([
      `Ok(${value}) => return ${value},`,
      `Err(${catchBinding}) => {`,
      ...indentSourceLines(emitStatementBody(catchClause.body, context)),
      '}',
    ]),
    '}',
  ];
}

function emitAsyncTryLocalTryCompletionRust(
  plan: Readonly<RustAsyncTryLocalCompletionPlan>,
  label: string,
  context: EmitContext,
): string[] {
  const lines: string[] = [];
  for (const statement of plan.tryStatements) {
    if (statement === plan.protectedTaskReturn?.statement) {
      assertIrAsyncTryProtectedTaskReturnCarrierRust(plan.protectedTaskReturn, context);
      const target = emitAsyncTryProtectedTaskOperandRust(plan.protectedTaskReturn.expression, context);
      const value = getGeneratedTargetNameRust('try_value', context);
      const error = getGeneratedTargetNameRust('try_error', context);
      lines.push(
        `match ${target}.settle() {`,
        ...indentSourceLines([
          `Ok(${value}) => break '${label} Ok(Some(${value})),`,
          `Err(${error}) => break '${label} Err(${error}),`,
        ]),
        '}',
      );
      return lines;
    }
    const step = getIrAsyncTryDirectAwaitStepRust(statement);
    if (step) {
      assertIrAsyncTrySettledStepCarrierRust(step, context);
      const target = emitAsyncTrySettlementOperandRust(step.awaitTarget, context);
      const error = getGeneratedTargetNameRust('try_error', context);
      if (step.kind === 'return') {
        const value = getGeneratedTargetNameRust('try_value', context);
        lines.push(
          `match ${target}.settle() {`,
          ...indentSourceLines([
            `Ok(${value}) => break '${label} Ok(Some(${value})),`,
            `Err(${error}) => break '${label} Err(${error}),`,
          ]),
          '}',
        );
        return lines;
      }
      if (step.kind === 'expression') {
        lines.push(
          `match ${target}.settle() {`,
          ...indentSourceLines(['Ok(_) => {}', `Err(${error}) => break '${label} Err(${error}),`]),
          '}',
        );
        continue;
      }
      const value = getGeneratedTargetNameRust('try_value', context);
      lines.push(
        `let ${value} = match ${target}.settle() {`,
        ...indentSourceLines([`Ok(${value}) => ${value},`, `Err(${error}) => break '${label} Err(${error}),`]),
        '};',
        ...emitAsyncTrySettledStepRust(step, context, value),
      );
      continue;
    }
    if (statement.kind === 'return') {
      if (!statement.expression) {
        if (context.sharedClassReturnRepresentation) {
          emissionRuleError(
            context,
            'shared class return requires one exact value',
            'rust-reference-shared-class-return-unrepresented',
          );
        }
        lines.push(`break '${label} Ok(Some(()));`);
      } else {
        const value = normalizeSourceTextGrouping(emitContextualOwnedReturnValueRust(statement.expression, context));
        lines.push(`break '${label} Ok(Some(${value}));`);
      }
      return lines;
    }
    if (statement.kind === 'throw') {
      const message = getIrAsyncTrySourceThrowMessageRust(statement, context);
      if (!message) {
        emissionRuleError(
          context,
          'protected source throw requires one terminal new Error with an exact owned String message',
          'rust-async-try-completion-unrepresented',
        );
      }
      lines.push(`break '${label} Err(${normalizeSourceTextGrouping(emitOwnedOperandRust(message, context))});`);
      return lines;
    }
    lines.push(...emitStatement(statement, context));
  }
  lines.push(`break '${label} Ok(None);`);
  return lines;
}

function emitAsyncTryCatchCompletionRust(
  statements: readonly Readonly<IrStatement>[],
  rethrowBinding: Readonly<IrBindingIdentity> | undefined,
  context: EmitContext,
): string[] {
  const tail = statements.at(-1);
  const hasAbruptTail = tail?.kind === 'return' || tail?.kind === 'throw';
  const body = hasAbruptTail ? statements.slice(0, -1) : statements;
  const bodyContext = rethrowBinding
    ? { ...context, movedBindingIds: new Set([...context.movedBindingIds, rethrowBinding.id]) }
    : context;
  const lines = emitStatements(body, bodyContext);
  if (tail?.kind === 'throw') {
    if (!rethrowBinding) {
      emissionRuleError(
        context,
        'catch throw requires the unchanged active String rejection binding',
        'rust-async-try-completion-unrepresented',
      );
    }
    return [...lines, `Err(${getBindingTargetNameRust(rethrowBinding, context)})`];
  }
  if (tail?.kind !== 'return') return [...lines, 'Ok(None)'];
  if (!tail.expression) {
    if (context.returnsSharedClass) {
      emissionRuleError(
        context,
        'shared class return requires one exact value',
        'rust-reference-shared-class-return-unrepresented',
      );
    }
    return [...lines, 'Ok(Some(()))'];
  }
  const value = normalizeSourceTextGrouping(emitContextualOwnedReturnValueRust(tail.expression, context));
  return [...lines, `Ok(Some(${value}))`];
}

function emitAsyncTryAwaitCatchCompletionRust(
  plan: Readonly<RustAsyncTryAwaitCatchCompletionPlan>,
  context: EmitContext,
): string[] {
  const handlerContext = plan.binding
    ? { ...context, movedBindingIds: new Set([...context.movedBindingIds, plan.binding.id]) }
    : context;
  if (plan.kind === 'await-two') {
    const first = plan.first;
    const second = plan.second;
    assertIrAsyncTrySettledStepCarrierRust(first, handlerContext);
    assertIrAsyncTrySettledStepCarrierRust(second, handlerContext);
    const firstTarget = emitAsyncTrySettlementOperandRust(first.awaitTarget, handlerContext);
    const firstError = getGeneratedTargetNameRust('catch_first_error', context);
    const firstValue = getGeneratedTargetNameRust('catch_first_value', context);
    const secondTarget = emitAsyncTrySettlementOperandRust(second.awaitTarget, handlerContext);
    const secondError = getGeneratedTargetNameRust('catch_second_error', context);
    const secondValue = getGeneratedTargetNameRust('catch_second_value', context);
    const secondFulfilled =
      second.kind === 'return'
        ? [`Ok(${secondValue}) => Ok(Some(${secondValue})),`]
        : [
            `Ok(${second.kind === 'expression' ? '_' : secondValue}) => {`,
            ...indentSourceLines([
              ...emitAsyncTrySettledStepRust(second, handlerContext, secondValue),
              ...emitAsyncTryCatchCompletionRust(plan.postStatements, plan.rethrowBinding, handlerContext),
            ]),
            '}',
          ];
    const secondSettlement = [
      `match ${secondTarget}.settle() {`,
      ...indentSourceLines([...secondFulfilled, `Err(${secondError}) => Err(${secondError}),`]),
      '}',
    ];
    return [
      ...emitStatements(plan.preStatements, handlerContext),
      `match ${firstTarget}.settle() {`,
      ...indentSourceLines([
        `Ok(${first.kind === 'expression' ? '_' : firstValue}) => {`,
        ...indentSourceLines([
          ...emitAsyncTrySettledStepRust(first, handlerContext, firstValue),
          ...emitStatements(plan.betweenStatements, handlerContext),
          ...secondSettlement,
        ]),
        '}',
        `Err(${firstError}) => Err(${firstError}),`,
      ]),
      '}',
    ];
  }
  const step = plan.step;
  assertIrAsyncTrySettledStepCarrierRust(step, handlerContext);
  const target = emitAsyncTrySettlementOperandRust(step.awaitTarget, handlerContext);
  const error = getGeneratedTargetNameRust('catch_error', context);
  const value = getGeneratedTargetNameRust('catch_value', context);
  const fulfilled =
    step.kind === 'return'
      ? [`Ok(${value}) => Ok(Some(${value})),`]
      : [
          `Ok(${step.kind === 'expression' ? '_' : value}) => {`,
          ...indentSourceLines([
            ...emitAsyncTrySettledStepRust(step, handlerContext, value),
            ...emitAsyncTryCatchCompletionRust(plan.postStatements, plan.rethrowBinding, handlerContext),
          ]),
          '}',
        ];
  return [
    ...emitStatements(plan.preStatements, handlerContext),
    `match ${target}.settle() {`,
    ...indentSourceLines([...fulfilled, `Err(${error}) => Err(${error}),`]),
    '}',
  ];
}

function emitAsyncTryAwaitedFinalizerCompletionRust(
  plan: Readonly<RustAsyncTryAwaitFinalizerCompletionPlan>,
  pending: string,
  context: EmitContext,
): string[] {
  if (plan.kind === 'await-two') {
    const first = plan.first;
    const second = plan.second;
    assertIrAsyncTrySettledStepCarrierRust(first, context);
    assertIrAsyncTrySettledStepCarrierRust(second, context);
    const firstTarget = emitAsyncTrySettlementOperandRust(first.awaitTarget, context);
    const firstError = getGeneratedTargetNameRust('finally_first_error', context);
    const firstValue = getGeneratedTargetNameRust('finally_first_value', context);
    const secondTarget = emitAsyncTrySettlementOperandRust(second.awaitTarget, context);
    const secondError = getGeneratedTargetNameRust('finally_second_error', context);
    const secondValue = getGeneratedTargetNameRust('finally_second_value', context);
    const secondSettlement = [
      `match ${secondTarget}.settle() {`,
      ...indentSourceLines([
        `Ok(${second.kind === 'expression' ? '_' : secondValue}) => {`,
        ...indentSourceLines([
          ...emitAsyncTrySettledStepRust(second, context, secondValue),
          ...emitStatements(plan.postStatements, context),
          pending,
        ]),
        '}',
        `Err(${secondError}) => Err(${secondError}),`,
      ]),
      '}',
    ];
    return [
      ...emitStatements(plan.preStatements, context),
      `match ${firstTarget}.settle() {`,
      ...indentSourceLines([
        `Ok(${first.kind === 'expression' ? '_' : firstValue}) => {`,
        ...indentSourceLines([
          ...emitAsyncTrySettledStepRust(first, context, firstValue),
          ...emitStatements(plan.betweenStatements, context),
          ...secondSettlement,
        ]),
        '}',
        `Err(${firstError}) => Err(${firstError}),`,
      ]),
      '}',
    ];
  }
  const step = plan.step;
  assertIrAsyncTrySettledStepCarrierRust(step, context);
  const target = emitAsyncTrySettlementOperandRust(step.awaitTarget, context);
  const error = getGeneratedTargetNameRust('finally_error', context);
  const value = getGeneratedTargetNameRust('finally_value', context);
  return [
    ...emitStatements(plan.preStatements, context),
    `match ${target}.settle() {`,
    ...indentSourceLines([
      `Ok(${step.kind === 'expression' ? '_' : value}) => {`,
      ...indentSourceLines([
        ...emitAsyncTrySettledStepRust(step, context, value),
        ...emitStatements(plan.postStatements, context),
        pending,
      ]),
      '}',
      `Err(${error}) => Err(${error}),`,
    ]),
    '}',
  ];
}

function emitAsyncTryLocalCompletionRust(
  statement: Readonly<Extract<IrStatement, { kind: 'try' }>>,
  plan: Readonly<RustAsyncTryLocalCompletionPlan>,
  context: EmitContext,
): Readonly<{ completion: string; lines: string[]; returnType: string }> {
  const returnType = emitAsyncTryCompletionReturnTypeRust(context);
  const pending = getGeneratedTargetNameRust('try_completion_result', context);
  const label = getGeneratedTargetNameRust('try_completion', context);
  const lines = [
    `let ${pending}: Result<Option<${returnType}>, String> = '${label}: {`,
    ...indentSourceLines(emitAsyncTryLocalTryCompletionRust(plan, label, context)),
    '};',
  ];
  let completion = pending;
  if (plan.catchPlan) {
    completion = getGeneratedTargetNameRust('try_completion_value', context);
    const carried = getGeneratedTargetNameRust('try_carried_completion', context);
    const catchBinding = statement.catchClause?.binding
      ? getBindingTargetNameRust(statement.catchClause.binding, context)
      : '_';
    const catchCompletion =
      plan.catchPlan.kind === 'straight'
        ? emitAsyncTryCatchCompletionRust(plan.catchPlan.statements, plan.catchPlan.rethrowBinding, context)
        : emitAsyncTryAwaitCatchCompletionRust(plan.catchPlan, context);
    lines.push(
      `let ${completion}: Result<Option<${returnType}>, String> = match ${pending} {`,
      ...indentSourceLines([
        `Ok(${carried}) => Ok(${carried}),`,
        `Err(${catchBinding}) => {`,
        ...indentSourceLines(catchCompletion),
        '}',
      ]),
      '};',
    );
  }
  return { completion, lines, returnType };
}

function emitAsyncTryCompletionDispatchRust(
  plan: Readonly<RustAsyncTryLocalCompletionPlan>,
  completion: string,
  context: EmitContext,
): string[] {
  const value = getGeneratedTargetNameRust('try_return_value', context);
  const tryCanCompleteNormally =
    plan.tryStatements.at(-1)?.kind !== 'return' && plan.tryStatements.at(-1)?.kind !== 'throw';
  const catchCanCompleteNormally = plan.catchPlan
    ? plan.catchPlan.kind === 'straight'
      ? plan.catchPlan.statements.at(-1)?.kind !== 'return' && plan.catchPlan.statements.at(-1)?.kind !== 'throw'
      : (plan.catchPlan.kind === 'await'
          ? plan.catchPlan.step.kind !== 'return'
          : plan.catchPlan.second.kind !== 'return') &&
        plan.catchPlan.postStatements.at(-1)?.kind !== 'return' &&
        plan.catchPlan.postStatements.at(-1)?.kind !== 'throw'
    : false;
  const error = getGeneratedTargetNameRust('try_error', context);
  return [
    `match ${completion} {`,
    ...indentSourceLines([
      `Ok(Some(${value})) => return ${value},`,
      `Ok(None) => ${tryCanCompleteNormally || catchCanCompleteNormally ? '{}' : 'unreachable!()'},`,
      `Err(${error}) => ${emitTaskRejectionPanicRust(error, context)},`,
    ]),
    '}',
  ];
}

function emitAsyncTryNoFinallyAwaitCatchCompletionRust(
  statement: Readonly<Extract<IrStatement, { kind: 'try' }>>,
  plan: Readonly<RustAsyncTryNoFinallyAwaitCatchCompletionPlan>,
  context: EmitContext,
): string[] {
  const emitted = emitAsyncTryLocalCompletionRust(statement, plan, context);
  return [...emitted.lines, ...emitAsyncTryCompletionDispatchRust(plan, emitted.completion, context)];
}

function emitAsyncTryFinallyCompletionRust(
  statement: Readonly<Extract<IrStatement, { kind: 'try' }>>,
  plan: Readonly<RustAsyncTryFinallyCompletionPlan>,
  context: EmitContext,
): string[] {
  const emitted = emitAsyncTryLocalCompletionRust(statement, plan, context);
  const lines = emitted.lines;
  let completion = emitted.completion;
  if (plan.finalizerPlan.kind !== 'straight') {
    const pendingCompletion = completion;
    completion = getGeneratedTargetNameRust('finally_completion_value', context);
    lines.push(
      `let ${completion}: Result<Option<${emitted.returnType}>, String> = {`,
      ...indentSourceLines(emitAsyncTryAwaitedFinalizerCompletionRust(plan.finalizerPlan, pendingCompletion, context)),
      '};',
    );
  } else {
    lines.push(...emitStatements(plan.finalizerPlan.statements, context));
  }
  lines.push(...emitAsyncTryCompletionDispatchRust(plan, completion, context));
  return lines;
}

function emitAsyncTryTwoAwaitRust(
  statement: Readonly<Extract<IrStatement, { kind: 'try' }>>,
  plan: Readonly<RustAsyncTryTwoAwaitPlan>,
  context: EmitContext,
): string[] {
  const catchClause = statement.catchClause!;
  const catchBinding = catchClause.binding ? safeRustValueName(catchClause.binding.name) : '_';
  const preStatements = emitStatements(plan.preStatements, context);
  const firstSettlement = emitAsyncTrySettledStepRust(plan.first, context);
  const secondSettlement = emitAsyncTrySettledStepRust(plan.second, context);
  const firstTarget = emitAsyncTrySettlementOperandRust(plan.first.awaitTarget, context);
  const betweenStatements = emitStatements(plan.betweenStatements, context);
  const secondTarget = emitAsyncTrySettlementOperandRust(plan.second.awaitTarget, context);
  const postStatements = emitStatements(plan.postStatements, context);
  const catchStatements = emitStatementBody(catchClause.body, context);
  const secondMatch = [
    `match ${secondTarget}.settle() {`,
    ...indentSourceLines([
      `${plan.second.kind === 'expression' ? 'Ok(_)' : 'Ok(__value)'} => {`,
      ...indentSourceLines([...secondSettlement, ...postStatements]),
      '}',
      `Err(${catchBinding}) => {`,
      ...indentSourceLines(catchStatements),
      '}',
    ]),
    '}',
  ];
  return [
    ...preStatements,
    `match ${firstTarget}.settle() {`,
    ...indentSourceLines([
      `${plan.first.kind === 'expression' ? 'Ok(_)' : 'Ok(__value)'} => {`,
      ...indentSourceLines([...firstSettlement, ...betweenStatements, ...secondMatch]),
      '}',
      `Err(${catchBinding}) => {`,
      ...indentSourceLines(catchStatements),
      '}',
    ]),
    '}',
  ];
}

function emitAsyncTryCatchRust(statement: Extract<IrStatement, { kind: 'try' }>, context: EmitContext): string[] {
  const finallyCompletion = getAsyncTryFinallyCompletionPlanRust(statement, context);
  if (finallyCompletion) {
    assertIrAsyncTaskCatchBindingUsesRust(statement, context);
    return emitAsyncTryFinallyCompletionRust(statement, finallyCompletion, context);
  }
  const noFinallyAwaitCatchCompletion = getAsyncTryNoFinallyAwaitCatchCompletionPlanRust(statement, context);
  if (noFinallyAwaitCatchCompletion) {
    assertIrAsyncTaskCatchBindingUsesRust(statement, context);
    return emitAsyncTryNoFinallyAwaitCatchCompletionRust(statement, noFinallyAwaitCatchCompletion, context);
  }
  const protectedTaskCatch = getAsyncTryProtectedTaskCatchPlanRust(statement, context);
  if (protectedTaskCatch) {
    assertIrAsyncTaskCatchBindingUsesRust(statement, context);
    return emitAsyncTryProtectedTaskCatchRust(statement, protectedTaskCatch, context);
  }
  const twoAwait = getAsyncTryTwoAwaitPlanRust(statement);
  assertIrAsyncTryProtectedEvidenceRust(statement, context, twoAwait !== undefined);
  assertIrAsyncTaskCatchBindingUsesRust(statement, context);
  if (twoAwait) return emitAsyncTryTwoAwaitRust(statement, twoAwait, context);
  const variableAwait = getAsyncTryVariableAwaitPlanRust(statement, context);
  if (variableAwait) {
    const catchBinding = statement.catchClause!.binding ? safeRustValueName(statement.catchClause!.binding.name) : '_';
    return [
      ...emitStatements(variableAwait.preStatements, context),
      `match ${emitAsyncTrySettlementOperandRust(variableAwait.awaitTarget, context)}.settle() {`,
      ...indentSourceLines([
        'Ok(__value) => {',
        ...indentSourceLines([
          emitAsyncTrySettledVariableRust(variableAwait.variable, context),
          ...emitStatements(variableAwait.postStatements, context),
        ]),
        '}',
        `Err(${catchBinding}) => {`,
        ...indentSourceLines(emitStatementBody(statement.catchClause!.body, context)),
        '}',
      ]),
      '}',
    ];
  }
  const expressionAwait = getAsyncTryExpressionAwaitPlanRust(statement, context);
  if (expressionAwait) {
    const catchBinding = statement.catchClause!.binding ? safeRustValueName(statement.catchClause!.binding.name) : '_';
    return [
      ...emitStatements(expressionAwait.preStatements, context),
      `match ${emitAsyncTrySettlementOperandRust(expressionAwait.awaitTarget, context)}.settle() {`,
      ...indentSourceLines([
        'Ok(_) => {',
        ...indentSourceLines(emitStatements(expressionAwait.postStatements, context)),
        '}',
        `Err(${catchBinding}) => {`,
        ...indentSourceLines(emitStatementBody(statement.catchClause!.body, context)),
        '}',
      ]),
      '}',
    ];
  }
  const tryStatements = statement.tryBody.kind === 'block' ? statement.tryBody.statements : [statement.tryBody];
  const awaitIndex = tryStatements.findIndex(
    (s) =>
      (s.kind === 'expression' && s.expression.kind === 'assignment' && s.expression.right.kind === 'await') ||
      (s.kind === 'return' && s.expression?.kind === 'await'),
  );
  if (awaitIndex === -1) {
    emissionRuleError(
      context,
      'async try/catch requires a recognizable await assignment or return',
      'rust-async-try-completion-unrepresented',
    );
    return [];
  }
  const awaitStatement = tryStatements[awaitIndex]!;
  const preStatements = tryStatements.slice(0, awaitIndex);
  const postStatements = tryStatements.slice(awaitIndex + 1);
  const isReturn = awaitStatement.kind === 'return';
  let awaitTarget: Readonly<IrExpression> | undefined;
  let assignmentExpression: Readonly<Extract<IrExpression, { kind: 'assignment' }>> | undefined;
  if (awaitStatement.kind === 'return' && awaitStatement.expression?.kind === 'await') {
    awaitTarget = awaitStatement.expression.expression;
  } else if (
    awaitStatement.kind === 'expression' &&
    awaitStatement.expression.kind === 'assignment' &&
    awaitStatement.expression.right.kind === 'await'
  ) {
    assignmentExpression = awaitStatement.expression;
    awaitTarget = awaitStatement.expression.right.expression;
  }
  if (!awaitTarget) {
    emissionRuleError(
      context,
      'async try/catch requires a direct await expression',
      'rust-async-try-completion-unrepresented',
    );
    return [];
  }
  const settledAssignment = assignmentExpression
    ? emitAsyncTrySettledAssignmentRust(assignmentExpression, context)
    : undefined;
  const settleExpr = `${emitAsyncTrySettlementOperandRust(awaitTarget, context)}.settle()`;
  const lines: string[] = [];
  lines.push(...emitStatements(preStatements, context));
  if (statement.catchClause) {
    const catchBinding = statement.catchClause.binding ? safeRustValueName(statement.catchClause.binding.name) : '_';
    lines.push(`match ${settleExpr} {`);
    if (isReturn) {
      lines.push(
        ...indentSourceLines([
          'Ok(__value) => {',
          ...indentSourceLines([...emitStatements(postStatements, context), 'return __value;']),
          '}',
        ]),
      );
    } else {
      const okBody: string[] = [];
      if (settledAssignment) okBody.push(settledAssignment);
      okBody.push(...emitStatements(postStatements, context));
      lines.push(...indentSourceLines(['Ok(__value) => {', ...indentSourceLines(okBody), '}']));
    }
    lines.push(
      ...indentSourceLines([
        `Err(${catchBinding}) => {`,
        ...indentSourceLines(emitStatementBody(statement.catchClause.body, context)),
        '}',
      ]),
    );
    lines.push('}');
    if (statement.finallyBody) {
      lines.push(...emitStatementBody(statement.finallyBody, context));
    }
  } else if (statement.finallyBody) {
    lines.push(`let __try_result = ${settleExpr};`);
    lines.push(...emitStatementBody(statement.finallyBody, context));
    if (isReturn) {
      lines.push('match __try_result {');
      lines.push(
        ...indentSourceLines([
          'Ok(__value) => return __value,',
          `Err(__error) => ${emitTaskRejectionPanicRust('__error', context)},`,
        ]),
      );
      lines.push('}');
    } else {
      lines.push('match __try_result {');
      const okBody: string[] = [];
      if (settledAssignment) okBody.push(settledAssignment);
      okBody.push(...emitStatements(postStatements, context));
      lines.push(
        ...indentSourceLines([
          'Ok(__value) => {',
          ...indentSourceLines(okBody),
          '}',
          `Err(__error) => ${emitTaskRejectionPanicRust('__error', context)},`,
        ]),
      );
      lines.push('}');
    }
  } else {
    emissionRuleError(context, 'async try without catch or finally', 'rust-async-try-completion-unrepresented');
  }
  return lines;
}

function hasIrExpressionThisReferenceRust(expression: Readonly<IrExpression>): boolean {
  let found = false;
  analyzeIrStatementSubtreeTraversal(
    { expression, kind: 'expression' },
    {
      expression(node) {
        if (node.kind === 'identifier' && node.reference.kind === 'this') found = true;
        return undefined;
      },
    },
  );
  return found;
}

function emitParameter(parameter: Readonly<IrParameter>, context: EmitContext): string {
  const parameterType =
    context.assertedUnknownBindingTypes.get(parameter.binding.id) ??
    context.bindingTypes.get(parameter.binding.id) ??
    parameter.type;
  const optionalSharedClassRepresentation = context.optionalSharedClassParameterRepresentations.get(
    parameter.binding.id,
  );
  const retainedClassRepresentation = context.retainedClassParameterRepresentations.get(parameter.binding.id);
  if (context.sharedArrayBindingIds.has(parameter.binding.id)) {
    if (parameter.initializer || parameter.optional || parameter.rest) {
      emissionRuleError(
        context,
        `owned shared array parameter ${parameter.binding.name} must be one fixed required binding in Rust`,
        'rust-reference-shared-array-use-unrepresented',
      );
    }
    return `${getBindingTargetNameRust(parameter.binding, context)}: ${emitOwnedSharedArrayCarrierTypeRust(parameterType, context)}`;
  }
  if (retainedClassRepresentation) {
    if (parameter.initializer || parameter.optional || parameter.rest) {
      emissionError(context, `retained class parameter ${parameter.binding.name} must be fixed and required in Rust`);
    }
    return `${getBindingTargetNameRust(parameter.binding, context)}: ${emitSharedClassCarrierTypeRust(parameterType, retainedClassRepresentation, context)}`;
  }
  if (optionalSharedClassRepresentation) {
    if (parameter.initializer || parameter.rest) {
      emissionError(
        context,
        `optional shared class parameter ${parameter.binding.name} must use one fixed exact carrier in Rust`,
      );
    }
    context.needsRcImport.add('Rc');
    context.needsRefCellImport.add('RefCell');
    const binding = `${context.reboundBindingIds.has(parameter.binding.id) ? 'mut ' : ''}${getBindingTargetNameRust(parameter.binding, context)}`;
    return `${binding}: ${emitSharedClassCarrierTypeRust(parameterType, optionalSharedClassRepresentation, context)}`;
  }
  // The source mutates what this parameter names, and the caller sees the change. Moving the value in
  // would mutate a copy and drop it — the same source, a different meaning — so the parameter is
  // borrowed mutably and every call site lends rather than gives.
  if (context.referentMutatedParameterIds.has(parameter.binding.id)) {
    if (parameter.initializer || parameter.optional || parameter.rest) {
      emissionError(
        context,
        `parameter ${parameter.binding.name} is mutated through and cannot also be optional or variadic in Rust`,
      );
    }
    return `${getBindingTargetNameRust(parameter.binding, context)}: &mut ${emitType(parameterType, context)}`;
  }
  if (context.borrowedClassParameterIds.has(parameter.binding.id)) {
    if (parameter.initializer || parameter.optional || parameter.rest) {
      emissionError(context, `borrowed class parameter ${parameter.binding.name} must be fixed and required in Rust`);
    }
    return `${getBindingTargetNameRust(parameter.binding, context)}: &${emitType(parameterType, context)}`;
  }
  // A parameter the body assigns to is a local binding in Rust as much as in the source language, and
  // Rust will not accept the assignment without `mut`. Emitting it unconditionally would instead earn
  // an unused-mut warning on every parameter that is only read.
  const binding = `${context.reboundBindingIds.has(parameter.binding.id) ? 'mut ' : ''}${getBindingTargetNameRust(parameter.binding, context)}`;
  if (parameter.initializer) {
    return `${binding}: Option<${emitType(parameterType, context)}>`;
  }
  if (parameter.optional) {
    return `${binding}: ${emitFunctionTypeParameterRust({ ...parameter, type: parameterType }, context)}`;
  }
  if (parameter.rest) return `${binding}: ${emitType(parameterType, context)}`;
  return `${binding}: ${emitType(parameterType, context)}`;
}

function emitFunctionTypeParameterRust(
  parameter: Readonly<{ optional: boolean; rest: boolean; type: IrType }>,
  context: EmitContext,
): string {
  const type = emitType(parameter.type, context);
  if (!parameter.optional) return type;
  if (hasIrTypeNullMemberRust(parameter.type) && hasIrTypeUndefinedMemberRust(parameter.type)) {
    emissionError(context, 'optional parameters containing both null and undefined require distinct Rust sentinels');
  }
  return hasIrTypeUndefinedMemberRust(parameter.type) && !hasIrTypeNullMemberRust(parameter.type)
    ? type
    : `Option<${type}>`;
}

function emitRecord(
  targetName: string,
  properties: readonly IrObjectTypeProperty[],
  typeParameters: readonly IrTypeParameter[],
  exported: boolean,
  context: EmitContext,
): string[] {
  // A record a public function names has to be at least as visible as that function, and a record
  // the source did not export is still named by one often enough that hiding it only produces a
  // private-interface warning. What leaves the crate is the crate root's decision, not this module's.
  void exported;
  const typeContext: EmitContext = { ...context, activeTypeParameters: typeParameters };
  const lines = [
    emitRustRecordDerive(
      properties.map((property) => property.type),
      typeContext,
    ),
    `pub struct ${targetName}${emitTypeParameters(typeParameters, context)} {`,
  ];
  for (const property of properties) {
    const type = emitType(property.type, typeContext);
    lines.push(`  pub ${safeRustValueName(property.name)}: ${property.optional ? `Option<${type}>` : type},`);
  }
  lines.push('}');
  return lines;
}

function emitStatementValueExpressionRust(
  expression: Readonly<Extract<IrExpression, { kind: 'call' }>>,
  context: EmitContext,
): string {
  if (expression.callee.kind !== 'function' || expression.arguments.length > 0) {
    emissionError(
      context,
      'statement-value call requires a zero-argument function carrier',
      'rust-statement-value-call-unsupported',
    );
  }
  const completion = expression.callee.body.at(-1);
  if (completion?.kind !== 'return' || !completion.expression) {
    emissionError(
      context,
      'statement-value call requires a final value return',
      'rust-statement-value-call-unsupported',
    );
  }
  const statements = emitStatements(expression.callee.body.slice(0, -1), context);
  return `{ ${[...statements, emitExpression(completion.expression, context)].join(' ')} }`;
}

function emitSynchronousTryFinallyRust(
  statement: Readonly<Extract<IrStatement, { kind: 'try' }>> & { finallyBody: IrStatement },
  context: EmitContext,
): string[] {
  assertIrSynchronousTryFinallyCompletionRust(statement, context);
  const completion = getGeneratedTargetNameRust('try_finally_completion', context);
  const panic = getGeneratedTargetNameRust('try_finally_panic', context);
  const protectedContext: EmitContext = { ...context, insideProtectedTry: true };
  return [
    `let ${completion} = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {`,
    ...indentSourceLines(emitStatementBody(statement.tryBody, protectedContext)),
    '}));',
    ...emitStatement(statement.finallyBody, context),
    `if let Err(${panic}) = ${completion} {`,
    `  std::panic::resume_unwind(${panic});`,
    '}',
  ];
}

function emitStatement(statement: Readonly<IrStatement>, context: EmitContext): string[] {
  if (
    context.discriminatedNominalUnionBranch?.direct === true &&
    ((statement.kind === 'block' && statement.label !== undefined) ||
      statement.kind === 'do' ||
      statement.kind === 'for' ||
      statement.kind === 'forIn' ||
      statement.kind === 'forOf' ||
      statement.kind === 'if' ||
      statement.kind === 'switch' ||
      statement.kind === 'throw' ||
      statement.kind === 'try' ||
      statement.kind === 'while')
  ) {
    return emitStatement(statement, {
      ...context,
      discriminatedNominalUnionBranch: { ...context.discriminatedNominalUnionBranch, direct: false },
    });
  }
  switch (statement.kind) {
    case 'block':
      return [
        `${emitControlFlowLabelRust(statement.label)}{`,
        ...indentSourceLines(emitStatements(statement.statements, context)),
        '}',
      ];
    case 'break':
      return [`break${statement.target ? ` ${emitControlFlowTargetRust(statement.target)}` : ''};`];
    case 'continue':
      return [`continue${statement.target ? ` ${emitControlFlowTargetRust(statement.target)}` : ''};`];
    case 'do':
      return [
        `${emitControlFlowLabelRust(statement.label)}loop {`,
        ...indentSourceLines(emitStatementBody(statement.body, context)),
        `  if !(${emitExpression(statement.condition, context)}) { break; }`,
        '}',
      ];
    case 'expression':
      return [`${emitExpression(statement.expression, context)};`];
    case 'for':
      emissionError(
        context,
        'C-style for loops require control-flow lowering before Rust emission',
        'rust-c-style-for-lowering-required',
      );
    case 'forIn':
      if ('pattern' in statement.variable)
        emissionError(
          context,
          'binding patterns require destructuring lowering before Rust emission',
          'rust-binding-pattern-lowering-required',
        );
      if (!statement.keyPlan) {
        emissionError(
          context,
          'object key iteration requires closed key evidence',
          'rust-object-key-iteration-unproven',
        );
      }
      if (statement.keyPlan.evaluation === 'preserve') {
        emissionError(context, 'effectful object key iteration requires Rust structural-object evaluation lowering');
      }
      return [
        `${emitControlFlowLabelRust(statement.label)}for ${statement.variable.mutable ? 'mut ' : ''}${getBindingTargetNameRust(statement.variable.binding, context)} in [${statement.keyPlan.keys.map((key) => `${JSON.stringify(key)}.to_owned()`).join(', ')}] {`,
        ...indentSourceLines(emitStatementBody(statement.body, context)),
        '}',
      ];
    case 'forOf': {
      if (statement.await) {
        emissionError(
          context,
          'async iteration requires Flight task lowering',
          'rust-async-iteration-lowering-required',
        );
      }
      if ('pattern' in statement.variable)
        emissionError(
          context,
          'binding patterns require destructuring lowering before Rust emission',
          'rust-binding-pattern-lowering-required',
        );
      const iterableRust = emitExpression(statement.iterable, context);
      const borrowPrefix = statement.iterable.kind === 'element' ? '&' : '';
      return [
        `${emitControlFlowLabelRust(statement.label)}for ${statement.variable.mutable ? 'mut ' : ''}${getBindingTargetNameRust(statement.variable.binding, context)} in ${borrowPrefix}${iterableRust} {`,
        ...indentSourceLines(emitStatementBody(statement.body, context)),
        '}',
      ];
    }
    case 'if': {
      const discriminated = getRustDiscriminatedNominalUnionIfElsePlanRust(statement, context);
      if (discriminated) {
        return [
          `if ${discriminated.test} {`,
          ...indentSourceLines(
            emitStatementBody(statement.consequent, {
              ...context,
              discriminatedNominalUnionBranch: discriminated.consequent,
            }),
          ),
          '}',
          'else {',
          ...indentSourceLines(
            emitStatementBody(statement.otherwise!, {
              ...context,
              discriminatedNominalUnionBranch: discriminated.otherwise,
            }),
          ),
          '}',
        ];
      }
      const guardTestBinding = getRustDiscriminatedNominalUnionGuardTestBindingRust(statement, context);
      const conditionContext: EmitContext = guardTestBinding
        ? { ...context, discriminatedNominalUnionGuardTestBindingId: guardTestBinding.id }
        : context;
      const lines = [
        `if ${normalizeSourceTextGrouping(emitExpression(statement.condition, conditionContext))} {`,
        ...indentSourceLines(emitStatementBody(statement.consequent, context)),
        '}',
      ];
      if (statement.otherwise)
        lines.push('else {', ...indentSourceLines(emitStatementBody(statement.otherwise, context)), '}');
      return lines;
    }
    case 'return': {
      if (!statement.expression) {
        if (context.returnsSharedArray) {
          emissionRuleError(
            context,
            'owned shared array return requires one exact value',
            'rust-reference-shared-array-use-unrepresented',
          );
        }
        if (context.returnsSharedClass) {
          emissionError(
            context,
            'shared class return requires one exact value',
            'rust-reference-shared-class-return-unrepresented',
          );
        }
        return ['return;'];
      }
      return [`return ${normalizeSourceTextGrouping(emitContextualReturnValueRust(statement.expression, context))};`];
    }
    case 'switch': {
      const discriminated = getRustDiscriminatedNominalUnionSwitchPlanRust(statement, context);
      if (discriminated) {
        const owner = emitType(discriminated.owner, context);
        const first = discriminated.cases[0];
        const second = discriminated.cases[1];
        const test = `matches!(&${getBindingTargetNameRust(discriminated.binding, context)}, ${owner}::${first.variantName}(_))`;
        return [
          `${emitControlFlowLabelRust(statement.label)}{`,
          ...indentSourceLines([
            `if ${test} {`,
            ...indentSourceLines(
              emitIrSwitchCaseStatementsRust(first.switchCase, statement.label, {
                ...context,
                discriminatedNominalUnionBranch: first.branch,
              }),
            ),
            '}',
            'else {',
            ...indentSourceLines(
              emitIrSwitchCaseStatementsRust(second.switchCase, statement.label, {
                ...context,
                discriminatedNominalUnionBranch: second.branch,
              }),
            ),
            '}',
          ]),
          '}',
        ];
      }
      const name = getGeneratedTargetNameRust('switch_value', context);
      const cases = statement.cases.filter((switchCase) => switchCase.expression);
      const otherwise = statement.cases.find((switchCase) => !switchCase.expression);
      const lines = [`let ${name} = ${emitExpression(statement.expression, context)};`];
      cases.forEach((switchCase, index) => {
        lines.push(
          `${index > 0 ? 'else ' : ''}if ${name} == ${emitExpression(switchCase.expression!, context)} {`,
          ...indentSourceLines(emitIrSwitchCaseStatementsRust(switchCase, statement.label, context)),
          '}',
        );
      });
      if (otherwise) {
        if (cases.length > 0) lines.push('else {');
        lines.push(
          ...indentSourceLines(
            emitIrSwitchCaseStatementsRust(otherwise, statement.label, context),
            cases.length > 0 ? 1 : 0,
          ),
        );
        if (cases.length > 0) lines.push('}');
      } else if (cases.length > 0) {
        lines.push('else {', '  unreachable!();', '}');
      }
      return [`${emitControlFlowLabelRust(statement.label)}{`, ...indentSourceLines(lines), '}'];
    }
    case 'throw': {
      const thrown = statement.expression;
      if (thrown.kind === 'new' && thrown.callee.kind === 'identifier' && thrown.arguments.length === 1) {
        return [`panic!("{}", ${emitExpression(thrown.arguments[0]!, context)});`];
      }
      return [`panic!("{:?}", ${emitExpression(thrown, context)});`];
    }
    case 'try': {
      const protectedContext: EmitContext = { ...context, insideProtectedTry: true };
      if (
        context.asyncTryStatements.has(statement) ||
        getIrTryProtectedCompletionEvidenceRust(statement).suspensionCount > 0 ||
        getIrAsyncTryProtectedTaskReturnStepRust(statement.tryBody, protectedContext) !== undefined
      ) {
        return emitAsyncTryCatchRust(statement, protectedContext);
      }
      if (statement.finallyBody) {
        return emitSynchronousTryFinallyRust(
          statement as Readonly<typeof statement> & { finallyBody: IrStatement },
          context,
        );
      }
      const catchBinding = statement.catchClause
        ? statement.catchClause.binding
          ? safeRustValueName(statement.catchClause.binding.name)
          : '_'
        : '_';
      const matchArms: string[] = statement.catchClause
        ? [
            'Ok(__catch_result) => return __catch_result,',
            `Err(${catchBinding}) => {`,
            ...indentSourceLines(emitStatementBody(statement.catchClause.body, protectedContext)),
            '}',
          ]
        : ['Ok(_) => {}', 'Err(_) => {}'];
      return [
        'match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {',
        ...indentSourceLines(emitStatementBody(statement.tryBody, protectedContext)),
        '})) {',
        ...indentSourceLines(matchArms),
        '}',
      ];
    }
    case 'variable':
      return statement.declarations.map((variable) => emitVariable(variable, context));
    case 'while':
      // Rust spells a loop with no exit condition `loop`, and warns on `while true` because the two
      // differ to the borrow checker: only `loop` tells it the body always runs.
      const condition = normalizeSourceTextGrouping(emitExpression(statement.condition, context));
      return [
        `${emitControlFlowLabelRust(statement.label)}${condition === 'true' ? 'loop' : `while ${condition}`} {`,
        ...indentSourceLines(emitStatementBody(statement.body, context)),
        '}',
      ];
  }
}

function emitIrSwitchCaseStatementsRust(
  switchCase: Readonly<IrSwitchCase>,
  switchLabel: Readonly<IrControlFlowLabelIdentity> | undefined,
  context: EmitContext,
): string[] {
  const last = switchCase.statements.at(-1);
  const localBreak = last?.kind === 'break' && (!last.target || (switchLabel && last.target.id === switchLabel.id));
  return emitStatements(localBreak ? switchCase.statements.slice(0, -1) : switchCase.statements, context);
}

function emitControlFlowLabelRust(label: Readonly<IrControlFlowLabelIdentity> | undefined): string {
  return label ? `${emitControlFlowTargetRust(label)}: ` : '';
}

function emitControlFlowTargetRust(label: Readonly<IrControlFlowLabelIdentity>): string {
  return `'${safeRustValueName(label.name)}`;
}

function emitStatementBody(statement: Readonly<IrStatement>, context: EmitContext): string[] {
  return statement.kind === 'block'
    ? emitStatements(statement.statements, context)
    : emitStatements([statement], context);
}

function emitStatements(statements: readonly IrStatement[], context: EmitContext): string[] {
  return statements.flatMap((statement) => emitStatement(statement, context));
}

function emitType(type: Readonly<IrType>, context: EmitContext): string {
  switch (type.kind) {
    case 'array':
      return `Vec<${emitType(type.element, context)}>`;
    case 'function': {
      if (type.typeParameters.length > 0) {
        emissionRuleError(
          context,
          'generic callable values require Rust monomorphization before they can enter a concrete carrier',
          'rust-generic-callable-representation-unrepresented',
        );
      }
      context.needsRcImport.add('Rc');
      const parameters = type.parameters.map((parameter) => emitFunctionTypeParameterRust(parameter, context));
      const returns = emitType(type.returns, context);
      return `Rc<dyn Fn(${parameters.join(', ')}) -> ${returns}>`;
    }
    case 'indexedAccess':
    case 'conditionalFacet':
    case 'typeOf':
      return opaqueHostType(context);
    case 'keyof': {
      const resolved = getIrKeyofTypeRust(type.type, context);
      if (!resolved) return opaqueHostType(context);
      return emitType(resolved, context);
    }
    case 'intersection': {
      if (type.types.filter((member) => member.kind === 'function').length > 1) {
        return getOrCreateCallableOverloadRecordRust(type, context).name;
      }
      const scalarDomain = getIrTypePrimitiveDomainRust(type, context);
      if (scalarDomain) return emitType({ kind: 'primitive', name: scalarDomain }, context);
      const callableObject = getOrCreateCallableObjectRecordRust(type, context);
      if (callableObject) {
        return `${callableObject.name}${emitTypeArguments(callableObject.typeParameters, context)}`;
      }
      const properties = getIrObjectTypePropertiesRust(type, context);
      if (properties) return getIrObjectTypeTargetNameRust(properties, context);
      emissionError(
        context,
        'intersection types require Rust record or trait lowering',
        'rust-intersection-type-unsupported',
      );
    }
    case 'literal':
      return typeof type.value === 'boolean' ? 'bool' : typeof type.value === 'number' ? 'f64' : 'String';
    case 'named': {
      const sourceName = type.reference.kind === 'ambient' ? type.reference.name : undefined;
      if ((sourceName === 'Readonly' || sourceName === 'Required') && type.typeArguments[0]) {
        return emitType(type.typeArguments[0], context);
      }
      if (sourceName === 'NoInfer' && type.typeArguments.length === 1 && type.typeArguments[0]) {
        return emitType(type.typeArguments[0], context);
      }
      if (sourceName === 'Exclude' || sourceName === 'Extract') {
        const projected = getIrFilteredTypeRust(sourceName, type.typeArguments, context);
        if (!projected) emissionError(context, `${sourceName} types require closed Rust type computation lowering`);
        return emitType(projected, context);
      }
      if (sourceName === 'Partial' || sourceName === 'Pick' || sourceName === 'Omit') {
        const properties = getIrObjectTypePropertiesRust(type, context);
        if (!properties) {
          emissionError(
            context,
            `${sourceName}<T> requires a statically resolvable Rust object shape`,
            'rust-utility-type-open-shape-unsupported',
          );
        }
        return getIrObjectTypeTargetNameRust(properties, context);
      }
      const mapped = getTypeReferenceTargetNameRust(type, context);
      const arguments_ = type.typeArguments.map((argument) => emitType(argument, context));
      return `${mapped}${arguments_.length > 0 ? `<${arguments_.join(', ')}>` : ''}`;
    }
    case 'never':
      return '!';
    case 'null':
    case 'undefined':
      return '()';
    case 'object':
      return getIrObjectTypeTargetNameRust(type.properties, context);
    case 'primitive':
      if (type.name === 'symbol') return recordRuntimeTypeRust('FlightSymbol', context);
      return { bigint: 'i64', boolean: 'bool', number: 'f64', string: 'String', symbol: 'FlightSymbol', void: '()' }[
        type.name
      ];
    case 'tuple': {
      const elements = type.elements.map((element) => {
        const emitted = emitType(element.type, context);
        return element.optional ? `Option<${emitted}>` : emitted;
      });
      return `(${elements.join(', ')}${elements.length === 1 ? ',' : ''})`;
    }
    case 'union': {
      const concrete = type.types.filter((item) => item.kind !== 'null' && item.kind !== 'undefined');
      const optional = concrete.length !== type.types.length;
      if (hasIrTypeNullMemberRust(type) && hasIrTypeUndefinedMemberRust(type)) {
        const union = getOrCreateAnonymousUnionEnumRust(type.types, context);
        return `${union.name}${emitTypeArguments(union.typeParameters, context)}`;
      }
      if (concrete.length === 1 && concrete.length !== type.types.length)
        return `Option<${emitType(concrete[0]!, context)}>`;
      const primitiveDomain = getIrUnionPrimitiveDomainRust(concrete, context);
      if (primitiveDomain) {
        const emitted = emitType({ kind: 'primitive', name: primitiveDomain }, context);
        return optional ? `Option<${emitted}>` : emitted;
      }
      const primitiveEnum = getOrCreatePrimitiveUnionEnumRust(concrete, context);
      if (primitiveEnum) return optional ? `Option<${primitiveEnum.name}>` : primitiveEnum.name;
      const generalEnum = getOrCreateAnonymousUnionEnumRust(concrete, context);
      const emitted = `${generalEnum.name}${emitTypeArguments(generalEnum.typeParameters, context)}`;
      return optional ? `Option<${emitted}>` : emitted;
    }
    case 'unknown':
      return opaqueHostType(context);
  }
}

// TypeScript's object utilities and intersections are representation decisions in Rust: once every
// participating declaration is closed, the result is one concrete record. Keep the resolver local
// to the backend because it decides Rust storage, but consume the shared substitution machinery so
// generic aliases and inherited interfaces do not acquire a second set of type-argument rules.
function getIrObjectTypePropertiesRust(
  type: Readonly<IrType>,
  context: EmitContext,
  module: Readonly<IrModule> = context.module,
  resolving: ReadonlySet<string> = new Set(),
): readonly IrObjectTypeProperty[] | undefined {
  if (type.kind === 'object') return type.properties;
  if (type.kind === 'intersection') {
    const shapes = type.types.map((member) => getIrObjectTypePropertiesRust(member, context, module, resolving));
    return shapes.some((shape) => !shape)
      ? undefined
      : mergeIrObjectTypePropertiesRust(shapes.flatMap((shape) => shape!));
  }
  if (type.kind !== 'named') return undefined;
  if (type.reference.kind === 'ambient') {
    const utility = type.reference.name;
    if (utility === 'Record') {
      if (type.typeArguments.length !== 2 || !type.typeArguments[0] || !type.typeArguments[1]) return undefined;
      const keys = getIrObjectProjectionKeysRust(type.typeArguments[0], context, module, resolving);
      if (!keys) return undefined;
      return [...keys].map((name) => ({
        name,
        optional: false,
        readonly: false,
        type: type.typeArguments[1]!,
      }));
    }
    if (utility === 'NoInfer' || utility === 'Partial' || utility === 'Readonly' || utility === 'Required') {
      if (type.typeArguments.length !== 1 || !type.typeArguments[0]) return undefined;
      const properties = getIrObjectTypePropertiesRust(type.typeArguments[0], context, module, resolving);
      if (!properties) return undefined;
      return properties.map((property) => ({
        ...property,
        ...(utility === 'Partial' ? { optional: true } : {}),
        ...(utility === 'Readonly' ? { readonly: true } : {}),
        ...(utility === 'Required' ? { optional: false } : {}),
      }));
    }
    if (utility === 'Exclude' || utility === 'Extract') {
      const projected = getIrFilteredTypeRust(utility, type.typeArguments, context, module, resolving);
      return projected ? getIrObjectTypePropertiesRust(projected, context, module, resolving) : undefined;
    }
    if (utility !== 'Omit' && utility !== 'Pick') return undefined;
    if (type.typeArguments.length !== 2 || !type.typeArguments[0] || !type.typeArguments[1]) return undefined;
    const properties = getIrObjectTypePropertiesRust(type.typeArguments[0], context, module, resolving);
    const keys = getIrObjectProjectionKeysRust(type.typeArguments[1], context, module, resolving);
    if (!properties || !keys) return undefined;
    return properties.filter((property) => (utility === 'Pick') === keys.has(property.name));
  }
  if (type.reference.path.length > 0) return undefined;
  if (type.reference.binding.space !== 'type' || type.reference.binding.kind === 'typeParameter') return undefined;
  const location = getIrNamedTypeDeclarationLocationRust(type.reference.binding, context, module);
  if (!location) return undefined;
  const key = `${location.module.packageName}\0${location.module.source}\0${location.declaration.binding.id}`;
  if (resolving.has(key)) return undefined;
  const active = new Set(resolving).add(key);
  let plan;
  try {
    plan = createIrTypeParameterSubstitutionPlan(location.declaration.typeParameters, type.typeArguments);
  } catch (error) {
    if (isCompilerStructuralTypeSubstitutionFailure(error)) return undefined;
    throw error;
  }
  if (location.declaration.kind === 'typeAlias') {
    let resolved: IrType;
    try {
      resolved = resolveIrTypeStructuralSubstitution(location.declaration.type, plan);
    } catch (error) {
      if (isCompilerStructuralTypeSubstitutionFailure(error)) return undefined;
      throw error;
    }
    return getIrObjectTypePropertiesRust(resolved, context, location.module, active);
  }
  const inherited = location.declaration.extends.map((reference) => {
    let resolved: IrType;
    try {
      resolved = resolveIrTypeStructuralSubstitution(reference, plan);
    } catch (error) {
      if (isCompilerStructuralTypeSubstitutionFailure(error)) return undefined;
      throw error;
    }
    return getIrObjectTypePropertiesRust(resolved, context, location.module, active);
  });
  if (inherited.some((properties) => !properties)) return undefined;
  let own: IrObjectTypeProperty[];
  try {
    own = location.declaration.properties.map((property) => ({
      ...property,
      type: resolveIrTypeStructuralSubstitution(property.type, plan),
    }));
  } catch (error) {
    if (isCompilerStructuralTypeSubstitutionFailure(error)) return undefined;
    throw error;
  }
  return mergeIrObjectTypePropertiesRust([...inherited.flatMap((properties) => properties!), ...own]);
}

function mergeIrObjectTypePropertiesRust(
  properties: readonly Readonly<IrObjectTypeProperty>[],
): readonly IrObjectTypeProperty[] | undefined {
  const merged = new Map<string, IrObjectTypeProperty>();
  for (const property of properties) {
    const existing = merged.get(property.name);
    if (!existing) {
      merged.set(property.name, { ...property });
      continue;
    }
    if (
      JSON.stringify(existing.computedKey) !== JSON.stringify(property.computedKey) ||
      existing.phantom !== property.phantom ||
      existing.role !== property.role
    ) {
      return undefined;
    }
    const type =
      JSON.stringify(existing.type) === JSON.stringify(property.type)
        ? existing.type
        : createIrIntersectionTypeRust(existing.type, property.type);
    merged.set(property.name, {
      ...existing,
      optional: existing.optional && property.optional,
      readonly: existing.readonly && property.readonly,
      type,
    });
  }
  return [...merged.values()];
}

function getIrObjectProjectionKeysRust(
  type: Readonly<IrType>,
  context: EmitContext,
  module: Readonly<IrModule>,
  resolving: ReadonlySet<string>,
): ReadonlySet<string> | undefined {
  const members = getIrClosedTypeMembersRust(type, context, module, resolving);
  if (!members || members.some((member) => member.kind !== 'literal' || typeof member.value === 'boolean')) {
    return undefined;
  }
  return new Set(members.map((member) => String((member as Extract<IrType, { kind: 'literal' }>).value)));
}

function getIrKeyofTypeRust(type: Readonly<IrType>, context: EmitContext): Readonly<IrType> | undefined {
  const properties = getIrObjectTypePropertiesRust(type, context);
  if (!properties) return undefined;
  const keys: IrType[] = [];
  if (properties.some((property) => !property.computedKey && !property.phantom)) {
    keys.push({ kind: 'primitive', name: 'string' });
  }
  if (properties.some((property) => property.computedKey && !property.phantom)) {
    keys.push({ kind: 'primitive', name: 'symbol' });
  }
  return createIrClosedTypeUnionRust(keys);
}

function getIrFilteredTypeRust(
  utility: 'Exclude' | 'Extract',
  typeArguments: readonly Readonly<IrType>[],
  context: EmitContext,
  module: Readonly<IrModule> = context.module,
  resolving: ReadonlySet<string> = new Set(),
): Readonly<IrType> | undefined {
  if (typeArguments.length !== 2 || !typeArguments[0] || !typeArguments[1]) return undefined;
  const included = getIrClosedTypeMembersRust(typeArguments[0], context, module, resolving);
  const filters = getIrClosedTypeMembersRust(typeArguments[1], context, module, resolving);
  if (!included || !filters) return undefined;
  const retained: IrType[] = [];
  for (const member of included) {
    const matches = filters.map((filter) =>
      isIrTypeAssignableForFilterRust(member, filter, context, module, resolving),
    );
    if (!matches.includes(true) && matches.includes(undefined)) return undefined;
    const matched = matches.includes(true);
    if ((utility === 'Extract') === matched) retained.push(member);
  }
  return createIrClosedTypeUnionRust(retained);
}

function getIrClosedTypeMembersRust(
  type: Readonly<IrType>,
  context: EmitContext,
  module: Readonly<IrModule> = context.module,
  resolving: ReadonlySet<string> = new Set(),
): readonly Readonly<IrType>[] | undefined {
  if (type.kind === 'never') return [];
  if (type.kind === 'union') {
    const members = type.types.map((member) => getIrClosedTypeMembersRust(member, context, module, resolving));
    return members.some((member) => !member) ? undefined : members.flatMap((member) => member!);
  }
  if (type.kind === 'keyof') {
    const resolved = getIrKeyofTypeRustInModule(type.type, context, module, resolving);
    return resolved ? getIrClosedTypeMembersRust(resolved, context, module, resolving) : undefined;
  }
  if (type.kind === 'typeOf') {
    const resolved = getIrTypeOfValueTypeRust(type, context, module);
    return resolved ? getIrClosedTypeMembersRust(resolved, context, module, resolving) : undefined;
  }
  if (type.kind === 'named' && type.reference.kind === 'binding' && type.reference.path.length === 0) {
    if (type.reference.binding.space !== 'type' || type.reference.binding.kind === 'typeParameter') return undefined;
    const location = getIrNamedTypeDeclarationLocationRust(type.reference.binding, context, module);
    if (location?.declaration.kind === 'typeAlias') {
      const key = `${location.module.packageName}\0${location.module.source}\0${location.declaration.binding.id}`;
      if (resolving.has(key)) return undefined;
      try {
        const plan = createIrTypeParameterSubstitutionPlan(location.declaration.typeParameters, type.typeArguments);
        const resolved = resolveIrTypeStructuralSubstitution(location.declaration.type, plan);
        return getIrClosedTypeMembersRust(resolved, context, location.module, new Set(resolving).add(key));
      } catch (error) {
        if (isCompilerStructuralTypeSubstitutionFailure(error)) return undefined;
        throw error;
      }
    }
  }
  if (type.kind === 'conditionalFacet' || type.kind === 'indexedAccess' || type.kind === 'unknown') {
    return undefined;
  }
  return [type];
}

function getIrTypeOfValueTypeRust(
  type: Readonly<Extract<IrType, { kind: 'typeOf' }>>,
  context: EmitContext,
  module: Readonly<IrModule>,
): Readonly<IrType> | undefined {
  if (type.reference.kind !== 'binding' || type.reference.path.length > 0) return undefined;
  const binding = type.reference.binding;
  const local = module.declarations.find(
    (declaration) =>
      declaration.kind === 'variable' && 'binding' in declaration && declaration.binding.id === binding.id,
  );
  if (local?.kind === 'variable' && 'binding' in local) return getIrVariableTypeRust(local);
  const imported = module.imports
    .flatMap((item) => item.bindings.map((candidate) => ({ candidate, specifier: item.specifier })))
    .find(({ candidate }) => candidate.binding.id === binding.id);
  if (!imported || imported.candidate.imported === '*' || imported.candidate.imported === 'default') return undefined;
  const targetModule = resolveImportModuleRust(imported.specifier, imported.candidate.imported, context, module);
  const declaration = targetModule?.declarations.find(
    (candidate) =>
      candidate.kind === 'variable' && 'binding' in candidate && candidate.binding.name === imported.candidate.imported,
  );
  return declaration?.kind === 'variable' && 'binding' in declaration ? getIrVariableTypeRust(declaration) : undefined;
}

function getIrVariableTypeRust(variable: Readonly<IrVariableDeclaration>): Readonly<IrType> | undefined {
  if ('pattern' in variable) return undefined;
  if (variable.type && variable.type.kind !== 'unknown') return variable.type;
  const initializer = variable.initializer;
  if (initializer?.kind !== 'call') return variable.type;
  const directSymbol =
    initializer.callee.kind === 'identifier' &&
    initializer.callee.reference.kind === 'ambient' &&
    initializer.callee.reference.name === 'Symbol';
  const symbolMember =
    initializer.callee.kind === 'property' &&
    initializer.callee.object.kind === 'identifier' &&
    initializer.callee.object.reference.kind === 'ambient' &&
    initializer.callee.object.reference.name === 'Symbol';
  return directSymbol || symbolMember ? { kind: 'primitive', name: 'symbol' } : variable.type;
}

function getIrKeyofTypeRustInModule(
  type: Readonly<IrType>,
  context: EmitContext,
  module: Readonly<IrModule>,
  resolving: ReadonlySet<string>,
): Readonly<IrType> | undefined {
  const properties = getIrObjectTypePropertiesRust(type, context, module, resolving);
  if (!properties) return undefined;
  const keys: IrType[] = [];
  if (properties.some((property) => !property.computedKey && !property.phantom)) {
    keys.push({ kind: 'primitive', name: 'string' });
  }
  if (properties.some((property) => property.computedKey && !property.phantom)) {
    keys.push({ kind: 'primitive', name: 'symbol' });
  }
  return createIrClosedTypeUnionRust(keys);
}

function isIrTypeAssignableForFilterRust(
  source: Readonly<IrType>,
  target: Readonly<IrType>,
  context: EmitContext,
  module: Readonly<IrModule>,
  resolving: ReadonlySet<string>,
): boolean | undefined {
  if (target.kind === 'primitive') {
    if (source.kind === 'primitive') return source.name === target.name;
    if (source.kind !== 'literal') return false;
    return typeof source.value === target.name;
  }
  if (target.kind === 'literal') return source.kind === 'literal' && Object.is(source.value, target.value);
  if (target.kind === 'null' || target.kind === 'undefined') return source.kind === target.kind;
  const sourceProperties = getIrObjectTypePropertiesRust(source, context, module, resolving);
  const targetProperties = getIrObjectTypePropertiesRust(target, context, module, resolving);
  if (!sourceProperties || !targetProperties) return undefined;
  // Discriminant filters are closed even when the wider structural comparison is indeterminate.
  // `Extract<Union, { kind: "x" }>` only asks whether each alternative's named literal slot is
  // compatible; unrelated fields and their host types cannot affect that decision.
  if (targetProperties.length > 0 && targetProperties.every((property) => property.type.kind === 'literal')) {
    const decisions = targetProperties.map((targetProperty) => {
      const sourceProperty = sourceProperties.find((property) => property.name === targetProperty.name);
      if (!sourceProperty || sourceProperty.optional) return false;
      const members = getIrClosedTypeMembersRust(sourceProperty.type, context, module, resolving);
      if (!members) return undefined;
      return members.every(
        (member) =>
          member.kind === 'literal' &&
          targetProperty.type.kind === 'literal' &&
          Object.is(member.value, targetProperty.type.value),
      );
    });
    if (decisions.includes(false)) return false;
    if (decisions.every((decision) => decision === true)) return true;
  }
  const report = analyzeIrTypeStructuralAssignability(
    { kind: 'object', properties: sourceProperties },
    { kind: 'object', properties: targetProperties },
  );
  return report.status === 'indeterminate' ? undefined : report.status === 'compatible';
}

function createIrClosedTypeUnionRust(types: readonly Readonly<IrType>[]): Readonly<IrType> {
  const unique = [...new Map(types.map((type) => [JSON.stringify(type), type])).values()];
  if (unique.length === 0) return { kind: 'never' };
  if (unique.length === 1) return unique[0]!;
  return { kind: 'union', types: [unique[0]!, unique[1]!, ...unique.slice(2)] };
}

function createIrIntersectionTypeRust(left: Readonly<IrType>, right: Readonly<IrType>): Readonly<IrType> {
  const types = [
    ...(left.kind === 'intersection' ? left.types : [left]),
    ...(right.kind === 'intersection' ? right.types : [right]),
  ];
  return { kind: 'intersection', types: [types[0]!, types[1]!, ...types.slice(2)] };
}

function getIrUnionPrimitiveDomainRust(
  types: readonly Readonly<IrType>[],
  context: EmitContext,
): 'boolean' | 'number' | 'string' | undefined {
  const domains = types.map((type) => getIrTypePrimitiveDomainRust(type, context));
  const domain = domains[0];
  return domain !== undefined && domains.every((candidate) => candidate === domain) ? domain : undefined;
}

function getIrTypePrimitiveDomainRust(
  type: Readonly<IrType>,
  context: EmitContext,
  module: Readonly<IrModule> = context.module,
  resolving: ReadonlySet<string> = new Set(),
): 'boolean' | 'number' | 'string' | undefined {
  if (type.kind === 'literal') {
    const domain = typeof type.value;
    return domain === 'boolean' || domain === 'number' || domain === 'string' ? domain : undefined;
  }
  if (type.kind === 'primitive' && (type.name === 'boolean' || type.name === 'number' || type.name === 'string')) {
    return type.name;
  }
  if (type.kind === 'typeOf') {
    const resolved = getIrTypeOfValueTypeRust(type, context, module);
    return resolved ? getIrTypePrimitiveDomainRust(resolved, context, module, resolving) : undefined;
  }
  if (type.kind === 'intersection') {
    const meaningful = type.types.filter(
      (member) =>
        member.kind !== 'object' && getIrObjectTypePropertiesRust(member, context, module, resolving) === undefined,
    );
    const domains = meaningful.map((member) => getIrTypePrimitiveDomainRust(member, context, module, resolving));
    const domain = domains[0];
    return domain !== undefined && domains.every((candidate) => candidate === domain) ? domain : undefined;
  }
  if (
    type.kind !== 'named' ||
    type.reference.kind !== 'binding' ||
    type.reference.path.length > 0 ||
    type.reference.binding.space !== 'type' ||
    type.reference.binding.kind === 'typeParameter'
  ) {
    return undefined;
  }
  const location = getIrNamedTypeDeclarationLocationRust(type.reference.binding, context, module);
  if (location?.declaration.kind !== 'typeAlias') return undefined;
  const key = `${location.module.packageName}\0${location.module.source}\0${location.declaration.binding.id}`;
  if (resolving.has(key)) return undefined;
  try {
    const plan = createIrTypeParameterSubstitutionPlan(location.declaration.typeParameters, type.typeArguments);
    const resolved = resolveIrTypeStructuralSubstitution(location.declaration.type, plan);
    return getIrTypePrimitiveDomainRust(resolved, context, location.module, new Set(resolving).add(key));
  } catch (error) {
    if (isCompilerStructuralTypeSubstitutionFailure(error)) return undefined;
    throw error;
  }
}

// A union of string literals is how the source language spells a closed set of names, and the source
// treats a value of it as a string everywhere: comparing it, returning it, storing it in a string
// field. Rust has no implicit conversion, so a unit-variant enum would need a coercion inserted at
// every one of those positions — type-directed work this backend does not do yet.
//
// So the set becomes the string it is made of, and the closed-ness is what is lost. Haxe keeps the
// enum because `from String to String` gives it exactly those coercions for free; that the two
// targets diverge here is a property of the targets, not an inconsistency in the compiler.
function emitStringLiteralUnionRust(declaration: Readonly<IrTypeAliasDeclaration>, context: EmitContext): string[] {
  return [
    `${isRustDeclarationExportedRust(declaration, context) ? 'pub ' : ''}type ${getBindingTargetNameRust(declaration.binding, context)} = String;`,
  ];
}

function emitTypeAlias(declaration: Readonly<IrTypeAliasDeclaration>, context: EmitContext): string[] {
  if (getIrUnionTypeStringLiteralValues(declaration.type)) return emitStringLiteralUnionRust(declaration, context);
  const declaredType: IrTypeReference = {
    kind: 'named',
    reference: { binding: declaration.binding, kind: 'binding', path: [] },
    typeArguments: [],
  };
  const dualSentinelNominalEnum = createRustDualSentinelNominalEnumPlanRust(declaredType, context);
  if (
    dualSentinelNominalEnum &&
    dualSentinelNominalEnum.ownerIdentity.location.declaration.binding.id === declaration.binding.id &&
    isRustCompilerModuleIdentityEqual(dualSentinelNominalEnum.ownerIdentity.location.module, context.module)
  ) {
    return emitGeneralUnionRust(
      getBindingTargetNameRust(declaration.binding, context),
      [
        ...dualSentinelNominalEnum.valueVariants.map(
          (variant): RustGeneralUnionVariant => ({ kind: 'tuple', name: variant.name, rustType: variant.rustType }),
        ),
        { kind: 'unit', name: dualSentinelNominalEnum.nullVariantName },
        { kind: 'unit', name: dualSentinelNominalEnum.undefinedVariantName },
      ],
      [],
      isRustDeclarationExportedRust(declaration, context),
      context,
    );
  }
  const optionalGeneratedEnum = createRustOptionalGeneratedEnumPlanRust(declaredType, context);
  if (optionalGeneratedEnum) {
    const exported = isRustDeclarationExportedRust(declaration, context);
    return [
      ...emitTaggedUnionRust(
        optionalGeneratedEnum.payloadOwner.name,
        optionalGeneratedEnum.payloadType,
        exported,
        context,
      ),
      '',
      `${exported ? 'pub ' : ''}type ${getBindingTargetNameRust(declaration.binding, context)} = Option<${optionalGeneratedEnum.payloadOwner.name}>;`,
    ];
  }
  if (declaration.type.kind === 'union' && getIrUnionTypeMemberRecordsRust(declaration.type, context)) {
    return emitTaggedUnionRust(
      getBindingTargetNameRust(declaration.binding, context),
      declaration.type,
      isRustDeclarationExportedRust(declaration, context),
      context,
    );
  }
  const typeContext: EmitContext = { ...context, activeTypeParameters: declaration.typeParameters };
  if (
    declaration.type.kind === 'union' &&
    !hasIrTypeNullMemberRust(declaration.type) &&
    !hasIrTypeUndefinedMemberRust(declaration.type) &&
    !getIrUnionPrimitiveDomainRust(declaration.type.types, typeContext)
  ) {
    return emitGeneralUnionRust(
      getBindingTargetNameRust(declaration.binding, context),
      createGeneralUnionVariantsRust(declaration.type.types, typeContext),
      declaration.typeParameters,
      isRustDeclarationExportedRust(declaration, context),
      typeContext,
    );
  }
  const recordProperties = isIrTypeRecordMaterializationRust(declaration.type)
    ? getIrObjectTypePropertiesRust(declaration.type, context)
    : undefined;
  if (recordProperties) {
    return emitRecord(
      getBindingTargetNameRust(declaration.binding, context),
      recordProperties,
      declaration.typeParameters,
      isRustDeclarationExportedRust(declaration, context),
      context,
    );
  }
  return [
    `${isRustDeclarationExportedRust(declaration, context) ? 'pub ' : ''}type ${getBindingTargetNameRust(declaration.binding, context)}${emitTypeParameters(declaration.typeParameters, context)} = ${emitType(declaration.type, typeContext)};`,
  ];
}

function isIrTypeRecordMaterializationRust(type: Readonly<IrType>): boolean {
  if (type.kind === 'object' || type.kind === 'intersection') return true;
  return (
    type.kind === 'named' &&
    type.reference.kind === 'ambient' &&
    ['Exclude', 'Extract', 'Omit', 'Partial', 'Pick', 'Required'].includes(type.reference.name)
  );
}

function emitTupleSpreadExpressionRust(
  expression: Readonly<Extract<IrExpression, { kind: 'tupleSpread' }>>,
  context: EmitContext,
): string {
  const declarations: string[] = [];
  const elements: string[] = [];
  let resultIndex = 0;
  for (const segment of expression.segments) {
    if (segment.kind === 'element') {
      const target = expression.type.elements[resultIndex]!;
      if (!segment.element.expression) {
        elements.push('None');
      } else {
        const name = getGeneratedTargetNameRust('tuple_spread_element', context);
        declarations.push(`let ${name} = ${emitExpression(segment.element.expression, context)};`);
        elements.push(target.optional ? `Some(${name})` : name);
      }
      resultIndex += 1;
      continue;
    }
    segment.type.elements.forEach((element, offset) => {
      if (!isIrTypeCloneSafeRust(element.type)) {
        emissionError(
          context,
          `fixed tuple spread source index ${String(offset)} lacks clone-safe Rust ownership evidence`,
        );
      }
    });
    const name = getGeneratedTargetNameRust('tuple_spread_value', context);
    declarations.push(`let ${name} = &(${emitExpression(segment.expression, context)});`);
    segment.type.elements.forEach((element, offset) => {
      const value = `${name}.${String(offset)}.clone()`;
      const target = expression.type.elements[resultIndex + offset]!;
      elements.push(target.optional && !element.optional ? `Some(${value})` : value);
    });
    resultIndex += segment.type.elements.length;
  }
  const tuple = `(${elements.join(', ')}${elements.length === 1 ? ',' : ''})`;
  return `({ ${declarations.join(' ')} ${tuple} })`;
}

function emitTypeArguments(parameters: readonly IrTypeParameter[], context: EmitContext): string {
  return parameters.length === 0
    ? ''
    : `<${parameters.map((parameter) => getBindingTargetNameRust(parameter.binding, context)).join(', ')}>`;
}

function emitTypeParameters(parameters: readonly IrTypeParameter[], context: EmitContext): string {
  if (parameters.length === 0) return '';
  return `<${parameters
    .map((parameter) => {
      const name = getBindingTargetNameRust(parameter.binding, context);
      // A TypeScript constraint is a value shape, not a Rust trait. Spelling `T extends string` as
      // `T: String` produces invalid Rust because `String` is a concrete type. Generated records do
      // clone generic storage, so Clone is the one target capability this declaration can require
      // without claiming that a source value type is a trait.
      return `${name}: Clone`;
    })
    .join(', ')}>`;
}

function emitVariable(variable: Readonly<IrVariable>, context: EmitContext): string {
  if ('pattern' in variable)
    emissionError(
      context,
      'binding patterns require destructuring lowering before Rust emission',
      'rust-binding-pattern-lowering-required',
    );
  const sharedArrayTuplePlan = context.sharedArrayTupleBindings.get(variable.binding.id);
  if (sharedArrayTuplePlan) {
    const carrier = assertRustOwnedSharedArrayTupleVariablePlanRust(variable, sharedArrayTuplePlan, context);
    const name = getBindingTargetNameRust(variable.binding, context);
    return `let ${name}: ${emitOwnedSharedArrayTupleCarrierTypeRust(carrier, context)} = ${emitOwnedSharedArrayTupleInitializerRust(carrier, context)};`;
  }
  if (context.adaptedNativeFutureLocalBindingIds.has(variable.binding.id)) {
    const awaitedType = getIrAdaptedNativeFutureLocalAwaitedTypeRust(variable, context);
    if (variable.mutable || variable.initializer?.kind !== 'call' || !awaitedType || context.insideProtectedTry) {
      emissionError(
        context,
        `native future local ${variable.binding.name} lost its exact adapted task evidence`,
        'rust-native-future-task-adapter-unavailable',
        'target-runtime',
      );
    }
    const initializer = emitExactNativeFutureTaskAdapterRust(variable.initializer, context);
    return `let ${getBindingTargetNameRust(variable.binding, context)}: FlightTask<${emitType(awaitedType, context)}> = ${normalizeSourceTextGrouping(initializer)};`;
  }
  const representationType =
    variable.type?.kind === 'unknown' && variable.initializer
      ? (inferIrExpressionTypeRust(variable.initializer, context) ?? variable.type)
      : variable.type;
  if (context.sharedArrayBindingIds.has(variable.binding.id)) {
    const type = variable.type ?? context.bindingTypes.get(variable.binding.id);
    if (!type || !getRustOwnedSharedArrayTypeRust(type, context) || !variable.initializer) {
      emissionError(
        context,
        `shared array binding ${variable.binding.name} requires an initialized array representation`,
        'rust-reference-shared-array-use-unrepresented',
      );
    }
    context.needsRefCellImport.add('RefCell');
    context.needsRcImport.add('Rc');
    const name = getBindingTargetNameRust(variable.binding, context);
    const initializer =
      variable.initializer.kind === 'identifier' &&
      variable.initializer.reference.kind === 'binding' &&
      context.sharedArrayBindingIds.has(variable.initializer.reference.binding.id)
        ? `Rc::clone(&${getBindingTargetNameRust(variable.initializer.reference.binding, context)})`
        : isIrOwnedSharedArrayReturnCallRust(variable.initializer, context)
          ? emitExpression(variable.initializer, context)
          : isIrSharedArrayIdentityMethodCallRust(variable.initializer, context)
            ? emitExpression(variable.initializer, context)
            : `Rc::new(RefCell::new(${emitOwnedOperandRust(variable.initializer, context)}))`;
    return `let ${name}: ${emitOwnedSharedArrayCarrierTypeRust(type, context)} = ${initializer};`;
  }
  const sharedClassRepresentation = context.sharedClassBindingRepresentations.get(variable.binding.id);
  if (sharedClassRepresentation) {
    const type = variable.type ?? context.bindingTypes.get(variable.binding.id);
    if (!type || !variable.initializer) {
      emissionError(
        context,
        `shared class binding ${variable.binding.name} requires an initialized exact class carrier`,
        'rust-reference-shared-class-use-unrepresented',
      );
    }
    context.needsRefCellImport.add('RefCell');
    context.needsRcImport.add('Rc');
    const name = getBindingTargetNameRust(variable.binding, context);
    const initializer = emitSharedClassCarrierExpressionRust(variable.initializer, sharedClassRepresentation, context);
    return `let ${name}: ${emitSharedClassCarrierTypeRust(type, sharedClassRepresentation, context)} = ${initializer};`;
  }
  const sharedHashCollectionKind = context.sharedMapBindingIds.has(variable.binding.id)
    ? 'map'
    : context.sharedSetBindingIds.has(variable.binding.id)
      ? 'set'
      : undefined;
  if (sharedHashCollectionKind) {
    const type = variable.type ?? context.bindingTypes.get(variable.binding.id);
    if (!isIrTypeSupportedSharedHashCollectionRust(type, sharedHashCollectionKind) || !variable.initializer) {
      const collectionName = sharedHashCollectionKind === 'map' ? 'Map' : 'Set';
      emissionError(
        context,
        `shared ${collectionName} binding ${variable.binding.name} requires an initialized exact ${collectionName}<string${sharedHashCollectionKind === 'map' ? ', primitive' : ''}> representation`,
        sharedHashCollectionKind === 'map'
          ? 'rust-reference-shared-map-use-unrepresented'
          : 'rust-reference-shared-set-use-unrepresented',
      );
    }
    context.needsRefCellImport.add('RefCell');
    context.needsRcImport.add('Rc');
    const name = getBindingTargetNameRust(variable.binding, context);
    const sharedBindingIds =
      sharedHashCollectionKind === 'map' ? context.sharedMapBindingIds : context.sharedSetBindingIds;
    const initializer =
      variable.initializer.kind === 'identifier' &&
      variable.initializer.reference.kind === 'binding' &&
      sharedBindingIds.has(variable.initializer.reference.binding.id)
        ? `Rc::clone(&${getBindingTargetNameRust(variable.initializer.reference.binding, context)})`
        : `Rc::new(RefCell::new(${emitOwnedOperandRust(variable.initializer, context)}))`;
    return `let ${name}: Rc<RefCell<${emitType(type, context)}>> = ${initializer};`;
  }
  if (variable.initialValue === 'undefined') {
    if (!variable.type) {
      emissionError(context, 'observable undefined function-entry value requires a nullable Rust type domain');
    }
    const dualSentinelNominalEnum = createRustDualSentinelNominalEnumPlanRust(variable.type, context);
    if (!isNullableType(variable.type) && !dualSentinelNominalEnum) {
      const plan = createRustUnionRepresentationPlanForTypeRust(variable.type, context);
      if (
        plan.kind === 'nominalEnum' &&
        plan.sentinels.kind === 'distinct' &&
        hasIrTypeContextualGeneralUnionCandidateRust(variable.type, plan, context)
      ) {
        refuseRustContextualGeneralUnionConstructionRust(context);
      }
      emissionError(context, 'observable undefined function-entry value requires a nullable Rust type domain');
    }
    const dualSentinelUnion = resolveDualSentinelUnionEnumRust(variable.type, context);
    const initial = dualSentinelNominalEnum
      ? `${emitType(dualSentinelNominalEnum.owner, context)}::${dualSentinelNominalEnum.undefinedVariantName}`
      : dualSentinelUnion
        ? `${dualSentinelUnion.name}::Undefined`
        : 'None';
    return `let ${variable.mutable ? 'mut ' : ''}${getBindingTargetNameRust(variable.binding, context)}: ${emitType(variable.type, context)} = ${initial};`;
  }
  if (context.cellWrappedBindingIds.has(variable.binding.id)) {
    context.needsCellImport.add('Cell');
    context.needsRcImport.add('Rc');
    const name = getBindingTargetNameRust(variable.binding, context);
    const type = variable.type ? emitType(variable.type, context) : 'f64';
    const init = variable.initializer ? emitExpression(variable.initializer, context) : '0.0';
    return `let ${name}: Rc<Cell<${type}>> = Rc::new(Cell::new(${init}));`;
  }
  if (context.refCellWrappedBindingIds.has(variable.binding.id)) {
    context.needsRefCellImport.add('RefCell');
    context.needsRcImport.add('Rc');
    const name = getBindingTargetNameRust(variable.binding, context);
    const type = variable.type ? emitType(variable.type, context) : 'String';
    const init = variable.initializer ? emitExpression(variable.initializer, context) : 'Default::default()';
    return `let ${name}: Rc<RefCell<${type}>> = Rc::new(RefCell::new(${init}));`;
  }
  if (variable.type && variable.initializer) {
    const dualSentinelUnion = resolveDualSentinelUnionEnumRust(variable.type, context);
    if (dualSentinelUnion) {
      const wrapped = emitDualSentinelUnionConstructionRust(variable.initializer, dualSentinelUnion, context);
      if (wrapped) {
        const mutable =
          variable.mutable ||
          (context.referentMutatedBindingIds.has(variable.binding.id) && !isIrTypeTypedArrayRust(variable.type));
        return `let ${mutable ? 'mut ' : ''}${getBindingTargetNameRust(variable.binding, context)}: ${emitType(variable.type, context)} = ${wrapped};`;
      }
    }
    const targetEnum = resolvePrimitiveUnionEnumRust(variable.type, context);
    if (targetEnum) {
      const wrapped = emitPrimitiveUnionConstructionRust(variable.initializer, targetEnum, context);
      if (wrapped) {
        const deferred = !variable.initializer && context.deferredBindingIds.has(variable.binding.id);
        const mutable =
          (variable.mutable && !deferred) ||
          (context.referentMutatedBindingIds.has(variable.binding.id) && !isIrTypeTypedArrayRust(variable.type));
        return `let ${mutable ? 'mut ' : ''}${getBindingTargetNameRust(variable.binding, context)}: ${emitType(variable.type, context)} = ${wrapped};`;
      }
    }
    const nominalUnion = emitExactContextualGeneralUnionConstructionRust(variable.initializer, variable.type, context);
    if (nominalUnion) {
      const mutable =
        variable.mutable ||
        (context.referentMutatedBindingIds.has(variable.binding.id) && !isIrTypeTypedArrayRust(variable.type));
      return `let ${mutable ? 'mut ' : ''}${getBindingTargetNameRust(variable.binding, context)}: ${emitType(variable.type, context)} = ${nominalUnion};`;
    }
  }
  const isArrayElementBinding = 'binding' in variable && context.arrayElementBindingIds.has(variable.binding.id);
  const type =
    representationType && !(variable.initializer?.kind === 'objectRest' && representationType.kind === 'object')
      ? `: ${isArrayElementBinding ? `Option<${emitType(representationType, context)}>` : emitType(representationType, context)}`
      : '';
  const isCallbackInitializer = variable.type?.kind === 'function' && variable.initializer?.kind === 'function';
  if (isCallbackInitializer) context.needsRcImport.add('Rc');
  const isNullableArrayElement =
    'binding' in variable &&
    (context.nullableBindingIds.has(variable.binding.id) || isArrayElementBinding) &&
    variable.initializer?.kind === 'element' &&
    !variable.initializer.optional &&
    variable.initializer.semantics.receivers.includes('array');
  const initializer = variable.initializer
    ? ` = ${normalizeSourceTextGrouping(isCallbackInitializer ? emitClosureWithCellClonesRust(variable.initializer, context) : isNullableArrayElement ? emitOptionShapedOperandRust(variable.initializer, context) : emitOwnedOperandRust(variable.initializer, context))}`
    : '';
  // A binding declared without a value and written once afterwards is Rust's deferred
  // initialization, not a mutation: the source hoisted the declaration above the assignment, and
  // `mut` on it would claim a rebinding that never happens.
  const deferred = !variable.initializer && context.deferredBindingIds.has(variable.binding.id);
  // Rust asks for `mut` to reach a value's own fields through a method, where the source language
  // only asks for it to rebind the name. A `const` the source mutates through is still `mut` here.
  const mutable =
    (variable.mutable && !deferred) ||
    (context.referentMutatedBindingIds.has(variable.binding.id) && !isIrTypeTypedArrayRust(variable.type));
  return `let ${mutable ? 'mut ' : ''}${getBindingTargetNameRust(variable.binding, context)}${type}${initializer};`;
}

function emitVariableDeclaration(declaration: Readonly<IrVariableDeclaration>, context: EmitContext): string[] {
  if ('pattern' in declaration)
    emissionError(
      context,
      'binding patterns require destructuring lowering before Rust emission',
      'rust-binding-pattern-lowering-required',
    );
  const refusal = context.moduleConstantRefusals.get(declaration.binding.id);
  if (refusal?.code === 'rust-module-array-value-unrepresented') {
    emissionRuleError(context, refusal.message, refusal.code);
  }
  const moduleState = context.moduleStateBindings.get(declaration.binding.id);
  if (moduleState) return emitModuleStateDeclarationRust(moduleState);
  if (!declaration.initializer || !declaration.type) {
    emissionRuleError(
      context,
      `module variable ${declaration.binding.name} requires an initializer and type`,
      'rust-module-variable-initializer-and-type-required',
    );
  }
  if (declaration.mutable) {
    refuseRustModuleVariableSynchronization(declaration.binding, context);
  }
  if (refusal) emissionRuleError(context, refusal.message, refusal.code);
  const plan = context.moduleConstantBindings.get(declaration.binding.id);
  const declarationIndex = context.module.declarations.indexOf(declaration);
  if (plan?.capability === 'literal-string-constant') {
    if (
      plan.declarationPath.length !== 2 ||
      plan.declarationPath[0] !== 'declarations' ||
      plan.declarationPath[1] !== declarationIndex ||
      declaration.type.kind !== 'primitive' ||
      declaration.type.name !== 'string' ||
      declaration.initializer.kind !== 'literal' ||
      typeof declaration.initializer.value !== 'string'
    ) {
      emissionRuleError(
        context,
        `module constant ${declaration.binding.name} has no matching literal string constant proof`,
        'rust-module-constant-initializer-unsupported',
      );
    }
    return [
      `${isRustDeclarationExportedRust(declaration, context) ? 'pub ' : ''}const ${getBindingTargetNameRust(declaration.binding, context)}: &'static str = ${JSON.stringify(declaration.initializer.value)};`,
    ];
  }
  if (
    !plan ||
    plan.capability !== 'primitive-const-expression' ||
    plan.declarationPath.length !== 2 ||
    plan.declarationPath[0] !== 'declarations' ||
    plan.declarationPath[1] !== declarationIndex ||
    declaration.type.kind !== 'primitive' ||
    declaration.type.name !== plan.scalar
  ) {
    emissionRuleError(
      context,
      `module constant ${declaration.binding.name} has no matching primitive Rust const-expression proof`,
      'rust-module-constant-initializer-unsupported',
    );
  }
  return [
    `${isRustDeclarationExportedRust(declaration, context) ? 'pub ' : ''}const ${getBindingTargetNameRust(declaration.binding, context)}: ${emitType(declaration.type, context)} = ${emitExpression(declaration.initializer, context)};`,
  ];
}

function emitModuleStateDeclarationRust(state: Readonly<RustModuleStateEmission>): string[] {
  const rustType = state.plan.scalar === 'number' ? 'f64' : 'bool';
  const lines = [
    `static ${state.storageName}: std::sync::Mutex<${rustType}> = std::sync::Mutex::new(${emitLiteral(state.plan.initializer)});`,
    '',
    `fn ${state.readName}() -> ${rustType} {`,
    `  *${state.storageName}.lock().unwrap_or_else(|poisoned| poisoned.into_inner())`,
    '}',
  ];
  if (state.updateName) {
    lines.push(
      '',
      `fn ${state.updateName}(increment: bool) -> (${rustType}, ${rustType}) {`,
      `  let mut guard = ${state.storageName}.lock().unwrap_or_else(|poisoned| poisoned.into_inner());`,
      '  let previous = *guard;',
      '  let updated = if increment { previous + 1.0 } else { previous - 1.0 };',
      '  *guard = updated;',
      '  (previous, updated)',
      '}',
    );
  }
  lines.push(
    '',
    `fn ${state.writeName}(value: ${rustType}) -> ${rustType} {`,
    `  *${state.storageName}.lock().unwrap_or_else(|poisoned| poisoned.into_inner()) = value;`,
    '  value',
    '}',
  );
  return lines;
}

// A string constant is emitted as `&'static str`; every value read must adapt into the owned String
// carrier. Classification follows the same export lane the emitted `use` item does, so a read is
// adapted exactly when the binding it names resolves to one planned literal string constant.
function collectRustStringConstantReadBindingIdsRust(
  module: Readonly<IrModule>,
  plan: Readonly<CompilerRustModuleConstantPlan>,
  modules: readonly Readonly<IrModule>[],
  moduleResolution: Readonly<CompilerModuleResolutionPlan> | undefined,
): ReadonlySet<string> {
  const ids = new Set<string>();
  const localPlan = plan.modules.find((candidate) => isRustCompilerModuleIdentityEqual(candidate.module, module));
  for (const binding of localPlan?.bindings ?? []) {
    if (binding.capability === 'literal-string-constant') ids.add(binding.bindingId);
  }
  for (const imported of module.imports) {
    if (imported.typeOnly) continue;
    for (const binding of imported.bindings) {
      if (binding.typeOnly || binding.imported === '*' || binding.imported === 'default') continue;
      const target = resolveImportModuleFromGraphRust(
        imported.specifier,
        binding.imported,
        moduleResolution,
        modules,
        module,
      );
      if (!target) continue;
      const location = resolveRustStringConstantProviderRust(
        target,
        binding.imported,
        modules,
        moduleResolution,
        new Set(),
      );
      if (location && isRustPlannedStringConstantProviderRust(plan, location)) {
        ids.add(binding.binding.id);
      }
    }
  }
  return ids;
}

interface RustStringConstantProviderLocation {
  readonly bindingId: string;
  readonly module: Readonly<IrModule>;
}

function resolveRustStringConstantProviderRust(
  module: Readonly<IrModule>,
  exportedName: string,
  modules: readonly Readonly<IrModule>[],
  moduleResolution: Readonly<CompilerModuleResolutionPlan> | undefined,
  visited: ReadonlySet<string>,
): RustStringConstantProviderLocation | undefined {
  const key = `${getRustModuleIdentityKey(module)}\0${exportedName}`;
  if (visited.has(key)) return undefined;
  const nextVisited = new Set(visited).add(key);
  const direct = module.declarations.flatMap((declaration): RustStringConstantProviderLocation[] =>
    declaration.kind === 'variable' &&
    'binding' in declaration &&
    declaration.exported &&
    declaration.binding.name === exportedName
      ? [{ bindingId: declaration.binding.id, module }]
      : [],
  );
  const local = module.exports.flatMap((entry): RustStringConstantProviderLocation[] => {
    if (entry.kind !== 'local' || entry.typeOnly || entry.exported !== exportedName) return [];
    const declaration = module.declarations.find(
      (candidate) =>
        candidate.kind === 'variable' && 'binding' in candidate && candidate.binding.id === entry.binding.id,
    );
    return declaration && 'binding' in declaration ? [{ bindingId: declaration.binding.id, module }] : [];
  });
  const forwarded = module.exports.flatMap((entry): RustStringConstantProviderLocation[] => {
    if (entry.kind !== 'all' && entry.kind !== 'reexport') return [];
    if (entry.typeOnly) return [];
    const importedName =
      entry.kind === 'all' ? exportedName : entry.exported === exportedName ? entry.imported : undefined;
    if (!importedName) return [];
    const target = resolveImportModuleFromGraphRust(entry.specifier, importedName, moduleResolution, modules, module);
    const location = target
      ? resolveRustStringConstantProviderRust(target, importedName, modules, moduleResolution, nextVisited)
      : undefined;
    return location ? [location] : [];
  });
  const unique = [
    ...new Map(
      [...direct, ...local, ...forwarded].map((location) => [
        `${getRustModuleIdentityKey(location.module)}\0${location.bindingId}`,
        location,
      ]),
    ).values(),
  ];
  return unique.length === 1 ? unique[0] : undefined;
}

function isRustPlannedStringConstantProviderRust(
  plan: Readonly<CompilerRustModuleConstantPlan>,
  location: RustStringConstantProviderLocation,
): boolean {
  const providerPlan = plan.modules.find((candidate) =>
    isRustCompilerModuleIdentityEqual(candidate.module, location.module),
  );
  return (
    providerPlan?.bindings.some(
      (binding) => binding.bindingId === location.bindingId && binding.capability === 'literal-string-constant',
    ) ?? false
  );
}

function isRustStringConstantNamespaceMemberRust(
  object: Readonly<IrExpression>,
  member: string,
  context: EmitContext,
): boolean {
  if (object.kind !== 'identifier' || object.reference.kind !== 'binding') return false;
  const bindingId = object.reference.binding.id;
  const imported = context.module.imports.find((item) =>
    item.bindings.some((candidate) => candidate.binding.id === bindingId && candidate.imported === '*'),
  );
  if (!imported) return false;
  const target = resolveImportModuleFromGraphRust(
    imported.specifier,
    member,
    context.moduleResolution,
    context.sourceModules,
    context.module,
  );
  if (!target) return false;
  const location = resolveRustStringConstantProviderRust(
    target,
    member,
    context.sourceModules,
    context.moduleResolution,
    new Set(),
  );
  return location ? isRustPlannedStringConstantProviderRust(context.moduleConstantPlan, location) : false;
}

function refuseRustModuleVariableSynchronization(binding: Readonly<IrBindingIdentity>, context: EmitContext): never {
  emissionRuleError(
    context,
    `mutable module variable ${binding.name} requires synchronization lowering`,
    'rust-module-variable-synchronization-unsupported',
  );
}

function getBindingTargetNameRust(
  binding: Readonly<IrBindingIdentity | IrTypeBindingIdentity>,
  context: EmitContext,
): string {
  const targetName = context.targetNames.get(binding.id);
  if (!targetName) emissionError(context, `binding ${binding.name} has no Rust target name allocation`);
  return targetName;
}

function getGeneratedTargetNameRust(preferredName: string, context: EmitContext): string {
  return allocateRustGeneratedTargetName(preferredName, context.generatedNames);
}

function allocateRustGeneratedTargetName(preferredName: string, occupied: Set<string>): string {
  let name = preferredName;
  const separator = /^[A-Z]/u.test(preferredName) ? '' : '_';
  for (let suffix = 2; occupied.has(name); suffix += 1) {
    name = `${preferredName}${separator}${String(suffix)}`;
  }
  occupied.add(name);
  return name;
}

function getElementAccessTupleIndexRust(
  expression: Readonly<Extract<IrExpression, { kind: 'element' }>>,
  context: EmitContext,
): number {
  if (
    expression.semantics.receivers.length !== 1 ||
    expression.index.kind !== 'literal' ||
    typeof expression.index.value !== 'number' ||
    !Number.isSafeInteger(expression.index.value) ||
    expression.index.value < 0
  ) {
    emissionError(context, 'tuple projection requires one statically known nonnegative integer index');
  }
  return expression.index.value;
}

// Every module's allocation, computed the same way its own emission computes it. A module whose names
// collide cannot be emitted at all, and its own emission reports that; leaving it out here keeps an
// importing module's resolution defensive instead of failing it early for someone else's collision.
function createRustTargetNameMaps(
  modules: readonly Readonly<IrModule>[],
): ReadonlyMap<string, ReadonlyMap<string, string>> {
  const maps = new Map<string, ReadonlyMap<string, string>>();
  for (const module of modules) {
    try {
      const constants = getRustConstantBindingIds(module);
      maps.set(
        getRustModuleIdentityKey(module),
        new Map(
          createIrModuleTargetNameAllocation(module, (binding) => ({
            namespace: 'identifier',
            preferredName: getRustPreferredBindingName(binding, constants),
          })).map((allocation) => [allocation.identity, allocation.name]),
        ),
      );
    } catch (error) {
      if (!isCompilerTargetNameAllocationFailure(error)) throw error;
    }
  }
  return maps;
}

function populateRustOptionalGeneratedEnumAllocations(
  modules: readonly Readonly<IrModule>[],
  targetNameMaps: ReadonlyMap<string, ReadonlyMap<string, string>>,
  allocations: Map<string, RustOptionalGeneratedEnumAllocation>,
  context: EmitContext,
): void {
  for (const module of modules) {
    const moduleKey = getRustModuleIdentityKey(module);
    const targetNames = targetNameMaps.get(moduleKey);
    if (!targetNames) continue;
    const occupied = new Set(targetNames.values());
    for (const declaration of module.declarations) {
      if (declaration.kind !== 'typeAlias' || declaration.typeParameters.length > 0) continue;
      const shape = getIrSingleSentinelUnionShapeRust(declaration.type);
      if (!shape) continue;
      const moduleContext: EmitContext = {
        ...context,
        generatedNames: new Set(targetNames.values()),
        module,
        targetNames,
      };
      if (!getIrUnionTypeMemberRecordsRust(shape.payloadType, moduleContext)) continue;
      const ownerName = targetNames.get(declaration.binding.id);
      if (!ownerName) continue;
      const key = getRustOptionalGeneratedEnumAllocationKey(module, declaration.binding.id);
      allocations.set(key, {
        key,
        module,
        name: allocateRustGeneratedTargetName(`${ownerName}Payload`, occupied),
        ownerBindingId: declaration.binding.id,
      });
    }
  }
}

function getRustOptionalGeneratedEnumAllocationKey(module: Readonly<IrModule>, ownerBindingId: string): string {
  return `${getRustModuleIdentityKey(module)}\0${ownerBindingId}\0optional-payload`;
}

function getRustModuleIdentityKey(module: Readonly<IrModule>): string {
  return `${module.packageName}\0${path.posix.normalize(module.source)}\0${module.name}`;
}

// The same identity a person reads in a diagnostic. The key above separates its fields with NUL so a
// package, path, or name cannot forge a boundary, which is exactly what a message must not print.
function formatRustModuleSubjectRust(module: Readonly<IrModule>): string {
  return `${module.packageName}/${module.source}#${module.name}`;
}

// What a facade names a re-export. The alias is this module's own public name, so it follows the same
// space rule a declaration of that space would.
function getRustExportAliasName(space: 'type' | 'value', exported: string): string {
  return space === 'type' ? safeRustTypeName(exported) : safeRustValueName(exported);
}

type RustExportedTargetNameResolution =
  | Readonly<{ kind: 'absent'; starExports: boolean }>
  | Readonly<{ kind: 'ambiguous'; owners: readonly string[] }>
  | Readonly<{ kind: 'resolved'; name: string }>
  | Readonly<{ kind: 'ungrounded' }>
  | Readonly<{ kind: 'undetermined' }>;

type RustDeclaredExportResolution =
  | Readonly<{ kind: 'absent'; starExports: boolean }>
  | Readonly<{ kind: 'ambiguous'; owners: readonly string[] }>
  | Readonly<{ kind: 'resolved'; name: string; space: 'type' | 'value' }>
  | Readonly<{ kind: 'ungrounded' }>
  | Readonly<{ kind: 'undetermined' }>;

type RustExplicitExportGroundingResolution =
  | Readonly<{ kind: 'ambiguous'; owners: readonly string[] }>
  | Readonly<{ kind: 'grounded'; name: string; space: 'type' | 'value' }>
  | Readonly<{ kind: 'ungrounded' }>
  | Readonly<{ kind: 'undetermined' }>;

/**
 * The spelling a module's own allocation gave one of the names it exports.
 *
 * A direct exported declaration answers from that module's allocation; a facade entry answers with the
 * alias its `pub use` spells, which is the same helper the re-export emission uses, so an import and the
 * re-export it names cannot disagree. An `export *` entry carries no exported name of its own, so the
 * only evidence for one is the module it stars, followed transitively; the visited set ends a cycle and
 * the owners decide whether the name is reachable exactly once or through competing barrels.
 */
function resolveRustExportedTargetNameRust(
  module: Readonly<IrModule>,
  exportedName: string,
  space: 'type' | 'value',
  context: EmitContext,
  visited: ReadonlySet<string>,
): RustExportedTargetNameResolution {
  const visitKey = `${getRustModuleIdentityKey(module)}\0${exportedName}\0${space}`;
  // A re-export cycle returns to a module it already asked, so it can answer for nothing on its own.
  if (visited.has(visitKey)) return { kind: 'absent', starExports: false };
  const nextVisited = new Set(visited).add(visitKey);
  const allocation = context.targetNameMaps.get(getRustModuleIdentityKey(module));
  const isTypeDeclaration = (kind: string): boolean =>
    kind === 'class' || kind === 'enum' || kind === 'interface' || kind === 'typeAlias';
  const isValueDeclaration = (kind: string): boolean =>
    kind === 'class' || kind === 'enum' || kind === 'function' || kind === 'variable';
  const declaration = module.declarations.find(
    (candidate) =>
      'binding' in candidate &&
      candidate.exported &&
      candidate.binding.name === exportedName &&
      (space === 'type' ? isTypeDeclaration(candidate.kind) : isValueDeclaration(candidate.kind)),
  );
  if (declaration && 'binding' in declaration) {
    const name = allocation?.get(declaration.binding.id);
    return name === undefined ? { kind: 'absent', starExports: false } : { kind: 'resolved', name };
  }
  const exported = module.exports.find(
    (entry) =>
      'exported' in entry &&
      entry.exported === exportedName &&
      (space === 'type' ? entry.typeOnly === true : entry.typeOnly !== true || entry.kind !== 'local'),
  );
  if (exported && 'exported' in exported) {
    if (exported.kind === 'local') {
      const name = allocation?.get(exported.binding.id);
      return name === undefined ? { kind: 'absent', starExports: false } : { kind: 'resolved', name };
    }
    if (exported.kind === 'namespace') return { kind: 'resolved', name: safeRustValueName(exported.exported) };
    const inner = resolveImportModuleRust(exported.specifier, exported.imported, context, module);
    if (!inner) return { kind: 'undetermined' };
    const grounding = resolveRustExplicitExportGroundingRust(
      inner,
      exported.imported,
      exported.typeOnly ? 'type' : 'value',
      context,
      nextVisited,
    );
    if (grounding.kind !== 'grounded') return grounding;
    return { kind: 'resolved', name: getRustExportAliasName(grounding.space, exported.exported) };
  }
  // The entries left are `export *` (and default, which has no exported name). A star re-exports the
  // names its target publishes verbatim, so the target's allocation is the answer; a type-only star
  // publishes no values.
  const owners = new Map<string, string>();
  let starExports = false;
  let undetermined = false;
  for (const entry of module.exports) {
    if (entry.kind !== 'all') continue;
    if (space === 'value' && entry.typeOnly) continue;
    const target = resolveImportModuleRust(entry.specifier, exportedName, context, module);
    if (!target) {
      undetermined = true;
      continue;
    }
    starExports = true;
    const ownerLabel = formatRustModuleSubjectRust(target);
    const answer = resolveRustExportedTargetNameRust(target, exportedName, space, context, nextVisited);
    if (answer.kind === 'resolved') {
      owners.set(ownerLabel, answer.name);
      continue;
    }
    if (answer.kind === 'ambiguous') {
      for (const owner of answer.owners) owners.set(owner, '');
      continue;
    }
    if (answer.kind === 'undetermined') undetermined = true;
    else if (answer.kind === 'ungrounded') starExports = true;
    else if (answer.starExports) starExports = true;
  }
  if (owners.size > 1) return { kind: 'ambiguous', owners: [...owners.keys()].sort(compareTextCodeUnits) };
  if (owners.size === 1) return { kind: 'resolved', name: [...owners.values()][0]! };
  return undetermined ? { kind: 'undetermined' } : { kind: 'absent', starExports };
}

// An explicit alias is sound only when its target reaches a declaration. Probe both of TypeScript's
// independent spaces, bounded by the same module/name/space key as ordinary export resolution. Missing
// graph edges stay undetermined for legacy isolated emission, while a completely explored chain that
// reaches no declaration is ungrounded.
function resolveRustExplicitExportGroundingRust(
  module: Readonly<IrModule>,
  exportedName: string,
  preferredSpace: 'type' | 'value',
  context: EmitContext,
  visited: ReadonlySet<string>,
): RustExplicitExportGroundingResolution {
  const preferred = resolveRustExportedTargetNameRust(module, exportedName, preferredSpace, context, visited);
  if (preferred.kind === 'resolved') return { kind: 'grounded', name: preferred.name, space: preferredSpace };
  const other = preferredSpace === 'type' ? 'value' : 'type';
  const secondary = resolveRustExportedTargetNameRust(module, exportedName, other, context, visited);
  if (secondary.kind === 'resolved') return { kind: 'grounded', name: secondary.name, space: other };
  if (preferred.kind === 'ambiguous') {
    const owners = new Set([...preferred.owners, ...(secondary.kind === 'ambiguous' ? secondary.owners : [])]);
    return { kind: 'ambiguous', owners: [...owners].sort(compareTextCodeUnits) };
  }
  if (secondary.kind === 'ambiguous') return secondary;
  if (preferred.kind === 'undetermined' || secondary.kind === 'undetermined') return { kind: 'undetermined' };
  return { kind: 'ungrounded' };
}

// TypeScript lets a name change space between the declaration and the use: `export interface X` is a
// type while `import { X }` is written in value space, and `export { X }` does not say which it means.
// The declaring module is the only authority, so ask it in the preferred space and then in the other one.
function resolveRustDeclaredExportRust(
  module: Readonly<IrModule>,
  exportedName: string,
  preferredSpace: 'type' | 'value',
  context: EmitContext,
): RustDeclaredExportResolution {
  const preferred = resolveRustExportedTargetNameRust(module, exportedName, preferredSpace, context, new Set());
  if (preferred.kind === 'resolved') return { kind: 'resolved', name: preferred.name, space: preferredSpace };
  const other = preferredSpace === 'type' ? 'value' : 'type';
  const secondary = resolveRustExportedTargetNameRust(module, exportedName, other, context, new Set());
  if (secondary.kind === 'resolved') return { kind: 'resolved', name: secondary.name, space: other };
  if (preferred.kind === 'ambiguous') {
    const owners = new Set([...preferred.owners, ...(secondary.kind === 'ambiguous' ? secondary.owners : [])]);
    return { kind: 'ambiguous', owners: [...owners].sort(compareTextCodeUnits) };
  }
  if (secondary.kind === 'ambiguous') return secondary;
  if (preferred.kind === 'undetermined' || secondary.kind === 'undetermined') return { kind: 'undetermined' };
  if (preferred.kind === 'ungrounded' || secondary.kind === 'ungrounded') return { kind: 'ungrounded' };
  return { kind: 'absent', starExports: preferred.starExports || secondary.starExports };
}

// A name no barrel publishes and a name every one of several barrels publishes are both facts a caller
// can branch on, and both would otherwise become a guessed spelling that only rustc rejects.
function assertRustDeclaredExportResolutionRust(
  resolution: RustDeclaredExportResolution,
  module: Readonly<IrModule>,
  exportedName: string,
  context: EmitContext,
): void {
  assertRustExportedTargetNameResolutionRust(resolution, module, exportedName, context);
}

function assertRustExportedTargetNameResolutionRust(
  resolution: RustDeclaredExportResolution | RustExplicitExportGroundingResolution | RustExportedTargetNameResolution,
  module: Readonly<IrModule>,
  exportedName: string,
  context: EmitContext,
): void {
  const subject = formatRustModuleSubjectRust(module);
  if (resolution.kind === 'ambiguous') {
    emissionRuleError(
      context,
      `exported name ${exportedName} of ${subject} is reached through multiple star re-exports (${resolution.owners.join(', ')})`,
      'rust-export-name-ambiguous',
    );
  }
  if (resolution.kind === 'ungrounded') {
    emissionRuleError(
      context,
      `exported name ${exportedName} of ${subject} has no grounded declaration through its explicit re-export chain`,
      'rust-export-name-ungrounded',
    );
  }
  if (resolution.kind === 'absent' && resolution.starExports) {
    emissionRuleError(
      context,
      `exported name ${exportedName} of ${subject} is unreachable through its star re-exports`,
      'rust-export-name-unresolved',
    );
  }
}

// A namespace import is a module alias in Rust, so a member read off it is a path, not a field. The
// member is spelled the way the declaring module allocated it, exactly as a named import is.
function getRustNamespaceImportMemberRust(
  object: Readonly<IrExpression>,
  member: string,
  context: EmitContext,
): string | undefined {
  if (object.kind !== 'identifier' || object.reference.kind !== 'binding') return undefined;
  const bindingId = object.reference.binding.id;
  const imported = context.module.imports.find((item) =>
    item.bindings.some((candidate) => candidate.binding.id === bindingId && candidate.imported === '*'),
  );
  if (!imported) return undefined;
  const targetModule = resolveImportModuleRust(imported.specifier, member, context);
  let memberName: string | undefined;
  if (targetModule) {
    const resolution = resolveRustDeclaredExportRust(targetModule, member, 'value', context);
    assertRustDeclaredExportResolutionRust(resolution, targetModule, member, context);
    memberName = resolution.kind === 'resolved' ? resolution.name : undefined;
  }
  return `${getBindingTargetNameRust(object.reference.binding, context)}::${memberName ?? safeRustValueName(member)}`;
}

// An imported enum member is a variant of a foreign type. The consumer's `use` item owns the only
// spelling it may use: the import alias, which keeps any collision renaming in step with that item.
// The declaration is still resolved so the member and the enum itself are facts rather than guesses.
// A named import reads `Alias::Variant`; a namespace import reads through the already-correct
// `alias::Enum` path emitted for its inner member.
function emitRustImportedEnumMemberRust(
  expression: Readonly<Extract<IrExpression, { kind: 'property' }>>,
  context: EmitContext,
): string | undefined {
  const declaration = resolveRustImportedEnumMemberDeclarationRust(expression, context);
  if (!declaration) return undefined;
  const object = expression.object;
  if (object.kind === 'identifier' && object.reference.kind === 'binding') {
    return `${getBindingTargetNameRust(object.reference.binding, context)}::${safeRustTypeName(expression.name)}`;
  }
  if (object.kind !== 'property') return undefined;
  return `${emitExpression(object, context)}::${safeRustTypeName(expression.name)}`;
}

// The evidence a member read carries, independent of how it is spelled. Named and namespace imports
// reduce to the same question: which declaration, and does it own this member. A property read that
// resolves no enum is not this shape and keeps whatever path it already had.
function resolveRustImportedEnumMemberDeclarationRust(
  expression: Readonly<Extract<IrExpression, { kind: 'property' }>>,
  context: EmitContext,
): Readonly<IrEnumDeclaration> | undefined {
  const object = expression.object;
  let targetModule: Readonly<IrModule> | undefined;
  let exportedName: string;
  let space: 'type' | 'value';
  if (object.kind === 'identifier' && object.reference.kind === 'binding') {
    const imported = getRustNamedImportBindingRust(object.reference.binding.id, context);
    if (!imported) return undefined;
    targetModule = resolveImportModuleRust(imported.specifier, imported.imported, context);
    exportedName = imported.imported;
    space = imported.space;
  } else if (
    object.kind === 'property' &&
    object.object.kind === 'identifier' &&
    object.object.reference.kind === 'binding'
  ) {
    const namespace = getRustNamespaceImportBindingRust(object.object.reference.binding.id, context);
    if (!namespace) return undefined;
    targetModule = resolveImportModuleRust(namespace.specifier, object.name, context);
    exportedName = object.name;
    space = 'value';
  } else {
    return undefined;
  }
  if (!targetModule) return undefined;
  const declaration = resolveRustImportedEnumDeclarationRust(targetModule, exportedName, space, context);
  if (!declaration) return undefined;
  assertRustImportedEnumMemberExistsRust(declaration, expression.name, context);
  return declaration;
}

function getRustNamedImportBindingRust(
  bindingId: string,
  context: EmitContext,
): Readonly<{ imported: string; space: 'type' | 'value'; specifier: string }> | undefined {
  for (const item of context.module.imports) {
    for (const candidate of item.bindings) {
      if (candidate.binding.id === bindingId && candidate.imported !== '*' && candidate.imported !== 'default') {
        return { imported: candidate.imported, space: candidate.binding.space, specifier: item.specifier };
      }
    }
  }
  return undefined;
}

function getRustNamespaceImportBindingRust(
  bindingId: string,
  context: EmitContext,
): Readonly<{ specifier: string }> | undefined {
  const imported = context.module.imports.find((item) =>
    item.bindings.some((candidate) => candidate.binding.id === bindingId && candidate.imported === '*'),
  );
  return imported ? { specifier: imported.specifier } : undefined;
}

// The shared export lane decides whether the name is reachable at all, and keeps its own rule ids for
// ambiguity, ungrounded explicit chains, and unreachable star export lanes. Only a uniquely grounded
// enum declaration answers here; a non-enum export is not this shape and stays on its existing path.
function resolveRustImportedEnumDeclarationRust(
  module: Readonly<IrModule>,
  exportedName: string,
  preferredSpace: 'type' | 'value',
  context: EmitContext,
): Readonly<IrEnumDeclaration> | undefined {
  const resolution = resolveRustDeclaredExportRust(module, exportedName, preferredSpace, context);
  assertRustDeclaredExportResolutionRust(resolution, module, exportedName, context);
  if (resolution.kind !== 'resolved' || resolution.space !== 'value') return undefined;
  const locations = getRustExportedEnumDeclarationLocations(module, exportedName, context, new Set());
  if (locations.length > 1) {
    emissionRuleError(
      context,
      `imported enum ${exportedName} of ${formatRustModuleSubjectRust(module)} reaches multiple enum declarations`,
      'rust-imported-enum-member-unresolved',
    );
  }
  return locations[0]?.declaration;
}

function assertRustImportedEnumMemberExistsRust(
  declaration: Readonly<IrEnumDeclaration>,
  member: string,
  context: EmitContext,
): void {
  if (declaration.members.some((candidate) => candidate.name === member)) return;
  emissionRuleError(
    context,
    `imported enum ${declaration.binding.name} has no member ${member}`,
    'rust-imported-enum-member-unresolved',
  );
}

// The rule a name gets when nothing can be asked. A single-module emission has no declaring allocation
// to read, and this is the rule it has always used; it is the fallback, not the answer.
function getRustNameShapeFallback(name: string, typeOnly: boolean): string {
  return typeOnly || /^[A-Z]/u.test(name) ? safeRustTypeName(name) : safeRustValueName(name);
}

function getTypeReferenceTargetNameRust(type: Readonly<IrTypeReference>, context: EmitContext): string {
  if (type.reference.kind === 'ambient') {
    if (rustPanicErrorConstructorNames.has(type.reference.name)) {
      emissionError(
        context,
        `typed ambient ${type.reference.name} requires a represented Rust error carrier and member API`,
        'rust-runtime-error-carrier-incomplete',
        'target-runtime',
      );
    }
    const targetName = getCompilerRuntimeExternalSymbolTargetRust(
      type.reference.name,
      'type',
      context.options.hostBindings,
    );
    if (!targetName)
      emissionError(
        context,
        `external type ${type.reference.name} has no Rust binding`,
        'rust-runtime-external-symbol-binding-incomplete',
        'target-runtime',
      );
    return isCompilerRuntimeExternalSymbolProvidedRust(type.reference.name, 'type', context.options.hostBindings)
      ? recordRuntimeTypeRust(targetName, context)
      : targetName;
  }
  return [
    getTypeBindingTargetNameRust(type.reference.binding, context),
    ...type.reference.path.map(safeRustTypeName),
  ].join('::');
}

function getTypeBindingTargetNameRust(
  binding: Readonly<IrBindingIdentity | IrTypeBindingIdentity>,
  context: EmitContext,
): string {
  const allocated = context.targetNames.get(binding.id);
  if (allocated) return allocated;
  for (const module of context.sourceModules) {
    const declaration = module.declarations.find(
      (candidate) => 'binding' in candidate && candidate.binding.id === binding.id,
    );
    if (declaration && 'binding' in declaration) {
      return getRustQualifiedTypeName(module, declaration.binding.name, context);
    }
    const imported = module.imports
      .flatMap((item) => item.bindings.map((candidate) => ({ candidate, specifier: item.specifier })))
      .find(({ candidate }) => candidate.binding.id === binding.id);
    if (!imported || imported.candidate.imported === '*' || imported.candidate.imported === 'default') continue;
    const target = resolveImportModuleRust(imported.specifier, imported.candidate.imported, context, module);
    if (target) return getRustQualifiedTypeName(target, imported.candidate.imported, context);
  }
  emissionError(context, `binding ${binding.name} has no Rust type target resolution`);
}

function getRustQualifiedTypeName(module: Readonly<IrModule>, name: string, context: EmitContext): string {
  const targetName = safeRustTypeName(name);
  const base =
    module.packageName === context.module.packageName
      ? 'crate'
      : convertPackageNameToRustCrateName(module.packageName).replaceAll('-', '_');
  return `${formatRustModuleCratePathRust(getRustModulePathRust(module, context.sourceModules), base)}::${targetName}`;
}

function assertStructuralObjectCompatibilityRust(
  module: Readonly<IrModule>,
  modules: readonly Readonly<IrModule>[],
  resolution: Readonly<CompilerModuleResolutionPlan> | undefined,
): void {
  // An object literal passed straight to an ambient Object method has no contextual structural target
  // and is refused by the Object rules that own that call. The structural gate would otherwise report
  // the open target first and hide the more specific refusal; nothing is accepted here that the
  // Object surface does not either enumerate (Object.keys) or refuse.
  const objectArgumentExpressions = collectRustAmbientObjectArgumentExpressionsRust(module);
  const diagnostics = analyzeIrModuleStructuralObjectCompatibilityAcrossModules(
    module,
    modules,
    resolution,
  ).diagnostics.filter(
    (candidate) => !isRustAmbientObjectArgumentPathRust(module, objectArgumentExpressions, candidate.path),
  );
  const diagnostic =
    diagnostics.find((candidate) => candidate.disposition !== 'indeterminate') ??
    diagnostics.find((candidate) => candidate.code !== 'unresolved-named-construction-target');
  if (diagnostic) {
    throw createBackendEmissionFailure(
      'rust',
      module,
      `structural object compatibility ${diagnostic.code} at ${JSON.stringify(diagnostic.path)}: ${diagnostic.message}`,
    );
  }
}

function replaceIrModuleBackendContext(
  modules: readonly Readonly<IrModule>[],
  replacement: Readonly<IrModule>,
): readonly Readonly<IrModule>[] {
  return modules.map((module) =>
    module.packageName === replacement.packageName &&
    module.source === replacement.source &&
    module.name === replacement.name
      ? replacement
      : module,
  );
}

function assertSparseArrayLiteralRepresentationRust(module: Readonly<IrModule>): void {
  let sparse = false;
  analyzeIrModuleTraversal(module, {
    expression(expression) {
      if (expression.kind === 'array' && expression.elements.some((element) => element === undefined)) sparse = true;
    },
  });
  if (!sparse) return;
  throw createBackendEmissionFailure(
    'rust',
    module,
    'sparse array literals require a hole-preserving Rust sequence carrier; dense Vec cannot distinguish an omitted element from a stored value',
    'rust-sparse-array-literal-runtime-required',
    { classification: 'target-runtime' },
  );
}

function assertModuleArrayValueRepresentationRust(
  sourceModule: Readonly<IrModule>,
  module: Readonly<IrModule>,
  plan: Readonly<CompilerRustModuleConstantModulePlan> | undefined,
  salvage: RustSalvageRequest | undefined,
): void {
  const local = plan?.refusals.find((refusal) => refusal.code === 'rust-module-array-value-unrepresented');
  if (salvage === undefined && local) {
    const index = local.declarationPath[0] === 'declarations' ? local.declarationPath[1] : undefined;
    const declaration = typeof index === 'number' ? sourceModule.declarations[index] : undefined;
    const origin =
      declaration?.kind === 'variable' && 'binding' in declaration && declaration.binding.id === local.bindingId
        ? declaration.origin
        : undefined;
    throw createBackendEmissionFailure('rust', module, local.message, local.code, {
      ...(origin ? { column: origin.column, line: origin.line } : {}),
    });
  }
  const imported = plan?.importRefusals.find(
    (refusal) => salvage === undefined || !isRustModuleArrayImportDeclarationOwned(module, refusal.bindingId),
  );
  if (imported) {
    throw createBackendEmissionFailure('rust', module, imported.message, imported.code);
  }
}

function isRustModuleArrayImportDeclarationOwned(module: Readonly<IrModule>, bindingId: string): boolean {
  if (module.exports.some((exported) => exported.kind === 'local' && exported.binding.id === bindingId)) return false;
  const declarations = new Set<Readonly<IrDeclaration>>();
  let outsideDeclaration = false;
  const observe = (candidateBindingId: string | undefined, traversalPath: CompilerIrTraversalPath): void => {
    if (candidateBindingId !== bindingId) return;
    const declaration = getRustTraversalDeclarationRust(module, traversalPath);
    if (declaration) declarations.add(declaration);
    else outsideDeclaration = true;
  };
  analyzeIrModuleTraversal(module, {
    expression(expression, traversalPath) {
      observe(
        expression.kind === 'identifier' && expression.reference.kind === 'binding'
          ? expression.reference.binding.id
          : expression.kind === 'property' && expression.namespaceMember?.kind === 'binding'
            ? expression.namespaceMember.binding.id
            : undefined,
        traversalPath,
      );
    },
    type(type, traversalPath) {
      observe(
        'reference' in type && type.reference.kind === 'binding' ? type.reference.binding.id : undefined,
        traversalPath,
      );
    },
  });
  return declarations.size > 0 && !outsideDeclaration;
}

function assertRuntimeExternalSymbolBindingsRust(
  module: Readonly<IrModule>,
  options: Readonly<RustCompilerBackendOptions>,
): void {
  const completeness = analyzeCompilerRuntimeExternalSymbolCompleteness(
    collectIrModulesRuntimeExternalSymbolIdentities([module]),
    createCompilerRuntimeExternalSymbolBindingPlanRust(options.hostBindings),
  );
  if (completeness.kind === 'complete') return;
  const problems = [
    completeness.missingExternalSymbols.length > 0
      ? `missing: ${completeness.missingExternalSymbols.map(formatRuntimeExternalSymbolIdentity).join(', ')}`
      : undefined,
    completeness.duplicateExternalSymbols.length > 0
      ? `duplicate: ${completeness.duplicateExternalSymbols.map(formatRuntimeExternalSymbolIdentity).join(', ')}`
      : undefined,
  ].filter((problem): problem is string => problem !== undefined);
  throw createBackendEmissionFailure(
    'rust',
    module,
    `runtime external symbol binding plan is incomplete (${problems.join('; ')})`,
    'rust-runtime-external-symbol-binding-incomplete',
    { classification: 'target-runtime' },
  );
}

type RustArrayBoundsValueUse =
  | Readonly<{
      expression: Readonly<Extract<IrExpression, { kind: 'assignment' | 'binary' | 'undefinedDefault' }>>;
      kind: 'expression';
      position: 'fallback' | 'left' | 'right' | 'value';
    }>
  | Readonly<{ kind: 'discarded' }>
  | Readonly<{ kind: 'optionalChainReceiver' }>
  | Readonly<{ kind: 'return'; type: Readonly<IrType> | undefined }>
  | Readonly<{ bindingId: string | undefined; kind: 'variable'; type: Readonly<IrType> | undefined }>;

interface RustArrayBoundsPlan {
  readonly elementPlaces: ReadonlySet<Readonly<Extract<IrExpression, { kind: 'element' }>>>;
  readonly optionElementReads: ReadonlySet<Readonly<Extract<IrExpression, { kind: 'element' }>>>;
  readonly provenElementProofs: ReadonlyMap<
    Readonly<Extract<IrExpression, { kind: 'element' }>>,
    RustArrayBoundsProofKind
  >;
}

interface RustArrayBoundsRefusal {
  readonly member: 'index' | 'pop' | 'shift';
  readonly message: string;
  readonly rule:
    | 'rust-array-index-key-domain-unrepresented'
    | 'rust-array-index-result-absence-unrepresented'
    | 'rust-array-pop-invocation-unrepresented'
    | 'rust-array-pop-result-carrier-unrepresented'
    | 'rust-array-pop-result-observation-unrepresented'
    | 'rust-array-shift-invocation-unrepresented'
    | 'rust-array-shift-result-carrier-unrepresented'
    | 'rust-array-shift-result-observation-unrepresented';
}

function createRustArrayBoundsPlan(
  module: Readonly<IrModule>,
  sharedArrayBindingIds: ReadonlySet<string>,
): RustArrayBoundsPlan {
  const uses = new Map<Readonly<IrExpression>, RustArrayBoundsValueUse>();
  const signatures: Array<Readonly<{ path: CompilerIrTraversalPath; returns: Readonly<IrType> }>> = [];
  const pendingReturns: Array<Readonly<{ expression: Readonly<IrExpression>; path: CompilerIrTraversalPath }>> = [];
  const elementReads: Array<Readonly<Extract<IrExpression, { kind: 'element' }>>> = [];
  const popCalls: Array<Readonly<Extract<IrExpression, { kind: 'call' }>>> = [];
  const shiftCalls: Array<Readonly<Extract<IrExpression, { kind: 'call' }>>> = [];

  analyzeIrModuleTraversal(module, {
    expression(expression) {
      if (expression.kind === 'assignment') {
        uses.set(expression.left, { expression, kind: 'expression', position: 'left' });
        uses.set(expression.right, { expression, kind: 'expression', position: 'right' });
      } else if (expression.kind === 'binary') {
        uses.set(expression.left, { expression, kind: 'expression', position: 'left' });
        uses.set(expression.right, { expression, kind: 'expression', position: 'right' });
      } else if (expression.kind === 'undefinedDefault') {
        uses.set(expression.value, { expression, kind: 'expression', position: 'value' });
        uses.set(expression.fallback, { expression, kind: 'expression', position: 'fallback' });
      } else if (expression.kind === 'function' && expression.expression) {
        uses.set(expression.expression, { kind: 'return', type: expression.returns });
      }
      // An ordinary element read used as the object of a short-circuiting optional chain is an
      // absence-observed use: the chain's Option carrier is exactly the element's absence, and the
      // existing optional property/element lowering maps over it.
      // An ordinary element read as the object of an optional access is absence-observed even when
      // the chain's payload receiver excludes nullish: the element's own absence is what short-
      // circuits, exactly as the C++ indexed-runtime-collection case models it. Only an ordinary
      // element object qualifies; every other excluded receiver keeps its direct-read behaviour.
      if (expression.kind === 'property' && expression.optional) {
        const object = expression.object;
        if (object.kind === 'element' && !object.optional && hasOnlyOrdinaryArrayReceiverRust(object)) {
          uses.set(object, { kind: 'optionalChainReceiver' });
        }
      }

      if (expression.kind === 'element' && hasOnlyOrdinaryArrayReceiverRust(expression)) {
        elementReads.push(expression);
      } else if (expression.kind === 'call' && isArrayShiftCallRust(expression)) {
        shiftCalls.push(expression);
      } else if (expression.kind === 'call' && isArrayPopCallRust(expression)) {
        popCalls.push(expression);
      }
    },
    functionSignature(signature, path_) {
      signatures.push({ path: path_, returns: signature.returns });
    },
    statement(statement, path_) {
      if (statement.kind === 'return' && statement.expression) {
        pendingReturns.push({ expression: statement.expression, path: path_ });
      } else if (statement.kind === 'expression') {
        uses.set(statement.expression, { kind: 'discarded' });
      }
    },
    variable(variable) {
      if (variable.initializer) {
        uses.set(variable.initializer, {
          bindingId: 'binding' in variable ? variable.binding.id : undefined,
          kind: 'variable',
          type: variable.type,
        });
      }
    },
  });

  for (const returned of pendingReturns) {
    const owner = signatures
      .filter(({ path: signaturePath }) => isRustTraversalPathPrefix(signaturePath, returned.path))
      .sort((left, right) => right.path.length - left.path.length)[0];
    uses.set(returned.expression, { kind: 'return', type: owner?.returns });
  }

  const bindingTypes = collectIrModuleBindingTypesRust(module);
  const arrayElementBindingIds = collectIrModuleArrayElementBindingIdsRust(module);
  const elementPlaces = new Set<Readonly<Extract<IrExpression, { kind: 'element' }>>>();
  const optionElementReads = new Set<Readonly<Extract<IrExpression, { kind: 'element' }>>>();
  const excludedWriteElements = collectRustExcludedProvenWriteElementsRust(module, bindingTypes, sharedArrayBindingIds);
  const provenElementProofs = collectRustProvenBoundsElementReadsRust(
    module,
    bindingTypes,
    excludedWriteElements,
    collectRustArrayWriteTargetElementsRust(module),
    sharedArrayBindingIds,
  );
  const refusals: RustArrayBoundsRefusal[] = [];

  for (const expression of elementReads) {
    const use = uses.get(expression);
    if (
      use?.kind === 'expression' &&
      use.expression.kind === 'assignment' &&
      use.position === 'left' &&
      use.expression.operator === '='
    ) {
      elementPlaces.add(expression);
      continue;
    }
    if (hasMultipleOrdinaryArrayReceiverAlternativesRust(expression, bindingTypes, module)) {
      if (
        use?.kind === 'return' &&
        expression.semantics.key === 'number' &&
        !hasRustUnionArrayElementUndefinedResultCarrierRust(use.type, module)
      ) {
        refusals.push({
          member: 'index',
          message: 'ordinary array element read can be absent, but this use has no Rust Option carrier',
          rule: 'rust-array-index-result-absence-unrepresented',
        });
      }
      continue;
    }
    if (expression.semantics.key !== 'number') {
      refusals.push({
        member: 'index',
        message:
          'ordinary array element access requires a numeric JavaScript index domain; property-like keys have no Vec representation',
        rule: 'rust-array-index-key-domain-unrepresented',
      });
      continue;
    }
    if (
      provenElementProofs.has(expression) &&
      !isRustArrayAbsenceRepresentedUse(use, bindingTypes, arrayElementBindingIds)
    ) {
      continue;
    }
    if (isRustArrayAbsenceRepresentedUse(use, bindingTypes, arrayElementBindingIds)) {
      optionElementReads.add(expression);
      continue;
    }
    refusals.push({
      member: 'index',
      message: 'ordinary array element read can be absent, but this use has no Rust Option carrier',
      rule: 'rust-array-index-result-absence-unrepresented',
    });
  }

  for (const expression of shiftCalls) {
    if (expression.arguments.length !== 0) {
      refusals.push({
        member: 'shift',
        message: 'array.shift with arguments has no exact Rust invocation',
        rule: 'rust-array-shift-invocation-unrepresented',
      });
      continue;
    }
    if (!isRustSingleUndefinedOptionCarrier(expression.semantics.resultType)) {
      refusals.push({
        member: 'shift',
        message: 'array.shift result does not have one undefined-admitting Rust Option carrier',
        rule: 'rust-array-shift-result-carrier-unrepresented',
      });
      continue;
    }
    if (!isRustArrayAbsenceRepresentedUse(uses.get(expression), bindingTypes, arrayElementBindingIds)) {
      refusals.push({
        member: 'shift',
        message:
          'array.shift can return undefined for an empty array, but this observed result has no Rust Option carrier',
        rule: 'rust-array-shift-result-observation-unrepresented',
      });
    }
  }

  for (const expression of popCalls) {
    if (expression.arguments.length !== 0) {
      refusals.push({
        member: 'pop',
        message: 'array.pop with arguments has no exact Rust invocation',
        rule: 'rust-array-pop-invocation-unrepresented',
      });
      continue;
    }
    if (!isRustSingleUndefinedOptionCarrier(expression.semantics.resultType)) {
      refusals.push({
        member: 'pop',
        message: 'array.pop result does not have one undefined-admitting Rust Option carrier',
        rule: 'rust-array-pop-result-carrier-unrepresented',
      });
      continue;
    }
    if (!isRustArrayAbsenceRepresentedUse(uses.get(expression), bindingTypes, arrayElementBindingIds)) {
      refusals.push({
        member: 'pop',
        message:
          'array.pop can return undefined for an empty array, but this observed result has no Rust Option carrier',
        rule: 'rust-array-pop-result-observation-unrepresented',
      });
    }
  }

  const refusal = refusals.sort((left, right) =>
    compareTextCodeUnits(`${left.rule}\u0000${left.member}`, `${right.rule}\u0000${right.member}`),
  )[0];
  if (refusal) {
    throw createBackendEmissionFailure('rust', module, refusal.message, refusal.rule, {
      classification: 'target-runtime',
    });
  }
  return { elementPlaces, optionElementReads, provenElementProofs };
}

type RustArrayBoundsProofKind = 'dual-bound' | 'monotone' | 'nonempty-zero';

type RustArrayBoundsProvenGuard =
  | Readonly<{
      arrayBindingId: string;
      indexBindingId: string;
      kind: 'dual-bound';
    }>
  | Readonly<{
      arrayBindingId: string;
      indexBindingId: string;
      kind: 'monotone';
      monotoneLoop: Readonly<Extract<IrStatement, { kind: 'while' }>>;
    }>
  | Readonly<{
      arrayBindingId: string;
      kind: 'nonempty-zero';
    }>;

interface RustArrayIndexWrite {
  readonly node: Readonly<Extract<IrExpression, { kind: 'assignment' | 'unary' }>>;
  readonly operator: IrAssignmentOperator | '++' | '--';
  readonly right: Readonly<IrExpression> | undefined;
}

interface RustArrayIndexEvidence {
  readonly writes: RustArrayIndexWrite[];
  declared: boolean;
  initializer: Readonly<IrExpression> | undefined;
  parameter: boolean;
}

interface RustArrayBoundsProvenReadContext {
  readonly bindingTypes: ReadonlyMap<string, Readonly<IrType>>;
  readonly excludedWriteElements: ReadonlySet<Readonly<Extract<IrExpression, { kind: 'element' }>>>;
  readonly sharedArrayBindingIds: ReadonlySet<string>;
  readonly integerEvidence: ReadonlyMap<string, RustArrayIndexEvidence>;
  readonly integerProven: Set<string>;
  readonly integerVisiting: Set<string>;
  readonly loopInitializerBindingIds: ReadonlyMap<
    Readonly<Extract<IrStatement, { kind: 'while' }>>,
    ReadonlySet<string>
  >;
  readonly proven: Map<Readonly<Extract<IrExpression, { kind: 'element' }>>, RustArrayBoundsProofKind>;
  readonly writeTargetElements: ReadonlySet<Readonly<Extract<IrExpression, { kind: 'element' }>>>;
}

// A proven read exists only under evidence that dominates it: either the condition's bounds hold when
// a branch or loop is entered, or an exact empty check exits before literal zero is read. The read names
// exactly those bindings, and nothing in between can change the index binding or array length. The walk
// follows statement structure rather than visit order because a loop condition runs before every body.
function collectRustProvenBoundsElementReadsRust(
  module: Readonly<IrModule>,
  bindingTypes: ReadonlyMap<string, Readonly<IrType>>,
  excludedWriteElements: ReadonlySet<Readonly<Extract<IrExpression, { kind: 'element' }>>>,
  writeTargetElements: ReadonlySet<Readonly<Extract<IrExpression, { kind: 'element' }>>>,
  sharedArrayBindingIds: ReadonlySet<string>,
): ReadonlyMap<Readonly<Extract<IrExpression, { kind: 'element' }>>, RustArrayBoundsProofKind> {
  const context: RustArrayBoundsProvenReadContext = {
    bindingTypes,
    excludedWriteElements,
    sharedArrayBindingIds,
    integerEvidence: collectRustArrayIndexEvidenceRust(module),
    integerProven: new Set(),
    integerVisiting: new Set(),
    loopInitializerBindingIds: collectRustArrayLoopInitializerBindingIdsRust(module),
    proven: new Map(),
    writeTargetElements,
  };
  for (const declaration of module.declarations) {
    if (declaration.kind === 'function') {
      walkRustGuardedStatementsRust(
        declaration.body,
        [],
        context,
        !declaration.async && declaration.typeParameters.length === 0,
      );
      continue;
    }
    if (declaration.kind !== 'class') continue;
    if (declaration.classConstructor) {
      walkRustGuardedStatementsRust(
        declaration.classConstructor.body,
        [],
        context,
        declaration.typeParameters.length === 0,
      );
    }
    for (const method of declaration.methods) {
      walkRustGuardedStatementsRust(
        method.body,
        [],
        context,
        !method.async && declaration.typeParameters.length === 0 && method.typeParameters.length === 0,
      );
    }
  }
  return context.proven;
}

// A guarded write may only use the narrow carrier this lane owns: a plain owned Vec of numbers whose
// compound right side cannot reach the receiver or index. Anything else stays on the existing
// absence refusal rather than being marked proven and emitted with different borrow or carrier order.
function collectRustExcludedProvenWriteElementsRust(
  module: Readonly<IrModule>,
  bindingTypes: ReadonlyMap<string, Readonly<IrType>>,
  sharedArrayBindingIds: ReadonlySet<string>,
): ReadonlySet<Readonly<Extract<IrExpression, { kind: 'element' }>>> {
  const excluded = new Set<Readonly<Extract<IrExpression, { kind: 'element' }>>>();
  analyzeIrModuleTraversal(module, {
    expression(expression) {
      if (expression.kind === 'assignment' && expression.operator !== '=' && expression.left.kind === 'element') {
        const element = expression.left;
        if (!isRustNarrowGuardedArrayWriteTargetRust(element, bindingTypes, sharedArrayBindingIds)) {
          excluded.add(element);
          return;
        }
        const receiver = element.object;
        if (receiver.kind !== 'identifier' || receiver.reference.kind !== 'binding') {
          excluded.add(element);
          return;
        }
        const referenced = collectRustExpressionReferencedBindingIdsRust(expression.right);
        if (referenced.has(receiver.reference.binding.id)) {
          excluded.add(element);
          return;
        }
        if (
          element.index.kind === 'identifier' &&
          element.index.reference.kind === 'binding' &&
          referenced.has(element.index.reference.binding.id)
        ) {
          excluded.add(element);
        }
        return;
      }
      if (
        expression.kind === 'unary' &&
        (expression.operator === '++' || expression.operator === '--') &&
        expression.operand.kind === 'element' &&
        !isRustNarrowGuardedArrayWriteTargetRust(expression.operand, bindingTypes, sharedArrayBindingIds)
      ) {
        excluded.add(expression.operand);
      }
    },
  });
  return excluded;
}

// Compound and update targets are owned by the staged write lane, which accepts only double-bounded
// evidence. The set lets a monotone proof protect reads without silently widening that lane.
function collectRustArrayWriteTargetElementsRust(
  module: Readonly<IrModule>,
): ReadonlySet<Readonly<Extract<IrExpression, { kind: 'element' }>>> {
  const targets = new Set<Readonly<Extract<IrExpression, { kind: 'element' }>>>();
  analyzeIrModuleTraversal(module, {
    expression(expression) {
      if (expression.kind === 'assignment' && expression.operator !== '=' && expression.left.kind === 'element') {
        targets.add(expression.left);
        return;
      }
      if (
        expression.kind === 'unary' &&
        (expression.operator === '++' || expression.operator === '--') &&
        expression.operand.kind === 'element'
      ) {
        targets.add(expression.operand);
      }
    },
  });
  return targets;
}

function isRustNarrowGuardedArrayWriteTargetRust(
  element: Readonly<Extract<IrExpression, { kind: 'element' }>>,
  bindingTypes: ReadonlyMap<string, Readonly<IrType>>,
  sharedArrayBindingIds: ReadonlySet<string>,
): boolean {
  if (element.optional || !hasOnlyOrdinaryArrayReceiverRust(element)) return false;
  const receiver = element.object;
  if (receiver.kind !== 'identifier' || receiver.reference.kind !== 'binding') return false;
  if (sharedArrayBindingIds.has(receiver.reference.binding.id)) return false;
  const type = bindingTypes.get(receiver.reference.binding.id);
  return type?.kind === 'array' && type.element.kind === 'primitive' && type.element.name === 'number';
}

function collectRustExpressionReferencedBindingIdsRust(expression: Readonly<IrExpression>): Set<string> {
  const ids = new Set<string>();
  analyzeIrExpressionSubtreeTraversal(expression, {
    expression(node) {
      if (node.kind === 'identifier' && node.reference.kind === 'binding') {
        ids.add(node.reference.binding.id);
      }
    },
  });
  return ids;
}

function walkRustGuardedStatementsRust(
  statements: readonly IrStatement[],
  guards: readonly RustArrayBoundsProvenGuard[],
  context: RustArrayBoundsProvenReadContext,
  triangularScopeEligible: boolean,
): readonly RustArrayBoundsProvenGuard[] {
  let active = guards;
  for (const statement of statements) {
    active = walkRustGuardedStatementRust(statement, active, context, triangularScopeEligible);
  }
  return active;
}

function walkRustGuardedStatementRust(
  statement: Readonly<IrStatement>,
  guards: readonly RustArrayBoundsProvenGuard[],
  context: RustArrayBoundsProvenReadContext,
  triangularScopeEligible: boolean,
): readonly RustArrayBoundsProvenGuard[] {
  switch (statement.kind) {
    case 'block':
      return walkRustGuardedStatementsRust(statement.statements, guards, context, triangularScopeEligible);
    case 'break':
    case 'continue':
      return guards;
    case 'do': {
      // A do-while condition does not dominate the first body execution, and inherited proofs do not
      // survive across iterations. The body and condition keep no inherited proof.
      walkRustGuardedStatementRust(statement.body, [], context, triangularScopeEligible);
      markRustGuardedExpressionReadsRust(statement.condition, [], context);
      return filterRustArrayBoundsGuardsRust(guards, collectRustGuardedStatementInvalidatingBindingIdsRust(statement));
    }
    case 'expression':
      markRustGuardedExpressionReadsRust(statement.expression, guards, context);
      return filterRustArrayBoundsGuardsRust(
        guards,
        collectRustGuardedExpressionInvalidatingBindingIdsRust(statement.expression),
      );
    case 'for': {
      const initializers: IrExpression[] = [];
      if (Array.isArray(statement.initializer)) {
        for (const variable of statement.initializer) {
          if (variable.initializer) initializers.push(variable.initializer);
        }
      } else if (statement.initializer) {
        initializers.push(statement.initializer as IrExpression);
      }
      const initializerGuards = filterRustArrayBoundsGuardsRust(
        guards,
        collectRustGuardedExpressionInvalidatingBindingIdsRustForExpressionsRust(initializers),
      );
      // The initializer runs once before the loop and keeps the enclosing proof; the condition,
      // increment, and body run on every iteration and keep no inherited proof.
      for (const initializer of initializers) {
        markRustGuardedExpressionReadsRust(initializer, initializerGuards, context);
      }
      if (statement.condition) markRustGuardedExpressionReadsRust(statement.condition, [], context);
      if (statement.increment) markRustGuardedExpressionReadsRust(statement.increment, [], context);
      walkRustGuardedStatementRust(statement.body, [], context, triangularScopeEligible);
      return filterRustArrayBoundsGuardsRust(guards, collectRustGuardedStatementInvalidatingBindingIdsRust(statement));
    }
    case 'forIn': {
      const objectGuards = filterRustArrayBoundsGuardsRust(
        guards,
        collectRustGuardedExpressionInvalidatingBindingIdsRust(statement.object),
      );
      markRustGuardedExpressionReadsRust(statement.object, objectGuards, context);
      walkRustGuardedStatementRust(statement.body, [], context, triangularScopeEligible);
      return filterRustArrayBoundsGuardsRust(guards, collectRustGuardedStatementInvalidatingBindingIdsRust(statement));
    }
    case 'forOf': {
      const iterableGuards = filterRustArrayBoundsGuardsRust(
        guards,
        collectRustGuardedExpressionInvalidatingBindingIdsRust(statement.iterable),
      );
      markRustGuardedExpressionReadsRust(statement.iterable, iterableGuards, context);
      walkRustGuardedStatementRust(statement.body, [], context, triangularScopeEligible);
      return filterRustArrayBoundsGuardsRust(guards, collectRustGuardedStatementInvalidatingBindingIdsRust(statement));
    }
    case 'if': {
      const conditionGuards = filterRustArrayBoundsGuardsRust(
        guards,
        collectRustGuardedExpressionInvalidatingBindingIdsRust(statement.condition),
      );
      markRustGuardedExpressionReadsRust(statement.condition, conditionGuards, context);
      const provenGuard = createRustArrayBoundsProvenGuardRust(statement.condition, context);
      const consequentGuards =
        provenGuard && !statementContainsFunctionExpressionRust(statement.consequent)
          ? [...conditionGuards, provenGuard]
          : conditionGuards;
      walkRustGuardedStatementRust(statement.consequent, consequentGuards, context, triangularScopeEligible);
      if (statement.otherwise) {
        walkRustGuardedStatementRust(statement.otherwise, conditionGuards, context, triangularScopeEligible);
      }
      const survivingGuards = filterRustArrayBoundsGuardsRust(
        guards,
        collectRustGuardedStatementInvalidatingBindingIdsRust(statement),
      );
      const fallthroughGuard = createRustArrayNonemptyFallthroughGuardRust(statement, context);
      return fallthroughGuard ? [...survivingGuards, fallthroughGuard] : survivingGuards;
    }
    case 'return':
      if (statement.expression) markRustGuardedExpressionReadsRust(statement.expression, guards, context);
      return filterRustArrayBoundsGuardsRust(guards, collectRustGuardedStatementInvalidatingBindingIdsRust(statement));
    case 'switch': {
      const subjectGuards = filterRustArrayBoundsGuardsRust(
        guards,
        collectRustGuardedExpressionInvalidatingBindingIdsRust(statement.expression),
      );
      markRustGuardedExpressionReadsRust(statement.expression, subjectGuards, context);
      for (const switchCase of statement.cases) {
        if (switchCase.expression) {
          markRustGuardedExpressionReadsRust(switchCase.expression, subjectGuards, context);
        }
        walkRustGuardedStatementsRust(switchCase.statements, subjectGuards, context, triangularScopeEligible);
      }
      return filterRustArrayBoundsGuardsRust(guards, collectRustGuardedStatementInvalidatingBindingIdsRust(statement));
    }
    case 'throw':
      markRustGuardedExpressionReadsRust(statement.expression, guards, context);
      return filterRustArrayBoundsGuardsRust(guards, collectRustGuardedStatementInvalidatingBindingIdsRust(statement));
    case 'try': {
      let active = walkRustGuardedStatementRust(statement.tryBody, guards, context, triangularScopeEligible);
      if (statement.catchClause) {
        active = walkRustGuardedStatementRust(statement.catchClause.body, active, context, triangularScopeEligible);
      }
      if (statement.finallyBody) {
        active = walkRustGuardedStatementRust(statement.finallyBody, active, context, triangularScopeEligible);
      }
      return filterRustArrayBoundsGuardsRust(guards, collectRustGuardedStatementInvalidatingBindingIdsRust(statement));
    }
    case 'variable': {
      const initializers = statement.declarations.flatMap((variable) =>
        variable.initializer ? [variable.initializer] : [],
      );
      const initializerGuards = filterRustArrayBoundsGuardsRust(
        guards,
        collectRustGuardedExpressionInvalidatingBindingIdsRustForExpressionsRust(initializers),
      );
      for (const initializer of initializers)
        markRustGuardedExpressionReadsRust(initializer, initializerGuards, context);
      return initializerGuards;
    }
    case 'while': {
      // Condition reads run on every iteration after a possible previous body write, so they keep no
      // inherited proof. A loop may establish only its own proof, from its own condition.
      markRustGuardedExpressionReadsRust(statement.condition, [], context);
      const provenGuard = statementContainsFunctionExpressionRust(statement.body)
        ? undefined
        : (createRustArrayBoundsProvenGuardRust(statement.condition, context) ??
          createRustMonotoneArrayBoundsProvenGuardRust(statement, context));
      const triangularGuards = createRustTriangularArrayBoundsProvenGuardsRust(
        statement,
        provenGuard,
        guards,
        context,
        triangularScopeEligible,
      );
      walkRustGuardedStatementRust(
        statement.body,
        triangularGuards ?? (provenGuard ? [provenGuard] : []),
        context,
        triangularScopeEligible,
      );
      return filterRustArrayBoundsGuardsRust(guards, collectRustGuardedStatementInvalidatingBindingIdsRust(statement));
    }
  }
}

function filterRustArrayBoundsGuardsRust(
  guards: readonly RustArrayBoundsProvenGuard[],
  invalidatingBindingIds: ReadonlySet<string>,
): readonly RustArrayBoundsProvenGuard[] {
  return guards.filter(
    (guard) =>
      !invalidatingBindingIds.has(guard.arrayBindingId) &&
      (!('indexBindingId' in guard) || !invalidatingBindingIds.has(guard.indexBindingId)),
  );
}

function markRustGuardedExpressionReadsRust(
  expression: Readonly<IrExpression>,
  guards: readonly RustArrayBoundsProvenGuard[],
  context: RustArrayBoundsProvenReadContext,
): void {
  if (guards.length === 0 || expressionContainsFunctionRust(expression)) return;
  analyzeIrExpressionSubtreeTraversal(expression, {
    expression(node) {
      if (node.kind !== 'element' || node.optional || !hasOnlyOrdinaryArrayReceiverRust(node)) return;
      if (context.excludedWriteElements.has(node)) return;
      const object = node.object;
      const index = node.index;
      if (object.kind !== 'identifier' || object.reference.kind !== 'binding') return;
      const arrayBindingId = object.reference.binding.id;
      const indexBindingId =
        index.kind === 'identifier' && index.reference.kind === 'binding' ? index.reference.binding.id : undefined;
      const matching = guards.filter((guard) => {
        if (guard.arrayBindingId !== arrayBindingId) return false;
        if (guard.kind === 'nonempty-zero') return isRustZeroLiteralRust(index);
        return indexBindingId !== undefined && guard.indexBindingId === indexBindingId;
      });
      if (matching.length === 0) return;
      // The staged compound/update write lane owns only dual-bound evidence. A monotone proof may
      // protect reads, and a fallthrough proof may protect literal zero, but neither marks a write
      // target as writable under that lane.
      if (context.writeTargetElements.has(node) && matching.every((guard) => guard.kind !== 'dual-bound')) {
        return;
      }
      context.proven.set(
        node,
        matching.some((guard) => guard.kind === 'dual-bound')
          ? 'dual-bound'
          : matching.some((guard) => guard.kind === 'monotone')
            ? 'monotone'
            : 'nonempty-zero',
      );
    },
  });
}

function expressionContainsFunctionRust(expression: Readonly<IrExpression>): boolean {
  let found = false;
  analyzeIrExpressionSubtreeTraversal(expression, {
    expression(node) {
      if (node.kind === 'function') found = true;
    },
  });
  return found;
}

function statementContainsFunctionExpressionRust(statement: Readonly<IrStatement>): boolean {
  let found = false;
  forEachRustStatementExpressionRust(statement, (expression) => {
    if (!found && expressionContainsFunctionRust(expression)) found = true;
  });
  return found;
}

function forEachRustStatementExpressionRust(
  statement: Readonly<IrStatement>,
  visit: (expression: Readonly<IrExpression>) => void,
): void {
  switch (statement.kind) {
    case 'block':
      for (const child of statement.statements) forEachRustStatementExpressionRust(child, visit);
      return;
    case 'break':
    case 'continue':
      return;
    case 'do':
    case 'while':
      forEachRustStatementExpressionRust(statement.body, visit);
      visit(statement.condition);
      return;
    case 'expression':
    case 'throw':
      visit(statement.expression);
      return;
    case 'for':
      if (Array.isArray(statement.initializer)) {
        for (const variable of statement.initializer) {
          if (variable.initializer) visit(variable.initializer);
        }
      } else if (statement.initializer) {
        visit(statement.initializer as IrExpression);
      }
      if (statement.condition) visit(statement.condition);
      if (statement.increment) visit(statement.increment);
      forEachRustStatementExpressionRust(statement.body, visit);
      return;
    case 'forIn':
      visit(statement.object);
      forEachRustStatementExpressionRust(statement.body, visit);
      return;
    case 'forOf':
      visit(statement.iterable);
      forEachRustStatementExpressionRust(statement.body, visit);
      return;
    case 'if':
      visit(statement.condition);
      forEachRustStatementExpressionRust(statement.consequent, visit);
      if (statement.otherwise) forEachRustStatementExpressionRust(statement.otherwise, visit);
      return;
    case 'return':
      if (statement.expression) visit(statement.expression);
      return;
    case 'switch':
      visit(statement.expression);
      for (const switchCase of statement.cases) {
        if (switchCase.expression) visit(switchCase.expression);
        for (const child of switchCase.statements) forEachRustStatementExpressionRust(child, visit);
      }
      return;
    case 'try':
      forEachRustStatementExpressionRust(statement.tryBody, visit);
      if (statement.catchClause) forEachRustStatementExpressionRust(statement.catchClause.body, visit);
      if (statement.finallyBody) forEachRustStatementExpressionRust(statement.finallyBody, visit);
      return;
    case 'variable':
      for (const variable of statement.declarations) {
        if (variable.initializer) visit(variable.initializer);
      }
      return;
  }
}

function collectRustGuardedStatementInvalidatingBindingIdsRust(statement: Readonly<IrStatement>): Set<string> {
  const ids = new Set<string>();
  forEachRustStatementExpressionRust(statement, (expression) => {
    for (const id of collectRustGuardedExpressionInvalidatingBindingIdsRust(expression)) ids.add(id);
  });
  return ids;
}

function collectRustGuardedExpressionInvalidatingBindingIdsRustForExpressionsRust(
  expressions: readonly Readonly<IrExpression>[],
): Set<string> {
  const ids = new Set<string>();
  for (const expression of expressions) {
    for (const id of collectRustGuardedExpressionInvalidatingBindingIdsRust(expression)) ids.add(id);
  }
  return ids;
}

// A guard's proof is broken by rebinding the index or receiver, changing the receiver's length, or any
// call that could reach either binding. Nested function bodies count for invalidation because a call
// can run them, even though reads inside them are never marked.
function collectRustGuardedExpressionInvalidatingBindingIdsRust(expression: Readonly<IrExpression>): Set<string> {
  const ids = new Set<string>();
  analyzeIrExpressionSubtreeTraversal(expression, {
    expression(node) {
      if (node.kind === 'assignment') {
        if (node.left.kind === 'identifier' && node.left.reference.kind === 'binding') {
          ids.add(node.left.reference.binding.id);
        } else if (
          node.left.kind === 'property' &&
          node.left.name === 'length' &&
          node.left.object.kind === 'identifier' &&
          node.left.object.reference.kind === 'binding'
        ) {
          ids.add(node.left.object.reference.binding.id);
        }
        return;
      }
      if (
        node.kind === 'unary' &&
        (node.operator === '++' || node.operator === '--') &&
        node.operand.kind === 'identifier' &&
        node.operand.reference.kind === 'binding'
      ) {
        ids.add(node.operand.reference.binding.id);
        return;
      }
      if (node.kind !== 'call' && node.kind !== 'new') return;
      const collectReferenced = (candidate: Readonly<IrExpression>): void => {
        analyzeIrExpressionSubtreeTraversal(candidate, {
          expression(inner) {
            if (inner.kind === 'identifier' && inner.reference.kind === 'binding') {
              ids.add(inner.reference.binding.id);
            }
          },
        });
      };
      collectReferenced(node.callee);
      for (const argument of node.arguments) collectReferenced(argument);
    },
  });
  return ids;
}

// The guard is exactly two conjuncts: one lower bound of zero and one upper bound at the receiver's
// length, in either operand order. The index must be proven to hold integers; bounds alone would let a
// fractional index read the wrong element while the source read reports absence.
function createRustArrayBoundsProvenGuardRust(
  condition: Readonly<IrExpression>,
  context: RustArrayBoundsProvenReadContext,
): Extract<RustArrayBoundsProvenGuard, { kind: 'dual-bound' }> | undefined {
  if (condition.kind !== 'binary' || condition.operator !== '&&') return undefined;
  const left = parseRustArrayBoundsGuardConjunctRust(condition.left);
  const right = parseRustArrayBoundsGuardConjunctRust(condition.right);
  if (!left || !right || left.kind === right.kind) return undefined;
  const lower = left.kind === 'lower' ? left : right;
  const upper = left.kind === 'upper' ? left : right;
  if (lower.kind !== 'lower' || upper.kind !== 'upper' || lower.binding.id !== upper.index.id) return undefined;
  if (!isRustIntegerProvenBindingRust(lower.binding.id, context)) return undefined;
  const indexType = context.bindingTypes.get(lower.binding.id);
  if (indexType?.kind !== 'primitive' || indexType.name !== 'number') return undefined;
  const arrayType = context.bindingTypes.get(upper.array.id);
  if (arrayType?.kind !== 'array' || arrayType.element.kind !== 'primitive') return undefined;
  if (
    arrayType.element.name !== 'number' &&
    arrayType.element.name !== 'boolean' &&
    arrayType.element.name !== 'string'
  ) {
    return undefined;
  }
  if (arrayType.element.name === 'string' && context.sharedArrayBindingIds.has(upper.array.id)) return undefined;
  return { arrayBindingId: upper.array.id, indexBindingId: lower.binding.id, kind: 'dual-bound' };
}

// An abrupt empty branch makes the following path nonempty. This deliberately proves only literal
// zero on an owned exact String array: broader indices still need ordinary bounds, and a shared
// carrier could change length through an alias between the guard and read.
function createRustArrayNonemptyFallthroughGuardRust(
  statement: Readonly<Extract<IrStatement, { kind: 'if' }>>,
  context: RustArrayBoundsProvenReadContext,
): Extract<RustArrayBoundsProvenGuard, { kind: 'nonempty-zero' }> | undefined {
  if (statement.otherwise || !isRustUnconditionallyAbruptStatementRust(statement.consequent)) return undefined;
  const condition = statement.condition;
  if (condition.kind !== 'binary' || condition.operator !== '===') return undefined;
  const array = isRustZeroLiteralRust(condition.left)
    ? asRustArrayLengthPropertyBindingRust(condition.right)
    : isRustZeroLiteralRust(condition.right)
      ? asRustArrayLengthPropertyBindingRust(condition.left)
      : undefined;
  if (!array || context.sharedArrayBindingIds.has(array.id)) return undefined;
  const arrayType = context.bindingTypes.get(array.id);
  if (arrayType?.kind !== 'array' || arrayType.element.kind !== 'primitive' || arrayType.element.name !== 'string') {
    return undefined;
  }
  return { arrayBindingId: array.id, kind: 'nonempty-zero' };
}

function isRustUnconditionallyAbruptStatementRust(statement: Readonly<IrStatement>): boolean {
  if (statement.kind === 'return' || statement.kind === 'throw') return true;
  if (statement.kind !== 'block') return false;
  const last = statement.statements.at(-1);
  return last !== undefined && isRustUnconditionallyAbruptStatementRust(last);
}

// A while loop with only the upper bound can still prove the same read when the index is inductively
// nonnegative: it starts at a nonnegative integer literal and every write in the whole function is an
// exact +1 form located inside this loop body. The condition re-establishes the upper bound each
// iteration; the unit step preserves non-negativity, so the read before any body write is in range.
function createRustMonotoneArrayBoundsProvenGuardRust(
  statement: Readonly<Extract<IrStatement, { kind: 'while' }>>,
  context: RustArrayBoundsProvenReadContext,
): Extract<RustArrayBoundsProvenGuard, { kind: 'monotone' }> | undefined {
  const upper = parseRustArrayBoundsGuardConjunctRust(statement.condition);
  if (!upper || upper.kind !== 'upper') return undefined;
  const indexType = context.bindingTypes.get(upper.index.id);
  if (indexType?.kind !== 'primitive' || indexType.name !== 'number') return undefined;
  const arrayType = context.bindingTypes.get(upper.array.id);
  if (arrayType?.kind !== 'array' || arrayType.element.kind !== 'primitive') return undefined;
  if (arrayType.element.name !== 'number' && arrayType.element.name !== 'string') return undefined;
  if (context.sharedArrayBindingIds.has(upper.array.id)) return undefined;
  const evidence = context.integerEvidence.get(upper.index.id);
  if (!evidence || !evidence.declared || evidence.parameter) return undefined;
  if (!isRustNonnegativeIntegerLiteralRust(evidence.initializer)) return undefined;
  if (!isRustIntegerProvenBindingRust(upper.index.id, context)) return undefined;
  const bodyWrites = collectRustArrayIndexWriteNodesRust(statement.body, upper.index.id);
  if (bodyWrites.size !== evidence.writes.length) return undefined;
  if (
    evidence.writes.some((write) => !bodyWrites.has(write.node) || !isRustExactUnitIndexStepRust(write, upper.index.id))
  ) {
    return undefined;
  }
  return {
    arrayBindingId: upper.array.id,
    indexBindingId: upper.index.id,
    kind: 'monotone',
    monotoneLoop: statement,
  };
}

// A nested loop normally drops every inherited bound. The one exception is a triangular scan over
// the same owned number array: the child starts exactly one position after the outer index, and both
// indices retain their independently proven strict monotone bounds. Keeping the loop identities on
// the guards makes this a read-only provenance refinement rather than a new write capability.
function createRustTriangularArrayBoundsProvenGuardsRust(
  statement: Readonly<Extract<IrStatement, { kind: 'while' }>>,
  provenGuard: Readonly<RustArrayBoundsProvenGuard> | undefined,
  inheritedGuards: readonly RustArrayBoundsProvenGuard[],
  context: RustArrayBoundsProvenReadContext,
  triangularScopeEligible: boolean,
): readonly RustArrayBoundsProvenGuard[] | undefined {
  if (!triangularScopeEligible || inheritedGuards.length !== 1) return undefined;
  const outer = inheritedGuards[0];
  if (!outer || outer.kind !== 'monotone') return undefined;
  const child =
    provenGuard?.kind === 'monotone'
      ? provenGuard
      : createRustDerivedMonotoneArrayBoundsProvenGuardRust(statement, outer.indexBindingId, context);
  if (!child) return undefined;
  if (outer.arrayBindingId !== child.arrayBindingId || outer.indexBindingId === child.indexBindingId) {
    return undefined;
  }
  if (!context.loopInitializerBindingIds.get(outer.monotoneLoop)?.has(outer.indexBindingId)) return undefined;
  if (!context.loopInitializerBindingIds.get(statement)?.has(child.indexBindingId)) return undefined;
  const arrayType = context.bindingTypes.get(child.arrayBindingId);
  if (
    arrayType?.kind !== 'array' ||
    arrayType.element.kind !== 'primitive' ||
    arrayType.element.name !== 'number' ||
    context.sharedArrayBindingIds.has(child.arrayBindingId)
  ) {
    return undefined;
  }
  const childEvidence = context.integerEvidence.get(child.indexBindingId);
  if (!childEvidence || !isRustDerivedUnitIndexInitializerRust(childEvidence.initializer, outer.indexBindingId)) {
    return undefined;
  }
  if (!hasOnlyRustTriangularNestedControlFlowRust(outer.monotoneLoop.body, statement)) return undefined;
  if (collectRustArrayIndexWriteNodesRust(statement.body, outer.indexBindingId).size !== 0) return undefined;
  const invalidations = collectRustGuardedStatementInvalidatingBindingIdsRust(outer.monotoneLoop);
  if (invalidations.has(child.arrayBindingId)) return undefined;
  return [outer, child];
}

function createRustDerivedMonotoneArrayBoundsProvenGuardRust(
  statement: Readonly<Extract<IrStatement, { kind: 'while' }>>,
  outerIndexBindingId: string,
  context: RustArrayBoundsProvenReadContext,
): Extract<RustArrayBoundsProvenGuard, { kind: 'monotone' }> | undefined {
  const upper = parseRustArrayBoundsGuardConjunctRust(statement.condition);
  if (!upper || upper.kind !== 'upper') return undefined;
  const indexType = context.bindingTypes.get(upper.index.id);
  if (indexType?.kind !== 'primitive' || indexType.name !== 'number') return undefined;
  const arrayType = context.bindingTypes.get(upper.array.id);
  if (arrayType?.kind !== 'array' || arrayType.element.kind !== 'primitive' || arrayType.element.name !== 'number') {
    return undefined;
  }
  if (context.sharedArrayBindingIds.has(upper.array.id)) return undefined;
  const evidence = context.integerEvidence.get(upper.index.id);
  if (!evidence || !evidence.declared || evidence.parameter) return undefined;
  if (!isRustDerivedUnitIndexInitializerRust(evidence.initializer, outerIndexBindingId)) return undefined;
  if (!isRustIntegerProvenBindingRust(upper.index.id, context)) return undefined;
  const bodyWrites = collectRustArrayIndexWriteNodesRust(statement.body, upper.index.id);
  if (bodyWrites.size !== evidence.writes.length) return undefined;
  if (
    evidence.writes.some((write) => !bodyWrites.has(write.node) || !isRustExactUnitIndexStepRust(write, upper.index.id))
  ) {
    return undefined;
  }
  return {
    arrayBindingId: upper.array.id,
    indexBindingId: upper.index.id,
    kind: 'monotone',
    monotoneLoop: statement,
  };
}

function isRustDerivedUnitIndexInitializerRust(
  expression: Readonly<IrExpression> | undefined,
  outerIndexBindingId: string,
): boolean {
  if (!expression || expression.kind !== 'binary' || expression.operator !== '+') return false;
  const sameOuterIndex = (candidate: Readonly<IrExpression>): boolean =>
    candidate.kind === 'identifier' &&
    candidate.reference.kind === 'binding' &&
    candidate.reference.binding.id === outerIndexBindingId;
  const literalOne = (candidate: Readonly<IrExpression>): boolean =>
    candidate.kind === 'literal' && typeof candidate.value === 'number' && candidate.value === 1;
  return (
    (sameOuterIndex(expression.left) && literalOne(expression.right)) ||
    (literalOne(expression.left) && sameOuterIndex(expression.right))
  );
}

function hasOnlyRustTriangularNestedControlFlowRust(
  statement: Readonly<IrStatement>,
  childLoop: Readonly<Extract<IrStatement, { kind: 'while' }>>,
): boolean {
  let childSeen = false;
  const visit = (node: Readonly<IrStatement>, allowedChild: boolean): boolean => {
    switch (node.kind) {
      case 'block':
        return node.statements.every((child) => visit(child, allowedChild));
      case 'break':
      case 'expression':
      case 'return':
      case 'throw':
      case 'variable':
        return true;
      case 'continue':
      case 'do':
      case 'for':
      case 'forIn':
      case 'forOf':
      case 'try':
        return false;
      case 'if':
        return visit(node.consequent, allowedChild) && (!node.otherwise || visit(node.otherwise, allowedChild));
      case 'switch':
        return node.cases.every((switchCase) => switchCase.statements.every((child) => visit(child, allowedChild)));
      case 'while':
        if (!allowedChild || node !== childLoop || childSeen) return false;
        childSeen = true;
        return visit(node.body, false);
    }
  };
  return visit(statement, true) && childSeen;
}

function isRustNonnegativeIntegerLiteralRust(expression: Readonly<IrExpression> | undefined): boolean {
  return (
    expression?.kind === 'literal' &&
    typeof expression.value === 'number' &&
    Number.isInteger(expression.value) &&
    expression.value >= 0
  );
}

function isRustExactUnitIndexStepRust(write: Readonly<RustArrayIndexWrite>, indexBindingId: string): boolean {
  if (write.operator === '++') return true;
  if (write.operator === '+=') {
    return write.right?.kind === 'literal' && write.right.value === 1;
  }
  if (write.operator !== '=' || !write.right || write.right.kind !== 'binary' || write.right.operator !== '+') {
    return false;
  }
  const left = write.right.left;
  const right = write.right.right;
  const literalOne = (candidate: Readonly<IrExpression>): boolean =>
    candidate.kind === 'literal' && typeof candidate.value === 'number' && candidate.value === 1;
  const sameIndex = (candidate: Readonly<IrExpression>): boolean =>
    candidate.kind === 'identifier' &&
    candidate.reference.kind === 'binding' &&
    candidate.reference.binding.id === indexBindingId;
  return (sameIndex(left) && literalOne(right)) || (literalOne(left) && sameIndex(right));
}

function collectRustArrayIndexWriteNodesRust(
  statement: Readonly<IrStatement>,
  indexBindingId: string,
): ReadonlySet<Readonly<Extract<IrExpression, { kind: 'assignment' | 'unary' }>>> {
  const nodes = new Set<Readonly<Extract<IrExpression, { kind: 'assignment' | 'unary' }>>>();
  forEachRustStatementExpressionRust(statement, (expression) => {
    analyzeIrExpressionSubtreeTraversal(expression, {
      expression(node) {
        if (
          node.kind === 'assignment' &&
          node.left.kind === 'identifier' &&
          node.left.reference.kind === 'binding' &&
          node.left.reference.binding.id === indexBindingId
        ) {
          nodes.add(node);
          return;
        }
        if (
          node.kind === 'unary' &&
          (node.operator === '++' || node.operator === '--') &&
          node.operand.kind === 'identifier' &&
          node.operand.reference.kind === 'binding' &&
          node.operand.reference.binding.id === indexBindingId
        ) {
          nodes.add(node);
        }
      },
    });
  });
  return nodes;
}

type RustArrayBoundsGuardConjunct =
  | Readonly<{ binding: IrBindingIdentity; kind: 'lower' }>
  | Readonly<{ array: IrBindingIdentity; index: IrBindingIdentity; kind: 'upper' }>;

function parseRustArrayBoundsGuardConjunctRust(
  expression: Readonly<IrExpression>,
): RustArrayBoundsGuardConjunct | undefined {
  if (expression.kind !== 'binary') return undefined;
  if (expression.operator === '>=' || expression.operator === '<=') {
    const index =
      expression.operator === '>='
        ? asRustIdentifierBindingRust(expression.left)
        : asRustIdentifierBindingRust(expression.right);
    const zero = expression.operator === '>=' ? expression.right : expression.left;
    return index && isRustZeroLiteralRust(zero) ? { binding: index, kind: 'lower' } : undefined;
  }
  if (expression.operator !== '<' && expression.operator !== '>') return undefined;
  const length =
    expression.operator === '<'
      ? asRustArrayLengthPropertyBindingRust(expression.right)
      : asRustArrayLengthPropertyBindingRust(expression.left);
  const index =
    expression.operator === '<'
      ? asRustIdentifierBindingRust(expression.left)
      : asRustIdentifierBindingRust(expression.right);
  return index && length ? { array: length, index, kind: 'upper' } : undefined;
}

function asRustIdentifierBindingRust(expression: Readonly<IrExpression>): IrBindingIdentity | undefined {
  return expression.kind === 'identifier' && expression.reference.kind === 'binding'
    ? expression.reference.binding
    : undefined;
}

function asRustArrayLengthPropertyBindingRust(expression: Readonly<IrExpression>): IrBindingIdentity | undefined {
  return expression.kind === 'property' &&
    expression.name === 'length' &&
    expression.member?.name === 'length' &&
    expression.member.receiver === 'array' &&
    expression.object.kind === 'identifier' &&
    expression.object.reference.kind === 'binding'
    ? expression.object.reference.binding
    : undefined;
}

function isRustZeroLiteralRust(expression: Readonly<IrExpression>): boolean {
  return expression.kind === 'literal' && typeof expression.value === 'number' && expression.value === 0;
}

function collectRustArrayIndexEvidenceRust(module: Readonly<IrModule>): ReadonlyMap<string, RustArrayIndexEvidence> {
  const evidence = new Map<string, RustArrayIndexEvidence>();
  const ensure = (bindingId: string): RustArrayIndexEvidence => {
    const existing = evidence.get(bindingId);
    if (existing) return existing;
    const created: RustArrayIndexEvidence = {
      declared: false,
      initializer: undefined,
      parameter: false,
      writes: [],
    };
    evidence.set(bindingId, created);
    return created;
  };
  analyzeIrModuleTraversal(module, {
    expression(expression) {
      if (
        expression.kind === 'assignment' &&
        expression.left.kind === 'identifier' &&
        expression.left.reference.kind === 'binding'
      ) {
        ensure(expression.left.reference.binding.id).writes.push({
          node: expression,
          operator: expression.operator,
          right: expression.right,
        });
        return;
      }
      if (
        expression.kind === 'unary' &&
        (expression.operator === '++' || expression.operator === '--') &&
        expression.operand.kind === 'identifier' &&
        expression.operand.reference.kind === 'binding'
      ) {
        ensure(expression.operand.reference.binding.id).writes.push({
          node: expression,
          operator: expression.operator,
          right: undefined,
        });
      }
    },
    parameter(parameter) {
      ensure(parameter.binding.id).parameter = true;
    },
    variable(variable) {
      if (!('binding' in variable)) return;
      const record = ensure(variable.binding.id);
      record.declared = true;
      record.initializer = variable.initializer;
    },
  });
  return evidence;
}

function collectRustArrayLoopInitializerBindingIdsRust(
  module: Readonly<IrModule>,
): ReadonlyMap<Readonly<Extract<IrStatement, { kind: 'while' }>>, ReadonlySet<string>> {
  const loopInitializers = new Map<Readonly<Extract<IrStatement, { kind: 'while' }>>, ReadonlySet<string>>();
  const visitStatements = (statements: readonly IrStatement[]): void => {
    for (const [index, statement] of statements.entries()) {
      const previous = statements[index - 1];
      if (statement.kind === 'while' && previous?.kind === 'variable' && previous.declarations.length === 1) {
        const declaration = previous.declarations[0];
        if (declaration && 'binding' in declaration) {
          loopInitializers.set(statement, new Set([declaration.binding.id]));
        }
      }
      visitStatement(statement);
    }
  };
  const visitStatement = (statement: Readonly<IrStatement>): void => {
    switch (statement.kind) {
      case 'block':
        visitStatements(statement.statements);
        return;
      case 'do':
      case 'for':
      case 'forIn':
      case 'forOf':
      case 'while':
        visitStatement(statement.body);
        return;
      case 'if':
        visitStatement(statement.consequent);
        if (statement.otherwise) visitStatement(statement.otherwise);
        return;
      case 'switch':
        for (const switchCase of statement.cases) visitStatements(switchCase.statements);
        return;
      case 'try':
        visitStatement(statement.tryBody);
        if (statement.catchClause) visitStatement(statement.catchClause.body);
        if (statement.finallyBody) visitStatement(statement.finallyBody);
        return;
      case 'break':
      case 'continue':
      case 'expression':
      case 'return':
      case 'throw':
      case 'variable':
        return;
    }
  };
  for (const declaration of module.declarations) {
    if (declaration.kind === 'function') {
      visitStatements(declaration.body);
      continue;
    }
    if (declaration.kind !== 'class') continue;
    if (declaration.classConstructor) visitStatements(declaration.classConstructor.body);
    for (const method of declaration.methods) visitStatements(method.body);
  }
  return loopInitializers;
}

function isRustIntegerProvenBindingRust(bindingId: string, context: RustArrayBoundsProvenReadContext): boolean {
  const memo = context.integerProven;
  if (memo.has(bindingId)) return true;
  if (context.integerVisiting.has(bindingId)) return false;
  const evidence = context.integerEvidence.get(bindingId);
  if (!evidence || !evidence.declared || evidence.parameter || !evidence.initializer) return false;
  context.integerVisiting.add(bindingId);
  const initializerProven = isRustIntegerProvenExpressionRust(evidence.initializer, context);
  context.integerVisiting.delete(bindingId);
  if (!initializerProven) return false;
  // The initializer proves the first value; an update may read the value it replaces, so the binding
  // is assumed integer while its own writes are checked.
  memo.add(bindingId);
  const writesProven = evidence.writes.every((write) => isRustIntegerPreservingWriteRust(write, context));
  if (!writesProven) memo.delete(bindingId);
  return writesProven;
}

function isRustIntegerPreservingWriteRust(
  write: Readonly<RustArrayIndexWrite>,
  context: RustArrayBoundsProvenReadContext,
): boolean {
  if (write.operator === '++' || write.operator === '--') return true;
  if (
    write.operator !== '=' &&
    write.operator !== '+=' &&
    write.operator !== '-=' &&
    write.operator !== '*=' &&
    write.operator !== '%='
  ) {
    return false;
  }
  return write.right !== undefined && isRustIntegerProvenExpressionRust(write.right, context);
}

function isRustIntegerProvenExpressionRust(
  expression: Readonly<IrExpression>,
  context: RustArrayBoundsProvenReadContext,
): boolean {
  switch (expression.kind) {
    case 'literal':
      return typeof expression.value === 'number' && Number.isInteger(expression.value);
    case 'identifier':
      return (
        expression.reference.kind === 'binding' &&
        isRustIntegerProvenBindingRust(expression.reference.binding.id, context)
      );
    case 'binary':
      return (
        (expression.operator === '+' ||
          expression.operator === '-' ||
          expression.operator === '*' ||
          expression.operator === '%') &&
        isRustIntegerProvenExpressionRust(expression.left, context) &&
        isRustIntegerProvenExpressionRust(expression.right, context)
      );
    case 'unary':
      return (
        (expression.operator === '+' || expression.operator === '-') &&
        isRustIntegerProvenExpressionRust(expression.operand, context)
      );
    case 'cast':
      return (
        expression.type.kind === 'primitive' &&
        expression.type.name === 'number' &&
        isRustIntegerProvenExpressionRust(expression.expression, context)
      );
    default:
      return false;
  }
}

type RustArrayGrowthMember = 'push' | 'unshift';
type RustArrayOperationMember =
  | RustArrayGrowthMember
  | RustArraySearchMember
  | 'concat'
  | 'copyWithin'
  | 'every'
  | 'fill'
